window.__D("text/zohar-hebrew-translation/c002",{"p":[[9522011103,"<p>הֵיכָל שִׁשִּׁי. כָּאן הוּא רוּחַ שֶׁנִּקְרָא חוּ\"ט הַשָּׁנִי, סוֹד הַכָּתוּב (שם ד) כְּחוּט הַשָּׁנִי שִׂפְתוֹתַיִךְ. הַהֵיכָל הַזֶּה (היכל שנקרא) נִקְרָא הֵיכַל הָרָצוֹן. כָּאן רוּחַ שֶׁהוּא רָצוֹן שֶׁכָּל הָרוּחוֹת הַתַּחְתּוֹנוֹת הַלָּלוּ רָצִים אַחֲרֶיהָ לְהִדָּבֵק בָּהּ בִּנְשִׁיקָה בְּאַהֲבָה.</p>\n<p>רוּחַ זֶה נִכְלָל בְּשֵׁשׁ, וְעוֹמֵד בְּשֵׁשׁ. נִכְלָל בְּשֵׁשׁ שֶׁלְּמַטָּה יַחַד עִמּוֹ, וְעוֹמֵד בְּשֵׁשׁ עֶלְיוֹנִים. וְלָכֵן רוּחַ זֶה מוֹצִיא שְׁנֵים עָשָׂר אוֹרוֹת כְּלוּלִים כֻּלָּם מִלְּמַטָּה וּמִלְמַעְלָה. שְׁנֵים עָשָׂר הָאוֹרוֹת הַלָּלוּ הֵם שְׂמֵחִים לַעֲלוֹת לְמַעְלָה וּלְקַבֵּל כָּל אֵלּוּ שֶׁלְּמַטָּה.</p>\n<p>הֵיכָל זֶה שֶׁהוּא רָצוֹן, רְצוֹן הַכֹּל, מִי שֶׁקּוֹשֵׁר קְשָׁרִים וּמַעֲלֶה אוֹתָם לְכָאן, זֶהוּ שֶׁמֵּפִיק רָצוֹן מֵה' בַּחֲבִיבוּת. בְּתוֹךְ הַהֵיכָל הַזֶּה נֶאֱסַף מֹשֶׁה בְּאַהֲבָה, שֶׁנּוֹשֵׁק נְשִׁיקוֹת אַהֲבָה. זֶהוּ הַהֵיכָל שֶׁל מֹשֶׁה. רוּחַ זֶה רוּחַ הָאַהֲבָה. הָרוּחַ שֶׁל הַיִּחוּד שֶׁמַּמְשִׁיךְ אַהֲבָה לְכָל הַצְּדָדִים.</p>\n<p>וְאוֹתָם שְׁנֵים עָשָׂר אוֹרוֹת עוֹלִים וְלוֹהֲטִים. מֵהַנִּצְנוּץ שֶׁלָּהֶם יוֹצְאוֹת אַרְבַּע חַיּוֹת קְדוֹשׁוֹת אוֹהֲבֵי הָאַהֲבָה. אֵלֶּה נִקְרָאִים חַיּוֹת גְּדוֹלוֹת לְהִתְחַבֵּר אוֹתָם קְטַנּוֹת לְהִכָּלֵל בָּהֶם, שֶׁכָּתוּב (תהלים קד) חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת.</p>\n<p>אֵלּוּ אֲחוּזוֹת זוֹ בָּזוֹ לְאַרְבָּעָה צְדָדִים, כְּמוֹ אֱגוֹז שֶׁמְּחֻבָּר לְאַרְבָּעָה צְדָדִים, וְלָכֵן נִקְרָא הֵיכָל זֶה גִּנַּת אֱגוֹז, שֶׁכָּתוּב (שיר ו) אֶל גִּנַּת אֱגוֹז יָרַדְתִּי. מַה זֶּה אֶל גִּנַּת אֱגוֹז? מִשּׁוּם גִּנַּת אֱגוֹז יָרַדְתִּי, שֶׁהוּא הֵיכַל הָאַהֲבָה לְהִתְדַּבֵּק זָכָר בִּנְקֵבָה.</p>\n<p>אֵלֶּה הָאַרְבַּע נִפְרָדִים לִשְׁנֵים עָשָׂר, שָׁלֹשׁ שָׁלֹשׁ לְכָל צַד. כָּל אוֹתָם תַּחְתּוֹנִים כְּלוּלִים בָּהֶם. וּבָהֶם קַיָּמִים רוּחוֹת עִם רוּחוֹת, אוֹרוֹת עִם אוֹרוֹת. כֻּלָּם אֵלֶּה עִם אֵלֶּה עַד שֶׁנַּעֲשִׂים אֶחָד. וְאָז רוּחַ זֶה שֶׁכָּלוּל מִכֻּלָּם עוֹלֶה לְהִתְעַטֵּר (להתעורר) בָּרוּחַ שֶׁל מַעְלָה, אוֹתוֹ שֶׁנִּקְרָא שָׁמַיִם, וּמַזְמִין אוֹתוֹ לְהִתְחַבֵּר עִמּוֹ. כֵּיוָן שֶׁנִּקְשְׁרוּ כֻלָּם שֶׁלְּמַטָּה יַחַד עִמּוֹ, אָמַר (שם א) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ. וְאָז הַחֶדְוָה הִיא לְהִתְקַשֵּׁר רוּחַ בְּרוּחַ וּלְהִשְׁתַּלֵּם זֶה בָּזֶה, וְאָז הִיא הַשְּׁלֵמוּת בְּחִבּוּר אֶחָד.</p>\n<p>כֵּיוָן שֶׁרוּחַ זֶה מִתְחַבֵּר עִמּוֹ וְנִשְׁלְמוּ זֶה בָּזֶה וּמְאִירִים זֶה בָּזֶה בְּכָל הַשְּׁלֵמוּת כָּרָאוּי בְּרָצוֹן זֶה שֶׁמִּתְפַּלֵּל בֶּן אָדָם צַדִּיק שֶׁמַּעֲלֶה הַכֹּל כָּרָאוּי עַד אוֹתוֹ מָקוֹם לְחַבֵּר אַהֲבָה זֶה בָּזֶה, אָז (שמים מתחבר ברוח זה באהבה בשלמות בהארה מתדבקים זה בזה, ואז) כָּל אוֹתָם הֵיכָלוֹת וְכָל אוֹתָם רוּחוֹת שֶׁנִּכְלְלוּ בָזֶה, כָּל אֶחָד וְאֶחָד מֵאוֹתָם רוּחוֹת וְהֵיכָלוֹת שֶׁהֵם בִּכְלָל שֶׁל שָׁמַיִם, כָּל אֶחָד וְאֶחָד נוֹטֵל אוֹתוֹ הֵיכָל וְאוֹתוֹ רוּחַ שֶׁרָאוּי לוֹ לְהִתְחַבֵּר עִמּוֹ וּלְהִשְׁתַּלֵּם עִמּוֹ כָּרָאוּי.</p>\n<p>(משום שהרוח הששי הזה שנקרא שמים רוח קדוש למעלה, נוטל היכל זה, הרוח הזה שנקרא רצו\"ן מעלה אותם אליהם באותו יחוד, וכך מתחברים רצון להתנשק) (נ\"א: משום שאותו רוח ששי שנקרא רצון מעלה אותם אליהם באותו יחוד, וכך מתחברים שמים, שהוא רוח קדוש למעלה, נוטל היכל זה רוח זה שנקרא רצון להתנשק) זֶה בָּזֶה, לְהִתְחַבֵּר זֶה בָּזֶה, לְהִשְׁתַּלֵּם זֶה בָּזֶה. וְזֶה סוֹד (בראשית כט) וַיִּשַּׁק יַעֲקֹב לְרָחֵל וְגוֹ'.</p>\n<p>אַבְרָהָם שֶׁהוּא יָמִין לְמַעְלָה נוֹטֵל (ההיכל שאמרנו) (היכל אהבה) רוּחַ שֶׁנִּקְרָא אַהֲבָ\"ה לְהִתְקַשֵּׁר זֶה בָּזֶה, לְהִתְחַבֵּר זֶה בָּזֶה לִהְיוֹת אֶחָד, וְסִימָן לַדָּבָר - (שם יב) הִנֵּה נָא יָדַעְתִּי כִּי אִשָּׁה יְפַת מַרְאֶה אָתְּ. וְיֹפִי שֶׁל הָאִשָּׁה בְּאוֹתָם שָׁדַיִם.</p>\n<p>יִצְחָק שֶׁהוּא שְׂמֹאל, נָטַל אוֹתוֹ הֵיכָל (של בית דין שכל הדינים מתעוררים, משם הרוח שנקראת זכות להתחבר זה בזה ולהשתלם זה בזה להיות הכל אחד כראוי, שאר הנביאים נטלו שני היכלות (שלמטה)). שְׁנֵי רוּחוֹת נֹגַ\"הּ וְזֹהַ\"ר, בְּסוֹד הַכָּתוּב (שיר ז) חֲמוּקֵי יְרֵכַיִךְ וְגוֹ', לְהִתְקַשֵּׁר אֵלֶּה בְּאֵלֶּה לִהְיוֹת אֶחָד.</p>\n<p>יוֹסֵף הַצַּדִּיק עַמּוּד הָעוֹלָם נָטַל הֵיכָל שֶׁל סַפִּיר, הָרוּחַ שֶׁנִּקְרֵאת לִבְנַת הַסַּפִּיר, וְאַף עַל גַּב שֶׁכָּתוּב (שמות כד) וְתַחַת רַגְלָיו, בִּשְׁבִיל כְּבוֹד הַמֶּלֶךְ. וְכָךְ הוּא בְּוַדַּאי. וְאַחַר כָּךְ הָעַמּוּד הַזֶּה נָטַל יוֹתֵר, שֶׁהוּא סוֹד הַסּוֹדוֹת, בַּמָּקוֹם שֶׁל הַהֵיכָל הַשְּׁבִיעִי. עַד כָּאן מִתְחַבְּרוֹת דְּרָגוֹת וּמִתְחַבְּרִים זֶה בָּזֶה לְהִשְׁתַּלֵּם זֶה עִם זֶה לִהְיוֹת כֻּלָּם אֶחָד. הַכֹּל כָּרָאוּי. וְאָז ה' הוּא הָאֱלֹהִים וְגוֹ'. אַשְׁרֵי חֶלְקוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא מִי שֶׁיּוֹדֵעַ לְקָשְׁרָם וּלְהִדָּבֵק בְּרִבּוֹנוֹ.</p>\n<p>כָּאן הַכְרִיעָה (בהכרעה כאן ומוסיף הווי\"ן) וְהִשְׁתַּחֲוָאָה וְקִידָה וּפְרִישַׂת כַּפַּיִם וּנְפִילַת אַפַּיִם לְהַמְשִׁיךְ רְצוֹן הָרוּחַ הָעֶלְיוֹן, נִשְׁמַת כָּל הַנְּשָׁמוֹת, שֶׁתָּלוּי לְמַעְלָה עַד אֵין סוֹף, שֶׁמִּמֶּנּוּ יוֹצְאִים אוֹרוֹת וּבְרָכוֹת לְהַשְׁלִים הַכֹּל מִלְמַעְלָה כָּרָאוּי וְלִהְיוֹת הַכֹּל בִּשְׁלֵמוּת מִלְּמַטָּה וּמִלְמַעְלָה, וְכָל הַפָּנִים מְאִירוֹת בְּכָל הַצְּדָדִים כָּרָאוּי. וְאָז מִתְבַּטְּלִים כָּל גִּזְרֵי הַדִּין, וְכָל הָרָצוֹן נַעֲשֶׂה לְמַעְלָה וּלְמַטָּה. וְעַל זֶה כָּתוּב (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר. וְכָתוּב (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו.</p>"],[9522011104,"<p>הֵיכָל שְׁבִיעִי. בְּהֵיכָל זֶה אֵין בּוֹ דְּמוּת מַמָּשׁ, הַכֹּל הוּא בְּנִסְתָּר וְגוֹ' (תוך) סוֹד הַסּוֹדוֹת, הַפָּרֹכֶת שֶׁפְּרוּסָה (פרוסה), כָּל הַהֵיכָלוֹת עוֹמְדִים שֶׁלֹּא יִתְרָאוּ שְׁנֵי כְרוּבִים (ד\"א זה מזה עומדים). לִפְנִים מִזֶּה עוֹמֶדֶת כַּפֹּרֶת, דְּמוּת שֶׁל קֹדֶשׁ הַקְּדָשִׁים, וְלָכֵן הֵיכָל זֶה נִקְרָא קֹדֶשׁ הַקְּדָשִׁים. קֹדֶשׁ הַקְּדָשִׁים הַזֶּה מָקוֹם מְתֻקָּן לְאוֹתָהּ נְשָׁמָה עֶלְיוֹנָה, כְּלָל שֶׁל כָּל הָעוֹלָם הַבָּא לְגַבֵּי (עולם) הָעֶלְיוֹנִים הַלָּלוּ.</p>\n<p>שֶׁהֲרֵי כְּשֶׁמִּתְחַבְּרִים כָּל הָרוּחוֹת זֶה בָּזֶה וְנִשְׁלָמִים זֶה בָּזֶה כָּרָאוּי, אָז מִתְעוֹרֵר רוּחַ עֶלְיוֹן נִשְׁמַת הַכֹּל כְּלַפֵּי מַעְלָה נִסְתַּר כָּל הַנִּסְתָּרִים, לְהִתְעוֹרֵר עַל הַכֹּל וּלְהָאִיר לָהֶם מִלְמַעְלָה לְמַטָּה, וּלְהַשְׁלִים אוֹתָם לְהַדְלִיק נֵרוֹת.</p>\n<p>וּכְשֶׁהַכֹּל (נ\"א: הוא) בִּשְׁלֵמוּת בָּאוֹר שֶׁל הַכֹּל וְיוֹרֵד אוֹר עֶלְיוֹן, אָז הַהֵיכָל הַשְּׁבִיעִי הַזֶּה הוּא הֵיכָל נִסְתָּר בְּסֵתֶר הַכֹּל, לְקַבֵּל אֶת אוֹתוֹ קֹדֶשׁ הַקְּדָשִׁים אוֹר שֶׁיּוֹרֵד, וּלְהִתְמַלֵּא מִשָּׁם כְּמוֹ נְקֵבָה שֶׁמִּתְעַבֶּרֶת מִן הַזָּכָר וּמִתְמַלֵּאת, וְלֹא מִתְמַלֵּאת אֶלָּא מֵהֵיכָל זֶה שֶׁמְּתֻקָּן לְקַבֵּל אוֹתוֹ אוֹר עֶלְיוֹן. וְזֶה סוֹד הַהֵיכָל הַשְּׁבִיעִי, הוּא מָקוֹם שֶׁל חִבּוּר הַזִּוּוּג לְהִתְחַבֵּר שְׁבִיעִי בִּשְׁבִיעִי, לִהְיוֹת הַכֹּל אֶחָד שְׁלֵמוּת (אחת) כָּרָאוּי.</p>\n<p>וּמִי שֶׁיּוֹדֵעַ לִקְשֹׁר יִחוּד זֶה - אַשְׁרֵי חֶלְקוֹ, אָהוּב לְמַעְלָה וְאָהוּב לְמַטָּה, הַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹזֵר וְהוּא מְבַטֵּל. הֲיַעֲלֶה עַל דַּעְתְּךְ שֶׁהוּא מְקַטְרֵג בְּרִבּוֹנוֹ? לֹא כָּךְ! אֶלָּא מִשּׁוּם שֶׁכְּשֶׁהוּא קוֹשֵׁר קְשָׁרִים וְיוֹדֵעַ לְיַחֵד יִחוּד וְכָל הַפָּנִים מְאִירוֹת, וְכָל הַשְּׁלֵמוּת נִמְצֵאת, וְהַכֹּל מִתְבָּרֵךְ כָּרָאוּי, כָּל הַדִּינִים מִסְתַּלְּקִים וּמִתְבַּטְּלִים וְלֹא נִמְצָא דִין בָּעוֹלָם. אַשְׁרֵי חֶלְקוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. זֶהוּ לְמַטָּה, שֶׁכָּתוּב בּוֹ (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. זֶהוּ קִיּוּם הָעוֹלָם. בְּכָל יוֹם קוֹרֵא עָלָיו הַכָּרוֹז, (ישעיה מא) וְאַתָּה תָּגִיל בַּה' בִּקְדוֹשׁ יִשְׂרָאֵל תִּתְהַלָּל.</p>\n<p>כְּמוֹ זֶה קָרְבָּן (זה) עוֹלֶה עָשָׁן, וּמִסְתַּפְּקִים (בו) כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, וְכֹהֲנִים בְּרָצוֹן, וּלְוִיִּם בִּנְעִימוּת הַשִּׁירָה. זֶה נִכְלָל בָּזֶה, וְנִכְנָסִים הֵיכָל בְּהֵיכָל, רוּחַ בְּרוּחַ, עַד שֶׁמִּתְחַבְּרִים בִּמְקוֹמָם כָּרָאוּי לוֹ אֵיבָר בְּאֵיבָר וּמִשְׁתַּלְּמִים זֶה בָּזֶה, וּמִתְיַחֲדִים זֶה בָּזֶה, עַד שֶׁהֵם אֶחָד (ונאורים) וּמְאִירִים זֶה בָּזֶה.</p>\n<p>אָז הַנְּשָׁמָה הָעֶלְיוֹנָה שֶׁל הַכֹּל בָּאָה מִלְמַעְלָה וּמְאִירָה לָהֶם, וְכָל הַנֵּרוֹת מְאִירִים בִּשְׁלֵמוּת כָּרָאוּי, עַד שֶׁאוֹתוֹ אוֹר עֶלְיוֹן מִתְעוֹרֵר, וְהַכֹּל נִכְנָס אֶל קֹדֶשׁ הַקְּדָשִׁים, וּמִתְבָּרֵךְ וּמִתְמַלֵּא כִּבְאֵר שֶׁל מַיִם נוֹבְעִים וְלֹא פוֹסְקִים, וְכֻלָּם מִתְבָּרְכִים לְמַעְלָה וּלְמַטָּה.</p>\n<p>כָּאן סוֹד הַסּוֹדוֹת אוֹתוֹ שֶׁלֹּא נוֹדָע וְלֹא נִכְנָס בְּחֶשְׁבּוֹן, רָצוֹן שֶׁלֹּא נִתְפָּס לְעוֹלָמִים מַמְתִּיק לִפְנַי וְלִפְנִים בְּתוֹכָם. וְלֹא נוֹדָע אוֹתוֹ רָצוֹן וְלֹא נִתְפָּס לַדַּעַת (לנו). וְאָז הַכֹּל רָצוֹן אֶחָד עַד אֵין סוֹף, וְהַכֹּל הוּא בִּשְׁלֵמוּת מִלְּמַטָּה וּמִלְמַעְלָה וּמִלִּפְנַי וְלִפְנִים, עַד שֶׁנַּעֲשֶׂה הַכֹּל אֶחָד.</p>\n<p>הָרָצוֹן הַזֶּה לֹא נִכְנָס פְּנִימָה, אַף עַל גַּב שֶׁלֹּא נוֹדָע, עַד שֶׁהַכֹּל נִשְׁלָם וּמֵאִיר בַּהַתְחָלָה בְּכָל הַצְּדָדִים. אָז מַמְתִּיק אוֹתוֹ רָצוֹן (לכל) וְלֹא (שלא) נִתְפָּס לִפְנַי וְלִפְנִים בְּנִסְתָּר. וְאָז אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁנִּדְבָּק בְּרִבּוֹנוֹ בְּאוֹתָהּ שָׁעָה, אַשְׁרָיו לְמַעְלָה וְאַשְׁרָיו לְמַטָּה, עָלָיו כָּתוּב (משלי כג) יִשְׂמַח אָבִיךְ וְאִמֶּךְ וְתָגֵל יוֹלַדְתֶּךְ.</p>\n<p>בֹּא רְאֵה, כֵּיוָן שֶׁכֻּלָּם נִתְקְנוּ זֶה בָּזֶה וְנִקְשְׁרוּ זֶה בָּזֶה בְּקֶשֶׁר אֶחָד, וְהַנְּשָׁמָה הָעֶלְיוֹנָה מְאִירָה לָהֶם מִצַּד שֶׁל מַעְלָה, וְכָל הָאוֹרוֹת הֵם נֵר אֶחָד בִּשְׁלֵמוּת, אָז רָצוֹן אֶחָד שֶׁל הַמַּחֲשָׁבָה (במחשבה) נִתְפָּס (ד\"א לפני ולפנים, שאור שעולה על הכל ובפני לפנים באותו רצון נתפס במחשבה) אוֹר שֶׁלֹּא נִתְפָּס וְלֹא נוֹדָע, פְּרָט לְאוֹתוֹ רָצוֹן שֶׁהַמַּחֲשָׁבָה תּוֹפֶסֶת וְלֹא יוֹדַעַת מַה תּוֹפֶסֶת, אֶלָּא שֶׁמֵּאִיר וּמִתְמַתֵּק אוֹתוֹ רְצוֹן הַמַּחֲשָׁבָה. וְהַכֹּל מִתְמַלֵּא וְהַכֹּל נִשְׁלָם וּמֵאִיר וּמִתְבַּשֵּׂם הַכֹּל כָּרָאוּי. וְעַל זֶה כָּתוּב (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ וְגוֹ'.</p>\n<p>מִי שֶׁזּוֹכֶה לְהִדָּבֵק בְּרִבּוֹנוֹ כְּמוֹ זֶה, יוֹרֵשׁ אֶת כָּל הָעוֹלָמוֹת. אָהוּב לְמַעְלָה וְאָהוּב לְמַטָּה. תְּפִלָּתוֹ לֹא חוֹזֶרֶת רֵיקָם. זֶה מִתְחַטֵּא לִפְנֵי רִבּוֹנוֹ כְּמוֹ בֵּן לִפְנֵי אָבִיו וְעוֹשֶׂה לוֹ רָצוֹן בְּכָל מַה שֶּׁצָּרִיךְ, וְאֵימָתוֹ שׁוֹלֶטֶת עַל כָּל הַבְּרִיּוֹת. הוּא גוֹזֵר וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְקַיֵּם. עָלָיו כָּתוּב (איוב כב) וְתִגְזַר אֹמֶר וְיָקָם לָךְ וְעַל דְּרָכֶיךְ נָגַהּ אוֹר.</p>\n<p>וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר וְגוֹ'. אָמַר רַבִּי יִצְחָק, מִכָּאן שֶׁעָקַר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַנְּטִיעוֹת הַלָּלוּ (ושתל אותם, ממשמע שכתוב יהי, רבי יהודה אומר, אור שכבר היה שנינו, ממשמע שכתוב ויהי אור, לא כתוב והיה אלא ויהי, וכשהסתכל הקדוש ברוך הוא באותם דורות של רשעים, גנזו לצדיקים, זהו שכתוב (תהלים צו) אור זרע לצדיק ולישרי לב שמחה, והרי נאמר ויאמר אלהים יהי אור, זהו שכתוב (ישעיה מא) מי העיר ממזרח וגו',</p>\n<p>(וירא אלהים את האור כי טוב, מה ראה? אמר רבי חייא כפי שאמרנו, ראה במעשי הרשעים וגנז אותו, רבי אבא אמר, וירא אלהים את האור כי טוב לגנז אותו, וירא אלהים את האור), (נ\"א: ושתל אותם, שכתוב ויהי אור, מה משמיע אור? שכבר היה אור, רבי יהודה אומר, אור לא נאמר אלא ויהי, לומר שכבר היה, וכתוב אור זרע לצדיק וגו', וזהו שכתוב מי העיר ממזרח וגו', וירא אלהים את האור ויבדל, אמר רבי יצחק כמו שאמרנו, שראה במעשי הרשעים וגנז אותו, רבי אבא אמר ראה) שסלק אורו מסוף העולם ועד סוף העולם, וכי טוב הוא לגנזו כדי שלא יהנו ממנו רשעי העולם.)</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, שֶׁלֹּא יִמָּצֵא בּוֹ רִתְחָה. כָּתוּב כָּאן כִּי טוֹב, וְכָתוּב שָׁם (במדבר כד) כִּי טוֹב בְּעֵינֵי ה' לְבָרֵךְ אֶת יִשְׂרָאֵל, וְסוֹף הַפָּסוּק (מוכיח) - וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ. וְלָכֵן לֹא נִמְצְאָה בּוֹ רִתְחָה, וְאַף עַל גַּב שֶׁשִּׁתֵּף אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא כְּאֶחָד.</p>\n<p>בֹּא רְאֵה, הָאוֹר עֶלְיוֹן לִהְיוֹת מֵאִיר הָאוֹר הַזֶּה, וּמֵאוֹתוֹ אוֹר שִׂמְחָה לַכֹּל בּוֹ. וְהוּא יָמִין לְהִתְעַטֵּר חֲקִיקוֹתָיו (חקוקיו) חֲקוּקִים יַחַד אִתּוֹ, וַהֲרֵי נֶאֱמַר. כָּתוּב (תהלים לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ פָּעַלְתָּ לַחוֹסִים בָּךְ. מָה רַב טוּבְךְ - זֶה אוֹר רִאשׁוֹן שֶׁגָּנַז הַקָּדוֹשׁ בָּרוּךְ הוּא. לִּירֵאֶיךְ - לַצַּדִּיקִים, שֶׁהֵם יִרְאֵי חֵטְא כְּמוֹ שֶׁאָמַרְנוּ.</p>"],[9522011105,"<p>וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם אֶחָד. וַיְהִי עֶרֶב - מִצַּד הַחֹשֶׁךְ. וַיְהִי בֹקֶר - מִצַּד הָאוֹר. וּמִתּוֹךְ שֶׁהֵם מִשְׁתַּתְּפִים כְּאֶחָד, כָּתוּב יוֹם אֶחָד. רַבִּי יְהוּדָה אָמַר, מָה הַטַּעַם בְּכָל יוֹם וָיוֹם כָּתוּב וַיְהִי עֶרֶב וַיְהִי בֹקֶר? לָדַעַת שֶׁהֲרֵי אֵין יוֹם בְּלִי לַיְלָה וְאֵין לַיְלָה בְּלִי יוֹם, וְלֹא צְרִיכִים לְהִפָּרֵד.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אוֹתוֹ הַיּוֹם שֶׁיָּצָא אוֹר רִאשׁוֹן, הִתְפַּשֵּׁט בְּכָל הַיָּמִים, שֶׁכָּתוּב בְּכֻלָּם יוֹם. אָמַר רַבִּי אֶלְעָזָר, מַשְׁמָע שֶׁכָּתוּב בְּכֻלָּם בּקֶר, וְאֵין בֹּקֶר אֶלָּא מִצַּד שֶׁל אוֹר רִאשׁוֹן. רַבִּי שִׁמְעוֹן אָמַר, יוֹם רִאשׁוֹן הוֹלֵךְ עִם כֻּלָּם, וְכֻלָּם בּוֹ, כְּדֵי לְהַרְאוֹת שֶׁאֵין בָּהֶם פֵּרוּד וְהַכֹּל אֶחָד.</p>\n<p>וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר, תִּהְיֶה הִתְפַּשְּׁטוּת הָאוֹר הַזֶּה לְמַטָּה, וְאֵלֶּה הֵם הַמַּלְאָכִים שֶׁנִּבְרְאוּ בַּיּוֹם הָרִאשׁוֹן, יֵשׁ לָהֶם קִיּוּם לְהִתְקַיֵּם לְצַד יָמִין. וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, אֶת - לִכְלֹל אֶת הָאַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה עִם אַסְפַּקְלַרְיָה מְאִירָה, שֶׁנֶּאֱמַר (בו) כִּי טוֹב. אָמַר רַבִּי אֶלְעָזָר, אֶת - לִכְלֹל (להכליל) וּלְרַבּוֹת אֶת כָּל הַמַּלְאָכִים שֶׁבָּאִים מִצַּד הָאוֹר הַזֶּה, וְכֻלָּם מְאִירִים כְּבַתְּחִלָּה בְּקִיּוּם שָׁלֵם.</p>\n<p>יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם. אָמַר רַבִּי יְהוּדָה, בָּזֶה נִפְרְדוּ מַיִם עֶלְיוֹנִים מִמַּיִם תַּחְתּוֹנִים. רָקִיעַ - הִתְפַּשְּׁטוּת הַמַּיִם, וַהֲרֵי נֶאֱמַר. וִיהִי מַבְדִּיל - בֵּין מַיִם עֶלְיוֹנִים לַתַּחְתּוֹנִים.</p>\n<p>וַיַּעַשׂ אֱלֹהִים אֶת הָרָקִיעַ - בְּמַעֲלָה עֶלְיוֹנָה. וַיְהִי רָקִיעַ לֹא כָתוּב, אֶלָּא וַיַּעַשׂ, שֶׁהִגְדִּיל אוֹתוֹ בְּגַדְלוּת רַבָּה.</p>\n<p>אָמַר רַבִּי יִצְחָק, בַּשֵּׁנִי נִבְרָא גֵיהִנֹּם לְרִשְׁעֵי הָעוֹלָם. בַּשֵּׁנִי נִבְרְאָה מַחֲלֹקֶת. בַּשֵּׁנִי לֹא נִשְׁלַם בּוֹ הַמַּעֲשֶׂה, וְלָכֵן לֹא כָתוּב בּוֹ כִּי טוֹב, עַד שֶׁבָּא יוֹם שְׁלִישִׁי וְנִשְׁלַם בּוֹ הַמַּעֲשֶׂה. מִשּׁוּם כָּךְ כִּי טוֹב פַּעֲמַיִם, אֶחָד עַל הַשְׁלָמַת הַמַּעֲשֶׂה שֶׁל יוֹם שֵׁנִי, וְאֶחָד לְעַצְמוֹ. בַּיּוֹם הַשְּׁלִישִׁי הִתְתַּקֵּן הַיּוֹם הַשֵּׁנִי וְנִבְדְּלָה בוֹ מַחֲלֹקֶת, וּבוֹ הִשְׁתַּלְּמוּ רַחֲמִים עַל רִשְׁעֵי הַגֵּיהִנֹּם. בַּיּוֹם הַשְּׁלִישִׁי מִשְׁתַּכְּכִים שַׁלְהֲבוֹת הַגֵּיהִנֹּם. מִשּׁוּם כָּךְ נִכְלַל בּוֹ שֵׁנִי וְנִשְׁלַם בּוֹ.</p>\n<p>רַבִּי חִיָּיא הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ, אוֹר זֶה בְּיוֹם רִאשׁוֹן, וְחֹשֶׁךְ בְּיוֹם שֵׁנִי, וְנִפְרְדוּ הַמַּיִם וּמַחֲלֹקֶת הָיְתָה בּוֹ, לָמָּה לֹא נִשְׁלַם בַּיּוֹם הָרִאשׁוֹן, שֶׁהֲרֵי יָמִין כּוֹלֵל אֶת הַשְּׂמֹאל? אָמַר לוֹ, עַל זֶה הָיְתָה מַחֲלֹקֶת, וּשְׁלִישִׁי רָצָה לְהִכָּנֵס בֵּינֵיהֶם לְהַכְרִיעַ וּלְהַרְבּוֹת בָּהֶם שָׁלוֹם.</p>"],[9522011106,"<p>תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא - הִתְחַבְּרוּת שֶׁל מַיִם עֶלְיוֹנִים בַּתַּחְתּוֹנִים לַעֲשׂוֹת פֵּרוֹת. מַיִם עֶלְיוֹנִים (ד\"א פרים ורבים) וְעוֹשִׂים פֵּרוֹת, וְהַתַּחְתּוֹנִים קוֹרְאִים לָהֶם לָעֶלְיוֹנִים כִּנְקֵבָה לַזָּכָר, מִשּׁוּם שֶׁמַּיִם עֶלְיוֹנִים זְכָרִיִּים, וְתַחְתּוֹנִים נְקֵבִיִּים.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, כָּל זֶה הוּא לְמַעְלָה וְהוּא לְמַטָּה. אָמַר רַבִּי יוֹסֵי, אִם כָּךְ, אֱלֹהִים שֶׁאָמַרְנוּ (ד\"א אמר) מִי הָאֱלֹהִים? (ד\"א אלא אלהים סתם) אֱלֹהִים חַיִּים לְמַעְלָה. וְאִם תֹּאמַר אֱלֹהִים לְמַטָּה סְתָם, אֶלָּא לְמַטָּה הוּא תוֹלָדוֹת, כְּמוֹ שֶׁנֶּאֱמַר אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. וְאָמַרְנוּ בְּה' בְּרָאָם. וְאוֹתוֹ (שלמעלה) לְמַעְלָה אֲבִיהֶם שֶׁל הַכֹּל הוּא, הִיא הָעֲשִׂיָּה, וְעַל זֶה הָאָרֶץ עוֹשָׂה תוֹלָדוֹת, שֶׁהֲרֵי הִיא מִתְעַבֶּרֶת כִּנְקֵבָה מִן הַזָּכָר.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, כָּל הַצְּבָאוֹת הָיוּ בָּאָרֶץ, וְלֹא הוֹצִיאָה אֶת כֹּחָהּ, וְהֵם תּוֹלְדוֹתֶיהָ, עַד יוֹם (חמישי) הַשִּׁשִּׁי, שֶׁכָּתוּב תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה. וְאִם תֹּאמַר, וַהֲרֵי כָּתוּב וַתּוֹצֵא הָאָרֶץ דֶּשֶׁא אֶלָּא? הוֹצִיאָה תִקּוּן כֹּחוֹתֶיהָ כְּדֵי לְהִתְיַשֵּׁב כָּרָאוּי, וְהַכֹּל הָיָה גָנוּז בָּהּ עַד שֶׁהִצְטָרֵךְ. שֶׁהֲרֵי בַּהַתְחָלָה כָּתוּב שׁוֹמֵמָה וְרֵיקָה כְּתַרְגּוּמוֹ, אַחַר כָּךְ נִתְקְנָה וְהִתְיַשְּׁבָה וְקִבְּלָה זֶרַע וּדְשָׁאִים וַעֲשָׂבִים וְאִילָנוֹת כָּרָאוּי, וְהוֹצִיאָה אוֹתָם אַחַר כָּךְ. וְהַמְּאוֹרוֹת גַּם כֵּן לֹא שִׁמְּשׁוּ אוֹרוֹת שֶׁלָּהֶם עַד שֶׁהִצְטָרֵךְ.</p>"],[9522011107,"<p>יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם (מארת כתוב חסר), לְהַכְלִיל נָחָשׁ הָרָע שֶׁהִטִּיל זֻהֲמָה וְעָשָׂה פֵרוּד שֶׁהַשֶּׁמֶשׁ לֹא מְשַׁמֵּשׁ עִם לְבָנָה. מְאֹרֹת - קְלָלוֹת. וְעַל זֶה גָּרַם שֶׁהִתְקַלְּלָה הָאָרֶץ, שֶׁכָּתוּב אֲרוּרָה הָאֲדָמָה. וְלָכֵן מְאֹרֹת כָּתוּב אֶחָד.</p>\n<p>יְהִי מְאֹרֹת - זוֹ הַלְּבָנָה. רְקִיעַ הַשָּׁמַיִם - זוֹ הַשֶּׁמֶשׁ. וּשְׁנֵיהֶם בִּכְלָל אֶחָד לְהִזְדַּוֵּג לְהָאִיר הָעוֹלָמוֹת לְמַעְלָה וּלְמַטָּה. מִמַּשְׁמָע שֶׁכָּתוּב עַל הָאָרֶץ וְלֹא כָתוּב בָּאָרֶץ, שֶׁמַּשְׁמָע לְמַעְלָה וּלְמַטָּה, חֶשְׁבּוֹן שֶׁל הַכֹּל בַּלְּבָנָה הוּא.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, גִּימַטְרִיָּאוֹת וְחֶשְׁבּוֹן תְּקוּפוֹת וְעִבּוּרִים - הַכֹּל הוּא בַּלְּבָנָה, שֶׁהֲרֵי לְמַעְלָה אֵינוֹ. אָמַר לוֹ רַבִּי אֶלְעָזָר, וָלֹא!? וַהֲרֵי כַּמָּה חֶשְׁבּוֹנוֹת וְשִׁעוּרִים עוֹשִׂים הַחֲבֵרִים? אָמַר לוֹ, לֹא כָּךְ! אֶלָּא הַחֶשְׁבּוֹן עוֹמֵד בַּלְּבָנָה, וּמִשָּׁם יִכָּנֵס הָאָדָם לָדַעַת לְמַעְלָה. אָמַר לוֹ, וַהֲרֵי כָּתוּב וְהָיוּ לְאֹתֹת וּלְמוֹעֲדִים? אָמַר לוֹ, לְאֹתֹת כָּתוּב חָסֵר. אָמַר לוֹ, הֲרֵי כָּתוּב וְהָיוּ? אָמַר לוֹ, הֲוָיוֹת כֻּלָּם שֶׁיִּהְיוּ בוֹ, כְּאוֹצָר זוֹ שֶׁמִּתְמַלֵּא מֵהַכֹּל. אֲבָל הַחֶשְׁבּוֹן שֶׁל הַכֹּל הוּא בַּלְּבָנָה.</p>\n<p>בֹּא רְאֵה, יֵשׁ נְקֻדָּה אַחַת וּמִשָּׁם הָרֵאשִׁית לִמְנוֹת, שֶׁהֲרֵי מַה שֶּׁלִּפְנִים שֶׁל אוֹתָהּ נְקֻדָּה לֹא נוֹדָע וְלֹא נִתָּן לִמְנוֹת, וְיֵשׁ נְקֻדָּה לְמַעְלָה נִסְתֶּרֶת שֶׁלֹּא הִתְגַּלְּתָה כְּלָל וְלֹא נוֹדְעָה, וּמִשָּׁם הָרֵאשִׁית לִמְנוֹת כָּל נִסְתָּר וְעֹמֶק. כָּךְ גַּם יֵשׁ נְקֻדָּה לְמַטָּה שֶׁהִתְגַּלְּתָה, וּמִשָּׁם הוּא רֵאשִׁית לְכָל חֶשְׁבּוֹן וּלְכָל מִנְיָן, וְעַל זֶה כָּאן הוּא הַמָּקוֹם לְכָל הַתְּקוּפוֹת וְהַגִּימַטְרִיָּאוֹת וְהָעִבּוּרִים וְהַזְּמַנִּים וְחַגִּים וְשַׁבָּתוֹת. וְיִשְׂרָאֵל שֶׁדְּבֵקִים בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, עוֹשִׂים חֶשְׁבּוֹן לַלְּבָנָה, וְהֵם דְּבֵקִים בּוֹ וּמַעֲלִים אוֹתוֹ לְמַעְלָה, שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם וְגוֹ'.</p>\n<p>יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה. אָמַר רַבִּי אֶלְעָזָר, הֲרֵי פֵּרְשׁוּהָ שֶׁאוֹתָם מַיִם רָחֲשׁוּ וְהוֹלִידוּ כְּמוֹ שֶׁלְּמַעְלָה, וַהֲרֵי נֶאֱמַר. וְעוֹף יְעוֹפֵף עַל הָאָרֶץ - יָעוּף צָרִיךְ לִכְתֹּב, מַה זֶה יְעוֹפֵף?</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, סוֹד הוּא, וְעוֹף זֶה מִיכָאֵ\"ל, שֶׁכָּתוּב (ישעיה ו) וַיָּעָף אֵלַי אֶחָד מִן הַשְּׂרָפִים. יְעוֹפֵף - (ד\"א יעוף צריך לו, אלא) זֶה גַבְרִיאֵ\"ל, שֶׁכָּתוּב (דניאל ט) וְהָאִישׁ גַּבְרִיאֵל אֲשֶׁר רָאִיתִי בֶחָזוֹן בַּתְּחִלָּה מֻעָף בִּיעָף. (ד\"א וזהו יעופף). עַל הָאָרֶץ - (זה אליהו שנמצא תמיד בארץ ולא מצד של אבא ואמא הוא, נמצא שהוא (טס את העולם) בארבע טיסות, שכתוב ורוח ה' ישאך על אשר לא אדע, ורוח ה' אחת, ישאך שתים, על אשר שלש, לא אדע ארבע, על פני זה מלאך המות) שֶׁהוּא (מחשיך הארץ, על פני מחשיך פני העולם, וכתוב בו וחשך על פני תהום,) רְקִיעַ הַשָּׁמָיִם - כְּמוֹ שֶׁאָמַרְנוּ עוֹלֶה וּמַסְטִין וְכוּ'.</p>\n<p>אָמַר רַבִּי אַבָּא, וַהֲרֵי מַלְאַךְ הַמָּוֶת בַּשֵּׁנִי נִבְרָא? אֶלָּא עַל הָאָרֶץ זֶה רְפָאֵ\"ל, שֶׁהוּא מְמֻנֶּה עַל רְפוּאַת הָאָרֶץ, שֶׁבִּגְלָלוֹ נִרְפֵּאת הָאָרֶץ, וְקַיָּם בֶּן אָדָם עָלֶיהָ וּמְרַפֵּא לְכָל כֹּחוֹ. עַל פְּנֵי רְקִיעַ הַשָּׁמָיִם - זֶה אוֹרִיאֵ\"ל. וְהַכֹּל הוּא בַּפָּסוּק.</p>\n<p>וְלָכֵן כָּתוּב אַחֲרָיו וַיִּבְרָא אֱלֹהִים אֶת הַתַּנִּינִם הַגְּדלִים. אָמַר רַבִּי אֶלְעָזָר (ד\"א הרי בארנו אלו, לויתן ובת זוגו) אֵלֶּה הֵם שִׁבְעִים מְמֻנִּים גְּדוֹלִים עַל שִׁבְעִים הָעַמִּים, וְלָכֵן נִבְרְאוּ כֻלָּם לִהְיוֹת שׁוֹלְטִים עַל הָאָרֶץ.</p>\n<p>וְאֵת כָּל נֶפֶשׁ הַחַיָּה הָרֹמֶשֶׂת - אֵלֶּה הֵם יִשְׂרָאֵל שֶׁהֵם נֶפֶשׁ וַדַּאי שֶׁל אוֹתָהּ חַיָּה, וְנִקְרָאִים גּוֹי אֶחָד בָּאָרֶץ. אֲשֶׁר שָׁרְצוּ הַמַּיִם לְמִינֵהֶם - שֶׁהֵם מִשְׁתַּדְּלִים בַּתּוֹרָה. וְאֵת כָּל עוֹף כָּנָף לְמִינֵהוּ - אֵלֶּה הַצַּדִּיקִים שֶׁבָּהֶם, וְלָכֵן הֵם נֶפֶשׁ חַיָּה. דָּבָר אַחֵר, וְאֵת כָּל עוֹף כָּנָף - כְּמוֹ שֶׁנֶּאֱמַר, אֵלֶּה הֵם שְׁלוּחֵי הָעוֹלָם.</p>\n<p>אָמַר רַבִּי אַבָּא, נֶפֶשׁ חַיָּה שֶׁהֵם (הם) יִשְׂרָאֵל, מִשּׁוּם שֶׁהֵם בְּנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא (ד\"א בנים לקדוש ברוךהוא) וּנְשָׁמוֹת הַקְּדוֹשׁוֹת שֶׁלָּהֶם בָּאוֹת מִמֶּנּוּ. נַפְשׁוֹת שְׁאָר הָעַמִּים עוֹבְדֵי עַכּוּ\"ם מֵאֵיזֶה מָקוֹם הֵם? אָמַר רַבִּי אֶלְעָזָר, מֵאוֹתָם צִדְדֵי הַשְּׂמֹאל שֶׁמְּטַמְּאִים אוֹתָם יֵשׁ לָהֶם נְשָׁמוֹת, וְלָכֵן כֻּלָּם טְמֵאִים וּמְטַמְּאִים מִי שֶׁקָּרֵב עִמָּם.</p>\n<p>וַיֹּאמֶר אֱלֹהִים תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה וְגוֹ' - כָּל שְׁאָר הַחַיּוֹת הָאֲחֵרוֹת כָּל אַחַת וְאַחַת כְּפִי מִינָהּ. וְאָמַר רַבִּי אֶלְעָזָר, זֶה מְסַיֵּעַ לְמַה שֶּׁאָמַרְנוּ שֶׁנֶּפֶשׁ חַיָּה אֵלּוּ יִשְׂרָאֵל, שֶׁהֵם נֶפֶשׁ חַיָּה קְדוֹשָׁה עֶלְיוֹנָה. בְּהֵמָה וָרֶמֶשׂ וְחַיְתוֹ אֶרֶץ - אֵלּוּ שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁאֵינָם נֶפֶשׁ חַיָּה, אֶלָּא (ד\"א ערלה) כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>נַעָשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ - שֶׁנִּכְלָל בְּשִׁשָּׁה צְדָדִים כָּלוּל מֵהַכֹּל כְּמוֹ שֶׁלְּמַעְלָה, בְּאֵיבָרִים מְתֻקָּנִים בְּסוֹד הַחָכְמָה כָּרָאוּי, הַכֹּל תִּקּוּן עֶלְיוֹן. נַעֲשֶׂה אָדָם - סוֹד שֶׁל זָכָר וּנְקֵבָה, הַכֹּל בְּחָכְמָה קְדוֹשָׁה עֶלְיוֹנָה. בְּצַלְמֵנוּ כִּדְמוּתֵנוּ - לְהִתְתַּקֵּן זֶה בָּזֶה לִהְיוֹת (אחד) הוּא יְחִידִי בָּעוֹלָם שַׁלִּיט עַל הַכֹּל.</p>"],[9522011108,"<p>וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה (ד\"א כלל) וְהִנֵּה טוֹב מְאֹד - כָּאן נִתְקַן מַה שֶּׁלֹּא נֶאֱמַר כִּי טוֹב בַּשֵּׁנִי, מִשּׁוּם שֶׁבּוֹ נִבְרָא הַמָּוֶת. וְכָאן נֶאֱמַר וְהִנֵּה טוֹב מְאֹד, וְהוֹלְכִים כְּמוֹ שֶׁאָמְרוּ הַחֲבֵרִים, וְהִנֵּה טוֹב מְאֹד - זֶה הַמָּוֶת.</p>\n<p>וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד, וְכִי לֹא רָאָה אוֹתוֹ קֹדֶם? אֶלָּא הַכֹּל רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמַה שֶּׁאָמַר אֶת כָּל - לְרַבּוֹת כָּל הַדּוֹרוֹת שֶׁיָּבוֹאוּ אַחַר כָּךְ, וְכֵן כָּל מַה שֶּׁיִּתְחַדֵּשׁ בָּעוֹלָם בְּכָל דּוֹר וָדוֹר בְּטֶרֶם שֶׁיָּבוֹאוּ לָעוֹלָם. אֲשֶׁר עָשָׂה - זֶה כָּל מַעֲשֵׂי בְרֵאשִׁית שֶׁשָּׁם נִבְרָא יְסוֹד וְעִקָּר לְכָל מַה שֶּׁיָּבֹא וְיִתְחַדֵּשׁ בָּעוֹלָם לְאַחַר מִכֵּן. וּמִשּׁוּם כָּךְ רָאָה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁלֹּא הָיָה, וְשָׂם אֶת הַכֹּל בְּמַעֲשֵׂה בְרֵאשִׁית.</p>\n<p>יוֹם הַשִּׁשִּׁי - מַה שּׁוֹנֶה בְּכָל הַיָּמִים שֶׁלֹּא נֶאֱמַר בָּהֶם הֵ\"א? אֶלָּא כָּאן כַּאֲשֶׁר נִתְקַן הָעוֹלָם, הִתְחַבְּרָה הַנְּקֵבָה בַּזָּכָר בְּחִבּוּר אֶחָד. ה' בַּשִּׁשִּׁי (שהוא) (יסוד) לִהְיוֹת הַכֹּל אֶחָד. וַיְכֻלּוּ - נִתְקְנוּ הַכֹּל אֶחָד (כאחד). נִתְקְנוּ מֵהַכֹּל וְהִשְׁתַּלְּמוּ בַּכֹּל.</p>"],[9522011109,"<p>וַיְכֻלּוּ הַשָּׁמַיִם וְהָאָרֶץ וְכָל צְבָאָם. רַבִּי אֶלְעָזָר פָּתַח, (תהלים לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ פָּעַלְתָּ לַחוֹסִים בָּךְ נֶגֶד בְּנֵי אָדָם. בּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אָדָם בָּעוֹלָם וְהִתְקִין אוֹתוֹ לִהְיוֹת שָׁלֵם בַּעֲבוֹדָתוֹ וּלְתַקֵּן אֶת דְּרָכָיו כְּדֵי שֶׁיִּזְכֶּה לָאוֹר הָעֶלְיוֹן שֶׁגָּנַז הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיקִים, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ.</p>\n<p>וּבַמֶּה יִזְכֶּה הָאָדָם לְאוֹתוֹ הָאוֹר? בַּתּוֹרָה. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה בְּכָל יוֹם, יִזְכֶּה לִהְיוֹת לוֹ חֵלֶק בָּעוֹלָם הַבָּא, וְיֵחָשֵׁב לוֹ כְּאִלּוּ בָּנָה עוֹלָמוֹת, שֶׁהֲרֵי בַּתּוֹרָה נִבְנָה הָעוֹלָם וְנִתְקַן. זֶהוּ שֶׁכָּתוּב (משלי ג) ה' בְּחָכְמָה יָסַד אֶרֶץ כּוֹנֵן שָׁמַיִם בִּתְבוּנָה, וְכָתוּב (שם ח) וָאֶהְיֶה אֶצְלוֹ אָמוֹן וָאֶהְיֶה שַׁעֲשׁוּעִים יוֹם יוֹם. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בָּהּ, מְתַקֵּן עוֹלָמוֹת וּמְקַיֵּם אוֹתָם. וּבֹא וּרְאֵה, בָּרוּחַ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם וּבָרוּחַ הוּא עוֹמֵד, רוּחַ שֶׁל אֵלּוּ שֶׁעוֹסְקִים בַּתּוֹרָה, וְכָל שֶׁכֵּן רוּחַ שֶׁל הֶבֶל תִּינוֹקוֹת שֶׁל בֵּית רַבָּן.</p>\n<p>מָה רַב טוּבְךְ - זֶה הַטּוּב שֶׁנִּגְנַז. לִּירֵאֶיךְ - לְאוֹתָם יִרְאֵי חֵטְא. פָּעַלְתָּ לַחוֹסִים בָּךְ - מַה זֶּה פָּעַלְתָּ? זֶה מַעֲשֵׂה בְרֵאשִׁית. רַבִּי אַבָּא אָמַר, זֶה גַּן עֵדֶן, שֶׁהֲרֵי בְּאֻמָּנוּת עָשָׂה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ כְּמוֹ שֶׁלְּמַעְלָה, לְחַזֵּק בּוֹ אֶת הַצַּדִּיקִים. זֶהוּ שֶׁכָּתוּב (תהלים לא) פָּעַלְתָּ לַחוֹסִים בָּךְ נֶגֶד בְּנֵי אָדָם. שֶׁהֲרֵי הוּא נֶגֶד (בני) אָדָם, וְהָאַחֵר נֶגֶד עֶלְיוֹנִים קְדוֹשִׁים. אָמַר רַבִּי שִׁמְעוֹן, גַּן הָעֵדֶן לְמַעְלָה וְנֶגֶד בְּנֵי אָדָם הוּא, (ואפלו האחר הוא נגד בני אדם) לְהִתְכַּנֵּס בּוֹ צַדִּיקִים שֶׁעוֹשִׂים רְצוֹן רִבּוֹנָם.</p>\n<p>וַיְכֻלּוּ - שֶׁכָּלוּ מַעֲשִׂים שֶׁלְּמַעְלָה וּמַעֲשִׂים שֶׁלְּמַטָּה. הַשָּׁמַיִם וְהָאָרֶץ - לְמַעְלָה וּלְמַטָּה. רַבִּי שִׁמְעוֹן אָמַר, מַעֲשֵׂה וְאֻמָּנוּת הַתּוֹרָה שֶׁבִּכְתָב וּמַעֲשֵׂה וְאֻמָּנוּת תּוֹרָה שֶׁבְּעַל פֶּה. וְכָל צְבָאָם - אֵלֶּה פְּרָטֵי הַתּוֹרָה, פָּנִים שֶׁל הַתּוֹרָה, שִׁבְעִים פָּנִים לַתּוֹרָה. וַיְכֻלּוּ - שֶׁהִתְקַיְּמוּ וְנִתְקְנוּ זֶה בָּזֶה. שָׁמַיִם וָאָרֶץ - פְּרָט וּכְלָל. וְכָל צְבָאָם - סוֹדוֹת הַתּוֹרָה, טְהָרוֹת שֶׁבַּתּוֹרָה וְטֻמְאוֹת שֶׁבַּתּוֹרָה.</p>"],[9522011110,"<p>וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי - זוֹ תוֹרָה שֶׁבְּעַל פֶּה שֶׁהוּא יוֹם שְׁבִיעִי, וּבָהּ נִתְקַן הָעוֹלָם שֶׁהוּא קִיּוּם שֶׁל הַכֹּל. מְלַאכְתּוֹ אֲשֶׁר עָשָׂה, וְלֹא כָּל מְלַאכְתּוֹ, שֶׁהֲרֵי תּוֹרָה שֶׁבִּכְתָב הוֹצִיאָה הַכֹּל בְּתֹקֶף שֶׁל כְּתָב שֶׁיּוֹצֵא מֵחָכְמָה.</p>\n<p>שָׁלֹשׁ פְּעָמִים כָּאן בַּיּוֹם הַשְּׁבִיעִי: וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי. וַיִּשְׁבּוֹת בַּיּוֹם הַשְּׁבִיעִי. וַיְבָרֶךְ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי. הֲרֵי שָׁלֹשׁ. וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי - זוֹ תוֹרָה שֶׁבְּעַל פֶּה, שֶׁעִם יוֹם הַשְּׁבִיעִי הַזֶּה נִתְקַן הָעוֹלָם כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>וַיִּשְׁבּוֹת בַּיּוֹם הַשְּׁבִיעִי - זֶה יְסוֹד הָעוֹלָם. בְּסִפְרוֹ שֶׁל רַבִּי יֵיבָא הַזָּקֵן זֶה יוֹבֵל. וְעַל כָּךְ כָּתוּב כָּאן מִכָּל מְלַאכְתּוֹ, שֶׁהַכֹּל יָצָא מִמֶּנּוּ. וְאָנוּ זֶה יְסוֹד, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁהֲרֵי מְנוּחָה בוֹ הָיְתָה יוֹתֵר מֵהַכֹּל.</p>\n<p>וַיְבָרֶךָ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי - זֶה כֹּהֵן גָּדוֹל שֶׁמְּבָרֵךְ אֶת הַכֹּל וְהוּא נוֹטֵל בָּרֹאשׁ, שֶׁשָּׁנִינוּ כֹּהֵן נוֹטֵל בָּרֹאשׁ, וּבוֹ הַבְּרָכוֹת שׁוֹרוֹת לְבָרֵךְ, וְנִקְרָא שְׁבִיעִי. רַבִּי יֵיסָא הַזָּקֵן אָמַר, הַשְּׁנַיִם הַלָּלוּ - אֶחָד הוּא בִּיסוֹד הָעוֹלָם וְאֶחָד בָּעַמּוּד הָאֶמְצָעִי (ד\"א אבל שלשת אלה אחד בערב שבת של לילה, ואחד של היום, ואחד של העולם הבא שהוא שבת הגדול),</p>\n<p>וְכֵן (ויקדש) אֹתוֹ, אֶת מִי? אֶת אוֹתוֹ מָקוֹם שֶׁאוֹת הַבְּרִית בּוֹ שׁוֹרָה, כְּמוֹ שֶׁנֶּאֱמַר (שמואל ב טו) וְהִרְאַנִי אֹתוֹ וְאֶת נָוֵהוּ. וּבְמָקוֹם זֶה שׁוֹרִים כָּל הַקִּדּוּשִׁים לְמַעְלָה (שלמעלה) וְיוֹצְאִים מִמֶּנּוּ לִכְנֶסֶת יִשְׂרָאֵל לָתֵת לָהּ תַּפְנוּק לֶחֶם עֹנֶג, וְהוֹלֵךְ זֶה כְּמוֹ שֶׁכָּתוּב (בראשית מט) מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ וְהוּא יִתֵּן מַעֲדַנֵּי מֶלֶךְ. מֵאָשֵׁר - זֶה קִיּוּם שָׁלֵם. שְׁמֵנָה לַחְמוֹ - (מה) שֶּׁהָיָה (לו) לֶחֶם עֹנִי, חוֹזֵר לִהְיוֹת לֶחֶם עֹנֶג. וְהוּא יִתֵּן מַעֲדַנֵּי מֶלֶךְ - מִי הַמֶּלֶךְ? זוֹ כְּנֶסֶת יִשְׂרָאֵל, הוּא נוֹתֵן לָהּ כָּל תַּפְנוּקֵי הָעוֹלָם, וְכָל הַקִּדּוּשִׁים שֶׁיּוֹצְאִים מִלְמַעְלָה, מֵהַמָּקוֹם הַזֶּה יוֹצְאִים. וְלָכֵן וַיְקַדֵּשׁ אֹתוֹ, אֹתוֹ - אוֹת הַבְּרִית.</p>"],[9522011111,"<p>כִּי בוֹ שָׁבַת - בּוֹ מְנוּחַת הַכֹּל (ד\"א בו מנוחה) שֶׁלָּעֶלְיוֹנִים וְתַחְתּוֹנִים. בּוֹ שַׁבָּת (ד\"א באה) לִמְנוּחָה. אֲשֶׁר בָּרָא אֱלֹהִים - מִכְּלָל שֶׁל זָכוֹר יוֹצֵא שָׁמוֹר לְהַתְקִין מַעֲשֵׂה הָעוֹלָם. לַעֲשׂוֹת - זֶה אֻמַּן הָעוֹלָם, לַעֲשׂוֹת מַעֲשֶׂה שֶׁל הַכֹּל. (ס\"א אשר ברא אמן צריך לעולם וכל המעשה של הכל).</p>\n<p>עוֹד פֵּרַשׁ רַבִּי שִׁמְעוֹן אֶת הַדָּבָר וְאָמַר, כָּתוּב (דברים ז) שׁוֹמֵר הַבְּרִית וְהַחֶסֶד. שׁוֹמֵר - זוֹ כְּנֶסֶת יִשְׂרָאֵל. הַבְּרִית - זֶה יְסוֹד הָעוֹלָם. וְהַחֶסֶד - זֶה אַבְרָהָם, שֶׁכְּנֶסֶת יִשְׂרָאֵל הִיא שׁוֹמֵר הַבְּרִית וְהַחֶסֶד. וְנִקְרֵאת שׁוֹמֵר יִשְׂרָאֵל, זֶהוּ שׁוֹמֵר הַפֶּתַח שֶׁל הַכֹּל, בּוֹ תְּלוּיִים כָּל מַעֲשֵׂי הָעוֹלָם וַדַּאי. אֲשֶׁר בָּרָא אֱלֹהִים לַעֲשׂוֹת - לְשַׁכְלֵל לְהַתְקִין הַכֹּל כָּל יוֹם וָיוֹם וּלְהוֹצִיא רוּחוֹת וּנְשָׁמוֹת, וַאֲפִלּוּ רוּחוֹת וְשֵׁדִים.</p>\n<p>וְאִם תֹּאמַר שֶׁאֵינָם תִּקּוּן הָעוֹלָם - לֹא כָּךְ! שֶׁהֲרֵי הֵם הָיוּ לְתִקּוּן הָעוֹלָם וּלְהַלְקוֹת בָּהֶם רִשְׁעֵי הָעוֹלָם, שֶׁהֵם הוֹלְכִים כְּנֶגְדָּם לְהוֹכִיחַ אוֹתָם. וּמִי שֶׁהוֹלֵךְ לִשְׂמֹאל, נֶאֱחָז בְּצַד הַשְּׂמֹאל כְּנֶגְדָּם (לוקה בהם), לָכֵן הֵם לְתִקּוּן. בֹּא רְאֵה מַה כָּתוּב בִּשְׁלֹמֹה, (שמואל ב ז) וְהוֹכַחְתִּיו בְּשֵׁבֶט אֲנָשִׁים וּבְנִגְעֵי בְּנֵי אָדָם. מִי הֵם נִגְעֵי בְּנֵי אָדָם? אֵלֶּה אוֹתָם הַמַּזִּיקִים.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁנִּבְרְאוּ, הִתְקַדֵּשׁ הַיּוֹם וְנִשְׁאֲרוּ רוּחַ בְּלִי גוּף, וְאֵלּוּ הֵם בְּרִיּוֹת שֶׁלֹּא נִתְקְנוּ (ולא התיסדו), וּמִצַּד שְׂמֹאל הֵם זֻהֲמַת הַזָּהָב. וְעַל זֶה, מִשּׁוּם שֶׁלֹּא נִתְקְנוּ וְהֵם פְּגוּמִים, הַשֵּׁם הַקָּדוֹשׁ לֹא שׁוֹרֶה בָהֶם וְלֹא נִדְבְּקוּ בּוֹ, וְהַפַּחַד שֶׁלָּהֶם הוּא מֵהַשֵּׁם הַקָּדוֹשׁ וְזָעִים וּפוֹחֲדִים מִמֶּנּוּ, וְהַשֵּׁם הַקָּדוֹשׁ לֹא שׁוֹרֶה בְּמָקוֹם פָּגוּם.</p>\n<p>וּבֹא וּרְאֵה, הָאָדָם הַזֶּה שֶׁנִּפְגַּם, שֶׁלֹּא הִשְׁאִיר בֵּן בָּעוֹלָם הַזֶּה, כְּשֶׁיּוֹצֵא מִמֶּנּוּ, לֹא נִדְבָּק בַּשֵּׁם הַקָּדוֹשׁ וְלֹא מַכְנִיסִים אוֹתוֹ לַפַּרְגּוֹד, מִשּׁוּם שֶׁהוּא פָגוּם וְלֹא נִשְׁלָם. וְעֵץ שֶׁנֶּעֱקַר צָרִיךְ נְטִיעָה פַּעַם אַחֶרֶת כְּדֵי שֶׁהַשֵּׁם הַקָּדוֹשׁ יֻשְׁלַם בְּכָל הַצְּדָדִים, וְחִסָּרוֹן לֹא יִדְבַּק בּוֹ לְעוֹלָמִים.</p>\n<p>וּבֹא וּרְאֵה, הַבְּרִיּוֹת הַלָּלוּ פְּגוּמִים הֵם מִלְמַעְלָה וּמִלְּמַטָּה, וְלָכֵן לֹא נִדְבָּקִים לְמַעְלָה וְלֹא נִדְבָּקִים לְמַטָּה. וְאֵלֶּה שֶׁכָּתוּב בָּהֶם אֲשֶׁר בָּרָא אֱלֹהִים לַעֲשׂוֹת, שֶׁלֹּא נִשְׁלְמוּ לְמַעְלָה וּלְמַטָּה. וְאִם תֹּאמַר, הֲרֵי רוּחוֹת הֵם, לָמָּה לֹא נִשְׁלְמוּ לְמַעְלָה? אֶלָּא כֵּיוָן שֶׁלֹּא נִשְׁלְמוּ לְמַטָּה בָּאָרֶץ, לֹא נִשְׁלְמוּ לְמַעְלָה. וְכֻלָּם בָּאִים מִצַּד שְׂמֹאל וּמְכֻסִּים מֵעֵינֵי בְּנֵי אָדָם, וְעוֹמְדִים כְּנֶגְדָּם לְהָרַע לָהֶם. בְּשָׁלֹשׁ הֵם כְּמוֹ מַלְאֲכֵי הַשָּׁרֵת, וּבְשָׁלֹשׁ הֵם כְּמוֹ בְּנֵי אָדָם, וַהֲרֵי בֵּאֲרוּהָ.</p>\n<p>אַחַר שֶׁנִּבְרְאוּ רוּחוֹת (ד\"א נטמנו), נִשְׁאֲרוּ אוֹתָם רוּחוֹת אַחַר הָרֵחַיִם שֶׁל נֶקֶב תְּהוֹם רַבָּה לֵיל הַשַּׁבָּת וְיוֹם הַשַּׁבָּת. כֵּיוָן שֶׁיָּצְאָה קְדֻשַּׁת הַיּוֹם וְלֹא הֻשְׁלְמוּ, יָצְאוּ לָעוֹלָם וּמְשׁוֹטְטִים לְכָל הָרוּחוֹת, וְצָרִיךְ הָעוֹלָם לְהִשָּׁמֵר מֵהֶם, שֶׁהֲרֵי אָז מִתְעוֹרֵר כָּל צַד שְׂמֹאל, וְאֵשׁ הַגֵּיהִנֹּם לוֹהֶטֶת, וְכָל אוֹתָם שֶׁבְּצַד שְׂמאֹל הוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם. וְרוֹצִים לְהִתְלַבֵּשׁ בְּגוּף וְלֹא יְכוֹלִים, וְאָז צְרִיכִים לְהִשָּׁמֵר מֵהֶם, וְהִתְקִינוּ שִׁיר שֶׁל פְּגָעִים בְּכָל שָׁעָה שֶׁפַּחַד שֶׁלָּהֶם שָׁרוּי בָּעוֹלָם.</p>"],[9522011112,"<p>בֹּא רְאֵה, כְּשֶׁמִּתְקַדֵּשׁ הַיּוֹם בְּעֶרֶב שַׁבָּת, סֻכַּת שָׁלוֹם שׁוֹרָה וְנִפְרֶסֶת בָּעוֹלָם. מִי זוֹ סֻכַּת שָׁלוֹם? זוֹ שַׁבָּת. וְכָל רוּחוֹת וּסְעָרוֹת וְשֵׁדִים וְכָל רוּחוֹת הַטֻּמְאָה, כֻּלָּם נִטְמָנִים וְנִכְנָסִים בְּעֵין הָרֵחַיִם שֶׁל נֶקֶב תְּהוֹם רַבָּה. שֶׁהֲרֵי כֵּיוָן שֶׁמִּתְעוֹרֶרֶת קְדֻשָּׁה עַל הָעוֹלָם, רוּחַ הַטֻּמְאָה לֹא מִתְעוֹרֶרֶת אִתּוֹ, וְזֶה בּוֹרֵחַ מִלִּפְנֵי זֶה.</p>\n<p>וְאָז הָעוֹלָם בִּשְׁמִירָה עֶלְיוֹנָה, וְלֹא צָרִיךְ לְהִתְפַּלֵּל עַל שְׁמִירָה כְּמוֹ שׁוֹמֵר אֶת עַמּוֹ יִשְׂרָאֵל לָעַד אָמֵן, שֶׁהֲרֵי זֶה הֻתְקַן לְיוֹם חֹל כְּשֶׁהָעוֹלָם צָרִיךְ שְׁמִירָה. אֲבָל בְּשַׁבָּת נִפְרֶסֶת סֻכַּת שָׁלוֹם עַל הָעוֹלָם, וְנִשְׁמָר בְּכָל הָרוּחוֹת, וַאֲפִלּוּ רִשְׁעֵי הַגֵּיהִנֹּם שְׁמוּרִים הֵם, וְהַכֹּל נִמְצָאִים בְּשָׁלוֹם - הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים. וְלָכֵן בְּקִדּוּשׁ הַיּוֹם מְבָרְכִים הַפּוֹרֵס סֻכַּת שָׁלוֹם עָלֵינוּ וְעַל כָּל עַמּוֹ יִשְׂרָאֵל וְעַל יְרוּשָׁלַיִם.</p>\n<p>לָמָּה עַל יְרוּשָׁלַיִם? אֶלָּא זֶהוּ מָדוֹר שֶׁל אוֹתָהּ סֻכָּה, וְצָרִיךְ לְזַמֵּן אֶת אוֹתָהּ סֻכָּה שֶׁנִּפְרְסָה עָלֵינוּ וְלִשְׁרוֹת עִמָּנוּ, לִהְיוֹת (מגנה) עָלֵינוּ כְּמוֹ אֵם שֶׁשּׁוֹרָה עַל הַבָּנִים, וְלָכֵן לֹא פוֹחֲדִים מִכָּל הָרוּחוֹת, וְלָכֵן הַפּוֹרֵס סֻכַּת שָׁלוֹם עָלֵינוּ.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁיִּשְׂרָאֵל מְבָרְכִים וּמַזְמִינִים אֶת סֻכַּת הַשָּׁלוֹם הַ את אוֹרַחַת קְדוֹשָׁה, וְאוֹמְרִים הַפּוֹרֵס סֻכַּת שָׁלוֹם, אָז קְדֻשָּׁה עֶלְיוֹנָה יוֹרֶדֶת וּפוֹרֶסֶת כְּנָפֶיהָ עַל יִשְׂרָאֵל, וּמְכַסָּה אוֹתָם כְּמוֹ אֵם עַל הַבָּנִים. וְכָל הַמִּינִים הָרָעִים מִתְכַּנְּסִים מֵהָעוֹלָם, וְיִשְׂרָאֵל יוֹשְׁבִים תַּחַת קְדֻשַּׁת רִבּוֹנָם. וְאָז סֻכַּת הַשָּׁלוֹם הַזּוֹ נוֹתֶנֶת נְשָׁמוֹת חֲדָשׁוֹת לְבָנֶיהָ. מָה הַטַּעַם? מִשּׁוּם שֶׁבָּהּ שְׁרוּיוֹת הַנְּשָׁמוֹת (ס\"א שאז זמן הזווג, ונוטלת נשמות והן שורות בה) וּמִמֶּנָּה יוֹצְאוֹת. וְכֵיוָן שֶׁשּׁוֹרָה וּפוֹרֶסֶת כְּנָפֶיהָ עַל בָּנֶיהָ, מוֹרִיקָה נְשָׁמוֹת חֲדָשׁוֹת לְכָל אֶחָד וְאֶחָד.</p>\n<p>עוֹד אָמַר רַבִּי שִׁמְעוֹן, עַל זֶה שָׁנִינוּ, שַׁבָּת דֻּגְמָא שֶׁל עוֹלָם הַבָּא הִיא. כָּךְ זֶה וַדַּאי. וְעַל זֶה שְׁמִטָּה וְיוֹבֵל דֻּגְמָא זֶה בָּזֶה. וְשַׁבָּת וְעוֹלָם הַבָּא כָּךְ הוּא. וְאוֹתָהּ תּוֹסֶפֶת נְשָׁמָה, מִסּוֹד שֶׁל זָכוֹר הִיא בָאָה עַל סֻכַּת הַשָּׁלוֹם הַזֹּאת שֶׁלּוֹקַחַת מֵהָעוֹלָם הַבָּא. וְהַתּוֹסֶפֶת הַ את נוֹתֶנֶת לָעָם הַקָּדוֹשׁ. וּבְאוֹתָהּ תּוֹסֶפֶת הֵם שְׂמֵחִים, וְנִשְׁכָּחִים מֵהֶם כָּל דִּבְרֵי הַחֹל, וְכָל צַעַר וְכָל הַצָּרוֹת, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה יד) בְּיוֹם הָנִיחַ ה' לְךְ מֵעָצְבְּךְ וּמֵרָגְזֶךְ וּמִן הָעֲבֹדָה הַקָּשָׁה וְגוֹ'.</p>\n<p>וּבְלֵיל שַׁבָּת צָרִיךְ אָדָם לִטְעֹם מֵהַכֹּל כְּדֵי לְהַרְאוֹת שֶׁסֻּכַּת שָׁלוֹם הַ את נִכְלְלָה מֵהַכֹּל, וּבִלְבַד שֶׁלֹּא יִפְגֹּם מַאֲכָל אֶחָד לְיוֹם, וְיֵשׁ אוֹמְרִים שְׁנַיִם, לִשְׁתֵּי הַסְּעוּדוֹת הָאֲחֵרוֹת שֶׁל הַיּוֹם, וְיָפֶה. וְכָל שֶׁכֵּן אִם מַעֲלֶה יוֹתֵר לַיּוֹם וְיָכוֹל לִטְעֹם מִמַּאֲכָלִים אֲחֵרִים. וְלִקְטַנִּים בִּשְׁנֵי תַבְשִׁילִים מַסְפִּיק. וּבֵאֲרוּהָ הַחֲבֵרִים.</p>\n<p>נֵר שֶׁל שַׁבָּת נִתָּן לְהַדְלָקָה לִנְשׁוֹת הָעָם הַקָּדוֹשׁ. וַהֲרֵי אָמְרוּ הַחֲבֵרִים, שֶׁהִיא כִבְּתָה נֵרוֹ שֶׁל עוֹלָם וְהֶחְשִׁיכָה אוֹתוֹ וְכוּ', וְיָפֶה. אֲבָל סוֹד הַדָּבָר - סֻכַּת שָׁלוֹם זוֹ הִיא גְּבִירַת הָעוֹלָם, וּנְשָׁמוֹת שֶׁהֵם נֵרוֹת עֶלְיוֹנִים בָּהּ הֵם שׁוֹרוֹת. וְעַל זֶה הַגְּבִירָה צְרִיכָה לְהַדְלִיק, שֶׁהֲרֵי בִּמְקוֹמָהּ נֶאֱחֶזֶת וְעוֹשָׂה מַעֲשֶׂה.</p>\n<p>וְאִשָּׁה צְרִיכָה בְּחֶדְוַת הַלֵּב וְרָצוֹן לְהַדְלִיק נֵר שַׁבָּת, שֶׁהֲרֵי כָּבוֹד עֶלְיוֹן הוּא לָהּ, וּזְכוּת גְּדוֹלָה לְעַצְמָהּ לִזְכּוֹת לְבָנִים קְדוֹשִׁים שֶׁיִּהְיוּ נֵר הָעוֹלָם בְּתוֹרָה וּבְיִרְאָה וְיַרְבּוּ שָׁלוֹם בָּאָרֶץ, וְנוֹתֶנֶת לְבַעְלָהּ חַיִּים אֲרֻכִּים. לָכֵן צְרִיכָה לְהִזָּהֵר בָּהּ.</p>\n<p>בֹּא רְאֵה, שַׁבָּת לַיְלָה וָיוֹם, זָכוֹר וְשָׁמוֹר הוּא כְּאֶחָד, וְעַל זֶה כָּתוּב זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ, וְכָתוּב שָׁמוֹר אֶת יוֹם הַשַּׁבָּת. זָכוֹר לְזָכָר, שָׁמוֹר לִנְקֵבָה, וְהַכֹּל אֶחָד. אַשְׁרֵיהֶם יִשְׂרָאֵל חֶלְקוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, גּוֹרָלוֹ וִירֻשָּׁתוֹ, עֲלֵיהֶם כָּתוּב (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו.</p>"],[9522011113,"<p>וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע אֲשֶׁר לָקַח מִן הָאָדָם וְגוֹ'. אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב (איוב כח) אֱלֹהִים הֵבִין דַּרְכָּהּ וְהוּא יָדַע אֶת מְקוֹמָהּ. בַּפָּסוּק הַזֶּה יֵשׁ גְּוָנִים רַבִּים, אֶלָּא מַה זֶּה אֱלֹהִים הֵבִין דַּרְכָּהּ? כְּמוֹ שֶׁנֶּאֱמַר וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע, זוֹ תוֹרָה שֶׁבְּעַל פֶּה שֶׁיֵּשׁ בָּהּ דֶּרֶךְ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מג) הַנּוֹתֵן בַּיָּם דָּרֶךְ. מִשּׁוּם כָּךְ אֱלֹהִים הֵבִין דַּרְכָּהּ.</p>\n<p>וְהוּא יָדַע אֶת מְקוֹמָהּ, מִי מְקוֹמָהּ? זוֹ תוֹרָה שֶׁבִּכְתָב שֶׁיֵּשׁ בָּהּ דַּעַת. (דעת ותבונה הולכים כאחד), ה' אֱלֹהִים, שֵׁם מָלֵא לְהַתְקִין לָהּ בַּכֹּל, וְעַל זֶה נִקְרְאָה חָכְמָה וְנִקְרְאָה בִּינָה, מִשּׁוּם שֶׁהָיָה בְשֵׁם מָלֵא - ה' אֱלֹהִים, בַּכֹּל בִּשְׁלֵמוּת בִּשְׁנֵי הַשֵּׁמוֹת.</p>\n<p>אֶת הַצֵּלָע - זוֹ אַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לה) וּבְצַלְעִי שָׂמְחוּ וְנֶאֱסָפוּ. אֲשֶׁר לָקַח מִן הָאָדָם - מִשּׁוּם שֶׁהֲרֵי מִתּוֹרָה שֶׁבִּכְתָב יָצְאָה. לְאִשָּׁה - לְהִתְקַשֵּׁר בְּשַׁלְהֶבֶת שֶׁל צַד שְׂמֹאל, שֶׁהֲרֵי הַתּוֹרָה מִצַּד הַגְּבוּרָה נִתְּנָה. לְאִשָּׁה - לִהְיוֹת אֵשׁ ה' קְשׁוּרָה כְּאֶחָד.</p>\n<p>וַיְבִאֶהָ אֶל הָאָדָם - מִשּׁוּם שֶׁלֹּא צְרִיכָה לְהִמָּצֵא לְבַדָּהּ, אֶלָּא לְהִתְכַּלֵּל וּלְהִתְחַבֵּר בַּתּוֹרָה שֶׁבִּכְתָב. כֵּיוָן שֶׁהִתְחַבְּרָה עִמּוֹ, הוּא יָזוּן אתָהּ וִיתַקֵּן אוֹתָהּ וְיִתֵּן לָהּ מַה שֶּׁצָּרִיךְ, הַיְנוּ מַה שֶּׁכָּתוּב וְאֵת הָאָרֶץ, וַהֲרֵי בֵּאַרְנוּ. מִכָּאן לָמַדְנוּ, שֶׁמִּי שֶׁמַּשִּׂיא אֶת בִּתּוֹ, עַד שֶׁלֹּא תִכָּנֵס לְבַעְלָהּ, אָבִיהָ וְאִמָּהּ מְתַקְּנִים אוֹתָהּ וְנוֹתְנִים לָהּ כָּל מַה שֶּׁצָּרִיךְ. כֵּיוָן שֶׁהִתְחַבְּרָה בְּבַעְלָהּ, הוּא יָזוּן אוֹתָהּ וְיִתֵּן לָהּ מַה שֶּׁצָּרִיךְ.</p>\n<p>בֹּא רְאֵה, בַּתְּחִלָּה כָּתוּב וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע, שֶׁאַבָּא וְאִמָּא הִתְקִינוּ לָהּ (בעשרים וארבעה קשוטים, ויבאה בגימטריא עשרים וארבע). וְאַחַר כָּךְ וַיְבִאֶהָ אֶל הָאָדָם. (והכניס אותה בחמשה קולות, ' (ירמיה כה) קול ששון וקול שמחה קול חתן וקול כלה קול מצהלות חתנים) לְהִתְקַשֵּׁר הַכֹּל כְּאֶחָד וּלְהִתְחַבֵּר אֶחָד בְּאֶחָד. וְהוּא נוֹתֵן (לה) מַה שֶּׁצָּרִיךְ.</p>\n<p>דָּבָר אַחֵר אֱלֹהִים הֵבִין דַּרְכָּהּ - כְּשֶׁהַבַּת בְּבֵית אִמָּא, הִיא מִסְתַּכֶּלֶת בְּכָל יוֹם בְּכָל מַה שֶּׁבִּתָּהּ צְרִיכָה, שֶׁכָּתוּב (איוב כח) אֱלֹהִים הֵבִין דַּרְכָּהּ. כֵּיוָן שֶׁהִתְחַבְּרָה בְּבַעְלָהּ, הוּא נוֹתֵן לָהּ כָּל מַה שֶּׁצָּרִיךְ וִיתַקֵּן מַעֲשֶׂיהָ. זֶהוּ שֶׁכָּתוּב וְהוּא יָדַע אֶת מְקוֹמָהּ (ופסוק זה נקשר בסודות עליונים) (ד\"א פסוק זה נאמר על חכמה העליונה ונקשר בסודות עליונים, שהרי בנקדה הראשונה אין מי שיודע בה כלל, אבל אלהים הבין דרכה, זה העולם הבא, והו\"א זה הטמיר מכל הטמירים, הנסתר שנקרא הו\"א ולא ידוע בשם).</p>"],[9522011114,"<p>כָּתוּב וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם. כָּאן נִתְקַן הַכֹּל בְּיָמִין וּבִשְׂמֹאל, וַהֲרֵי בֵּאַרְנוּ שֶׁנִּכְלַל בַּיֵּצֶר הַטּוֹב, אֲבָל וַיִּיצֶר ה' אֱלֹהִים - בְּיֵצֶר טוֹב וְיֵצֶר רָע. לָמָּה,? אֶלָּא יֵצֶר טוֹב לוֹ לְעַצְמוֹ, יֵצֶר הָרָע לְעוֹרֵר אֵלָיו אֶת נְקֵבָתוֹ (ס\"א ומצד שמאל מתעורר תמיד לנקבה). סוֹד הַדָּבָר, מִכָּאן לָמַדְנוּ שֶׁצָּפוֹן מִתְעוֹרֵר תָּמִיד לִנְקֵבָה וְנִקְשָׁר עִמָּהּ, וְלָכֵן נִקְרֵאת אִשָּׁה.</p>\n<p>וּבֹא וּרְאֵה, יֵצֶר טוֹב וְיֵצֶר הָרָע, מִשּׁוּם שֶׁהַנְּקֵבָה נִתְּנָה בֵּינֵיהֶם (נ\"א שנקבה נכללת בהם) וְהִתְקַשְּׁרָה עִמָּם, וְלֹא מִתְקַשֶּׁרֶת עַד שֶׁיֵּצֶר הָרָע מִתְעוֹרֵר אֵלֶיהָ וּמִתְקַשְּׁרִים זֶה בָּזֶה. וְכֵיוָן שֶׁמִּתְקַשְּׁרִים זֶה בָּזֶה, אָז מִתְעוֹרֵר יֵצֶר הַטּוֹב שֶׁהוּא חֶדְוָה וּמֵבִיא אוֹתָהּ אֵלָיו, (ואז נתנת ביניהם לתקן, ועל זה וייצר ה' אלהים שם מלא אליו יצר טוב ויצר רע) (ד\"א ולמעלה צד הצפון ממש שהיא חדוה בלי זהמה, שיצר הרע אוחז בה בתחלה, שכתוב (שיר ב) שמאלו תחת לראשי, ואחר כך וימינו תחבקני, ונתנה בין ימין ושמאל להזון, ועל זה וייצר ה' אלהים, שם מלא לגבי שני הצדדים הללו).</p>"],[9522011115,"<p>אֶת הָאָדָם, הֲרֵי בֵּאַרְנוּ, אֲבָל זָכָר וּנְקֵבָה כְּאֶחָד, (ולא היו) נִפְרָדִים לִהְיוֹת פָּנִים בְּפָנִים. מַה כָּתוּב? עָפָר מִן הָאֲדָמָה. עַכְשָׁו עוֹמֵד לְהַתְקִין. בּא תִרְאֶה, כְּשֶׁאִשָּׁה מִתְחַבֶּרֶת בְּבַעְלָהּ, הִיא נִקְרֵאת עַל שֵׁם בַּעְלָהּ. אִישׁ אִשָּׁה. צַדִּי\"ק צֶדֶ\"ק. הוּא עֹפֶר וְהִיא עָפָר. (ואז) הוּא צְבִי וְהִיא צְבִיָּה, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל כ) צְבִי הִיא לְכָל הָאֲ רָצוֹת.</p>\n<p>כָּתוּב (דברים טז) לֹא תִטַּע לְךְ אֲשֵׁרָה כָּל עֵץ אֵצֶל מִזְבַּח ה' אֱלֹהֶיךְ אֲשֶׁר תַּעֲשֶׂה לָּךְ. אֵצֶל מִזְבַּח - וְכִי לְמַעְלָה מִמֶּנּוּ אוֹ בְּמָקוֹם אַחֵר מִי הִתִּיר? אֶלָּא הֲרֵי בֵּאַרְנוּ, אָשֵׁר זֶה בַּעְלָהּ, שֶׁהָאִשָּׁה הִיא נִקְרֵאת עַל שֵׁם בַּעְלָהּ אֲשֵׁרָה (נ\"א: הרי הם אשר ה\"א), וְעַל זֶה כָּתוּב (מלכים ב כג) לַבַּעַל וְלָאֲשֵׁרָה. מִשּׁוּם כָּךְ כָּתוּב לֹא תִטַּע לְךְ אֲשֵׁרָה כָּל עֵץ אֵצֶל מִזְבַּח ה' אֱלֹהֶיךְ, כְּנֶגֶד הַמָּקוֹם שֶׁל אוֹתוֹ מִזְבַּח ה', שֶׁהֲרֵי מִזְבַּח ה' הוּא עוֹמֵד עַל זֶה, וְעַל זֶה כְּנֶגְדָּהּ לֹא תִטַּע לְךְ אֲשֵׁרָה אַחֶרֶת.</p>\n<p>בֹּא רְאֵה, בְּכָל מָקוֹם, כָּל אוֹתָם עוֹבְדֵי הַשֶּׁמֶשׁ נִקְרָאִים עוֹבְדִים לַבַּעַל, וְאֵלּוּ שֶׁעוֹבְדִים לַלְּבָנָה נִקְרָאִים עוֹבְדֵי אֲשֵׁרָה. וְלָכֵן לַבַּעַל וְלָאֲשֵׁרָה. וַאֲשֵׁרָה נִקְרֵאת עַל שֵׁם בַּעְלָהּ אָשֵׁ\"ר. אִם כָּךְ, לָמָּה נִתְבַּטֵּל הַשֵּׁם הַזֶּה? אֶלָּא אֲשֵׁרָה עַל שֵׁם שֶׁכָּתוּב (בראשית ל) בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָּנוֹת, וְהוּא (הרי) שֶׁלֹּא אִשְּׁרוּהָ שְׁאָר הָעַמִּים וְעוֹמֶדֶת אַחֶרֶת תַּחְתֶּיהָ. וְלֹא עוֹד, אֶלָּא שֶׁכָּתוּב (איכה א) כָּל מְכַבְּדֶיהָ הִזִּילוּהָ, וְלָכֵן (נעבד) נִתְבַּטֵּל הַשֵּׁם הַזֶּה, וּכְדֵי שֶׁלֹּא יִתְחַזְּקוּ אוֹתָם שֶׁעוֹשִׂים שְׁאָר עַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, וְקוֹרְאִים מִזְבֵּחַ שֶׁהוּא מֵאֲדָמָה, שֶׁכָּתוּב (שמות כ) מִזְבַּח אֲדָמָה וְגוֹ'. מִשּׁוּם כָּךְ עָפָר מִן הָאֲדָמָה.</p>\n<p>וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים - (דבר נכלל, אבל ויפח באפיו) נִכְלְלָה נִשְׁמַת חַיִּים בְּאוֹתוֹ עָפָר, כִּנְקֵבָה שֶׁמִּתְעַבֶּרֶת מִן הַזָּכָר, שֶׁהֲרֵי מִתְחַבְּרִים וּמִתְמַלֵּא הֶעָפָר הַזֶּה מֵהַכֹּל, וּמַהוּ? רוּחוֹת וּנְשָׁמוֹת. וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה - כָּאן הִתְתַּקֵּן וְקַיָּם אָדָם לְהַתְקִין וְלָזוּן אֶת הַנֶּפֶשׁ חַיָּה.</p>"],[9522011116,"<p>וַיִּבֶן ה' אֱלֹהִים. אַף כָּאן גַּם כֵּן בְּשֵׁם מָלֵא, שֶׁהֲרֵי אַבָּא וְאִמָּא הִתְקִינוּ אוֹתָהּ עַד שֶׁלֹּא בָאָה לְבַעְלָהּ. אֶת הַצֵּלָע, כְּמוֹ שֶׁנֶּאֱמַר (שיר א) שְׁחוֹרה אֲנִי וְנָאוָה בְּנוֹת יְרוּשָׁלָיִם, אַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה. אֲבָל אַבָּא וְאִמָּא הִתְקִינוּ לָהּ שֶׁיִּתְפַּיֵּס בַּעְלָהּ עִמָּהּ.</p>\n<p>וַיְבִאֶהָ אֶל הָאָדָם, מִכָּאן לָמַדְנוּ שֶׁצְּרִיכִים אַבָּא וְאִמָּא שֶׁל הַכַּלָּה לְהַכְנִיסָהּ בִּרְשׁוּתוֹ שֶׁל הֶחָתָן, כְּמוֹ שֶׁנֶּאֱמַר (דברים כב) אֶת בִּתִּי נָתַתִּי לָאִישׁ הַזֶּה וְגוֹ'. מִכָּאן וְאֵילָךְ בַּעְלָהּ יָבוֹא אֵלֶיהָ, שֶׁהֲרֵי הַבַּיִת הוּא שֶׁלָּהּ, שֶׁכָּתוּב (בראשית כט) וַיָּבֹא אֵלֶיהָ. וַיָּבֹא גַּם אֶל רָחֵל. בַּהַתְחָלָה וַיְבִאֶהָ אֶל הָאָדָם, שֶׁעַד כָּאן יֵשׁ לְאַבָּא וּלְאִמָּא לַעֲשׂוֹת, אַחַר כָּךְ הוּא יָבא אֵלֶיהָ, וְכָל הַבַּיִת שֶׁלָּהּ הוּא, וְיִטֹּל רְשׁוּת מִמֶּנָּה.</p>\n<p>וְעַל זֶה הֵעַרְנוּ, שֶׁכָּתוּב (שם כח) וַיִּפְגַּע בַּמָּקוֹם וַיָּלֶן שָׁם, שֶׁנָּטַל רְשׁוּת בַּהַתְחָלָה. מִכָּאן לָמַדְנוּ, שֶׁמִּי שֶׁמִּתְחַבֵּר בְּאִשְׁתּוֹ, צָרִיךְ לְבַקֵּשׁ מִמֶּנָּה וּלְשַׂמֵּח אוֹתָהּ בִּדְבָרִים, וְאִם לֹא - שֶׁלֹּא יָלוּן אֶצְלָהּ, כְּדֵי שֶׁיִּהְיֶה רָצוֹן שֶׁלָּהֶם כְּאֶחָד בְּלֹא אֹנֶס.</p>\n<p>וַיָּלֶן שָׁם כִּי בָא הַשֶּׁמֶשׁ, לְהַרְאוֹת שֶׁאָסוּר לוֹ לָאָדָם לְשַׁמֵּשׁ מִטָּתוֹ בַּיּוֹם. וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם וַיָּשֶׂם מְרַאֲשּתָיו, כָּאן לָמַדְנוּ שֶׁאֲפִלּוּ יִהְיוּ לַמֶּלֶךְ מִטּוֹת זָהָב וּלְבוּשֵׁי כָבוֹד לָלוּן בָּהֶם, וְהַמַּלְכָּה תַּתְקִין לוֹ מִטָּה מְתֻקֶּנֶת מֵאֲבָנִים - יַעֲזֹב אֶת שֶׁלּוֹ וְיָלוּן בְּמַה שֶּׁהִיא תַתְקִין, שֶׁכָּתוּב וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב כָּאן, וַיֹּאמֶר הָאָדָם זֹאת הַפַּעַם וְגוֹ'. הֲרֵי עֲרֵבוּת שֶׁל הַדְּבָרִים לְהַמְשִׁיךְ עִמָּהּ חֲבִיבוּת וּלְהַמְשִׁיךְ אוֹתָהּ (עמה) לִרְצוֹנוֹ לְעוֹרֵר עִמָּהּ אַהֲבָה. רְאֵה כַּמָּה עֲרֵבִים אוֹתָם דְּבָרִים, כַּמָּה דִּבְרֵי אַהֲבָה הֵם, עֶצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי, כְּדֵי לְהַרְאוֹת לָהּ שֶׁהֵם אֶחָד וְאֵין פֵּרוּד בֵּינֵיהֶם בַּכֹּל.</p>\n<p>עֵכְשָׁו מַתְחִיל לְשַׁבֵּחַ אוֹתָהּ - לְזאת יִקָּרֵא אִשָּׁה. זוֹ הִיא שֶׁלֹּא יִמְצָא כְמוֹתָהּ, זוֹהִי כְּבוֹד הַבַּיִת, כָּל הַנָּשִׁים לְפָנֶיהָ כְּקוֹף בִּפְנֵי אָדָם. אֲבָל לְזאת יִקָּרֵא אִשָּׁה - שְׁלֵמוּת הַכֹּל. לְזֹאת וְלֹא לְאַחֶרֶת. הַכֹּל הוּא דִּבְרֵי אַהֲבָה, כְּמוֹ שֶׁנֶּאֱמַר (משלי לא) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל וְאַתְּ עָלִית עַל כֻּלָּנָה.</p>\n<p>עַל כֵּן יַעֲזָב אִישׁ אֶת אָבִיו וְאֶת אִמּוֹ וְדָבַק בְּאִשְׁתּוֹ וְהָיוּ לְבָשָׂר אֶחָד, הַכֹּל לְהַמְשִׁיכָהּ בְּאַהֲבָה וּלְהִדָּבֵק עִמָּהּ. כֵּיוָן שֶׁעוֹרֵר אֵלֶיהָ כָּל הַדְּבָרִים הַלָּלוּ, מַה כָּתוּב? וְהַנָּחָשׁ הָיָה עָרוּם וְגוֹ'. הֲרֵי הִתְעוֹרֵר יֵצֶר הָרָע לֶאֱחֹז בָּהּ כְּדֵי לְקָשְׁרָהּ בְּתַאֲוַת הַגּוּף וּלְעוֹרֵר אֵלֶיהָ דְּבָרִים אֲחֵרִים שֶׁיֵּצֶר הָרָע מִתְעַנֵּג בָּהֶם.</p>\n<p>עַד שֶׁלְּאַחַר כָּךְ מַה כָּתוּב, וַתֵּרֶא הָאִשָּׁה כִּי טוֹב הָעֵץ לְמַאֲכָל וְכִי תַאֲוָה הוּא לָעֵינַיִם, וַתִּקַּח מִפִּרְיוֹ וַתֹּאכַל. קִבְּלָה אוֹתוֹ בְּרָצוֹן, וַתִּתֵּן גַּם לְאִישָׁהּ עִמָּהּ (ויאכל). הֲרֵי אָז הִיא הִתְעוֹרְרָה אֵלָיו בְּתַאֲוָה לְהִתְעוֹרֵר (לתת) לוֹ רָצוֹן וְאַהֲבָה, זֶה דָּבָר לְהַרְאוֹת מַעֲשֶׂה לִבְנֵי אָדָם כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אִם כָּךְ, בַּמֶּה נַעֲמִיד אוֹתוֹ לְמַעְלָה יֵצֶר הָרָע שֶׁאוֹחֵז בִּנְקֵבָה? אָמַר לוֹ, הֲרֵי הִתְעוֹרְרוּ אֵלּוּ לְמַעְלָה וְאֵלּוּ לְמַטָּה, יֵצֶר טוֹב וְיֵצֶר רַע. יֵצֶר טוֹב מִיָּמִין, וְיֵצֶר רַע מִשְּׂמֹאל. וּשְׂמֹאל לְמַעְלָה אוֹחֵז בַּנְּקֵבָה לְקָשְׁרָהּ (להתקשר בה) כְּאֶחָד בַּגּוּף, כְּמוֹ שֶׁנֶּאֱמַר (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. וְעַל זֶה דְּבָרִים הִתְפָּרְשׁוּ לְמַעְלָה וּלְמַטָּה עַד כָּאן. מִכָּאן וָהָלְאָה מִלִּים שֶׁל קַטְנוּת (נ\"א: בשרף) שֶׁל זֶפֶת לִקְטַנִּים שֶׁבָּעֲרִיסוֹת לְפָרֵשׁ הַדָּבָר, וַהֲרֵי נִתְעוֹרְרוּ בוֹ הַחֲבֵרִים.</p>"],[9522011117,"<p>רַבִּי שִׁמְעוֹן הָיָה הוֹלֵךְ לִטְבֶרְיָה, וְהָיוּ עִמּוֹ רַבִּי יוֹסֵי וְרַבִּי יְהוּדָה וְרַבִּי חִיָּיא. בֵּין כָּךְ רָאוּ אֶת רַבִּי פִּנְחָס שֶׁהָיָה בָּא. כֵּיוָן שֶׁהִתְחַבְּרוּ כְּאֶחָד, יָרְדוּ וְיָשְׁבוּ תַּחַת אִילָן אֶחָד מֵאִילָנֵי הָהָר. אָמַר רַבִּי פִּנְחָס, הֲרֵי יָשַׁבְנוּ, מֵאוֹתָם דְּבָרִים מְעֻלִּים שֶׁאַתָּה אוֹמֵר בְּכָל יוֹם אָנוּ רוֹצִים לִשְׁמֹעַ.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (בראשית יג) וַיֵּלֶךְ לְמַסָּעָיו מִנֶּגֶב וְעַד בֵּית אֵל עַד הַמָּקוֹם אֲשֶׁר הָיָה שָׁם אָהֳלֹה בַּתְּחִלָּה בֵּין בֵּית אֵל וּבֵין הָעָי. וַיֵּלֶךְ לְמַסָּעָיו? לְמַסָּעוֹ צָרִיךְ לִהְיוֹת! מַה זֶּה לְמַסָּעָיו? אֶלָּא שְׁנֵי מַסָּעוֹת הֵם, אֶחָד שֶׁלּוֹ וְאֶחָד שֶׁל הַשְּׁכִינָה, שֶׁהֲרֵי כָּל בֶּן אָדָם צָרִיךְ לְהִמָּצֵא זָכָר וּנְקֵבָה כְּדֵי לְחַזֵּק הָאֱמוּנָה, וְאָז הַשְּׁכִינָה לֹא נִפְרֶדֶת מִמֶּנּוּ לְעוֹלָמִים.</p>\n<p>וְאִם תֹּאמַר, מִי שֶׁיּוֹצֵא לַדֶּרֶךְ שֶׁלֹּא נִמְצָא זָכָר וּנְקֵבָה, הַשְּׁכִינָה נִפְרֶדֶת מִמֶּנּוּ? בּא רְאֵה, מִי שֶׁיּוֹצֵא לַדֶּרֶךְ יְסַדֵּר תְּפִלָּה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי לְהַמְשִׁיךְ עָלָיו שְׁכִינַת רִבּוֹנוֹ עַד שֶׁלֹּא יֵצֵא לַדֶּרֶךְ, בִּזְמַן שֶׁנִּמְצָא זָכָר וּנְקֵבָה. כֵּיוָן שֶׁסִּדֵּר תְּפִלָּתוֹ וּשְׁבָחָיו וּשְׁכִינָה שׁוֹרָה עָלָיו - יֵצֵא, שֶׁהֲרֵי הַשְּׁכִינָה הִזְדַּוְּגָה עִמּוֹ, כְּדֵי שֶׁיִּמָּצֵא זָכָר וּנְקֵבָה. זָכָר וּנְקֵבָה בָּעִיר, זָכָר וּנְקֵבָה בַּשָּׂדֶה. זֶהוּ שֶׁכָּתוּב (תהלים פה) צֶדֶק לְפָנָיו יְהַלֵּךְ וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו.</p>\n<p>בֹּא רְאֵה, כָּל זְמַן שֶׁבֶּן אָדָם מִתְעַכֵּב בַּדֶּרֶךְ, (בכל כחו) צָרִיךְ לִשְׁמֹר מַעֲשָׂיו כְּדֵי שֶׁהַזִּוּוּג הָעֶלְיוֹן לֹא יִפָּרֵד מִמֶּנּוּ, וְיִמָּצֵא פָגוּם בְּלִי זָכָר וּנְקֵבָה. בָּעִיר צָרִיךְ כְּשֶׁנְּקֵבָתוֹ עִמּוֹ, כָּל שֶׁכֵּן כָּאן שֶׁזִּוּוּג הָעֶלְיוֹן נִקְשָׁר בּוֹ. וְלֹא עוֹד, אֶלָּא שֶׁהַזִּוּוּג הָעֶלְיוֹן הַזֶּה שׁוֹמֵר אוֹתוֹ בַּדֶּרֶךְ וְלֹא נִפְרָד מִמֶּנּוּ עַד שֶׁיָּשׁוּב לְבֵיתוֹ.</p>\n<p>בְּשָׁעָה שֶׁנִּכְנָס לְבֵיתוֹ צָרִיךְ לְשַׂמֵּחַ אֶת אִשְׁתּוֹ (ביתו), מִשּׁוּם שֶׁאִשְׁתּוֹ גָּרְמָה לוֹ אוֹתוֹ זִוּוּג עֶלְיוֹן. כֵּיוָן שֶׁבָּא אֵלֶיהָ, צָרִיךְ לְשַׂמֵּחַ אוֹתָהּ מִשּׁוּם שְׁנֵי טְעָמִים. אֶחָד מִשּׁוּם חֶדְוַת אוֹתוֹ זִוּוּג, חֶדְוַת הַמִּצְוָה הִיא, וְחֶדְוַת הַמִּצְוָה חֶדְוַת הַשְּׁכִינָה הִיא.</p>\n<p>וְלֹא עוֹד, אֶלָּא שֶׁמַּרְבֶּה שָׁלוֹם סְתָם (למטה) (נ\"א: לאשה). זֶהוּ שֶׁכָּתוּב (איוב ה) וְיָדַעְתָּ כִּי שָׁלוֹם אָהֳלֶךְ וּפָקַדְתָּ נָוְךְ וְלֹא תֶחֱטָא. וְכִי אִם לֹא פוֹקֵד אֶת אִשְׁתּוֹ זֶה חֵטְא? כָּךְ זֶה בְּוַדַּאי! מִשּׁוּם שֶׁגּוֹרֵעַ כְּבוֹד זִוּוּג הָעֶלְיוֹן שֶׁהִזְדַּוְּגָה בּוֹ וְאִשְׁתּוֹ גָּרְמָה לוֹ.</p>\n<p>וְאֶחָד - שֶׁאִם אִשְׁתּוֹ מִתְעַבֶּרֶת, הַזִּוּוּג הָעֶלְיוֹן מֵרִיק בָּהּ נְשָׁמָה קְדוֹשָׁה, שֶׁהֲרֵי הַבְּרִית הַזּוֹ נִקְרֵאת בְּרִית הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעַל זֶה צָרִיךְ לְכַוֵּן בְּחֶדְוָה זוֹ כְּמוֹ שֶׁצָּרִיךְ בְּחֶדְוַת הַשַּׁבָּת (של אותם חכמים), שֶׁהוּא זִוּוּג הַחֲכָמִים. וְעַל זֶה וְיָדַעְתָּ כִּי שָׁלוֹם אָהֳלֶךְ, שֶׁהֲרֵי הַשְּׁכִינָה בָּאָה עִמְּךְ וְשׁוֹרָה בְּבֵיתְךְ. וְעַל זֶה (שם) וּפָקַדְתָּ נָוְךְ וְלֹא תֶחֱטָא. מַה זֶּה וְלֹא תֶחֱטָא? לְשַׁמֵּשׁ לִפְנֵי הַשְּׁכִינָה חֶדְוַת הַמִּצְוָה.</p>\n<p>כְּמוֹ זֶה תַּלְמִידֵי חֲכָמִים שֶׁפּוֹרְשִׁים מִנְּשׁוֹתֵיהֶם כָּל אוֹתָם יְמֵי הַשָּׁבוּעַ כדי להתעסק בתורה, הזווג העליון נזדוג בהם ולא נפרד מהם כדי שימצא זכר ונקבה. כיון שנכנסת שבת, צריכים תלמידי חכמים לשמח את נשותיהם משום כבוד הזווג העליון, ולכון לבם ברצון רבונם כמו שנאמר.</p>\n<p>כְּמוֹ זֶה מִי שֶׁאִשְׁתּוֹ בִּימֵי טֻמְאָתָהּ וְשׁוֹמֵר אוֹתָהּ כָּרָאוּי, כָּל אוֹתָם הַיָּמִים הַזִּוּוּג הָעֶלְיוֹן מִזְדַּוֵּג עִמּוֹ שֶׁיִּמָּצֵא זָכָר וּנְקֵבָה. כֵּיוָן שֶׁאִשְׁתּוֹ נִטְהֶרֶת, צָרִיךְ לְשַׂמֵּחַ אוֹתָהּ שִׂמְחַת מִצְוָה חֶדְוָה עֶלְיוֹנָה. וְכָל הַטְּעָמִים שֶׁאָמַרְנוּ עוֹלִים בְּדַרְגָּה אַחַת. סְתָמוֹ שֶׁל דָּבָר - כָּל אוֹתָם בְּנֵי הָאֱמוּנָה צְרִיכִים לְכַוֵּן לֵב וְרָצוֹן בָּזֶה.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ, שֶׁבַח הוּא שֶׁל הָאִישׁ כְּשֶׁיּוֹצֵא לַדֶּרֶךְ יוֹתֵר מֵאֲשֶׁר בְּבֵיתוֹ, מִשּׁוּם הַזִּוּוּג הָעֶלְיוֹן שֶׁמִּזְדַּוֶּגֶת עִמּוֹ - בֹּא רְאֵה, בִּזְמַן שֶׁבֶּן אָדָם הוּא בְּבֵיתוֹ, עִקַּר הַבַּיִת אִשְׁתּוֹ, מִשּׁוּם שֶׁשְּׁכִינָה לֹא זָזָה מֵהַבַּיִת מִשּׁוּם אִשְׁתּוֹ, כְּמוֹ שֶׁשָּׁנִינוּ, שֶׁכָּתוּב (בראשית כד) וַיְבִאֶהָ יִצְחָק הָאֹהֱלָה שָׂרָה אִמּוֹ, שֶׁנֵּר הִדְלִיקָה. מָה הַטַּעַם? מִשּׁוּם שֶׁהַשְּׁכִינָה בָּאָה לַבַּיִת.</p>\n<p>סוֹד הַדָּבָר - הָאֵם הָעֶלְיוֹנָה לֹא נִמְצֵאת אֵצֶל הַזָּכָר אֶלָּא בִּזְמַן שֶׁנִּתְקַן הַבַּיִת וְהִתְחַבְּרוּ זָכָר וּנְקֵבָה, וְאָז הָאֵם הָעֶלְיוֹנָה מוֹרִיקָה בְרָכוֹת כְּדֵי לְבָרֵךְ אוֹתָם. כְּמוֹ זֶה הָאֵם הַתַּחְתּוֹנָה לֹא נִמְצֵאת אֵצֶל הַזָּכָר אֶלָּא בִּזְמַן שֶׁהִתְתַּקֵּן הַבַּיִת, וּבָא הַזָּכָר לַנְּקֵבָה שֶׁלּוֹ וְהִתְחַבְּרוּ כְּאֶחָד. אָז הָאֵם הַתַּחְתּוֹנָה מוֹרִיקָה בְרָכוֹת לְבָרֵךְ אוֹתָם.</p>\n<p>וְעַל זֶה הַזָּכָר מִתְעַטֵּר בְּבֵיתוֹ בִּשְׁתֵּי נְקֵבוֹת כְּמוֹ שֶׁלְּמַעְלָה. וְזֶהוּ סוֹד הַכָּתוּב (שם מט) עַד תַּאֲוַת גִּבְעֹת עוֹלָם. הָעַ\"ד הַזֶּה, תַּאֲוַת שֶׁל גִּבְעוֹת עוֹלָם בּוֹ. נְקֵבָה עֶלְיוֹנָה לְתַקֵּן אוֹתוֹ וּלְעַטֵּר אוֹתוֹ וּלְבָרֵךְ אוֹתוֹ, נְקֵבָה הַתַּחְתּוֹנָה לְהִתְחַבֵּר בּוֹ וּלְהִזּוֹן מִמֶּנּוּ.</p>\n<p>וּכְמוֹ זֶה לְמַטָּה, כְּשֶׁזָּכָר נִשָּׂא, תַּאֲוַת גִּבְעוֹת עוֹלָם אֵלָיו, וּמִתְעַטֵּר בִּשְׁתֵּי נְקֵבוֹת - אַחַת עֶלְיוֹנָה וְאַחַת תַּחְתּוֹנָה. הָעֶלְיוֹנָה לְהוֹרִיק עָלָיו בְּרָכוֹת, וְהַתַּחְתּוֹנָה לְהִזּוֹן מִמֶּנּוּ וּלְהִתְחַבֵּר עִמּוֹ. וּבֶן אָדָם בְּבֵיתוֹ תַּאֲוַת גִּבְעוֹת עוֹלָם אֵלָיו וּמִתְעַטֵּר בָּהֶם.</p>\n<p>כְּשֶׁיּוֹצֵא לַדֶּרֶךְ לֹא כָּךְ. הָאֵם הָעֶלְיוֹנָה מִתְחַבֶּרֶת עִמּוֹ, וְהַתַּחְתּוֹנָה נִשְׁאֶרֶת. כְּשֶׁשָּׁב לְבֵיתוֹ, רוֹצֶה לְהִתְעַטֵּר בִּשְׁתֵּי נְקֵבוֹת כְּפִי שֶׁאָמַרְנוּ. אָמַר רַבִּי פִּנְחָס, אֲפִלּוּ בִּקְלִפּוֹת בְּקֶשֶׁר שֶׁל סַפִּירִים לֹא פוֹתְחִים פִּתְחוֹן לְפָנֶיךְ.</p>"],[9522011118,"<p>אָמַר רַבִּי שִׁמְעוֹן, כְּמוֹ זֶה הַתּוֹרָה עוֹמֶדֶת בֵּין שְׁנֵי בָתִּים, כְּמוֹ שֶׁכָּתוּב (ישעיה ח) לִשְׁנֵי בָּתֵּי יִשְׂרָאֵל וְגוֹ'. אֶחָד נִסְתָּר עֶלְיוֹן, וְאֶחָד גָּלוּי יוֹתֵר. (הנסתר) הָעֶלְיוֹן (זה) קוֹל גָּדוֹל, שֶׁכָּתוּב (דברים ה) קוֹל גָּדוֹל וְלֹא יָסָף.</p>\n<p>וְהַקּוֹל הַפְּנִימִי הַזֶּה הוּא שֶׁלֹּא נִשְׁמָע וְלֹא מִתְגַּלֶּה. וְזֶהוּ כְּשֶׁנּוֹבֵעַ בֵּית הַגָּרוֹן, יוֹצֵאת (בו) ה' בַּחֲשַׁאי, וְתָמִיד נוֹבֵעַ וְלֹא פוֹסֵק. וְהוּא דַּק פְּנִימִי שֶׁלֹּא נִשְׁמַע לְעוֹלָמִים.</p>\n<p>וּמִכָּאן יוֹצֵאת הַתּוֹרָה שֶׁהִיא קוֹל יַעֲקֹב. וְזֶה נִשְׁמָע (שנשמע) שֶׁיּוֹצֵא (יוצא) מֵאוֹתָהּ שֶׁלֹּא נִשְׁמַעַת, וְאַחַר כָּךְ הַדִּבּוּר נֶאֱחָז עִמּוֹ וְיוֹצֵא הַחוּצָה מִכֹּחוֹ וּמִתָּקְפּוֹ. וְקוֹל שֶׁל יַעֲקֹב שֶׁהוּא תּוֹרָה, אוֹחֵז בֵּין שְׁתֵּי נְקֵבוֹת. אוֹחֵז בַּפְּנִימִי הַזֶּה שֶׁלֹּא נִשְׁמָע, וְאוֹחֵז בָּזֶה שֶׁבַּחוּץ שֶׁנִּשְׁמָע.</p>\n<p>שְׁנַיִם הֵם שֶׁלֹּא נִשְׁמָעִים, וּשְׁנַיִם שֶׁנִּשְׁמָעִים. שְׁנַיִם שֶׁלֹּא נִשְׁמָעִים זוֹהִי חָכְמָה הָעֶלְיוֹנָה הַנִּסְתֶּרֶת שֶׁעוֹמֶדֶת בַּמַּחֲשָׁבָה שֶׁלֹּא מִתְגַּלָּה וְלֹא נִשְׁמַעַת. אַחַר כָּךְ יוֹצֵאת וּמִתְגַּלָּה מְעַט בַּחֲשַׁאי, שֶׁלֹּא נִשְׁמָע אוֹתוֹ שֶׁנִּקְרָא קוֹל גָּדוֹל, שֶׁהוּא דַּק וְיוֹצֵא בַּחֲשַׁאי.</p>\n<p>שְׁנַיִם הֵם שֶׁנִּשְׁמָעִים, אוֹתָם שֶׁיּוֹצְאִים מִכָּאן הַקּוֹל שֶׁל יַעֲקֹב וְדִבּוּר שֶׁנֶּאֱחָז עִמּוֹ. הַקּוֹל הַגָּדוֹל הַזֶּה שֶׁהוּא בַּחֲשַׁאי שֶׁלֹּא נִשְׁמָע, הִיא בַּיִת לַחָכְמָה הָעֶלְיוֹנָה, וְכָל נְקֵבָה נִקְרֵאת בַּיִ\"ת. וְהַדִּבּוּר הָאַחֲרוֹן הַזֶּה הוּא בַּיִת לַקּוֹל שֶׁל יַעֲקֹב שֶׁהוּא תּוֹרָה. וְעַל כֵּן הַתּוֹרָה מַתְחִילָה בְּבֵי\"ת, בֵּי\"ת רֵאשִׁית.</p>\n<p>פָּתַח וְאָמַר, בְּרֵאשִׁית בָּרָא אֱלֹהִים, הַיְנוּ שֶׁכָּתוּב וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע. אֵת הַשָּׁמַיִם, הַיְנוּ שֶׁכָּתוּב וַיְבִאֶהָ אֶל הָאָדָם. וְאֵת הָאָרֶץ, כְּמוֹ שֶׁנֶּאֱמַר עֶצֶם מֵעֲצָמַי. וַדַּאי זוֹהִי אֶרֶץ הַחַיִּים.</p>"],[9522011119,"<p>עוֹד פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים ק) נְאֻם ה' לַאדנִי שֵׁב לִימִינִי עַד אָשִׁית אֹיְבֶיךְ הֲדם לְרַגְלֶיךְ. נְאֻם ה' לַאדנִי - הַדַּרְגָּה הָעֶלְיוֹנָה לַדַּרְגָּה הַתַּחְתּוֹנָה אוֹמֶרֶת שֵׁב לִימִינִי, לְקַשֵּׁר מַעֲרָבִית בִּדְרוֹמִית, שְׂמֹאל בְּיָמִין, כְּדֵי לִשְׁבֹּר אֶת כֹּחָם שֶׁל שְׁאָר הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. נְאֻם ה' לַאדנִי - נְאֻם ה' זֶה יַעֲקֹב. לַאדנִי - זֶה (יהושע ג) אֲרוֹן הַבְּרִית אֲדוֹן כָּל הָאָרֶץ.</p>\n<p>דָּבָר אַחֵר נְאֻם ה' - זֶה יוֹבֵל. לַאדנִי - זוֹ שְׁמִטָּה, שֶׁכָּתוּב בָּהּ (שמות כא) אָהַבְתִּי אֶת אֲדנִי. שֵׁב לִימִינִי - שֶׁהֲרֵי הַיָּמִין מַתְחִיל בַּיּוֹבֵל, וּשְׁמִטָּה צָרִיךְ לְקַשֵּׁר בְּיָמִין.</p>\n<p>בֹּא רְאֵה, שְׁמִטָּה זוֹ לֹא נִקְשֶׁרֶת בְּקִיּוּם שָׁלֵם בְּיָמִין וּבִשְׂמֹאל מִיּוֹם שֶׁנִּבְרֵאת. כְּשֶׁרוֹצֶה לְהִתְקַשֵּׁר, הוֹשִׁיט זְרוֹעַ שְׂמֹאל כְּנֶגְדָּהּ וּבָרָא אֶת הָעוֹלָם הַזֶּה. וּבִגְלַל שֶׁהוּא מִצַּד שְׂמֹאל, אֵין בּוֹ קִיּוּם עַד הַזְּמַן שֶׁל הָאֶלֶף הַשְּׁבִיעִי, שֶׁבְּאוֹתוֹ יוֹם לְחוּד מִתְקַשֵּׁר אָז בְּיָמִין. וְאָז תִּהְיֶה בֵּין הַיָּמִין וְהַשְּׂמֹאל בְּקִיּוּם שָׁלֵם, וְיִמָּצְאוּ שָׁמַיִם חֲדָשִׁים וְאֶרֶץ חֲדָשָׁה, וְאָז לֹא תָזוּז מִשָּׁם לְעוֹלָמִים.</p>\n<p>אִם כָּךְ, בַּמֶּה נַעֲמִיד שֵׁב לִימִינִי? אֶלָּא עַד זְמַן יָדוּעַ, שֶׁכָּתוּב עַד אָשִׁית אֹיְבֶיךְ הֲדם לְרַגְלֶיךְ, וְלֹא תָמִיד. אֲבָל בְּאוֹתוֹ זְמַן לֹא תָזוּז מִשָּׁם לְעוֹלָמִים, שֶׁכָּתוּב (ישעיה נד) כִּי יָמִין וּשְׂמֹאול תִּפְרֹצִי, לִהְיוֹת הַכֹּל אֶחָד.</p>"],[9522011120,"<p>בֹּא רְאֵה, אֵת הַשָּׁמַיִם - זוֹ שְׁכִינָה עֶלְיוֹנָה (בינה). וְאֵת הָאָרֶץ - זוֹ שְׁכִינָה שֶׁלְּמַטָּה בְּהִתְחַבְּרוּת שֶׁל זָכָר וּנְקֵבָה כְּאֶחָד, וַהֲרֵי נֶאֱמַר כְּמוֹ שֶׁהֵעִירוּ בוֹ הַחֲבֵרִים עַד עַכְשָׁו.</p>\n<p>רָצוּ (רצה) לָלֶכֶת. קָמוּ. אָמַר רַבִּי שִׁמְעוֹן, דָּבָר כָּאן אֶצְלֵנוּ. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, שְׁנֵי פְסוּקִים כְּתוּבִים, (דברים ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא, וְכָתוּב שָׁם (שם) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם. אֶת הַפְּסוּקִים הַלָּלוּ בֵּאַרְנוּ אוֹתָם בְּכַמָּה מְקוֹמוֹת, וְהַחֲבֵרִים הֵעִירוּ בָהֶם. בּא תִרְאֶה, כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא, הֲרֵי נֶאֱמַר הַדָּבָר הַזֶּה בְּתוֹךְ הַחֲבֵרִים שֶׁיֵּשׁ אֵשׁ אוֹכֶלֶת אֵשׁ, (ויש אש) וְאוֹכֶלֶת אוֹתָהּ וּמַשְׁמִידָה אוֹתָהּ, הֱיוֹת שֶׁיֵּשׁ אֵשׁ חֲזָקָה מֵאֵשׁ, וּפֵרְשׁוּהָ.</p>\n<p>אֲבָל בּא רְאֵה, מִי שֶׁרוֹצֶה לָדַעַת חָכְמַת הַיִּחוּד הַקָּדוֹשׁ, יִסְתַּכֵּל בַּשַּׁלְהֶבֶת שֶׁעוֹלָה מִתּוֹךְ הַגַּחֶלֶת אוֹ מִתּוֹךְ נֵר שֶׁדּוֹלֵק. שֶׁהֲרֵי הַשַּׁלְהֶבֶת לֹא עוֹלָה אֶלָּא כְּשֶׁנֶּאֱחֶזֶת בְּדָבָר גַּס (אחר).</p>\n<p>בֹּא רְאֵה, בַּשַּׁלְהֶבֶת שֶׁעוֹלָה יֵשׁ שְׁנֵי אוֹרוֹת. אֶחָד אוֹר לָבָן שֶׁמֵּאִיר, וְאֶחָד אוֹר שֶׁנֶּאֱחָז בָּהּ שָׁחֹר אוֹ תְכֵלֶת. אוֹתוֹ אוֹר לָבָן הוּא לְמַעְלָה וְעוֹלֶה בְּדֶרֶךְ יָשָׁר, וְתַחְתָּיו אוֹתוֹ אוֹר תְּכֵלֶת אוֹ שָׁחֹר שֶׁהוּא כִּסֵּא לְאוֹתוֹ לָבָן.</p>\n<p>וְאוֹתוֹ אוֹר לָבָן שׁוֹרֶה עָלָיו, וְנֶאֱחָזִים זֶה בָּזֶה לִהְיוֹת הַכֹּל אֶחָד. וְאוֹתוֹ אוֹר שָׁחֹר אוֹ גָוֶן תְּכֵלֶת שֶׁהוּא לְמַטָּה הוּא כִּסֵּא כָבוֹד לְאוֹתוֹ לָבָן, וְעַל זֶה סוֹד הַתְּכֵלֶת.</p>\n<p>וְכִסֵּא זֶה תְּכֵלֶת שָׁחֹר נֶאֱחָז בְּדָבָר אַחֵר לְהִדָּלֵק, שֶׁהוּא מִלְּמַטָּה, וְהַהוּא מְעוֹרֵר אוֹתוֹ לְהֵאָחֵז בָּאוֹר הַלָּבָן (העליון).</p>\n<p>וְהַתְּכֵלֶת הַשָּׁחֹר הַזֶּה לִפְעָמִים חוֹזֵר לִהְיוֹת אָדם. וְאוֹתוֹ אוֹר לָבָן שֶׁעָלָיו לֹא מִשְׁתַּנֶּה לְעוֹלָמִים, שֶׁהֲרֵי הוּא תָּמִיד לָבָן, אֲבָל תְּכֵלֶת זֶה מִשְׁתַּנֶּה לַגְּוָנִים הַלָּלוּ. לִפְעָמִים תְּכֵלֶת אוֹ שָׁחֹר,</p>\n<p>וְלִפְעָמִים אָדם, וְזֶה נֶאֱחָז לִשְׁנֵי צְדָדִים. נֶאֱחָז לְמַעְלָה בְּאוֹתוֹ אוֹר (עליון) לָבָן. נֶאֱחָז לְמַטָּה בַּדָּבָר הַהוּא שֶׁתַּחְתָּיו שֶׁמְּתֻקָּן בּוֹ לְהָאִיר (דברים ששמים לו להדליק) וּלְהֵאָחֵז בּוֹ.</p>\n<p>וְזוֹ אוֹכֶלֶת תָּמִיד וּמַשְׁמִידָה לְאוֹתוֹ דָבָר שֶׁשָּׂמִים לָהּ. שֶׁהֲרֵי בְּכָל מַה שֶּׁנִּדְבָּק בּוֹ לְמַטָּה וְשׁוֹרֶה עָלָיו, אוֹתוֹ אוֹר תְּכֵלֶת מַשְׁמִיד אוֹתוֹ וְאוֹכֵל אוֹתוֹ, מִשּׁוּם שֶׁדַּרְכּוֹ הִיא לְהַשְׁמִיד וְלִהְיוֹת אוֹכֵל, שֶׁהֲרֵי בּוֹ תְּלוּיָה הַשְׁמָדַת הַכֹּל, מָוֶת שֶׁל הַכֹּל. וְלָכֵן הִיא אוֹכֶלֶת כָּל מַה שֶּׁנִּדְבָּק בָּהּ לְמַטָּה.</p>\n<p>וְאוֹתוֹ אוֹר לָבָן שֶׁשּׁוֹרֶה עָלָיו לֹא אוֹכֵל וְלֹא מַשְׁמִיד לְעוֹלָמִים וְלֹא מִשְׁתַּנֶּה אוֹרוֹ, וְעַל זֶה אָמַר מֹשֶׁה כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא. אֹכְלָה וַדַּאי. אוֹכֵל וּמַשְׁמִיד כָּל מַה שֶּׁשּׁוֹרֶה תַחְתָּיו. וְעַל זֶה אָמַר ה' אֱלֹהֶיךְ וְלֹא אֱלֹהֵינוּ, מִשּׁוּם שֶׁמֹּשֶׁה בְּאוֹתוֹ אוֹר לָבָן שֶׁלְּמַעְלָה הָיָה שֶׁלֹּא הִשְׁמִיד וְלֹא אָכַל.</p>\n<p>בֹּא רְאֵה, אֵין לוֹ הִתְעוֹרְרוּת לְהִדָּלֵק הָאוֹר הַתְּכֵלֶת הַזֶּה לְהִתְאַחֵד בְּאוֹר לָבָן אֶלָּא עַל יְדֵי יִשְׂרָאֵל שֶׁהֵם נִדְבָּקִים בּוֹ תַּחְתָּיו.</p>\n<p>וּבֹא וּרְאֵה, אַף עַל פִּי שֶׁדֶּרֶךְ שֶׁל הָאוֹר תְּכֵלֶת וְשָׁחֹר הַזֶּה לְהַשְׁמִיד כָּל מַה שֶּׁנִּדְבָּק בּוֹ תַּחְתָּיו, יִשְׂרָאֵל נִדְבָּקִים בּוֹ תַּחְתָּיו וְעוֹמְדִים בְּקִיּוּם. זֶהוּ שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים. בַּה' אֱלֹהֵיכֶם וְלֹא אֱלֹהֵינוּ (אלא בה' אלהיכם), בְּאוֹתוֹ אוֹר תְּכֵלֶת שָׁחֹר שֶׁאוֹכֵל וּמַשְׁמִיד כָּל מַה שֶּׁנִּדְבָּק בּוֹ תַּחְתָּיו, וְאַתֶּם מִתְדַּבְּקִים בּוֹ וְקַיָּמִים, שֶׁכָּתוּב חַיִּים כֻּלְּכֶם הַיּוֹם.</p>\n<p>וְעַל הָאוֹר הַלָּבָן שָׁרוּי לְמַעְלָה אוֹר נִסְתָּר שֶׁמַּקִּיף אוֹתוֹ, וְסוֹד עֶלְיוֹן כָּאן. וְהַכֹּל תִּמְצָא בַּשַּׁלְהֶבֶת שֶׁעוֹלָה וְחָכְמוֹת שֶׁל הָעֶלְיוֹנִים בָּהּ. בָּא ר' פִּנְחָס וּנְשָׁקוֹ. אָמַר, בָּרוּךְ הָרַחֲמָן שֶׁנִּפְגַּשְׁנוּ כָּאן. הָלְכוּ עִם רַבִּי פִּנְחָס שְׁלֹשָׁה מִילִין.</p>\n<p>חָזְרוּ רַבִּי שִׁמְעוֹן וְהַחֲבֵרִים. אָמַר רַבִּי שִׁמְעוֹן, זֶה שֶׁאָמַרְנוּ סוֹד הַחָכְמָה הוּא בַּיִּחוּד הַקָּדוֹשׁ שֶׁמִּשּׁוּם כָּךְ הֵ\"א אַחֲרוֹנָה שֶׁל הַשֵּׁם הַקָּדוֹשׁ הוּא אוֹר תְּכֵלֶת שָׁחֹר שֶׁנֶּאֱחָז בְּיה\"ו, שֶׁהוּא אוֹר לָבָן שֶׁמֵּאִיר.</p>\n<p>בֹּא רְאֵה, לִפְעָמִים הָאוֹר הַתְּכֵלֶת ד', וְלִפְעָמִים ה'. אֶלָּא בִּזְמַן שֶׁלֹּא נִדְבָּקִים בּוֹ יִשְׂרָאֵל לְמַטָּה לְהַדְלִיק אוֹתוֹ לְהֵאָחֵז בָּאוֹר הַלָּבָן הוּא ד', וְלִפְעָמִים שֶׁמְּעוֹרְרִים אוֹתוֹ לְהִתְחַבֵּר עִם הָאוֹר הַלָּבָן, אָז נִקְרָא ה'.</p>\n<p>מִנַּיִן לָנוּ? שֶׁכָּתוּב (שם כב) כִּי יִהְיֶה נַעֲרָה בְתוּלָה. נַעֲרָ כָּתוּב בְּלִי ה', מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא הִתְחַבְּרָה בְּזָכָר, וּבְכָל מָקוֹם שֶׁלֹּא נִמְצָאִים זָכָר וּנְקֵבָה, הֵ\"א לֹא נִמְצֵאת וְעוֹלָה מִשָּׁם, וְנִשְׁאָר ד'.</p>\n<p>שֶׁהֲרֵי הִיא כָּל זְמַן שֶׁמִּתְחַבֶּרֶת בָּאוֹר הַלָּבָן שֶׁמֵּאִיר נִקְרֵאת ה', שֶׁהֲרֵי אָז הַכֹּל מִתְחַבֵּר כְּאֶחָד. הִיא נִדְבֶּקֶת בָּאוֹר הַלָּבָן, וְיִשְׂרָאֵל נִדְבָּקִים בָּהּ (למטה) וְעוֹמְדִים תַּחְתֶּיהָ לְהַדְלִיק אוֹתָהּ, וְאָז הַכֹּל אֶחָד.</p>\n<p>וְזֶהוּ סוֹד הַקָּרְבָּן, שֶׁהֶעָשָׁן שֶׁעוֹלֶה מְעוֹרֵר אוֹתוֹ לָאוֹר הַתְּכֵלֶת הַזֶּה לְהַדְלִיק. וּכְשֶׁנִּדְלָק, מִתְחַבֵּר בָּאוֹר הַלָּבָן, וְהַנֵּר דּוֹלֵק בְּיִחוּד אֶחָד.</p>\n<p>וּמִשּׁוּם שֶׁדַּרְכּוֹ שֶׁל הָאוֹר הַתְּכֵלֶת הַזֶּה לְהַשְׁמִיד וְלִהְיוֹת אוֹכֵל כָּל מַה שֶּׁנִּדְבָּק בּוֹ תַּחְתָּיו. כְּשֶׁרָצוֹן נִמְצָא וְנֵר דּוֹלֵק בְּחִבּוּר אֶחָד, אָז כָּתוּב (מלכים א יח) וַתִּפֹּל אֵשׁ ה' וַתֹּאכַל אֶת הָעֹלָה וְגוֹ'. וְאָז נוֹדָע שֶׁאוֹתוֹ נֵר דּוֹלֵק בְּחִבּוּר אֶחָד וְקֶשֶׁר אֶחָד. אוֹר תְּכֵלֶת נִדְבָּק בְּאוֹר לָבָן וְהוּא אֶחָד. אוֹכֵל תַּחְתָּיו חֲלָבִים וְעוֹלוֹת שֶׁמַּשְׁמָע שֶׁזֶּה לֹא אוֹכֵל (נ\"א: והוא ועולות שהרי לא אוכל) תַּחְתָּיו, אֶלָּא בִּזְמַן שֶׁהוּא עוֹלֶה (דולק) וְהַכֹּל נִקְשָׁר וּמִתְחַבֵּר בָּאוֹר הַלָּבָן, וְאָז הוּא שְׁלוֹם הָעוֹלָמִים כֻּלָּם, וְהַכֹּל נִקְשָׁר בְּיִחוּד אֶחָד.</p>\n<p>וְאַחַר שֶׁסִּיֵּם לְהַשְׁמִיד תַּחְתָּיו אוֹר תְּכֵלֶת זֶה, מִתְדַּבְּקִים בּוֹ תַּחְתָּיו כֹּהֲנִים לְוִיִּם וְיִשְׂרָאֵל. אֵלֶּה בְּחֶדְוַת הַשִּׁיר, וְאֵלֶּה בִּרְצוֹן הַלֵּב, וְאֵלֶּה בִּתְפִלָּה. וְנֵר דּוֹלֵק עֲלֵיהֶם. וְנִדְבָּקִים הָאוֹרוֹת כְּאֶחָד וּמְאִירִים הָעוֹלָמוֹת, וּמִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>וְאָז וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם. וְאַתֶּם? אַתֶּם צָרִיךְ לִכְתֹּב! אֶלָּא ו' - לְהוֹסִיף עַל חֲלָבִים וְעוֹלוֹת שֶׁהֵם נִדְבָּקִים בּוֹ וְאוֹכְלִים וּמַשְׁמִידִים, וְאַתֶּם מִתְדַּבְּקִים בּוֹ בְּאוֹתוֹ אוֹר תְּכֵלֶת שָׁחֹר שֶׁאוֹכֶלֶת וְאַתֶּם קַיָּמִים. זֶהוּ שֶׁכָּתוּב חַיִּים כֻּלְּכֶם הַיּוֹם.</p>\n<p>(ס\"א ותכלת וארגמן) כָּל הַגְּוָנִים טוֹבִים לַחֲלוֹם, חוּץ מִתְּכֵלֶת שֶׁהוּא אוֹכֵל וּמַשְׁמִיד תָּמִיד, וְהוּא אִילָן שֶׁבּוֹ מָוֶת וְשׁוֹרֶה עַל הָעוֹלָם הַתַּחְתּוֹן. וּמִשּׁוּם שֶׁהַכֹּל שׁוֹרֶה תַחְתָּיו, הוּא אוֹכֵל וּמַשְׁמִיד.</p>\n<p>וְאִם תֹּאמַר כָּךְ, גַּם שׁוֹרֶה בַּשָּׁמַיִם לְמַעְלָה, וְכַמָּה צְבָאוֹת הֵם לְמַעְלָה, וְכֻלָּם (משמידים ואוכלים) קַיָּמִים. בֹּא רְאֵה, כָּל אוֹתָם שֶׁלְּמַעְלָה בְּאוֹתוֹ אוֹר תְּכֵלֶת נִכְלָלִים, אֲבָל הַתַּחְתּוֹנִים לֹא כָּךְ, שֶׁהֵם דָּבָר גַּס, הָעוֹלָם (נ\"א: אחר למטה על מה) שֶׁעוֹמֵד וְשׁוֹרֶה עָלָיו. וְלָכֵן אוֹכֵל וּמַשְׁמִיד אוֹתָם. וְאֵין לָהּ דָּבָר אַחֵר לְמַטָּה בָּעוֹלָם שֶׁלֹּא יֻשְׁמַד, מִשּׁוּם שֶׁאוֹר הַתְּכֵלֶת מַשְׁמִיד כָּל מַה שֶּׁעוֹמֵד עָלָיו.</p>"],[9522011121,"<p>בְּאַרְבָּעִים וַחֲמִשָּׁה גְוָנִים שֶׁל מִינֵי אוֹרוֹת נֶחֱלָק הָעוֹלָם. שִׁבְעָה נֶחֱלָקִים לְשִׁבְעָה תְהוֹמוֹת. כָּל אֶחָד מַכֶּה בַּתְּהוֹם שֶׁלּוֹ, וַאֲבָנִים מִתְגַּלְגְּלוֹת בְּתוֹךְ הַתְּהוֹם, וְנִכְנָס אוֹתוֹ אוֹר בְּאוֹתָם אֲבָנִים וְנוֹקֵב אוֹתָם, וּמַיִם יוֹצְאִים בָּהֶם, וְשׁוֹקְעִים כָּל אֶחָד וְאֶחָד עַל הַתְּהוֹם וּמְכַסֶּה לִשְׁנֵי צְדָדִים.</p>\n<p>יוֹצְאִים מַיִם בְּאוֹתָם נְקָבִים, וְנִכְנָס אוֹר וּמַכֶּה לְאַרְבַּעַת צִדְדֵי הַתְּהוֹם. מִתְגַּלְגֵּל הָאוֹר בְּחֶבְרָתוֹ, וּפוֹגְשִׁים בְּאֶחָד, וְנֶחֱלָקִים הַמַּיִם,</p>\n<p>וְאוֹחֲזִים כָּל אוֹתָם שִׁבְעָה בְּשִׁבְעָה תְהוֹמוֹת, וְכוֹרִים (שורים) בַּחֲשָׁכִים שֶׁל הַתְּהוֹם. וְהַחֲשָׁכִים הַלָּלוּ מִתְעָרְבִים בָּהֶם, וְעוֹלִים הַמַּיִם וְיוֹרְדִים וּמִתְגַּלְגְּלִים בְּאוֹתָם מְאוֹרוֹת. וּמִתְעָרְבִים כְּאֶחָד אוֹרוֹת וְחֹשֶׁךְ וּמַיִם, וְנַעֲשׂוּ מֵהֶם אוֹרוֹת שֶׁלֹּא נִרְאִים חֲשׁוּכִים.</p>\n<p>כָּל אֶחָד מַכֶּה בַּחֲבֵרוֹ, וְנֶחֱלָקִים לְשִׁבְעָה וַחֲמִשָּׁה צִנּוֹרוֹת שֶׁל הַתְּהוֹם, וּבָהֶם זוֹרְמִים מַיִם. כָּל צִנּוֹר וְצִנּוֹר עוֹלֶה בְקוֹלוֹ, וְהַתְּהוֹמוֹת מִזְדַּעְזְעִים. וּכְשֶׁאוֹתוֹ קוֹל נִשְׁמָע, כָּל תְּהוֹם קוֹרֵא לַחֲבֵרוֹ וְאוֹמֵר: חֲלֹק מֵימֶיךְ וְאֶכָּנֵס בְּךְ. זֶהוּ שֶׁכָּתוּב (תהלים מב) תְּהוֹם אֶל תְּהוֹם קוֹרֵא לְקוֹל צִנּוֹרֶיךְ.</p>\n<p>תַּחַת אֵלֶּה שְׁלֹשׁ מֵאוֹת (וששים) וּשְׁמוֹנִים (וחמשה) גִּידִים. מֵהֶם לְבָנִים וּמֵהֶם שְׁחֹרִים וּמֵהֶם אֲדֻמִּים. נִכְלְלוּ זֶה בָּזֶה וְנַעֲשׂוּ גָוֶן אֶחָד. אוֹתָם גִּידִים נִרְקְמוּ בִּשְׁבַע עֶשְׂרֵה רְשָׁתוֹת, וְכָל אַחַת נִקְרֵאת רֶשֶׁת גִּידִים. (התקימו) נִרְקְמוּ זֶה בָּזֶה וְיוֹרְדִים בְּתַחְתִּית הַתְּהוֹם. תַּחַת אֵלֶּה עוֹמְדוֹת שְׁתֵּי רְשָׁתוֹת כְּמַרְאֵה הַבַּרְזֶל, וּשְׁתֵּי רְשָׁתוֹת אֲחֵרוֹת כְּמַרְאֵה הַנְּחֹשֶׁת.</p>\n<p>שְׁנֵי כִסְאוֹת עוֹמְדִים עֲלֵיהֶם, אֶחָד מִיָּמִין וְאֶחָד מִשְּׂמֹאל. כָּל אוֹתָן רְשָׁתוֹת מְחֻבָּרוֹת כְּאֶחָד, וּמַיִם יוֹרְדִים מֵאוֹתָם צִנּוֹרוֹת וְנִכְנָסִים בָּרְשָׁתוֹת הָאֵלֶּה. אוֹתָם שְׁנֵי כִסְאוֹת, אֶחָד כִּסֵּא שֶׁל רָקִיעַ שָׁחֹר, וְאֶחָד כִּסֵּא שֶׁל רָקִיעַ תַּחַשׁ.</p>\n<p>שְׁנֵי הַכִּסְאוֹת הַלָּלוּ, כְּשֶׁהֵם עוֹלִים, עוֹלִים (באחד) בְּאוֹתוֹ כִּסֵּא שֶׁל הָרָקִיעַ הַשָּׁחֹר. וּכְשֶׁיּוֹרְדִים, יוֹרְדִים בְּאוֹתוֹ כִּסֵּא שֶׁל רְקִיעַ הַתַּחַשׁ.</p>\n<p>שְׁנֵי הַכִּסְאוֹת הַלָּלוּ, אֶחָד מִיָּמִין וְאֶחָד מִשְּׂמֹאל. וְאוֹתוֹ כִּסֵּא שֶׁל הָרָקִיעַ הַשָּׁחֹר מִיָּמִין, וְאוֹתוֹ כִּסֵּא שֶׁל רְקִיעַ הַתַּחַשׁ מִשְּׂמֹאל. כְּשֶׁעוֹלִים בַּכִּסֵּא שֶׁל הָרָקִיעַ הַשָּׁחֹר, מַנְמִיךְ הַכִּסֵּא שֶׁל רָקִיעַ שְׂמֹאל וְיוֹרְדִים בּוֹ.</p>\n<p>מִתְגַּלְגְּלִים הַכִּסְאוֹת אֶחָד בְּאֶחָד, (יורדים ולוקחים) לוֹקְחִים כָּל אוֹתָן הָרְשָׁתוֹת לְתוֹכָם וּמַכְנִיסִים אוֹתָם לְתַחְתִּית הַתְּהוֹם הַתַּחְתּוֹנָה. עוֹמֵד כִּסֵּא אֶחָד וְעוֹלֶה לְמַעְלָה מִכָּל אוֹתָם הַתְּהוֹמוֹת, וְעוֹמֵד כִּסֵּא אַחֵר לְמַטָּה שֶׁל כָּל הַתְּהוֹמוֹת. בֵּין שְׁנֵי כִסְאוֹת אֵלּוּ מִתְגַּלְגְּלִים כָּל אוֹתָם תְּהוֹמוֹת. וְכָל אוֹתָם צִנּוֹרוֹת נִנְעֲצוּ בֵּין שְׁנֵי הַכִּסְאוֹת הַלָּלוּ.</p>\n<p>שִׁבְעִים וַחֲמִשָּׁה (אורות) צִנּוֹרוֹת הֵם. שִׁבְעָה הֵם עֶלְיוֹנִים שֶׁל הַכֹּל, וְכָל אוֹתָם אֲחֵרִים אֲחוּזִים בָּהֶם, וְכֻלָּם נְעוּצִים בְּגַלְגַּלֵּי הַכִּסֵּא הַזֶּה בַּצַּד הַזֶּה, וּנְעוּצִים בְּגַלְגַּלֵּי הַכִּסֵּא הַזֶּה בַּצַּד הַזֶּה.</p>\n<p>בָּהֶם (נ\"א: בתהומות) מַיִם עוֹלִים וְיוֹרְדִים. אוֹתָם שֶׁיּוֹרְדִים כּוֹרִים בַּתְּהוֹמוֹת וּבוֹקְעִים אוֹתָם. אוֹתָם שֶׁעוֹלִים נִכְנָסִים בְּאוֹתָם נִקְבֵי הָאֲבָנִים, וְעוֹלִים וּמְמַלְּאִים לְשִׁבְעַת הַיַּמִּים. עַד כָּאן שִׁבְעָה גְוָנִים שֶׁל אוֹרוֹת בְּסוֹד עֶלְיוֹן.</p>\n<p>שִׁבְעָה אוֹרוֹת אֲחֵרִים נֶחֱלָקִים לְשִׁבְעָה יַמִּים, וְיָם אֶחָד כּוֹלֵל אוֹתָם. אוֹתוֹ הַיָּם הָאֶחָד הוּא יָם הָעֶלְיוֹן שֶׁכָּל שִׁבְעַת הַיַּמִּים כְּלוּלִים בּוֹ.</p>\n<p>שִׁבְעָה אוֹרוֹת הַלָּלוּ נִכְנָסִים לְתוֹךְ אוֹתוֹ הַיָּם וּמַכִּים בּוֹ לַיָּם (לשבעים) לְשִׁבְעָה צְדָדִים. וְכָל צַד וְצַד נֶחֱלָק לְשִׁבְעָה נְחָלִים, כַּכָּתוּב (ישעיה יא) וְהִכָּהוּ לְשִׁבְעָה נְחָלִים וְגוֹ'. וְכָל נַחַל וְנַחַל נֶחֱלָק לְשִׁבְעָה נְהָרוֹת, וְכָל נָהָר וְנָהָר נֶחֱלָק לְשֶׁבַע דְּרָכִים, וְכָל דֶּרֶךְ וְדֶרֶךְ נֶחֱלֶקֶת לְשִׁבְעָה שְׁבִילִים, וְכָל מֵימֵי הַיָּם כֻּלָּם נִכְנָסִים לְתוֹכָם.</p>\n<p>שִׁבְעָה אוֹרוֹת עוֹלִים וְיוֹרְדִים לְשִׁבְעָה צְדָדִים. שִׁבְעָה אוֹרוֹת עֶלְיוֹנִים נִכְנָסִים לְתוֹךְ הַיָּם. שִׁשָּׁה הֵם, וּמֵעֶלְיוֹן אֶחָד יוֹצְאִים. כְּמוֹ שֶׁנּוֹטֵל הַיָּם, כָּךְ מְחַלֵּק מֵימָיו לְכָל אוֹתָם יַמִּים, לְכָל אוֹתָם נְהָרוֹת.</p>\n<p>תַּנִּין אֶחָד לְמַטָּה בְּצַד שְׂמֹאל שָׁט בְּכָל אוֹתָם נְהָרוֹת בָּא בַּצַּד. קַשְׂקַשָּׂיו כֻּלָּם חֲזָקִים כְּבַרְזֶל, וּמַגִּיעַ לִשְׁאֹב, וְשׁוֹאֵב מְקוֹמָהּ. וְכָל אוֹתָם הָאוֹרוֹת נֶחְשָׁכִים לְפָנָיו. פִּיו וּלְשׁוֹנוֹ לוֹהֲטִים אֵשׁ. (חד לשונו) מְחֻדֶּדֶת לְשׁוֹנוֹ כְּחֶרֶב חֲזָקָה.</p>\n<p>עֵד שֶׁמַּגִּיעַ לְהִכָּנֵס לַמִּקְדָּשׁ לְתוֹךְ הַיָּם, וְאָז מְטַמֵּא אֶת הַמִּקְדָּשׁ וְהָאוֹרוֹת נֶחְשָׁכִים, וְאוֹרוֹת עֶלְיוֹנִים עוֹלִים מֵהַיָּם. וְאָז נֶחֱלָקִים מֵימֵי הַיָּם בְּצַד שְׂמֹאל, וְהַיָּם קוֹפֵא וּמֵימָיו לֹא זוֹרְמִים.</p>\n<p>וְעַל זֶה סוֹד הַדָּבָר, כְּמוֹ שֶׁכָּתוּב וְהַנָּחָשׁ הָיָה עָרוּם מִכֹּל חַיַּת הַשָּׂדֶה אֲשֶׁר עָשָׂה ה' אֱלֹהִים. סוֹד הַנָּחָשׁ הָרָע יוֹרֵד מִלְּמַטָּה לְמַעְלָה (ס\"י מלמעלה למטה), וְהוּא שָׁט עַל פְּנֵי הַמַּיִם הַמְּרִירִים, וְיוֹרֵד לְפַתּוֹת לְמַטָּה עַד שֶׁיִּפְּלוּ לְתוֹךְ רִשְׁתּוֹ.</p>\n<p>הַנָּחָשׁ הַזֶּה הוּא מָוֶת שֶׁבָּעוֹלָם, וְהוּא נִכְנָס בְּמֵעָיו הַנִּסְתָּרִים שֶׁל הָאָדָם. הוּא לְצַד שְׂמֹאל. וְיֵשׁ נָחָשׁ אַחֵר שֶׁל הַחַיִּים בְּצַד יָמִין. שְׁנֵיהֶם הוֹלְכִים עִם בֶּן הָאָדָם כְּמוֹ שֶׁבֵּאַרְנוּהָ.</p>\n<p>מִכֹּל חַיַּת הַשָּׂדֶה, שֶׁהֲרֵי כָּל שְׁאָר חַיּוֹת הַשָּׂדֶה אֵין בָּהֶם חָכָם לְהָרַע כְּמוֹ זֶה, מִשּׁוּם שֶׁהוּא זֻהֲמַת הַזָּהָב. אוֹי לְמִי שֶׁנִּמְשָׁךְ אַחֲרָיו, שֶׁהוּא גוֹרֵם לוֹ מָוֶת וּלְכָל מִי שֶׁהוֹלֵךְ אַחֲרָיו, וַהֲרֵי בֵּאַרְנוּהָ. אָדָם נִמְשָׁךְ אַחֲרָיו לְמַטָּה וְיוֹרֵד לָדַעַת בְּכָל מַה שֶּׁלְּמַטָּה. כְּמוֹ שֶׁיּוֹרֵד, כָּךְ נִמְשָׁךְ רְצוֹנוֹ וְדַרְכּוֹ אַחֲרֵיהֶם, עַד שֶׁמַּגִּיעִים לַנָּחָשׁ הַזֶּה וְרוֹאִים תַּאֲוַת הָעוֹלָם וּדְרָכָיו שָׁטִים בְּמָקוֹם זֶה. אָז קָם, וְהוּא נִמְשַׁךְ אַחַר אָדָם וְאִשְׁתּוֹ וְנִדְבַּק בָּהֶם, וְגָרַם לָהֶם מָוֶת וּלְכָל הַדּוֹרוֹת שֶׁבָּאוּ אַחֲרָיו. עַד שֶׁהִגִּיעוּ יִשְׂרָאֵל לְהַר סִינַי, לֹא פָסְקָה זֻהַמְתּוֹ מֵהָעוֹלָם, וַהֲרֵי נִתְבָּאֵר. כֵּיוָן שֶׁחָטְאוּ וְנִדְבְּקוּ בָּעֵץ שֶׁשּׁוֹרֶה בּוֹ מָוֶת לְמַטָּה, מַה כָּתוּב? וַיִּשְׁמְעוּ אֶת קוֹל ה' אֱלֹהִים מִתְהַלֵּךְ בַּגָּן. מְהַלֵּךְ אֵין כָּתוּב כָּאן, אֶלָּא מִתְהַלֵּךְ.</p>"],[9522011122,"<p>בֹּא רְאֵה, עַד שֶׁאָדָם לֹא חָטָא, הָיָה עוֹלֶה וְעוֹמֵד בְּחָכְמַת הָאוֹר הָעֶלְיוֹן וְלֹא הָיָה נִפְרָד מֵעֵץ הַחַיִּים. כֵּיוָן שֶׁהִגְדִּיל תַּאֲוָתוֹ לָדַעַת וְלָרֶדֶת לְמַטָּה, נִמְשַׁךְ אַחֲרֵיהֶם עַד שֶׁנִּפְרַד מֵעֵץ הַחַיִּים, וְיָדַע רָע וְעָזַב הַטּוֹב. וְעַל זֶה כָּתוּב (תהלים ה) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגֻרְךְ רָע. מִי שֶׁנִּמְשָׁךְ אַחַר רָע, אֵין לוֹ דִּירָה עִם עֵץ הַחַיִּים.</p>\n<p>וְעַד שֶׁלֹּא חָטְאוּ, הָיוּ שׁוֹמְעִים קוֹל מִלְמַעְלָה וְהָיוּ יוֹדְעִים חָכְמָה עֶלְיוֹנָה וְעוֹמְדִים בַּקִּיּוּם שֶׁל זהַר הָעֶלְיוֹן וְלֹא פוֹחֲדִים. כֵּיוָן שֶׁחָטְאוּ, אֲפִלּוּ קוֹל שֶׁלְּמַטָּה לֹא יָכְלוּ לַעֲמֹד בּוֹ.</p>\n<p>כְּמוֹ זֶה, עַד שֶׁלֹּא חָטְאוּ יִשְׂרָאֵל, בְּשָׁעָה שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי נִתְבַּטְּלָה מֵהֶם זֻהֲמַת הַנָּחָשׁ הַזֶּה, שֶׁהֲרֵי אָז בִּטּוּל יֵצֶר הָרָע הָיָה מֵהָעוֹלָם וְדָחוּ אוֹתוֹ מֵהֶם, וְאָז נֶאֶחְזוּ בְּעֵץ הַחַיִּים וְעָלוּ לְמַעְלָה וְלֹא יָרְדוּ לְמַטָּה.</p>\n<p>אָז הָיוּ יוֹדְעִים וְרוֹאִים אַסְפַּקְלַרְיוֹת עֶלְיוֹנוֹת, וְעֵינֵיהֶם אוֹרוּ וּשְׂמֵחִים לָדַעַת וְלִשְׁמֹעַ. וְאָז חָגַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא חֲגוֹרוֹת שֶׁל אוֹתִיּוֹת שְׁמוֹ הַקָּדוֹשׁ שֶׁלֹּא יוּכַל לִשְׁלֹט עֲלֵיהֶם הַנָּחָשׁ הַזֶּה וְלֹא יְטַמֵּא אוֹתָם כְּמוֹ קֹדֶם.</p>\n<p>כֵּיוָן שֶׁחָטְאוּ בָּעֵגֶל, בָּטְלוּ מֵהֶם כָּל אוֹתָן דְּרָגוֹת וְאוֹרוֹת עֶלְיוֹנִים, וּבָטְלוּ מֵהֶם אוֹתָן חֲגוֹרוֹת מְזֻיָּנוֹת שֶׁהִתְעַטְּרוּ מֵהַשֵּׁם הָעֶלְיוֹן הַקָּדוֹשׁ, וְהִמְשִׁיכוּ עֲלֵיהֶם נָחָשׁ הָרָע כְּמוֹ מִקֹּדֶם וְגָרְמוּ מָוֶת לְכָל הָעוֹלָם. וְאַחַר כָּךְ מַה כָּתוּב? (שמות לד) וַיַּרְא אַהֲרֹן וְכָל בְּנֵי יִשְׂרָאֵל אֶת מֹשֶׁה וְהִנֵּה קָרַן עוֹר פָּנָיו וַיִּירְאוּ מִגֶּשֶׁת אֵלָיו.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב בַּתְּחִלָּה (שמות יד), וירא ישראל את היד הגדלה. וכלם רואים אורות עליונים ומאירים באספקלריה שמאירה, שכתוב, (שם כ) וכל העם ראים את הקולת. ועל הים היו רואים ולא פוחדים, שכתוב (שם טו) זה אלי ואנוהו. אחר שחטאו, פני הסרסור לא היו יכולים לראות, שכתוב (שם לד) וייראו מגשת אליו.</p>"],[9522011123,"<p>בֹּא רְאֵה מַה כָּתוּב בָּהֶם, (שם לג) וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב, שֶׁבָּטְלוּ מֵהֶם אוֹתָם כְּלֵי זַיִן (שהתחברו בהם) (שהתחגרו בהם) בְּהַר סִינַי כְּדֵי שֶׁלֹּא יִשְׁלֹט בָּהֶם נָחָשׁ רָע. כֵּיוָן שֶׁבָּטְלוּ מֵהֶם מַה כָּתוּב? (שם) וּמֹשֶׁה יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה הַרְחֵק מִן הַמַּחֲנֶה.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, מָה הַפָּסוּק הַזֶּה אֶל זֶה? אֶלָּא כֵּיוָן שֶׁיָּדַע מֹשֶׁה שֶׁבָּטְלוּ מִיִּשְׂרָאֵל אוֹתָם כְּלֵי זַיִן עֶלְיוֹנִים, אָמַר, הֲרֵי וַדַּאי מִכָּאן וָהָלְאָה נָחָשׁ רָע יָבֹא לָדוּר בֵּינֵיהֶם, וְאִם יָקוּם כָּאן מִקְדָּשׁ בֵּינֵיהֶם - יִטְמָא. מִיָּד - וּמֹשֶׁה יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה הַרְחֵק מִן הַמַּחֲנֶה. כִּי רָאָה מֹשֶׁה שֶׁהֲרֵי אָז יִשְׁלֹט נָחָשׁ רָע מַה שֶּׁלֹּא הָיָה מִקֹּדֶם לָזֶה.</p>\n<p>וְקָרָא לוֹ אֹהֶל מוֹעֵד, וְכִי לֹא הָיָה בַּהַתְחָלָה אֹהֶל מוֹעֵד? אֶלָּא בַּהַתְחָלָה אֹהֶל סְתָם, וְכָעֵת אֹהֶל מוֹעֵד. מַה זֶּה מוֹעֵד? רַבִּי אֶלְעָזָר אָמַר לְטוֹב, וְרַבִּי אַבָּא אָמַר לְרַע. רַבִּי אֶלְעָזָר אָמַר לְטוֹב - מַה מּוֹעֵד שֶׁהוּא יוֹם חֶדְוָה שֶׁל הַלְּבָנָה שֶׁנִּתּוֹסְפָה בּוֹ קְדֻשָּׁה. (מה מועד) לֹא שׁוֹלֶטֶת בּוֹ חִסָּרוֹן, גַּם כָּאן קָרָא לָהּ בְּשֵׁם זֶה, לְהַרְאוֹת שֶׁהֲרֵי הִתְרַחֵק (נחש) אֹהֶל מִבֵּינֵיהֶם וְלֹא נִפְגַּם, וְעַל זֶה וְקָרָא לוֹ אֹהֶל מוֹעֵד כָּתוּב.</p>\n<p>וְרַבִּי אַבָּא אָמַר לְרַע - שֶׁהֲרֵי בַּהַתְחָלָה הָיָה אֹהֶל סְתָם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה לג) אֹהֶל בַּל יִצְעָן בַּל יִסַּע יְתֵדתָיו לָנֶצַח, וְעַכְשָׁו אֹהֶל מוֹעֵד. בַּהַתְחָלָה לָתֵת חַיִּים אֲרֻכִּים לְעוֹלָמִים שֶׁלֹּא יִשְׁלֹט בָּהֶם מָוֶת, מִכָּאן וָהָלְאָה אֹהֶל מוֹעֵד, כְּמוֹ שֶׁנֶּאֱמַר (איוב ל) וּבֵית מוֹעֵד לְכָל חָי. עַכְשָׁו נִתָּן בּוֹ זְמַן וְחַיִּים קְצוּבִים לָעוֹלָם. בַּהַתְחָלָה לֹא נִפְגַּם, וְעַכְשָׁו נִפְגָּם. בַּהַתְחָלָה חַבְרוּתָא וְזִוּוּג שֶׁל הַלְּבָנָה בַּשֶּׁמֶשׁ שֶׁלֹּא יָסוּרוּ, עַכְשָׁו אֹהֶל מוֹעֵד, הַזִּוּוּג שֶׁלָּהֶם מִזְּמַן לִזְמַן. וְלָכֵן קָרָא לוֹ אֹהֶל מוֹעֵד מַה שֶּׁלֹּא הָיָה קֹדֶם.</p>\n<p>רַבִּי שִׁמְעוֹן הָיָה יוֹשֵׁב לַיְלָה אֶחָד וְעוֹסֵק בַּתּוֹרָה, וְהָיוּ יוֹשְׁבִים לְפָנָיו רַבִּי יְהוּדָה וְרַבִּי יִצְחָק וְרַבִּי יוֹסֵי. אָמַר רַבִּי יְהוּדָה, הֲרֵי כָּתוּב (שמות לג) וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב, וְאָמַרְנוּ שֶׁגָּרְמוּ מָוֶת עֲלֵיהֶם מֵאוֹתוֹ זְמַן וָמַעְלָה, וְשׁוֹלֵט בָּהֶם אוֹתוֹ נָחָשׁ רָע שֶׁהֵסִירוּ אוֹתוֹ מֵהֶם בַּתְּחִלָּה. נַנִּיחַ יִשְׂרָאֵל, אֲבָל יְהוֹשֻׁעַ שֶׁלֹּא חָטָא, בָּטַל (יתבטל) מִמֶּנּוּ אוֹתוֹ כְּלִי זַיִן עֶלְיוֹן שֶׁקִּבֵּל עִמָּם בְּהַר סִינַי אוֹ לֹא.</p>\n<p>אִם תֹּאמַר שֶׁלֹּא בָטַל מִמֶּנּוּ, אִם כָּךְ, לָמָּה מֵת כִּשְׁאָר בְּנֵי אָדָם? אִם תֹּאמַר שֶׁהוּסַר מִמֶּנּוּ - לָמָּה? וַהֲרֵי לֹא חָטָא, שֶׁהֲרֵי הוּא הָיָה עִם מֹשֶׁה בְּשָׁעָה שֶׁחָטְאוּ יִשְׂרָאֵל? וְאִם תֹּאמַר שֶׁלֹּא קִבֵּל אוֹתָהּ עֲטָרָה בְּהַר סִינַי כְּמוֹ שֶׁקִּבְּלוּ יִשְׂרָאֵל - לָמָּה?</p>\n<p>פָּתַח וְאָמַר, (תהלים י) כִּי צַדִּיק ה' צְדָקוֹת אָהֵב יָשָׁר יֶחֱזוּ פָנֵימוֹ. בְּפָסוּק זֶה אָמְרוּ הַחֲבֵרִים מַה שֶּׁאָמְרוּ. אֲבָל כִּי צַדִּיק ה', צַדִּיק הוּא וּשְׁמוֹ צַדִּיק, וְלָכֵן צְדָקוֹת אָהֵב.</p>\n<p>יָשָׁר - הוּא יָשָׁר, כְּמוֹ שֶׁנֶּאֱמַר צַדִּיק וְיָשָׁר. וְעַל זֶה יֶחֱזוּ פָנֵימוֹ, כָּל בְּנֵי הָעוֹלָם, וִיתַקְנוּ דַרְכֵיהֶם לָלֶכֶת בְּדֶרֶךְ יְשָׁרָה כָּרָאוּי. בֹּא רְאֵה, כְּשֶׁדָּן הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, אֵינוֹ דָן אוֹתוֹ אֶלָּא לְפִי רֹב בְּנֵי הָאָדָם.</p>\n<p>וּבֹא וּרְאֵה, כְּשֶׁחָטָא אָדָם בָּעֵץ שֶׁאָכַל מִמֶּנּוּ, גָּרַם לְאוֹתוֹ עֵץ שֶׁשּׁוֹרֶה בּוֹ הַמָּוֶת לְכָל הָעוֹלָם, וְגָרַם פְּגָם לְהַפְרִיד אִשָּׁה מִבַּעְלָהּ, וְעָמַד חֵטְא הַפְּגָם הַזֶּה בַּלְּבָנָה עַד שֶׁעָמְדוּ יִשְׂרָאֵל בְּהַר סִינַי. כֵּיוָן שֶׁעָמְדוּ יִשְׂרָאֵל בְּהַר סִינַי, בָּטַל מֵהֶם אוֹתוֹ פְּגַם הַלְּבָנָה, וְעָמְדָה לְהָאִיר תָּמִיד.</p>\n<p>כֵּיוָן שֶׁחָטְאוּ יִשְׂרָאֵל בָּעֵגֶל, שָׁבָה הַלְּבָנָה לְהִפָּגֵם כְּמוֹ מִקֹּדֶם, וְשָׁלַט הַנָּחָשׁ הָרָע וְאָחַז בָּהּ וּמָשַׁךְ אוֹתָהּ אֵלָיו. וּכְשֶׁיָּדַע מֹשֶׁה שֶׁחָטְאוּ יִשְׂרָאֵל וְהוּסַר מֵהֶם אוֹתָם כְּלֵי זַיִן קְדוֹשִׁים עֶלְיוֹנִים, יָדַע וַדַּאי שֶׁהֲרֵי הַנָּחָשׁ אָחַז בַּלְּבָנָה לְהַמְשִׁיכָהּ אֵלָיו וְנִפְגְּמָה, וְאָז הוֹצִיא אוֹתָהּ הַחוּצָה.</p>\n<p>וְכֵיוָן שֶׁעָמְדָה לְהִפָּגֵם, אַף עַל גַּב שֶׁיְּהוֹשֻׁעַ עָמַד בָּעֲטָרָה שֶׁל כְּלִי הַזַּיִן שֶׁלּוֹ, כֵּיוָן שֶׁהַפְּגָם שָׁרָה בָהּ וְחָזְרָה כְּמוֹ שֶׁנִּפְגְּמָה בַּחֵטְא שֶׁל אָדָם, לֹא יָכוֹל אָדָם לְהִתְקַיֵּם, פְּרָט לְמֹשֶׁה שֶׁהָיָה שׁוֹלֵט בָּהּ, וּמוֹתוֹ הָיָה בְּצַד אַחֵר עֶלְיוֹן. וְעַל זֶה לֹא הָיָה רְשׁוּת בָּהּ לְקַיֵּם אֶת יְהוֹשֻׁעַ תָּמִיד וְלֹא אַחֵר. וְעַל כָּךְ אֹהֶל מוֹעֵד קָרְאוּ לוֹ. אֹהֶל, שֶׁהֲרֵי שׁוֹרֶה בּוֹ זְמַן קָצוּב לְכָל הָעוֹלָם.</p>\n<p>וְעַל זֶה סוֹד הַדָּבָר - יֵשׁ יָמִין לְמַעְלָה וְיֵשׁ יָמִין לְמַטָּה. יֵשׁ שְׂמֹאל לְמַעְלָה וְיֵשׁ שְׂמֹאל לְמַטָּה. יֵשׁ יָמִין לְמַעְלָה בִּקְדֻשָּׁה עֶלְיוֹנָה, וְיֵשׁ יָמִין לְמַטָּה שֶׁהוּא בַּצַּד הָאַחֵר.</p>\n<p>יֵשׁ שְׂמֹאל לְמַעְלָה שֶׁהוּא בִּקְדֻשָּׁה עֶלְיוֹנָה לְעוֹרֵר אַהֲבָה לְקַשֵּׁר אֶת הַלְּבָנָה בְּמָקוֹם קָדוֹשׁ לְמַעְלָה לְהָאִיר, וְיֵשׁ שְׂמֹאל לְמַטָּה שֶׁמַּפְרִיד אַהֲבָה שֶׁלְּמַעְלָה, וּמַפְרִיד אוֹתָהּ מִלְּהָאִיר בַּשֶּׁמֶשׁ וּלְהִתְקָרֵב אֵלָיו, וְזֶהוּ צַד שֶׁל הַנָּחָשׁ הָרָע.</p>\n<p>שֶׁכְּשֶׁשְּׂמֹאל הַזֶּה שֶׁלְּמַטָּה מִתְעוֹרֵר, אָז מוֹשֵׁךְ אֶת הַלְּבָנָה וּמַפְרִיד אוֹתָהּ מִלְמַעְלָה וְנֶחְשָׁךְ אוֹרָהּ וְנִדְבֶּקֶת בַּנָּחָשׁ הָרָע, וְאָז שׁוֹאֶבֶת מָוֶת לְמַטָּה לַכֹּל וְנִדְבֶּקֶת בַּנָּחָשׁ וּמִתְרַחֶקֶת מֵעֵץ הַחַיִּים.</p>\n<p>וְעַל זֶה גָּרַם מָוֶת לְכָל הָעוֹלָם. וְזֶהוּ שֶׁאָז נִטְמָא הַמִּקְדָּשׁ עַד זְמַן קָצוּב שֶׁנִּתְקְנָה הַלְּבָנָה וְשָׁבָה לְהָאִיר, וְזֶהוּ אֹהֶל מוֹעֵד. וְעַל זֶה יְהוֹשֻׁעַ לֹא מֵת אֶלָּא בְּעֶטְיוֹ שֶׁל הַנָּחָשׁ הַזֶּה שֶׁקָּרַב וּפָגַם אֶת הַמִּקְדָּשׁ כְּמוֹ קֹדֶם.</p>\n<p>וְזֶהוּ סוֹד הַכָּתוּב (שמות לג) וִיהוֹשֻׁעַ בִּן נוּן נַעַר לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל. שֶׁאַף עַל גַּב שֶׁהוּא נַעַר לְמַטָּה לְקַבֵּל אוֹר, לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל. כְּמוֹ שֶׁנִּפְגָּם זֶה - כָּךְ גַּם נִפְגָּם זֶה, אַף עַל גַּב שֶׁכְּלִי זַיִן קָדוֹשׁ הָיָה לוֹ. כֵּיוָן שֶׁנִּפְגְּמָה הַלְּבָנָה, כָּךְ הוּא וַדַּאי לֹא נִצָּל לְבַדּוֹ מִמֶּנּוּ מֵאוֹתוֹ גָוֶן מַמָּשׁ.</p>\n<p>בֹּא רְאֵה, כְּמוֹ זֶה, כֵּיוָן שֶׁחָטָא אָדָם, נָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא מִמֶּנּוּ אוֹתָם כְּלֵי זַיִן, אוֹתִיּוֹת מְאִירוֹת קְדוֹשׁוֹת שֶׁעִטֵּר אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאָז פָּחֲדוּ, וְיָדְעוּ שֶׁהֲרֵי הִתְפַּשְּׁטוּ מֵהֶם. זֶהוּ שֶׁכָּתוּב וַיֵּדְעוּ כִּי עֵירֻמִּם הֵם. בַּהַתְחָלָה הָיוּ מִתְלַבְּשִׁים בְּאוֹתָם כִּתְרֵי כָבוֹד מְזֻיָּנִים שֶׁהֵם חֵרוּת מֵהַכֹּל. כֵּיוָן שֶׁחָטְאוּ, הִתְפַּשְּׁטוּ מֵהֶם, וְאָז יָדְעוּ שֶׁהֲרֵי הַמָּוֶת קוֹרֵא לָהֶם, וְיָדְעוּ שֶׁהֻפְשְׁטוּ מֵחֵרוּת הַכֹּל, וְגָרְמוּ מָוֶת לָהֶם וּלְכָל הָעוֹלָם.</p>"],[9522011124,"<p>וַיִּתְפְּרוּ עֲלֵה תְאֵנָה. הֲרֵי פֵּרַשְׁנוּ שֶׁלָּמְדוּ כָּל מִינֵי כְשָׁפִים וּקְסָמִים וְנֶאֶחְזוּ בָּזֶה שֶׁלְּמַטָּה, כְּמוֹ שֶׁנִּתְבָּאֵר. בְּאוֹתָהּ שָׁעָה נִגְרְעָה הַזְּקִיפוּת וְקוֹמַת הָאָדָם מֵאָה אַמּוֹת. וְאָז נַעֲשָׂה פֵרוּד, וְעָמַד אָדָם בְּדִין וְהִתְקַלְלָה הָאָרֶץ, וַהֲרֵי בֵּאַרְנוּ.</p>"],[9522011125,"<p>וַיְגָרֶשׁ אֶת הָאָדָם. אָמַר רַבִּי אֶלְעָזָר, לֹא יָדַעְתִּי מִי עָשָׂה גֵרוּשִׁין לְמִי, אִם הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה גֵרוּשִׁים לָאָדָם אִם לֹא. אֲבָל הַדָּבָר הִתְהַפֵּךְ, וַיְגָרֶשׁ אֶת, אֶ\"ת דַּוְקָא, וּמִי גֵרַשׁ אֶת? הָאָדָם. הָאָדָם וַדַּאי גֵּרַשׁ אֶת,</p>\n<p>וְלָכֵן כָּתוּב וַיְשַׁלְּחֵהוּ ה' אֱלֹהִים מִגַּן עֵדֶן. לָמָּה וַיְשַׁלְּחֵהוּ? מִשּׁוּם שֶׁגֵּרַשׁ אָדָם אֶת, כְּפִי שֶׁבֵּאַרְנוּ. וַיַּשְׁכֵּן - הוּא הִשְׁרָה אוֹתָם בְּמָקוֹם זֶה. שֶׁהוּא גָּרַם וְסָתַם דְּרָכִים וּשְׁבִילִים וְהִשְׁרָה דִינִים עַל הָעוֹלָם, וְהִמְשִׁיךְ קְלָלוֹת מֵאוֹתוֹ יוֹם וָמַעְלָה.</p>\n<p>וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, כָּל אֵלּוּ שֶׁשְּׁרוּיִים בְּזוֹרְקֵי הַדִּינִים עַל הָעוֹלָם, שֶׁמִּתְהַפְּכִים לִגְוָנִים רַבִּים כְּדֵי לְהִפָּרַע מֵהָעוֹלָם. לִפְעָמִים אֲנָשִׁים וְלִפְעָמִים נָשִׁים. לִפְעָמִים אֵשׁ לוֹהֶטֶת וְלִפְעָמִים רוּחוֹת שֶׁאֵין מִי שֶׁיַּעֲמֹד בָּהֶם. וְכָל זֶה לִשְׁמֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים שֶׁלֹּא יוֹסִיפוּ לְהָרַע כְּמִקֹּדֶם.</p>\n<p>לַהַט הַחֶרֶב - אֵלּוּ שֶׁמְּלַהֲטִים אֵשׁ וְתַלְיָנִים עַל רָאשֵׁי הָרְשָׁעִים וְהַחוֹטְאִים. וְהַגְּוָנִים מִתְהַפְּכִים לְכַמָּה מִינִים לְפִי דַרְכֵי בְּנֵי הָאָדָם, וְעַל זֶה לַהַט, כְּמוֹ שֶׁנֶּאֱמַר (מלאכי ג) וְלִהַט אֹתָם הַיּוֹם הַבָּא וְגוֹ', וַהֲרֵי נֶאֱמַר. הַחֶרֶב - זוֹ חֶרֶב לַה', כְּמוֹ שֶׁנֶּאֱמַר (ישעיה לד) חֶרֶב לַה' מְלֵאָה דָּם וְגוֹ'.</p>\n<p>אָמַר רַבִּי יְהוּדָה, לַהַט הַחֶרֶב - (אפלו) כָּל אוֹתָם הַמְמֻנִּים שֶׁלְּמַטָּה שֶׁמִּתְהַפְּכִים מִדְּמוּת לִדְמוּת, כֻּלָּם מְמֻנִּים עַל הָעוֹלָם לְהָרַע וּלְהַסְטוֹת אֶת רִשְׁעֵי הָעוֹלָם שֶׁעוֹבְרִים עַל מִצְווֹת רִבּוֹנָם.</p>\n<p>בֹּא רְאֵה, כֵּיוָן שֶׁאָדָם חָטָא, הִמְשִׁיךְ עָלָיו כַּמָּה מִינִים רָעִים וְכַמָּה בַּעֲלֵי דִינִים, וּפָחַד מִכֻּלָּם וְלֹא יָכֹל לַעֲמֹד עֲלֵיהֶם. שְׁלֹמֹה יָדַע חָכְמָה עֶלְיוֹנָה, וְשָׂם לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עֲטֶרֶת מַלְכוּת, וְכָל הָעוֹלָם הָיָה פוֹחֵד מִמֶּנּוּ. כֵּיוָן שֶׁחָטָא, הִמְשִׁיךְ עָלָיו כַּמָּה מִינִים רָעִים וְכַמָּה בַּעֲלֵי דִינִים, וּפָחַד מִכֻּלָּם, וְאָז יָכְלוּ לְהָרַע לוֹ. וּמַה שֶּׁהָיָה בְּיָדוֹ לָקְחוּ מִמֶּנּוּ.</p>\n<p>וְעַל זֶה, בְּמַה שֶּׁהוֹלֵךְ בֶּן אָדָם וּבְאוֹתָהּ הַדֶּרֶךְ שֶׁנִּדְבָּק בָּהּ, כָּךְ מוֹשֵׁךְ עָלָיו כֹּחַ מְמֻנֶּה שֶׁהוֹלֵךְ כְּנֶגְדּוֹ. כָּךְ אָדָם הָיָה מוֹשֵׁךְ עָלָיו כֹּחַ טָמֵא אַחֵר שֶׁטִּמֵּא אוֹתוֹ וְאֶת כָּל בְּנֵי הָעוֹלָם.</p>\n<p>בֹּא רְאֵה, כְּשֶׁחָטָא אָדָם, מָשַׁךְ עָלָיו כֹּחַ טֻמְאָה וְטִמֵּא אוֹתוֹ וְאֶת כָּל בְּנֵי הָעוֹלָם, וְזֶהוּ נָחָשׁ הָרָע שֶׁהוּא טָמֵא וּמְטַמֵּא אֶת הָעוֹלָם. שֶׁשָּׁנִינוּ, כְּשֶׁמּוֹצִיא נְשָׁמוֹת מִבְּנֵי הָאָדָם, נִשְׁאָר מִמֶּנּוּ גּוּף טָמֵא, וּמְטַמֵּא אֶת הַבַּיִת וּמְטַמֵּא אֶת כָּל אֵלֶּה שֶׁמִּתְקָרְבִים אֵלָיו. זֶהוּ שֶׁכָּתוּב (במדבר יט) הַנֹּגֵעַ בְּמֵת וְגוֹ'.</p>\n<p>וְעַל זֶה, כֵּיוָן שֶׁהוּא נוֹטֵל נְשָׁמָה וּמְטַמֵּא אֶת הַגּוּף, אָז נִתְּנָה רְשׁוּת לְכָל אוֹתָם צְדָדִים טְמֵאִים לִשְׁרוֹת עָלָיו, שֶׁהֲרֵי אוֹתוֹ הַגּוּף נִטְמָא מִן הַצַּד שֶׁל אוֹתוֹ הַנָּחָשׁ הָרָע שֶׁשּׁוֹרֶה עָלָיו. וְעַל זֶה, בְּכָל מָקוֹם שֶׁאוֹתוֹ נָחָשׁ הָרָע שׁוֹרֶה, מְטַמֵּא אוֹתוֹ וְנִטְמָא.</p>\n<p>וּבֹא וּרְאֵה, כָּל בְּנֵי הָעוֹלָם בְּשָׁעָה שֶׁיְּשֵׁנִים עַל מִטּוֹתֵיהֶם בַּלַּיְלָה, וְהַלַּיְלָה פּוֹרֵשׂ כְּנָפָיו עַל כָּל בְּנֵי הָעוֹלָם, טוֹעֲמִים טַעַם הַמָּוֶת. וּמִתּוֹךְ שֶׁטּוֹעֲמִים טַעַם מָוֶת, רוּחַ הַטֻּמְאָה הַזּוֹ שָׁטָה עַל הָעוֹלָם וּמְטַמֵּאת (את) הָעוֹלָם (ד\"א בתוך האהל שלו), וְשׁוֹרָה עַל יְדֵי הָאִישׁ וְנִטְמָא.</p>\n<p>וּכְשֶׁמִּתְעוֹרֵר וְנִשְׁמָתוֹ חוֹזֶרֶת אֵלָיו, בְּכָל מַה שֶּׁיְּקָרֵב בְּיָדוֹ - הַכֹּל נִטְמָא, כִּי שׁוֹרָה עֲלֵיהֶם רוּחַ טֻמְאָה. וְעַל זֶה לֹא יִקַּח אָדָם בְּגָדָיו לִלְבֹּשׁ מִמִּי שֶׁלֹּא נָטַל יָדָיו, שֶׁהֲרֵי הִמְשִׁיךְ עָלָיו אוֹתוֹ רוּחַ טֻמְאָה וְנִטְמָא. וְיֵשׁ רְשׁוּת לְרוּחַ הַטֻּמְאָה הַזּוֹ לִשְׁרוֹת בְּכָל מָקוֹם שֶׁנִּמְצָא רֹשֶׁם מִצִּדּוֹ.</p>\n<p>וְלָכֵן לֹא יִטֹּל אָדָם יָדָיו מִמִּי שֶׁלֹּא נָטַל יָדָיו, מִשּׁוּם שֶׁהִמְשִׁיךְ עָלָיו אוֹתוֹ רוּחַ טֻמְאָה וְקִבְּלוֹ זֶה שֶׁנָּטַל מַיִם מִמֶּנּוּ, וְיֵשׁ לוֹ רְשׁוּת לִשְׁרוֹת עַל הָאָדָם. לָכֵן צָרִיךְ אָדָם לְהִשָּׁמֵר בְּכָל צְדָדָיו מִצַּד הַנָּחָשׁ הָרָע הַזֶּה שֶׁלֹּא יִשְׁלֹט עָלָיו, וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לָעוֹלָם הַבָּא לְבַטְּלוֹ מִן הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ, וְאָז כָּתוּב (ישעיה כב) בִּלַּע הַמָּוֶת לָנֶצַח וְגוֹ'.</p>"],[9522011126,"<p>וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ וְגוֹ'. רַבִּי אַבָּא פָּתַח וְאָמַר, (קהלת ג) מִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעֹלָה הִיא לְמָעְלָה וְרוּחַ הַבְּהֵמָה הַיֹּרֶדֶת הִיא לְמַטָּה לָאָרֶץ. לַפָּסוּק הַזֶּה יֵשׁ כַּמָּה גְוָנִים, וְכֵן הוּא כָּל דִּבְרֵי הַתּוֹרָה יֵשׁ בְּכָל אֶחָד וְאֶחָד כַּמָּה גְוָנִים, וְכֻלָּם נְאוֹתִים וְכָךְ הֵם.</p>\n<p>וְכָל הַתּוֹרָה מִתְפָּרֶשֶׁת בְּשִׁבְעִים פָּנִים כְּנֶגֶד שִׁבְעִים צְדָדִים וְשִׁבְעִים עֲנָפִים, וְכָךְ הוּא בְּכָל דָּבָר וְדָבָר שֶׁל הַתּוֹרָה. וְכָל מַה שֶּׁיּוֹצֵא מִכָּל דָּבָר וְדָבָר, כַּמָּה אֳפָנִים מִתְפָּרְשִׁים מִמֶּנּוּ לְכָל הַצְּדָדִים.</p>\n<p>בֹּא רְאֵה, כְּשֶׁבֶּן אָדָם הוֹלֵךְ בְּדֶרֶךְ אֱמֶת, הוּא הוֹלֵךְ לְיָמִין וּמַמְשִׁיךְ עָלָיו רוּחַ קְדוֹשָׁה עֶלְיוֹנָה מִלְמַעְלָה, וְרוּחַ זוֹ עוֹלָה בְרָצוֹן קָדוֹשׁ לְהֵאָחֵז לְמַעְלָה וּלְהִדָּבֵק בִּקְדֻשָּׁה עֶלְיוֹנָה שֶׁלֹּא תָזוּז מִמֶּנּוּ.</p>\n<p>וּכְשֶׁאָדָם הוֹלֵךְ בְּדֶרֶךְ רָעָה וְסוֹטֶה בִּדְרָכָיו, הוּא מוֹשֵׁךְ עָלָיו רוּחַ טֻמְאָה שֶׁלְּצַד שְׂמֹאל, וּמְטַמֵּא אוֹתוֹ וְנִטְמָא בּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא יא) וְלֹא תִטַּמְּאוּ בָּהֶם וְנִטְמֵתֶם בָּם. בָּא לְהִטָּמֵא - מְטַמְּאִים אוֹתוֹ.</p>\n<p>וּבֹא וּרְאֵה, בְּשָׁעָה שֶׁבֶּן אָדָם הוֹלֵךְ בְּדֶרֶךְ אֱמֶת וּמוֹשֵׁךְ עָלָיו רוּחַ קְדֻשָּׁה עֶלְיוֹנָה וְנִדְבָּק בָּהּ, הַבֵּן שֶׁיּוֹלִיד וְיֵצֵא מִמֶּנּוּ לָעוֹלָם הוּא מַמְשִׁיךְ עָלָיו קְדֻשָּׁה עֶלְיוֹנָה וְיִהְיֶה קָדוֹשׁ בִּקְדֻשַּׁת רִבּוֹנוֹ, כְּמוֹ שֶׁכָּתוּב (שם כ) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים וְגוֹ'.</p>\n<p>וּכְשֶׁהוּא הוֹלֵךְ בְּצַד שְׂמֹאל וּמַמְשִׁיךְ עָלָיו רוּחַ טֻמְאָה וְנִדְבָּק בּוֹ, הַבֵּן שֶׁיֵּצֵא מִמֶּנּוּ לָעוֹלָם הוּא מַמְשִׁיךְ עָלָיו רוּחַ טֻמְאָה וְיִטְמָא בְּטֻמְאַת אוֹתוֹ הַצַּד.</p>\n<p>וְעַל זֶה כָּתוּב, מִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעֹלָה הִיא לְמָעְלָה. וּכְשֶׁהוּא בְּהִדָּבְקוּת הַיָּמִין, הִיא עוֹלָה לְמַעְלָה. וּכְשֶׁהוּא בְּהִדָּבְקוּת הַשְּׂמֹאל, אוֹתוֹ צַד שְׂמֹאל שֶׁהוּא רוּחַ טֻמְאָה יוֹרֵד מִלְמַעְלָה לְמַטָּה, וְשָׂם דִּיּוּרוֹ בְּבֶן הָאָדָם וְלֹא זָז מִמֶּנּוּ. וְהַבֵּן (ומה) שֶׁהוֹלִיד בְּאוֹתָהּ (רוח) טֻמְאָה הוּא נִהְיָה בְּנוֹ מֵאוֹתוֹ רוּחַ הַטֻּמְאָה הוּא אוֹתוֹ הַבֵּן.</p>\n<p>אָדָם נִדְבַּק בְּאוֹתוֹ רוּחַ טָמֵא, וְאִשְׁתּוֹ נִדְבְּקָה בּוֹ בַּהַתְחָלָה, וְלָקְחָה וְקִבְּלָה אוֹתָהּ זֻהֲמָה מִמֶּנָּה הוֹלִיד בֵּן. בֵּן זֶה הוּא בֵּן שֶׁל רוּחַ הַטֻּמְאָה. וְעַל זֶה שְׁנֵי בָנִים הֵם - אֶחָד מֵאוֹתוֹ רוּחַ טָמֵא, וְאֶחָד כְּשֶׁשָּׁב אָדָם בִּתְשׁוּבָה. וְלָכֵן זֶה מִצַּד הַטֻּמְאָה, (וזה) וְזֶה מִצַּד הַטָּהֳרָה.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, בְּשָׁעָה שֶׁהִטִּיל נָחָשׁ אוֹתָהּ זֻהֲמָה בְּחַוָּה, הִיא קִבְּלָה אוֹתוֹ, וּכְשֶׁשִּׁמֵּשׁ עִמָּהּ אָדָם, הוֹלִידָה שְׁנֵי בָנִים - אֶחָד מֵאוֹתוֹ צַד טָמֵא, וְאֶחָד מִצַּד שֶׁל אָדָם. וְהֶבֶל הָיָה דּוֹמֶה בִּדְמוּת עֶלְיוֹנָה, וְקַיִן בִּדְמוּת תַּחְתּוֹנָה, וְלָכֵן דַּרְכֵיהֶם נִפְרְדוּ זֶה מִזֶּה.</p>\n<p>וַדַּאי שֶׁקַּיִן הָיָה בֵּן שֶׁל רוּחַ הַטֻּמְאָה שֶׁהוּא הַנָּחָשׁ הָרָע (והבל בן של אדם) הָיָה. וּבִגְלַל שֶׁקַּיִן בָּא מִצַּד שֶׁל מַלְאַךְ הַמָּוֶת, הָרַג אֶת אָחִיו, וְהוּא בְּצִדּוֹ, וּמִמֶּנּוּ כָּל הַמְּדוֹרִים הָרָעִים וּמַזִּיקִים וְשֵׁדִים וְרוּחוֹת בָּאִים לָעוֹלָם.</p>\n<p>אָמַר רַבִּי יוֹסֵי, קַיִן - קֵן שֶׁל מְדוֹרִים רָעִים שֶׁבָּאוּ מִצַּד הַטֻּמְאָה לָעוֹלָם. וְאַחַר כָּךְ הֵבִיאוּ קָרְבָּן. זֶה הִקְרִיב מִצַּד שֶׁלּוֹ, וְזֶה הִקְרִיב מִצַּד שֶׁלּוֹ. זֶהוּ שֶׁכָּתוּב וַיְהִי מִקֵּץ יָמִים וַיָּבֵא קַיִן מִפְּרִי הָאֲדָמָה וְגוֹ'. רַבִּי שִׁמְעוֹן אָמַר, וַיְהִי מִקֵּץ יָמִים, מַה זֶּה מִקֵּץ יָמִים? זֶהוּ קֵץ כָּל בָּשָׂר. וּמִיהוּ זֶה? מַלְאַךְ הַמָּוֶת.</p>\n<p>וְקַיִן מֵאוֹתוֹ קֵץ יָמִים הֵבִיא קָרְבָּן. דַּוְקָא שֶׁאָמַר מִקֵּץ יָמִים וְלֹא אָמַר מִקֵּץ יָמִין. וְלָכֵן כָּתוּב בְּדָנִיֵּאל (דניאל יב) וְאַתָּה לֵךְ לַקֵּץ וְתָנוּחַ וְתַעֲמֹד לְגֹרָלְךְ. אָמַר לוֹ, לְקֵץ הַיָּמִים אוֹ לְקֵץ הַיָּמִין? אָמַר לוֹ, לְקֵץ הַיָּמִין. וְקַיִן הֵבִיא מִקֵּץ הַיָּמִים.</p>\n<p>וַיָּבֵא קַיִן מִפְּרִי הָאֲדָמָה, כְּמוֹ שֶׁנֶּאֱמַר וּמִפְּרִי הָעֵץ. אָמַר רַבִּי אֶלְעָזָר, מִפְּרִי הָאֲדָמָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ג) אוֹי לְרָשָׁע רָע כִּי גְמוּל יָדָיו וְגוֹ' (כי פרי מעלליהם יאכלו, פרי מעלליהם יאכלו זה מלאך המות יאכלו). (גמול ידיו זה מלאך המות, יעשה לו שנמשך) עֲלֵיהֶם וְיִדְבַּק בָּהֶם לַהֲרֹג אוֹתָם וּלְטַמֵּא אוֹתָם. וְעַל זֶה קַיִן הִקְרִיב מִצִּדּוֹ.</p>\n<p>וְהֶבֶל הֵבִיא גַם הוּא מִבְּכֹרוֹת - לְרַבּוֹת הַצַּד הָעֶלְיוֹן שֶׁבָּא מִצַּד הַקְּדֻשָּׁה (מצד קדוש), וְלָכֵן וַיִּשַׁע ה' אֶל הֶבֶל וְאֶל מִנְחָתוֹ וְאֶל קַיִן וְאֶל מִנְחָתוֹ לֹא שָׁעָה. לֹא קִבֵּל אוֹתָם (אותו) הַקָּדוֹשׁ בָּרוּךְ הוּא. וְלָכֵן וַיִּחַר לְקַיִן מְאֹד וַיִּפְּלוּ פָּנָיו. שֶׁהֲרֵי לֹא הִתְקַבְּלוּ פָנָיו, אוֹתָם פָּנִים שֶׁל צִדּוֹ, וְקִבֵּל אֶת הֶבֶל.</p>\n<p>וְלָכֵן כָּתוּב וַיְהִי בִּהְיוֹתָם בַּשָּׂדֶה. בַּשָּׂדֶה זוֹ הָאִשָּׁה, כְּמוֹ שֶׁנֶּאֱמַר (דברים כב) כִּי בַּשָּׂדֶה מְצָאָהּ. וְקַיִן קִנֵּא עַל הַנְּקֵבָה הַיְתֵרָה שֶׁנּוֹלְדָה עִם הֶבֶל, שֶׁכָּתוּב וַתֹּסֶף לָלֶדֶת, וַהֲרֵי נֶאֱמַר.</p>"],[9522011127,"<p>הֲלוֹא אִם תֵּיטִיב שְׂאֵת, כְּמוֹ שֶׁנֶּאֱמַר. אֲבָל שְׂאֵת כְּמוֹ שֶׁאָמַר רַבִּי אַבָּא, שְׂאֵת תַּעֲלֶה לְמַעְלָה וְלֹא תֵרֵד לְמַטָּה. אָמַר רַבִּי יוֹסֵי, דָּבָר זֶה כָּעֵת נֶאֱמָר וְנָאֶה הוּא, אֲבָל כָּךְ שָׁמַעְתִּי, שְׂאֵת יַעֲלֶה מִמְּךְ וְיַעֲזֹב לְךְ הִדָּבְקוּת זוֹ שֶׁל רוּחַ הַטֻּמְאָה.</p>\n<p>וְאִם לֹא - לַפֶּתַח חַטָּאת רֹבֵץ. מַה זֶּה לַפֶּתַח? זֶה הַדִּין הָעֶלְיוֹן שֶׁהוּא הַפֶּתַח שֶׁל הַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק. חַטָּאת רֹבֵץ - אוֹתוֹ הַצַּד שֶׁנִּדְבְּקָה בּוֹ וְנִמְשָׁךְ עָלֶיךְ, יִשְׁמֹר אוֹתְךְ לְהִפָּרַע מִמְּךְ, כְּתַרְגּוּמוֹ.</p>"],[9522011128,"<p>אָמַר רַבִּי יִצְחָק, בֹּא רְאֵה, בְּשָׁעָה שֶׁקַּיִן הָרַג אֶת הֶבֶל, לֹא יָדַע אֵיךְ יוֹצִיא (יוצאת) נִשְׁמָתוֹ מִמֶּנּוּ, וְהָיָה נוֹשֵׁךְ אוֹתוֹ בְּשִׁנָּיו כְּנָחָשׁ, וַהֲרֵי בֵּאֲרוּהָ הַחֲבֵרִים. בְּאוֹתָהּ הַשָּׁעָה קִלְּלוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהָיָה הוֹלֵךְ לְכָל צִדְדֵי הָעוֹלָם, וְלֹא הָיָה מָקוֹם שֶׁמְּקַבֵּל אוֹתוֹ, עַד שֶׁטָּפַח עַל רֹאשׁוֹ וְשָׁב לִפְנֵי רִבּוֹנוֹ, וְהָאָרֶץ קִבְּלָה אוֹתוֹ בַּמָּדוֹר הַתַּחְתּוֹן לְמַטָּה.</p>\n<p>רַבִּי יוֹסֵי אָמַר, הָאָרֶץ קִבְּלָה אוֹתוֹ לָלֶכֶת בָּהּ, שֶׁכָּתוּב וַיָּשֶׂם ה' לְקַיִן אוֹת. רַבִּי יִצְחָק אָמַר, לֹא כָּךְ, אֶלָּא לְמַטָּה קִבְּלָה אוֹתוֹ הָאָרֶץ בְּמָדוֹר אֶחָד שֶׁתַּחְתֶּיהָ, שֶׁכָּתוּב הֵן גֵּרַשְׁתָּ אֹתִי הַיּוֹם מֵעַל פְּנֵי הָאֲדָמָה. מֵעַל פְּנֵי הָאֲדָמָה גֹּרַשׁ, אֲבָל לְמַטָּה לֹא גֹרַשׁ.</p>\n<p>וּבְאֵיזֶה מָקוֹם קִבְּלָה אוֹתוֹ הָאֲדָמָה? בְּאַרְקָא, וְעַל כָּל אֵלֶּה שֶׁדָּרִים שָׁם כָּתוּב (ירמיה י) יֹאבְדוּ מִן הָאָרֶץ וּמִתַּחַת הַשָּׁמַיִם הָאֵלֶּה. וְשָׁם שָׂם אֶת מְדוֹרוֹ, וְהַיְנוּ שֶׁכָּתוּב וַיֵּשֶׁב בְּאֶרֶץ נוֹד קִדְמַת עֵדֶן.</p>\n<p>כֵּיוָן שֶׁאָמַר קַיִן גָּדוֹל עֲוֹנִי מִנְּשׂוֹא, מָחַל לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא חֲצִי מֵעָנְשׁוֹ. מִשּׁוּם שֶׁגָּזַר עָלָיו בַּהַתְחָלָה וְאָמַר לוֹ נָע וָנָד תִּהְיֶה בָאָרֶץ, וְעַכְשָׁו נִשְׁאָר בְּנוֹד בִּלְבַדּוֹ. זֶהוּ שֶׁכָּתוּב וַיֵּצֵא קַיִן מִלִּפְנֵי ה' וְגוֹ'. כְּלוֹמַר, שֶׁכְּשֶׁיָּצָא מִלִּפְנֵי ה' הָיָה בִּשְׁבִיל לִהְיוֹת נָד בָּאָרֶץ וְלֹא נָע.</p>\n<p>וְעוֹד אָמְרוּ, כְּשֶׁיָּצָא קַיִן מִלִּפְנֵי ה', אָמַר לוֹ אָדָם: בְּנִי, מַה נַּעֲשָׂה עַל דִּינְךְ? אָמַר לוֹ קַיִן: אַבָּא, כְּבָר הִתְבַּשַּׂרְתִּי שֶׁמָּחַל לִי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּנוֹד בִּלְבַדּוֹ. אָמַר לוֹ: הֵיאַךְ הוּא? אָמַר לוֹ: מִשּׁוּם שֶׁחָטָאתִי וְהוֹדֵיתִי לְפָנָיו. אָמַר אָדָם: וְכִי זֶהוּ גֹּדֶל וְחֹזֶק כֹּחַ הַתְּשׁוּבָה וַאֲנִי לֹא יָדַעְתִּי!? הִתְחִיל לְשַׁבֵּחַ לְרִבּוֹנוֹ וּלְהוֹדוֹת לוֹ. פָּתַח וְאָמַר (תהלים צב) מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת טוֹב לְהוֹדוֹת לַה'. כְּלוֹמַר, טוֹב לְשַׁבֵּחַ וְלָשׁוּב וּלְהִתְוַדּוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. עד כאן התוספתא.</p>\n<p>וְאָמַר רַבִּי יִצְחָק, מֵאוֹתָהּ שָׁעָה שֶׁהָרַג קַיִן אֶת הֶבֶל, שֶׁנִּפְרַד (נפרד) אָדָם מֵאִשְׁתּוֹ, שְׁתֵּי רוּחוֹת נְקֵבוֹת הָיוּ בָּאוֹת וּמִזְדַּוְּגוֹת עִמּוֹ, וְהוֹלִיד רוּחוֹת וְשֵׁדִים שֶׁמְּשׁוֹטְטִים בָּעוֹלָם.</p>\n<p>וְזֶה לֹא יַקְשֶׁה לְךְ, שֶׁהֲרֵי בֶּן אָדָם כְּשֶׁהוּא בַּחֲלוֹמוֹ, בָּאוֹת רוּחוֹת נְקֵבוֹת וְצוֹחֲקוֹת עִמּוֹ וּמִתְחַמְּמוֹת מִמֶּנּוּ וּמוֹלִידוֹת אַחַר כָּךְ, וְאֵלֶּה נִקְרָאִים נִגְעֵי בְּנֵי אָדָם, וְלֹא מִתְהַפְּכִים אֶלָּא לִדְמֻיּוֹת בְּנֵי אָדָם, וְאֵין לָהֶם שְׂעָרוֹת בָּרֹאשׁ. וְעַל זֶה כָּתוּב בִּשְׁלֹמֹה (שמואל ב ז) וְהוֹכַחְתִּיו בְּשֵׁבֶט אֲנָשִׁים וּבְנִגְעֵי בְּנֵי אָדָם. וַאֲפִלּוּ כְּמוֹ זֶה רוּחוֹת זְכָרִים בָּאִים לִנְשׁוֹת הָעוֹלָם, וְהֵן מִתְעַבְּרוֹת מֵהֶם וּמוֹלִידוֹת רוּחוֹת. וְכֻלָּם נִקְרָאִים נִגְעֵי בְּנֵי אָדָם.</p>\n<p>אַחַר מֵאָה וּשְׁלוֹשִׁים שָׁנִים הִתְלַבֵּשׁ אָדָם בְּקִנְאָה וְהִתְחַבֵּר בְּאִשְׁתּוֹ, וְהוֹלִיד בֵּן וְקָרָא שְׁמוֹ שֵׁ\"ת. סוֹד שֶׁל סוֹף הָאוֹתִיּוֹת בִּקְשָׁרִים חֲקוּקִים. רַבִּי יְהוּדָה אָמַר, סוֹד שֶׁל רוּחַ שֶׁאוֹבֶדֶת שֶׁמִּתְלַבֶּשֶׁת בְּגוּף (של הארץ) אַחֵר בָּעוֹלָם, זֶהוּ שֶׁכָּתוּב כִּי שָׁת לִי אֱלֹהִים זֶרַע אַחֵר תַּחַת הֶבֶל.</p>\n<p>וְאָמַר רַבִּי יְהוּדָה, כָּתוּב וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ, מַשְׁמָע שֶׁבָּנִים אֲחֵרִים לֹא הָיוּ (בדמותו כצלמו, ודבר זה הוא) בִּדְמוּתוֹ. וְזֶה בִּדְמוּתוֹ כְּצַלְמוֹ, בְּתִקּוּן הַגּוּף וּבְתִקּוּן הַנֶּפֶשׁ בְּדֶרֶךְ יָשָׁר. (נ\"א: ודבר זה הוא כמו שנאמר, ואמר רבי אבא משם רבי ייסא) כְּמוֹ שֶׁאָמַר רַבִּי שִׁמְעוֹן מִשֵּׁם רַבִּי יֵיבָא הַזָּקֵן, בָּנִים אֲחֵרִים בְּהִתְדַּבְּקוּת זֻהֲמַת הַנָּחָשׁ, וְאוֹתוֹ שֶׁרוֹכֵב עָלָיו, שֶׁהוּא סָמָאֵ\"ל הָיוּ, וְלָכֵן לֹא הָיָה בִּדְמוּת אָדָם. וְאִם תֹּאמַר, הֲרֵי אָמַרְתָּ שֶׁהֶבֶל הָיָה מִצַּד אַחֵר - כָּךְ הוּא! אֲבָל שְׁנֵיהֶם לֹא הָיוּ בַּדְּמוּת שֶׁלְּמַטָּה.</p>\n<p>אָמַר (לו) רַבִּי יוֹסֵי, וַהֲרֵי כָּתוּב וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ וַתַּהַר וַתֵּלֶד אֶת קַיִן, וְלֹא (ד\"א אמר לה כך הוא, אבל שניהם לא היו בדמותו, שלא) כָתוּב וַיּוֹלֶד אֶת קַיִן. וַאֲפִלּוּ בְּהֶבֶל לֹא כָתוּב וַיּוֹלֶד, אֶלָּא וַתֹּסֶף לָלֶדֶת אֶת אָחִיו אֶת הָבֶל. וְזֶהוּ סוֹד הַדָּבָר. אֲבָל בָּזֶה מַה כָּתוּב? וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, מֵאָה וּשְׁלוֹשִׁים שָׁנִים נִפְרַד אָדָם מֵאִשְׁתּוֹ, וְכָל אוֹתָם מֵאָה וּשְׁלוֹשִׁים הַשָּׁנִים הָיָה מוֹלִיד רוּחוֹת וְשֵׁדִים בָּעוֹלָם בִּגְלַל אוֹתוֹ כֹּחַ הַזֻּהֲמָה שֶׁהָיָה שָׁאוּב בּוֹ. כֵּיוָן שֶׁחִסֵּל מִמֶּנּוּ אוֹתָהּ הַזֻּהֲמָה, שָׁב וְקִנֵּא (שעבר) אֶת אִשְׁתּוֹ וְהוֹלִיד בֵּן. אָז כָּתוּב וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ.</p>\n<p>בֹּא רְאֵה, כָּל בֶּן אָדָם שֶׁהוֹלֵךְ לְצַד שְׂמֹאל וּמְטַמֵּא אֶת דְּרָכָיו, כָּל רוּחוֹת הַטֻּמְאָה מוֹשֵׁךְ עַל עַצְמוֹ, וְרוּחַ טֻמְאָה נִדְבֶּקֶת בּוֹ וְלֹא זָזָה מִמֶּנּוּ, וְהִתְדַּבְּקוּת (שלו) שֶׁל אוֹתוֹ רוּחַ טָמֵא יִהְיֶה בָּאִישׁ הַזֶּה וְלֹא בְאַחֵר, וְלָכֵן הִתְדַּבְּקוּתָם אֵינָהּ אֶלָּא בְּאֵלֶּה שֶׁנִּדְבָּקִים בָּהֶם. אַשְׁרֵי הַצַּדִּיקִים שֶׁהוֹלְכִים בְּדֶרֶךְ יְשָׁרָה, וְהֵם צַדִּיקֵי אֱמֶת, וּבְנֵיהֶם צַדִּיקִים בָּעוֹלָם, וַעֲלֵיהֶם כָּתוּב (משלי ב) כִּי יְשָׁרִים יִשְׁכְּנוּ אָרֶץ.</p>\n<p>אָמַר רַבִּי חִיָּיא, מַה שֶּׁכָּתוּב וַאֲחוֹת תּוּבַל קַיִן נַעֲמָה, מַה קָּרָה כָּאן שֶׁהַכָּתוּב אָמַר שֶׁשְּׁמָהּ נַעֲמָה? אֶלָּא מִשּׁוּם שֶׁטָּעוּ בְּנֵי אָדָם אַחֲרֶיהָ וַאֲפִלּוּ רוּחוֹת וְשֵׁדִים. רַבִּי יִצְחָק אָמַר, אוֹתָם בְּנֵי הָאֱלֹהִים עֲזָא וַעֲזָאֵל טָעוּ אַחֲ רֶיהָ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, אִמָּם שֶׁל הַשֵּׁדִים הָיְתָה שֶׁיָּצְאָה מִצַּד קַיִן, וְהִיא הִתְמַנְּתָה עַל הַלַּיְלָה (עם לילית) בְּאַסְכָּרָה שֶׁל תִּינוֹקוֹת. אָמַר לוֹ רַבִּי אַבָּא, וַהֲרֵי אָמַר מַר שֶׁהִיא הִתְמַנְּתָה לְצַחֵק בִּבְנֵי אָדָם? אָמַר לוֹ, כָּךְ הוּא וַדַּאי, שֶׁהֲרֵי הִיא בָּאָה וּמְצַחֶקֶת בָּהֶם בִּבְנֵי אָדָם, וְלִפְעָמִים מוֹלִידָה רוּחוֹת בָּעוֹלָם מֵהֶם, וְעַד עַכְשָׁו הִיא עוֹמֶדֶת לְצַחֵק בִּבְנֵי אָדָם.</p>\n<p>אָמַר לוֹ רַבִּי אַבָּא, וַהֲרֵי הֵם מֵתִים כִּבְנֵי אָדָם, מָה הַטַּעַם הִיא עוֹמֶדֶת עַד עַכְשָׁו? אָמַר לוֹ, כָּךְ זֶה! אֲבָל לִילִית וְנַעֲמָה וְאַגְרַת בַּת מָחֲלַת שֶׁיָּצְאָה מֵהַצַּד שֶׁלָּהֶם, כֻּלָּן קַיָּמוֹת, עַד שֶׁיְּבַעֵר הַקָּדוֹשׁ בָּרוּךְ הוּא רוּחַ הַטֻּמְאָה מִן הָעוֹלָם, שֶׁכָּתוּב (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אוֹי לָהֶם לְאוֹתָם בְּנֵי אָדָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים וְלֹא מִסְתַּכְּלִים וְכֻלָּם אֲטוּמִים, שֶׁלֹּא יוֹדְעִים כַּמָּה מָלֵא הָעוֹלָם מִבְּרִיּוֹת מְשֻׁנּוֹת שֶׁלֹּא נִרְאוֹת וּמִדְּבָרִים נִסְתָּרִים. שֶׁאִלְמָלֵא (נתן) נִתְּנָה רְשׁוּת לָעַיִן לִרְאוֹת, יִתְמְהוּ בְּנֵי אָדָם אֵיךְ יְכוֹלִים לְהִתְקַיֵּם בָּעוֹלָם.</p>\n<p>בֹּא רְאֵה, נַעֲמָה הַזּוֹ, אֵם הַשֵּׁדִים הָיְתָה, וּמִצִּדָּהּ בָּאִים כָּל אוֹתָם שֵׁדִים שֶׁמִּתְחַמְּמִים בִּבְנֵי אָדָם וְלוֹקְחִים מֵהֶם רוּחַ תַּאֲוָה, וְצוֹחֶקֶת בָּהֶם, שֶׁעוֹשִׂים אוֹתָם בַּעֲלֵי קֶרִי. וּבִגְלַל שֶׁבַּעַל קֶרִי בָּא מִצַּד שֶׁל רוּחַ הַטֻּמְאָה, צָרִיךְ לִרְחֹץ עַצְמוֹ לְהִטָּהֵר מִמֶּנּוּ. וַהֲרֵי בֵּאֲרוּהָ הַחֲבֵרִים:</p>\n<p>זֶה סֵפֶר תּוֹלְדת אָדָם - לִדְמֻיּוֹתָיו. אָמַר רַבִּי יִצְחָק, הֶרְאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָדָם דְּמֻיּוֹת שֶׁל כָּל אוֹתָם דּוֹרוֹת שֶׁיָּבאוּ לָעוֹלָם, וְכָל חַכְמֵי הָעוֹלָם וּמַלְכֵי הָעוֹלָם שֶׁעֲתִידִים לַעֲמֹד עַל יִשְׂרָאֵל. הִגִּיעַ לִרְאוֹת אֶת דָּוִד מֶלֶךְ יִשְׂרָאֵל שֶׁנּוֹלַד וּמֵת. אָמַר לוֹ, (אמר) מֵהַשָּׁנִים שֶׁלִּי (אוסיף) אַלְוֶה לוֹ שִׁבְעִים שָׁנִים. וְגָרְעוּ מֵאָדָם שִׁבְעִים שָׁנִים וְהֶעֱלָה אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא לְדָוִד.</p>\n<p>וְעַל זֶה שִׁבַּח דָּוִד וְאָמַר, (תהלים צב) כִּי שִׂמַּחְתַּנִי ה' בְּפָעֳלֶךְ בְּמַעֲשֵׂי יָדֶיךְ אֲרַנֵּן. מִי גָרַם לִי חֶדְוָה בָּעוֹלָם (הזה)? פָּעֳלֶךְ, זֶהוּ אָדָם הָרִאשׁוֹן שֶׁהוּא פָעֳלוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא פָעֳלוֹ שֶׁל בָּשָׂר וָדָם, מַעֲשֵׂה יָדָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא מִבְּנֵי אָדָם. וְעַל זֶה גָּרְעוּ אוֹתָם שִׁבְעִים שָׁנִים מֵאָדָם מֵאֶלֶף שָׁנִים שֶׁהָיוּ לוֹ לְהִתְקַיֵּם בָּהֶם.</p>\n<p>וְהֶרְאָה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל חַכְמֵי דּוֹר וָדוֹר, עַד שֶׁהִגִּיעַ לְדוֹרוֹ שֶׁל רַבִּי עֲקִיבָא, וְרָאָה תוֹרָה שֶׁלּוֹ וְשָׂמַח. רָאָה מִיתָתוֹ וְהִתְעַצֵּב. פָּתַח וְאָמַר, (תהלים קלט) וְלִי מַה יָּקְרוּ רֵעֶיךְ אֵל מֶה עָצְמוּ רָאשֵׁיהֶם.</p>\n<p>זְהִ סֵפֶר - סֵפֶר וַדַּאי. וַהֲרֵי בֵּאַרְנוּ, כְּשֶׁהָיָה אָדָם בְּגַן עֵדֶן, הוֹרִיד לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא סֵפֶר עַל יְדֵי הַמַּלְאָךְ רָזִיאֵל הַקָּדוֹשׁ הַמְמֻנֶּה עַל הַסּוֹדוֹת הָעֶלְיוֹנִים הַקְּדוֹשִׁים, וּבוֹ חֲקוּקִים חֲקִיקוֹת עֶלְיוֹנוֹת וְחָכְמָה קְדוֹשָׁה, וְשִׁבְעִים וּשְׁנַיִם מִינֵי חָכְמָה הָיוּ מִתְפָּרְשִׁים מִמֶּנּוּ לְשֵׁשׁ מֵאוֹת וְשִׁבְעִים חֲקִיקוֹת שֶׁל סוֹדוֹת עֶלְיוֹנִים.</p>\n<p>בְּאֶמְצַע הַסֵּפֶר חֲקִיקַת הַחָכְמָה לָדַעַת אֶלֶף וַחֲמֵשׁ מֵאוֹת מַפְתְּחוֹת שֶׁלֹּא נִמְסְרוּ לְעֶלְיוֹנִים קְדוֹשִׁים, וְכֻלָּם נִסְתָּרִים בַּסֵּפֶר, עַד שֶׁהִגִּיעַ (לו לאדם, כיון שהגיע) אֵצֶל אָדָם, מִמֶּנּוּ הָיוּ מִתְכַּנְּסִים מַלְאָכִים עֶלְיוֹנִים לָדַעַת וְלִשְׁמֹעַ, וְהָיוּ אוֹמְרִים (שם נז) רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים עַל כָּל הָאָרֶץ כְּבוֹדֶךְ.</p>\n<p>בְּאוֹתָהּ שָׁעָה נִרְמַז אֵלָיו לְהדרניא\"ל הַמַּלְאָךְ הַקָּדוֹשׁ, וְאָמַר לוֹ: אָדָם, אָדָם, גְּנֹז אֶת כְּבוֹד רִבּוֹנְךְ, שֶׁלֹּא נִתְּנָה רְשׁוּת לָעֶלְיוֹנִים לָדַעַת בִּכְבוֹד רִבּוֹנְךְ פְּרָט לְךְ. וְהָיָה הַסֵּפֶר הַהוּא שָׁמוּר וְגָנוּז עִמּוֹ עַד שֶׁיָּצָא אָדָם מִגַּן עֵדֶן.</p>\n<p>שֶׁהֲרֵי בַּהַתְחָלָה הָיָה מְעַיֵּן בּוֹ וּמִשְׁתַּמֵּשׁ כָּל יוֹם בְּגִנְזֵי רִבּוֹנוֹ, וְהִתְגַּלּוּ לוֹ סוֹדוֹת עֶלְיוֹנִים מַה שֶּׁלֹּא יָדְעוּ שַׁמָּשִׁים עֶלְיוֹנִים. כֵּיוָן שֶׁחָטָא וְעָבַר עַל מִצְוַת רִבּוֹנוֹ, פָּרַח מִמֶּנּוּ אוֹתוֹ הַסֵּפֶר, וְהָיָה אָדָם טוֹפֵחַ עַל רֹאשׁוֹ וּבוֹכֶה, וְנִכְנַס בְּמֵי גִיחוֹן עַד צַוָּארוֹ, וְהַמַּיִם עוֹשִׂים אֶת גּוּפוֹ נְקָבִים נְקָבִים וְהִשְׁתַּנָּה זִיווֹ.</p>\n<p>בְּאוֹתָהּ שָׁעָה רָמַז הַקָּדוֹשׁ בָּרוּךְ הוּא לִרְפָאֵל, וְהֵשִׁיב לוֹ אוֹתוֹ הַסֵּפֶר, וּבוֹ הָיָה אָדָם עוֹסֵק וְהִנִּיחוֹ לְשֵׁת בְּנוֹ, וְכֵן לְכָל אוֹתָם צֶאֱצָאִים, עַד שֶׁהִגִּיעַ לְאַבְרָהָם, וּבוֹ הָיָה יוֹדֵעַ לְהִסְתַּכֵּל בִּכְבוֹד רִבּוֹנוֹ, וַהֲרֵי נֶאֱמַר. וְכֵן לַחֲנוֹךְ נִתַּן לוֹ הַסֵּפֶר וְהִסְתַּכֵּל מִמֶּנּוּ בַּכָּבוֹד הָעֶלְיוֹן.</p>"],[9522011129,"<p>זָכָר וּנְקֵבָה בְּרָאָם. רַבִּי שִׁמְעוֹן אָמַר, סוֹדוֹת עֶלְיוֹנִים הִתְגַּלּוּ בִּשְׁנֵי הַפְּסוּקִים הַלָּלוּ. זָכָר וּנְקֵבָה בְּרָאָם לָדַעַת הַכָּבוֹד הָעֶלְיוֹן, סוֹד הָאֱמוּנָה, שֶׁמִּתּוֹךְ סוֹד זֶה נִבְרָא אָדָם.</p>\n<p>בֹּא רְאֵה, בַּסּוֹד שֶׁל שָׁמַיִם וָאָרֶץ נִבְרָא אָדָם, בָּהֶם כָּתוּב אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ (בהבראם). בְּאָדָם כָּתוּב זֶה סֵפֶר תּוֹלְדת אָדָם. בָּהֶם כָּתוּב בְּהִבָּרְאָם, וּבְאָדָם כָּתוּב בְּיוֹם הִבָּרְאָם.</p>\n<p>זָכָר וּנְקֵבָה בְּרָאָם. מִכָּאן, כָּל דְּמוּת שֶׁלֹּא נִמְצָא בָּהּ זָכָר וּנְקֵבָה, אֵינָהּ דְּמוּת עֶלְיוֹנָה כָּרָאוּי, וּבְסוֹד הַמִּשְׁנָה בֵּאַרְנוּ.</p>\n<p>בֹּא רְאֵה, בְּכָל מָקוֹם שֶׁלֹּא נִמְצָאִים זָכָר וּנְקֵבָה כְּאֶחָד, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא שָׂם אֶת מְדוֹרוֹ בְּאוֹתוֹ הַמָּקוֹם, וְהַבְּרָכוֹת לֹא נִמְצָאוֹת רַק בְּמָקוֹם שֶׁנִּמְצָאִים זָכָר וּנְקֵבָה, שֶׁכָּתוּב וַיְבָרֶךְ אֹתָם וַיִּקְרָא אֶת שְׁמָם אָדָם בְּיוֹם הִבָּרְאָם, וְלֹא כָתוּב וַיְבָרֶךְ אוֹתוֹ וַיִּקְרָא אֶת שְׁמוֹ אָדָם. שֶׁאֲפִלּוּ אָדָם לֹא נִקְרָא אֶלָּא זָכָר וּנְקֵבָה כְּאֶחָד.</p>\n<p>רַבִּי יְהוּדָה אָמַר, מִיּוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ לֹא נִמְצָאוֹת בְּרָכוֹת בָּעוֹלָם, וְהֵם אוֹבְדוֹת בְּכָל יוֹם, שֶׁכָּתוּב (ישעיה נז) הַצַּדִּיק אָבָד. מָה אָבַד? אִבֵּד הַבְּרָכוֹת שֶׁהָיוּ שׁוֹרוֹת בּוֹ, כְּמוֹ שֶׁכָּתוּב (משלי י) בְּרָכוֹת לְרֹאשׁ צַדִּיק. וְכָתוּב (ירמיה ז) אָבְדָה הָאֱמוּנָה. כְּמוֹ זֶה כָּתוּב וַיְבָרֶךְ אֹתָם, וְכָתוּב וַיְבָרֶךְ אֹתָם אֱלֹהִים. מִשֵּׁ\"ת הִתְיַחֲסוּ כָּל דּוֹרוֹת הָעוֹלָם וְכָל אוֹתָם צַדִּיקֵי אֱמֶת שֶׁהָיוּ בָּעוֹלָם.</p>\n<p>אָמַר רַבִּי יוֹסֵי, הָאוֹתִיּוֹת הָאַחֲרוֹנוֹת הַלָּלוּ שֶׁהָיוּ בַּתּוֹרָה (להמצא) נִמְצְאוּ אַחַר שֶׁעָבַר אָדָם עַל אוֹתִיּוֹת הַתּוֹרָה כֻּלָּם (בסדר תשר\"ק, ולכן קרא לאותו הבן שהוא כדמותו כצלמו ש\"ת, שהם קיום האותיות). וּבִתְשׁוּבָתוֹ (ובתשוקתו) לִפְנֵי רִבּוֹנוֹ אָחַז בִּשְׁנֵי אֵלֶּה, וּמֵאָז חָזְרוּ הָאוֹתִיּוֹת לְמַפְרֵעַ בְּסֵדֶר תשר\"ק.</p>\n<p>וְלָכֵן קָרָא לְאוֹתוֹ בֵּן שֶׁנּוֹלַד לוֹ שֶׁהוּא בִּדְמוּתוֹ בְּצַלְמוֹ שֵׁ\"ת, שֶׁהֵם סִיּוּם הָאוֹתִיּוֹת. וְלֹא נִתְקְנוּ הָאוֹתִיּוֹת עַד שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי, וְאָז חָזְרוּ הָאוֹתִיּוֹת עַל תִּקּוּנָם כְּיוֹם שֶׁנִּבְרְאוּ שָׁמַיִם וָאָרֶץ, וְהִתְבַּסֵּם הָעוֹלָם וְעָמַד עַל קִיּוּמוֹ.</p>\n<p>רַבִּי אַבָּא אָמַר, בְּיוֹם שֶׁעָבַר אָדָם עַל מִצְוַת רִבּוֹנוֹ, רָצוּ שָׁמַיִם וָאָרֶץ (להנגף) לְהֵעָקֵר מִמְּקוֹמָם. מָה הַטַּעַם? מִשּׁוּם שֶׁהֵם לֹא עָמְדוּ רַק עַל הַבְּרִית, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. וְאָדָם עָבַר בְּרִית, שֶׁנֶּאֱמַר (הושע ו) וְהֵמָּה כְּאָדָם עָבְרוּ בְרִית.</p>\n<p>וְאִלְמָלֵא שֶׁגָּלוּי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁעֲתִידִים יִשְׂרָאֵל לַעֲמֹד עַל הַר סִינַי לְקַיֵּם אֶת הַבְּרִית הַ את, לֹא הִתְקַיֵּם הָעוֹלָם (הזה). רַבִּי חִזְקִיָּה אָמַר, כָּל מִי שֶׁמּוֹדֶה עַל חֶטְאוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא מֵנִיחַ לוֹ וּמוֹחֵל לוֹ עַל חֶטְאוֹ.</p>\n<p>בֹּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה בְּרִית זוֹ וְהֶעֱמִיד עָלֶיהָ אֶת הָעוֹלָם. מִנַּיִן לָנוּ? שֶׁכָּתוּב (בראשית), בָּרָא שִׁית. זוֹ הַבְּרִית שֶׁהָעוֹלָם עוֹמֵד עָלֶיהָ. שִׁית שֶׁמִּמֶּנּוּ שׁוֹפְעִים וְיוֹצְאִים בְּרָכוֹת לָעוֹלָם, וְעָלֶיהָ נִבְרָא הָעוֹלָם. וְאָדָם עָבַר עַל הַבְּרִית הַזּוֹ וְהֶעֱבִירָהּ מִמְּקוֹמָהּ (ס\"א מעמו).</p>\n<p>בְּרִית זוֹ נִרְמְזָה בָּאוֹת יוֹ\"ד, אוֹת קְטַנָּה עִקַּר וִיסוֹד הָעוֹלָם. כְּשֶׁהוֹלִיד בֵּן, הוֹדָה עַל חֶטְאוֹ וְקָרָא שְׁמוֹ שֵׁ\"ת, וְלֹא הִזְכִּיר בּוֹ יוֹ\"ד לִהְיוֹת שִׁית, מִשּׁוּם שֶׁעָבַר עָלָיו. וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא (מכאן) מִמֶּנּוּ שָׁתַל אֶת הָעוֹלָם, וְהִתְיַחֲסוּ כָּל דּוֹרוֹת צַדִּיקֵי הָעוֹלָם (משת).</p>\n<p>וּבֹא וּרְאֵה, כְּשֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי, נִכְנַס בֵּין שְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ סוֹד הַבְּרִית, וּמִיהוּ? בֵּי\"ת. וְנִכְנַס בֵּין שְׁתֵּי הָאוֹתִיּוֹת שֶׁנִּשְׁאֲרוּ, וְנָתַן אוֹתָהּ לְיִשְׂרָאֵל. וּכְשֶׁנִּכְנְסָה בֵּי\"ת, סוֹד הַבְּרִית, בֵּין שְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ, שֶׁהֵם שִׁי\"ן תָּי\"ו, (נכנסו) וְנַעֲשׂוּ שַׁבָּת, כְּמוֹ שֶׁנֶּאֱמַר (שמות לא) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת לַעֲשׂוֹת אֶת הַשַּׁבָּת לְדרֹתָם בְּרִית עוֹלָם. כְּמוֹ שֶׁהָיָה רֵאשִׁית הָעוֹלָם לְהִתְיַחֵס בָּהֶם כָּל דּוֹרוֹת הָעוֹלָם מִשְּׁתֵּי הָאוֹתִיּוֹת הַלָּלו ש\"ת, הָיוּ תְּלוּיִים עַד שֶׁנִּתְקַן הָעוֹלָם כָּרָאוּי וְנִכְנַס בֵּינֵיהֶם הַבְּרִית הַקָּדוֹשׁ, וְנִתְקַן בִּשְׁלֵמוּת וְנַעֲשָׂה שַׁבָּ\"ת.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אֵלּוּ שְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ נִתְקְנוּ בָּאוֹת בֵּי\"ת, וּכְשֶׁחָזְרוּ הָאוֹתִיּוֹת לְמַפְרֵעַ מִיּוֹם שֶׁנּוֹלַד שֵׁת, חָזְרוּ הָאוֹתִיּוֹת בְּכָל דּוֹר וָדוֹר עַד שֶׁהִגִּיעוּ יִשְׂרָאֵל לְהַר סִינַי וְנִתְקְנוּ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, לְמַטָּה חָזְרוּ. וּבְכָל דּוֹר וָדוֹר הָיָה מְחֻבָּק הָעוֹלָם בָּאוֹתִיּוֹת וְלֹא מִתְיַשְּׁבִים בִּמְקוֹמָם. כְּשֶׁנִּתְּנָה הַתּוֹרָה לְיִשְׂרָאֵל, הַכֹּל נִתְקַן (נ\"א: כל האותיות נתקנו). רַבִּי אֶלְעָזָר אוֹמֵר, בִּימֵי אֱנוֹשׁ הָיוּ הָאֲנָשִׁים חֲכָמִים בְּחָכְמָה שֶׁל כְּשָׁפִים וְקוֹסְמִים וּבְחָכְמָה לַעֲצֹר אֶת חֵילוֹת הַשָּׁמַיִם. וְלֹא הָיָה בֶּן אָדָם מִיּוֹם שֶׁיָּצָא אָדָם מִגַּן עֵדֶן וְהוֹצִיא עִמּוֹ חָכְמָה שֶׁל הֶעָלִים שֶׁל הָאִילָן שֶׁהִתְעַסֵּק בָּהּ. שֶׁהֲרֵי אָדָם וְאִשְׁתּוֹ, וְאוֹתָם שֶׁיָּצְאוּ מִמֶּנּוּ עַד שֶׁבָּא אֱנוֹשׁ, עָזְבוּ אוֹתָהּ.</p>\n<p>כְּשֶׁבָּא אֱנוֹשׁ, רָאָה אוֹתָם וְרָאָה אֶת חָכְמָתָם מְשַׁנָּה (ס\"א משטה) אֶת הָעֶלְיוֹנִים, וְעָסְקוּ בָהֶם וְעָשׂוּ (בהם) מַעֲשִׂים וּכְשָׁפִים וּקְסָמִים וְלָמְדוּ מֵהֶם, עַד שֶׁהִתְפַּשְּׁטָה אוֹתָהּ חָכְמָה בְּדוֹר הַמַּבּוּל. וְכֻלָּם הָיוּ עוֹשִׂים מַעֲשֵׂיהֶם לְהָרַע.</p>\n<p>וְהָיוּ מִתְחַזְּקִים כְּלַפֵּי נֹחַ בְּאוֹתָן חָכְמוֹת, וְאוֹמְרִים שֶׁלֹּא יָכוֹל דִּין הָעוֹלָם לִשְׁרוֹת עֲלֵיהֶם, שֶׁהֲרֵי הֵם עוֹשִׂים חָכְמָה לִדְחוֹת אֶת כָּל אוֹתָם בַּעֲלֵי הַדִּין. וּמֵאֱנוֹשׁ הִתְחִילוּ כֻלָּם לְהִתְעַסֵּק בַּחָכְמוֹת הַלָּלוּ. זֶהוּ שֶׁכָּתוּב אָז הוּחַל לִקְרֹא בְּשֵׁם ה'.</p>\n<p>רַבִּי יִצְחָק אָמַר, כָּל אוֹתָם צַדִּיקִים שֶׁהָיוּ בֵינֵיהֶם אַחַר אוֹתוֹ הַדּוֹר, כֻּלָּם הָיוּ מִשְׁתַּדְּלִים לִמְחוֹת בָּהֶם (נ\"א: כדי שלא יענשו עליהם), כְּמוֹ יֶרֶד מְתוּשֶׁלַח וַחֲנוֹךְ, וְלֹא יָכְלוּ, עַד שֶׁהִתְפַּשְּׁטוּ רְשָׁעִים הַמּוֹרְדִים בְּרִבּוֹנָם, וְאָמְרוּ (איוב כא) מַה שַּׁדַּי כִּי נַעַבְדֶנּוּ.</p>\n<p>וְכִי הַטִּפְּשׁוּת הַזּוֹ הֵם הָיוּ אוֹמְרִים? אֶלָּא מִשּׁוּם שֶׁהָיוּ יוֹדְעִים כָּל אוֹתָם הַחָכְמוֹת וְכָל אוֹתָם הַמְמֻנִּים שֶׁל הָעוֹלָם שֶׁהֻפְקְדוּ עֲלֵיהֶם וְהָיוּ סוֹמְכִים עֲלֵיהֶם, עַד שֶׁהֵשִׁיב הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם כְּשֶׁהָיָה. שֶׁהֲרֵי בַּתְּחִלָּה הָיָה מַיִם בְּמַיִם, אַחַר כָּךְ הֵשִׁיב הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם כְּבַתְּחִלָּה, וְלֹא נֶחֱרַב מֵהַכֹּל, שֶׁהֲרֵי בְּרַחֲמִים הִשְׁגִּיחַ עֲלֵיהֶם, שֶׁכָּתוּב (תהלים כט) ה' לַמַּבּוּל יָשָׁב, וְלֹא כָתוּב אֱלֹהִים.</p>\n<p>בִּימֵי אֱנוֹשׁ אֲפִלּוּ תִּינוֹקוֹת שֶׁל אוֹתוֹ (היום) הַדּוֹר הָיוּ מַשְׁגִּיחִים בְּחָכְמוֹת עֶלְיוֹנוֹת וְהָיוּ מִסְתַּכְּלִים בָּהֶם. אָמַר רַבִּי יֵיסָא, אִם כָּךְ, טִפְּשִׁים הָיוּ שֶׁלֹּא הָיוּ יוֹדְעִים שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָבִיא עֲלֵיהֶם מֵי מַבּוּל וְיָמוּתוּ בָהֶם?</p>\n<p>אָמַר רַבִּי יִצְחָק, יָדוֹעַ הָיוּ יוֹדְעִים, אֲבָל אָחֲזוּ טִפְּשׁוּת בְּלִבָּם. שֶׁהֵם הָיוּ יוֹדְעִים אוֹתוֹ מַלְאָךְ הַמְמֻנֶּה עַל אֵשׁ וְאוֹתוֹ הַמְמֻנֶּה עַל הַמַּיִם, וְהָיוּ יוֹדְעִים לַעֲצֹר אוֹתָם שֶׁלֹּא יוּכְלוּ לַעֲשׂוֹת דִּין עֲלֵיהֶם. וְהֵם לֹא הָיוּ יוֹדְעִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵט עַל הָאָרֶץ וּמִמֶּנּוּ יָבֹא דִין עַל הָעוֹלָם?</p>\n<p>אֶלָּא הָיוּ רוֹאִים שֶׁהָעוֹלָם הֻפְקַד בִּידֵי אוֹתָם מְמֻנִּים, וּבָהֶם כָּל דִּבְרֵי הָעוֹלָם, וְלָכֵן לֹא הָיוּ מִסְתַּכְּלִים בַּקָּדוֹשׁ-בָּרוּךְ-הוּא וְלֹא מַשְׁגִּיחִים בְּמַעֲשָׂיו עַד שֶׁהָאָרֶץ נִשְׁחֲתָה. וְרוּחַ הַקֹּדֶשׁ מַכְרִיזָה בְּכָל יוֹם וְאוֹמֶרֶת: יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ וּרְשָׁעִים עוֹד אֵינָם.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֶאֱרִיךְ לָהֶם כָּל אוֹתוֹ הַזְּמַן שֶׁאוֹתָם צַדִּיקִים, יֶרֶד וּמְתוּשֶׁלַח וַחֲנוֹךְ, קַיָּמִים בָּעוֹלָם. כֵּיוָן שֶׁהִסְתַּלְּקוּ מֵהָעוֹלָם, אָז הוֹרִיד הַקָּדוֹשׁ בָּרוּךְ הוּא דִּין עֲלֵיהֶם וְנֶאֶבְדוּ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ז) וַיִּמָּחוּ מִן הָאָרֶץ.</p>"],[9522011130,"<p>וַיִּתְהַלֵּךָ חֲנוֹךְ אֶת הָאֱלֹהִים וְאֵינֶנּוּ כִּי לָקַח אֹתוֹ אֱלֹהִים. רַבִּי יוֹסֵי פָּתַח, (שיר א) עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. פָּסוּק זֶה נֶאֱמַר. אֲבָל בּא רְאֵה, כָּךְ דַּרְכּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא - בְּשָׁעָה שֶׁבֶּן אָדָם נִדְבָּק בּוֹ וְהוּא מַשְׁרֶה דִיּוּרוֹ עָלָיו וְיוֹדֵעַ שֶׁאַחַר יָמִים הוּא יִסְרַח, מַקְדִּים וְלוֹקֵט רֵיחוֹ הַטּוֹב מִמֶּנּוּ וּמְסַלֵּק אוֹתוֹ מֵהָעוֹלָם.</p>\n<p>זֶהוּ שֶׁכָּתוּב עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. עַד שֶׁהַמֶּלֶךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. בִּמְסִבּוֹ - זֶה אוֹתוֹ בֶּן אָדָם שֶׁנִּדְבָּק בּוֹ וְהוֹלֵךְ בִּדְרָכָיו. נִרְדִּי נָתַן רֵיחוֹ - אוֹתָם מַעֲשִׂים טוֹבִים שֶׁבּוֹ שֶׁבִּגְלָלָם יִסְתַּלֵּק מֵהָעוֹלָם בְּטֶרֶם הִגִּיעַ זְמַנּוֹ.</p>\n<p>וְעַל זֶה הָיָה שְׁלֹמֹה הַמֶּלֶךְ אוֹמֵר (קהלת ח) יֵשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ אֲשֶׁר יֵשׁ צַדִּיקִים וְגוֹ'. יֵשׁ צַדִּיקִים אֲשֶׁר מַגִּיעַ אֲלֵיהֶם כְּמַעֲשֵׂה הָרְשָׁעִים - כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁבִּשְׁבִיל מַעֲשִׂים טוֹבִים הַקָּדוֹשׁ בָּרוּךְ הוּא מְסַלְּקָם מֵהָעוֹלָם (כדי שלא יתקלקלו (יחיו), ומתוך אהבתו בהם מסלק אותם) בְּטֶרֶם הִגִּיעַ זְמַנָּם, וְעוֹשֶׂה בָהֶם דִּינִים. וְיֵשׁ רְשָׁעִים שֶׁמַּגִּיעַ אֲלֵהֶם כְּמַעֲשֵׂה הַצַּדִּיקִים - שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַאֲרִיךְ לָהֶם יָמִים וּמַאֲרִיךְ בָּהֶם אֶת רֻגְזוֹ, וְכָל זֶה כְּמוֹ שֶׁנִּתְבָּאֵר. אֵלֶּה בִּשְׁבִיל שֶׁלֹּא יִתְקַלְקְלוּ, וְאֵלֶּה כְּדֵי שֶׁיַּחְזְרוּ אֵלָיו, אוֹ כְּדֵי שֶׁיֵּצְאוּ מֵהֶם בָּנִים מְעֻלִּים.</p>\n<p>בֹּא רְאֵה, חֲנוֹךְ הָיָה צַדִּיק, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רָאָה שֶׁאַחַר כָּךְ יְקַלְקֵל, וְלָקַח אוֹתוֹ בְּטֶרֶם יְקַלְקֵל. זֶהוּ שֶׁכָּתוּב (שיר ו) וְלִלְקֹט שׁוֹשַׁנִּים. מִשּׁוּם שֶׁנּוֹתְנִים רֵיחַ טוֹב, לוֹקֵחַ אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּטֶרֶם יְקַלְקְלוּ. וְאֵינֶנּוּ כִּי לָקַח אֹתוֹ אֱלֹהִים. וְאֵינֶנּוּ - לְהַאֲרִיךְ יָמִים כִּשְׁאָר בְּנֵי אָדָם שֶׁהָיוּ מַאֲרִיכִים יָמִים. מָה הַטַּעַם? כִּי לָקַח אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּטֶרֶם הִגִּיעַ זְמַנּוֹ.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, הַקָּדוֹשׁ בָּרוּךְ הוּא נְטָלוֹ אֶת חֲנוֹךְ וְהֶעֱלָהוּ לִשְׁמֵי מְרוֹמִים, וּמָסַר בְּיָדָיו כָּל הַגְּנָזִים הָעֶלְיוֹנִים וַחֲמִשָּׁה וְאַרְבָּעִים מַפְתְּחוֹת סְתָרִים חֲקוּקִים שֶׁבָּהֶם מִשְׁתַּמְּשִׁים מַלְאָכִים עֶלְיוֹנִים, וְכֻלָּם נִמְסְרוּ בְּיָדוֹ, וַהֲרֵי בֵּאַרְנוּ.</p>"],[9522011131,"<p>וַיַּרְא ה' כִּי רַבָּה רָעַת הָאָדָם בָּאָרֶץ וְכָל יֵצֶר מַחְשְׁבֹת לִבּוֹ. רַבִּי יְהוּדָה פָּתַח, (תהלים ה) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגֻרְךְ רָע. פָּסוּק זֶה נֶאֱמַר וּבֵאַרְנוּהוּ. אֲבָל בּא רְאֵה, מִי שֶׁנִּדְבָּק בַּיֵּצֶר הָרָע וְנִמְשָׁךְ אַחֲרָיו, יִטְמָא הוּא וִיטַמְּאוּ אוֹתוֹ, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>כִּי רַבָּה רָעַת הָאָדָם - כָּל הָרָעוֹת הָיוּ עוֹשִׂים, וְלֹא נִשְׁלַם חֶטְאָם עַד שֶׁהָיוּ שׁוֹפְכִים דָּמִים לְחִנָּם עַל הָאָרֶץ. וּמִי הֵם שֶׁהָיוּ מַשְׁחִיתִים דַּרְכָּם עַל הָאָרֶץ? זֶהוּ שֶׁכָּתוּב רַק רַע כָּל הַיּוֹם. כָּתוּב כָּאן רַק רַע, וְכָתוּב שָׁם (לא יגרך רע, וכתוב) (בראשית לח) וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי ה'.</p>\n<p>אָמַר רַבִּי יוֹסֵי, וְכִי רָע אֵינוֹ רָשָׁע? אָמַר לוֹ, לֹא. רָשָׁע - אֲפִלּוּ הֵרִים יָדוֹ עַל חֲבֵרוֹ, אַף עַל גַּב שֶׁלֹּא עָשָׂה לוֹ דָבָר, נִקְרָא רָשָׁע, כְּמוֹ שֶׁכָּתוּב (שמות ב) וַיֹּאמֶר לָרָשָׁע לָמָּה תַכֶּה רֵעֶךְ. הִכִּיתָ לֹא כָתוּב, אֶלָּא תַּכֶּה.</p>\n<p>אֲבָל רַע לֹא נִקְרָא אֶלָּא מִי שֶׁמַּשְׁחִית דַּרְכּוֹ וּמְטַמֵּא עַצְמוֹ וּמְטַמֵּא אֶת הָאָרֶץ, וְנוֹתֵן כֹּחַ וְחֹזֶק לְרוּחַ הַטֻּמְאָה שֶׁנִּקְרֵאת רַע, שֶׁכָּתוּב רַק רַע כָּל הַיּוֹם. וְלֹא נִכְנָס בְּפַלְטֵרִין וְלֹא רוֹאֶה פְּנֵי שְׁכִינָה, מִשּׁוּם שֶׁבָּזֶה מִסְתַּלֶּקֶת שְׁכִינָה מִן הָעוֹלָם.</p>\n<p>וּמִנַּיִן לָנוּ? מִיַּעֲקֹב. שֶׁכְּשֶׁהִסְתַּלְּקָה מִמֶּנּוּ שְׁכִינָה, חָשַׁב שֶׁיֵּשׁ פְּסוּל בְּבָנָיו שֶׁבִּגְלָלָם הִתְחַזְּקָה בָּעוֹלָם רוּחַ הַטֻּמְאָה וְנִגְרַע הָאוֹר מֵהַלְּבָנָה וּפָגַם אוֹתָהּ. וְאִם תֹּאמַר לָמָּה? מִשּׁוּם זֶה מְטַמֵּא אֶת הַמִּקְדָּשׁ וְהִסְתַּלְּקָה שְׁכִינָה מֵעַל יַעֲקֹב. כָּל שֶׁכֵּן אוֹתוֹ שֶׁמְּטַמֵּא דַרְכּוֹ וּמְטַמֵּא עַצְמוֹ שֶׁהוּא מְחַזֵּק אֶת רוּחַ הַטֻּמְאָה, וְלָכֵן כְּשֶׁנִּטְמָא נִקְרָא רַע.</p>\n<p>בֹּא רְאֵה, כְּשֶׁבֶּן אָדָם נִטְמָא, לֹא נִפְקָד מִן הַקָּדוֹשׁ בָּרוּךְ הוּא לְטוֹב, וּבְכָל פַּעַם נִפְקָד מֵאוֹתוֹ שֶׁנִּקְרָא רַע לְרַע. זֶהוּ שֶׁכָּתוּב (משלי יט) וְשָׂבֵעַ יָלִין בַּל יִפָּקֶד רָע. כְּשֶׁהוֹלֵךְ בְּדֶרֶךְ יָשָׁר, אָז בַּל יִפָּקֶד רָע. וְעַל זֶה כָּתוּב רַק רַע כָּל הַיּוֹם, וְכָתוּב לֹא יְגֻרְךְ רָע. וְזֶה נִקְרָא רַע וְלֹא נִקְרָא רָשָׁע. וְכָתוּב (תהלים כג) גַּם כִּי אֵלֵךְ בְּגֵיא צַלְמָוֶת לֹא אִירָע רָע כִּי אַתָּה עִמָּדִי.</p>"],[9522011132,"<p>וַיִּנָּחֶם ה' כִּי עָשָׂה אֶת הָאָדָם בָּאָרֶץ וַיִּתְעַצֵּב אֶל לִבּוֹ. רַבִּי יוֹסֵי פָּתַח, (ישעיה ה) הוֹי מוֹשְׁכֵי הֶעָון בְּחַבְלֵי הַשָּׁוְא וְכַעֲבוֹת הָעֲגָלָה חַטָּאָה. הוֹי מוֹשְׁכֵי הֶעָון - אֵלּוּ בְּנֵי אָדָם שֶׁחוֹטְאִים לִפְנֵי רִבּוֹנָם בְּכָל יוֹם, וְנִדְמִים בְּעֵינֵיהֶם אוֹתָם חֲטָאִים שֶׁהֵם כְּחַבְלֵי הַשָּׁוְא, וְחוֹשְׁבִים שֶׁאוֹתוֹ מַעֲשֶׂה שֶׁעָשׂוּ וְאוֹתוֹ חֵטְא שֶׁעָשׂוּ שֶׁאֵינוֹ כְלוּם, וְלֹא מַשְׁגִּיחַ בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁעוֹשִׂים אֶת אוֹתוֹ חֵטְא חָזָק וְגָדוֹל כַּעֲבוֹת הָעֲגָלָה, שֶׁהוּא חָזָק שֶׁלֹּא יוּכַל לְהִתְכַּלּוֹת.</p>\n<p>וּבֹא וּרְאֵה, כְּשֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא דִּין בְּרִשְׁעֵי הָעוֹלָם, אַף עַל גַּב שֶׁהֵם חָטְאוּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְהִרְגִּיזוּ אוֹתוֹ כָּל יוֹם, אֵינוֹ רוֹצֶה לְאַבֵּד אוֹתָם מֵהָעוֹלָם. וּכְשֶׁמַּשְׁגִּיחַ בְּמַעֲשֵׂיהֶם, מִתְנַחֵם עֲלֵיהֶם עַל שֶׁהֵם מַעֲשֵׂי יָדָיו וּמַאֲרִיךְ לָהֶם בָּעוֹלָם.</p>\n<p>וּבִגְלַל שֶׁהֵם מַעֲשֵׂי יָדָיו, נוֹטֵל נֶחָמָה וּמִתְנַחֵם עֲלֵיהֶם וְחָס עֲלֵיהֶם. וּכְשֶׁרוֹצֶה לַעֲשׂוֹת בָּהֶם דִּין, כִּבְיָכוֹל הוּא עָצוּב (ד\"א שמחות לא יכנסו לפניו). שֶׁכֵּיוָן שֶׁהֵם מַעֲשֵׂי יָדָיו, הוּא עָצוּב עֲלֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ו) וּשְׂמָחוֹת לֹא הִכְנִיס לְפָנָיו.</p>\n<p>כָּתוּב (ס\"א והרי כתוב) (תהלים צו) הוֹד וְהָדָר לְפָנָיו עֹז וְחֶדְוָה בִּמְקוֹמוֹ. אָמַר רַבִּי יוֹסֵי, בּא רְאֵה, וַיִּתְעַצֵּב אֶל לִבּוֹ כָּתוּב. הוּא הִתְעַצֵּב אֶל לִבּוֹ וְלֹא לְמָקוֹם אַחֵר. לִבּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א ב) כַּאֲשֶׁר בִּלְבָבִי וּבְנַפְשִׁי יַעֲשֶׂה. רַבִּי יִצְחָק אָמַר, וַיִּנָּחֶם ה', כְּמוֹ שֶׁנֶּאֱמַר (שמות לב) וַיִּנָּחֶם ה' עַל הָרָעָה אֲשֶׁר דִּבֶּר לַעֲשׂוֹת לְעַמּוֹ.</p>\n<p>רַבִּי יֵיסָא אָמַר לְטוֹב. רַבִּי חִזְקִיָּה אָמַר לְרַע. רַבִּי יֵיסָא אָמַר לְטוֹב, כְּמוֹ שֶׁנִּתְבָּאֵר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְנַחֵם עַל אוֹתָם מַעֲשֵׂי יָדָיו וְחָס עֲלֵיהֶם. וַיִּתְעַצֵּב, מִשּׁוּם שֶׁהֵם חוֹטְאִים לְפָנָיו.</p>\n<p>וְרַבִּי חִזְקִיָּה אָמַר לְרַע, שֶׁכְּשֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבֵּד רִשְׁעֵי הָעוֹלָם, נוֹטֵל עֲלֵיהֶם נִחוּמִים וּמְקַבֵּל נִחוּמִים, כִּבְיָכוֹל כְּמִי שֶׁמְּקַבֵּל נִחוּמִים עַל מַה שֶּׁאָבַד. כֵּיוָן שֶׁקִּבֵּל נִחוּמִים, וַדַּאי נַעֲשָׂה דִין, וְלֹא תָלוּי הַדָּבָר בִּתְשׁוּבָה.</p>\n<p>אֵימָתַי זֶה תָלוּי בִּתְשׁוּבָה? עַד שֶׁלֹּא קִבֵּל עֲלֵיהֶם תַּנְחוּמִים. הֲרֵי שֶׁקִּבֵּל עֲלֵיהֶם תַּנְחוּמִים, אָז הַדָּבָר כְּבָר לֹא תָלוּי בִּתְשׁוּבָה כְּלָל וְהַדִּין נַעֲשָׂה. וְאָז מוֹסִיף דִּין עַל דִּין וּמְחַזֵּק אֶת אוֹתוֹ מְקוֹם הַדִּין לַעֲשׂוֹת דִּין, וּמְאַבֵּד אֶת הָרְשָׁעִים מֵהָעוֹלָם, וְהַכֹּל בַּכָּתוּב, שֶׁכָּתוּב וַיִּנָּחֶם ה', קִבֵּל תַּנְחוּמִים. וְאַחַר כָּךְ וַיִּתְעַצֵּב אֶל לִבּוֹ, נָתַן כֹּחַ לַדִּין לַעֲשׂוֹת דִּין.</p>\n<p>רַבִּי חִיָּיא אָמַר, וַיִּנָּחֶם ה' כִּי עָשָׂה אֶת הָאָדָם בָּאָרֶץ - נָטַל תַּנְחוּמִים וְחֶדְוָה. כְּשֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם בָּאָרֶץ, שֶׁהוּא כְּדֻגְמָא עֶלְיוֹנָה, וְכָל הַמַּלְאָכִים הָעֶלְיוֹנִים מְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁרָאוּ אוֹתוֹ בִּדְמוּת עֶלְיוֹנָה, וְאָמְרוּ (תהלים ח) וַתְּחַסְּרֵהוּ מְּעַט מֵאֱלֹהִים וְכָבוֹד וְהָדָר תְּעַטְּרֵהוּ.</p>\n<p>אַחַר כָּךְ כְּשֶׁחָטָא אָדָם, הִתְעַצֵּב הַקָּדוֹשׁ בָּרוּךְ הוּא עַל שֶׁחָטָא. שֶׁנָּתַן פִּתְחוֹן פֶּה לְמַלְאֲכֵי הַשָּׁרֵת שֶׁאָמְרוּ לְפָנָיו בַּתְּחִלָּה כְּשֶׁרָצָה לִבְרֹא אוֹתוֹ, מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ וּבֶן אָדָם כִּי תִפְקְדֶנּוּ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, וַיִּתְעַצֵּב אֶל לִבּוֹ, כִּי רָצָה לַעֲשׂוֹת בָּהֶם דִּין, שֶׁנֶּאֱמַר (דברי הימים ב כ) בְּצֵאת לִפְנֵי הֶחָלוּץ וְאֹמְרִים הוֹדוּ לַה' כִּי לְעוֹלָם חַסְדּוֹ. וְאָמַר רַבִּי יִצְחָק, לָמָּה לֹא כָתוּב כָּאן כִּי טוֹב? אֶלָּא מִשּׁוּם שֶׁהֶאֱבִיד אֶת מַעֲשֵׂי יָדָיו מִפְּנֵי יִשְׂרָאֵל.</p>\n<p>כְּמוֹ זֶה כְּשֶׁהָיוּ יִשְׂרָאֵל עוֹבְרִים אֶת הַיָּם, בָּאוּ מַלְאָכִים עֶלְיוֹנִים לוֹמַר שִׁירָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתוֹ לַיְלָה. אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא: וּמָה מַעֲשֵׂי יָדַי טוֹבְעִים בַּיָּם, וְאַתֶּם אוֹמְרִים שִׁירָה!? אָז (שמות יד) וְלֹא קָרַב זֶה אֶל זֶה כָּל הַלָּיְלָה. גַּם כָּאן, בְּכָל הַפְּעָמִים שֶׁל אִבּוּד רְשָׁעִים מֵהָעוֹלָם, אָז נִמְצֵאת עֲלֵיהֶם עַצְבוּת.</p>\n<p>רַבִּי אַבָּא אָמַר, בְּשָׁעָה שֶׁחָטָא אָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְעָבַר עַל מִצְוָתוֹ, אָז נִמְצְאָה עַצְבוּת לְפָנָיו. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: אָדָם, אוֹי שֶׁהֶחֱלַשְׁתָּ אֶת הַכֹּחַ הָעֶלְיוֹן. בְּשָׁעָה זוֹ נֶחְשַׁךְ מָאוֹר אֶחָד. מִיָּד גֵּרַשׁ אוֹתוֹ מִגַּן עֵדֶן.</p>\n<p>אָמַר לוֹ: אֲנִי הִכְנַסְתִּי אוֹתְךְ לְגַן עֵדֶן לְהַקְרִיב קָרְבָּן, וְאַתָּה פָּגַמְתָּ אֶת הַמִּזְבֵּחַ שֶׁלֹּא נִקְרָב הַקָּרְבָּן!? מִכָּאן וָהָלְאָה - לַעֲבֹד אֶת הָאֲדָמָה. וְגָזַר עָלָיו מִיתָה. וְחָס עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא וּגְנָזוֹ בְּשָׁעָה שֶׁמֵּת סָמוּךְ לַגָּן.</p>\n<p>מֶה עָשָׂה אָדָם? עָשָׂה מְעָרָה אַחַת וְהִסְתַּתֵּר בָּהּ הוּא וְאִשְׁתּוֹ. מֵאֵיפֹה יָדַע? אֶלָּא רָאָה אוֹר דַּקִּיק אֶחָד שֶׁנִּכְנַס בְּאוֹתוֹ מָקוֹם שֶׁיּוֹצֵא מִגַּן עֵדֶן, וְהִתְאַוָּה תַאֲוָתוֹ לְקִבְרוֹ, וְשָׁם הוּא מָקוֹם סָמוּךְ לְשַׁעַר גַּן עֵדֶן.</p>\n<p>בֹּא רְאֵה, לֹא מִסְתַּלֵּק אָדָם מֵהָעוֹלָם עַד שֶׁיִּרְאֶה אֶת אָדָם הָרִאשׁוֹן. שׁוֹאֵל אוֹתוֹ: עַל מָה הָלַךְ מֵהָעוֹלָם וְאֵיךְ יָצָא? הוּא אוֹמֵר לוֹ: אוֹי שֶׁבִּגְלָלְךְ יָצָאתִי מֵהָעוֹלָם. וְהוּא מֵשִׁיב לוֹ: בְּנִי, אֲנִי עָבַרְתִּי עַל מִצְוָה אַחַת וְנֶעֱנַשְׁתִּי בִּשְׁבִילָהּ, רְאֵה אַתָּה כַּמָּה חֲטָאִים וְכַמָּה מִצְווֹת שֶׁל רִבּוֹנְךְ עָבַרְתָּ.</p>\n<p>אָמַר רַבִּי חִיָּיא, עַד הַיּוֹם הַזֶּה עוֹמֵד אָדָם הָרִאשׁוֹן וְרוֹאֶה אֶת הָאָבוֹת פַּעֲמַיִם בְּיוֹם וּמוֹדֶה עַל חֶטְאוֹ, וּמַרְאֶה לָהֶם אֶת אוֹתוֹ מָקוֹם שֶׁהָיָה בּוֹ בְּכָבוֹד עֶלְיוֹן, וְהוֹלֵךְ וְרוֹאֶה כָּל אוֹתָם הַצַּדִּיקִים וַחֲסִידִים שֶׁיָּצְאוּ מִמֶּנּוּ וְיָרְשׁוּ אֶת אוֹתוֹ כָבוֹד עֶלְיוֹן שֶׁבְּגַן עֵדֶן. וְכָל הָאָבוֹת מוֹדִים וְאוֹמְרִים, (תהלים לו) מַה יָּקָר חַסְדְּךְ אֱלֹהִים וּבְנֵי אָדָם בְּצֵל כְּנָפֶיךְ יֶחֱסָיוּן.</p>\n<p>רַבִּי יֵיסָא אָמַר, כָּל בְּנֵי הָעוֹלָם רוֹאִים אֶת אָדָם הָרִאשׁוֹן בְּשָׁעָה שֶׁמִּסְתַּלְּקִים מֵהָעוֹלָם, לְהַרְאוֹת עֵדוּת שֶׁמִּשּׁוּם חֲטָאֵי הָאִישׁ הוּא מִסְתַּלֵּק מֵהָעוֹלָם וְלֹא בִּגְלָלוֹ שֶׁל אָדָם, כְּמוֹ שֶׁשָּׁנִינוּ אֵין מִיתָה בְּלֹא חֵטְא,</p>\n<p>פְּרָט לְאוֹתָם שְׁלֹשָׁה שֶׁהִסְתַּלְּקוּ בְּעֶטְיוֹ שֶׁל נָחָשׁ הַקַּדְמוֹנִי, וְאֵלֶּה הֵם: עַמְרָם, לֵוִי וּבִנְיָמִין. וְיֵשׁ אוֹמְרִים גַּם יִשַׁי. שֶׁלֹּא חָטְאוּ, וְלֹא נִמְצָא בָהֶם חֵטְא שֶׁיָּמוּתוּ בוֹ, רַק שֶׁנִּזְכְּרָה עֲלֵיהֶם אוֹתָהּ עֲצַת הַנָּחָשׁ, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>בֹּא רְאֵה, כָּל הַדּוֹרוֹת שֶׁהָיוּ בִּימֵי נֹחַ, כֻּלָּם הִפְשִׁיטוּ חֲטָאִים עַל הָעוֹלָם בְּגָלוּי לְעֵינֵי כֹל. רַבִּי שִׁמְעוֹן הָיָה הוֹלֵךְ יוֹם אֶחָד בְּשַׁעֲרֵי טְבֶרְיָה. רָאָה בְּנֵי אָדָם שֶׁהָיוּ קוֹשְׁרִים בְּקֶשֶׁר הַקֶּשֶׁת בְּכַדֵּי חֶרֶס. אָמַר, וּמַה חֵטְא זֶה בְּגָלוּי לְהַרְגִּיז אֶת רִבּוֹנָם? נָתַן עֵינוֹ בָהֶם וְנִזְרְקוּ לְתוֹךְ הַיָּם וּמֵתוּ.</p>\n<p>בֹּא רְאֵה, כָּל חֵטְא שֶׁנַּעֲשֶׂה בְּגָלוּי, דּוֹחֶה אֶת הַשְּׁכִינָה מֵהָאָרֶץ וּמְסַלֵּק אֶת דִּיּוּרָהּ מִן הָעוֹלָם. אֵלֶּה הָיוּ הוֹלְכִים בְּרֹאשׁ זָקוּף וְעוֹשִׂים חֲטָאֵיהֶם בְּגָלוּי, וְדָחוּ אֶת הַשְּׁכִינָה מֵהָעוֹלָם, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא דָּחָה אוֹתָם וְהֶעֱבִיר אוֹתָם מִמֶּנּוּ. וְעַל זֶה כָּתוּב (משלי כה) הָגוֹ רָשָׁע לִפְנֵי מֶלֶךְ וְגוֹ', הָגוֹ סִיגִים מִכָּסֶף וְגוֹ'.</p>"],[9522011133,"<p>וַיֹּאמֶר ה' לֹא יָדוֹן רוּחִי בָאָדָם לְעֹלָם בְּשַׁגַּם הוּא בָשָׂר וְגוֹ'. אָמַר רַבִּי אֶלְעָזָר, בּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה אֶת הָעוֹלָם הַזֶּה לְהִשְׁתַּמֵּשׁ כְּמוֹ שֶׁלְּמַעְלָה, וּכְשֶׁבְּנֵי אָדָם הֵם צַדִּיקִים שֶׁהוֹלְכִים בְּדֶרֶךְ יָשָׁר, הַקָּדוֹשׁ בָּרוּךְ הוּא מְעוֹרֵר רוּחַ חַיִּים שֶׁלְּמַעְלָה, עַד שֶׁמַּגִּיעִים אוֹתָם חַיִּים לַמָּקוֹם שֶׁיַּעֲקֹב אָבִינוּ שָׁרוּי בּוֹ.</p>\n<p>וּמִשָּׁם שׁוֹפְעִים אוֹתָם חַיִּים, עַד שֶׁנִּמְשֶׁכֶת אוֹתָהּ רוּחַ לָעוֹלָם הַזֶּה שֶׁדָּוִד הַמֶּלֶךְ שָׁרוּי בּוֹ, וּמִשָּׁם שׁוֹפְעוֹת הַבְּרָכוֹת לְכָל אוֹתָם הַתַּחְתּוֹנִים. וְאוֹתָהּ רוּחַ עֶלְיוֹנָה שׁוֹפַעַת וְנִמְשֶׁכֶת לְמַטָּה, וִיכוֹלִים לְהִתְקַיֵּם בָּעוֹלָם.</p>\n<p>וּמִשּׁוּם כָּךְ לְעוֹלָם חַסְדּוֹ, זֶהוּ עוֹלָם שֶׁל דָּוִד הַמֶּלֶךְ, וְלָכֵן כָּתוּב לְעֹלָם בְּלִי וָא\"ו. שֶׁהֲרֵי כְּשֶׁאוֹתָהּ רוּחַ שׁוֹפַעַת לְאוֹתוֹ עוֹלָם, מִשָּׁם יוֹצְאוֹת בְּרָכוֹת וְחַיִּים לַכֹּל לְהִתְקַיֵּם. עַכְשָׁו שֶׁחָטְאוּ בְּנֵי אָדָם, הִסְתַּלֵּק הַכֹּל, בִּשְׁבִיל שֶׁלֹּא יַגִּיעַ אוֹתוֹ רוּחַ חַיִּים לְעוֹלָם זֶה לֵהָנוֹת מִמֶּנּוּ הַתַּחְתּוֹנִים וּלְהִתְקַיֵּם בּוֹ. בְּשַׁגַּם הוּא בָשָׂר - כְּדֵי שֶׁלֹּא תֻשְׁפַּע זוֹ הָרוּחַ לָעוֹלָם הַזֶּה. מָה הַטַּעַם? שֶׁלֹּא לְהַרְבּוֹת נָחָשׁ הַתַּחְתּוֹן. שֶׁדְּרָגוֹת שֶׁיִּתְחַזֵּק בּוֹ (וצריכים) רוּחַ שֶׁל קְדֻשָּׁה שֶׁלֹּא יִתְעָרֵב בְּרוּחַ טָמֵא.</p>\n<p>בְּשַׁגַּם הוּא בָשָׂר - זֶה נָחָשׁ הַקַּדְמוֹנִי שֶׁיִּתְבָּרֵךְ. מִשּׁוּם כָּךְ הוּא בָשָׂר, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ו) קֵץ כָּל בָּשָׂר בָּא לְפָנַי. וְאָמַר רַבִּי שִׁמְעוֹן, זֶהוּ מַלְאַךְ הַמָּוֶת. וְהָיוּ יָמָיו מֵאָה וְעֶשְׂרִים שָׁנָה - הַמְתָּנָה שֶׁל מִגְדָּל הַמְקֻשָּׁר.</p>"],[9522011134,"<p>הַנְּפִלִים הָיוּ בָאָרֶץ. שָׁנָה רַבִּי יוֹסֵי, אֵלּוּ עֲזָ\"א וַעֲזָאֵ\"ל, כְּמוֹ שֶׁנֶּאֱמַר שֶׁהוֹצִיא (ד\"א שהפיל) אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהַקְּדֻשָּׁה שֶׁלְּמַעְלָה. וְאִם תֹּאמַר, אֵיךְ יָכְלוּ לְהִתְקַיֵּם בָּעוֹלָם הַזֶּה? אָמַר רַבִּי חִיָּיא, אֵלֶּה הָיוּ מֵאוֹתָם שֶׁכָּתוּב וְעוֹף יְעוֹפֵף עַל הָאָרֶץ. וַהֲרֵי נֶאֱמַר שֶׁאֵלֶּה נִרְאִים לִבְנֵי אָדָם כַּמַּרְאֶה שֶׁלָּהֶם. וְאִם תֹּאמַר, אֵיךְ יָכְלוּ לְהִתְהַפֵּךְ? הֲרֵי נֶאֱמַר שֶׁמִּתְהַפְּכִים לְכַמָּה גְוָנִים. וּבְשָׁעָה שֶׁיָּרְדוּ, הִתְלַבְּשׁוּ בַּאֲוִיר הָעוֹלָם וְנִרְאוּ כִּבְנֵי אָדָם.</p>\n<p>וַעָזָ\"א וַעֲזָאֵ\"ל הַלָּלוּ שֶׁמָּרְדוּ לְמַעְלָה וְהִפִּילָם הַקָּדוֹשׁ בָּרוּךְ הוּא וְהִתְלַבְּשׁוּ בָאָרֶץ וְהִתְקַיְּמוּ בָהּ, וְלֹא יָכְלוּ לְהִתְפַּשֵּׁט מִמֶּנּוּ, וְאַחַר כָּךְ טָעוּ אַחַר נְשׁוֹת הָעוֹלָם. וְעַד הַיּוֹם הַזֶּה הֵם קַיָּמִים וּמְלַמְּדִים כְּשָׁפִים לִבְנֵי אָדָם, וְהוֹלִידוּ בָנִים, וְקָרְאוּ לָהֶם עֲנָקִים גִּבּוֹרִים. וְאוֹתָם נְפִילִים נִקְרָאִים בְּנֵי אֱלֹהִים, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522011135,"<p>וַיֹּאמֶר ה' אֶמְחֶה אֶת הָאָדָם אֲשֶׁר בָּרָאתִי מֵעַל פְּנֵי הָאֲדָמָה. רַבִּי יוֹסֵי פָּתַח, (ישעיה נה) כִּי לֹא מַחְשְׁבוֹתַי מַחְשְׁבוֹתֵיהֶם. בֹּא רְאֵה, כְּשֶׁבֶּן אָדָם רוֹצֶה לִנְקֹם מֵאַחֵר, הוּא שׁוֹתֵק וְלֹא אוֹמֵר דָּבָר. שֶׁאִם יוֹדִיעַ לוֹ, הַהוּא יִשָּׁמֵר וְלֹא יוּכַל לוֹ.</p>\n<p>אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא עוֹשֶׂה כָּךְ, לֹא עוֹשֶׂה דִין בָּעוֹלָם עַד שֶׁמַּכְרִיז וּמוֹדִיעַ לָהֶם פַּעַם פַּעֲמַיִם וְשָׁלֹשׁ, כִּי אֵין מִי שֶׁיִּמְחֶה בְיָדוֹ שֶׁיֹּאמַר לוֹ מֶה עָשִׂיתָ, וְלֹא יִשָּׁמֵר מִמֶּנּוּ וְלֹא יוּכַל לַעֲמֹד לְפָנָיו.</p>\n<p>בֹּא רְאֵה, וַיֹּאמֶר ה' אֶמְחֶה אֶת הָאָדָם אֲשֶׁר בָּרָאתִי מֵעַל פְּנֵי הָאֲדָמָה. הוֹדִיעַ לָהֶם עַל יְדֵי נֹחַ וְהִתְרָה בָהֶם כַּמָּה פְעָמִים וְלֹא שָׁמְעוּ. אַחַר שֶׁלֹּא שָׁמְעוּ, הֵבִיא עֲלֵיהֶם דִּין וְהֶאֱבִיד אוֹתָם מֵעַל פְּנֵי הָאָרֶץ.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב בְּנֹחַ, וַיִּקְרָא אֶת שְׁמוֹ נֹחַ לֵאמֹר זֶה יְנַחֲמֵנוּ מִמַּעֲשֵׂנוּ. (למה כאן לאמר, ולמה זה? אלא לאמר זו האשה, זה זה צדיק, רמז שהקדוש ברוך הוא קרא לנח, מנוחת הארץ, לאמר, מה זה לאמר? אלא מקום זה קורא לו נח, ומיהו? ארץ הקדושה, לאמר זה ינחמנו, עשה אותו הקדוש ברוך הוא למטה כדגמא עליונה, כתוב כאן זה ינחמנו, וכתוב שם (ישעיה כה) זה ה' קוינו לו. אשרי הצדיקים שרשומים ברשם של חותמת המלך העליונה להיות רשומים בשמו, והוא שם שמות בארץ כראוי. כתוב ויקרא את שמו נח, וכתוב (בראשית כה) ויקרא את שמו יעקב, למה לא כתוב את? אלא שם דרגה (אחת), וכאן דרגה אחרת, כמו שנאמר (ישעיה ו) ואראה את ה', ואראה ה' לא כתוב אלא את ה', גם כאן ויקרא שמו יעקב דרגתו ממש, הקדוש ברוך הוא קרא לו י קב, אבל כאן א\"ת להכליל את השכינה.) מֵאֵיפֹה הָיָה יוֹדֵעַ? אֶלָּא בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא קִלֵּל אֶת הָעוֹלָם, שֶׁכָּתוּב אֲרוּרָה הָאֲדָמָה בַּעֲבוּרֶךְ, אָמַר אָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: רִבּוֹנוֹ שֶׁל עוֹלָם, עַד מָתַי יִהְיֶה הָעוֹלָם בִּקְלָלָה? אָמַר לוֹ: עַד שֶׁיִּוָּלֵד לְךְ בֵּן מָהוּל כְּמוֹתְךְ.</p>\n<p>וְהָיוּ מְחַכִּים עַד שָׁעָה שֶׁנּוֹלַד נֹחַ. וְכֵיוָן שֶׁנּוֹלַד, רָאָה אוֹתוֹ מָהוּל רָשׁוּם בְּאוֹת הַקֹּדֶשׁ, וְרָאָה שְׁכִינָה דְּבוּקָה עִמּוֹ, וְאָז קָרָא אֶת שְׁמוֹ עַל מַה שֶּׁעָשָׂה אַחַר כָּךְ.</p>\n<p>בַּתְּחִלָּה לֹא הָיוּ יוֹדְעִים לִזְרֹעַ וְלִקְצֹר וְלַחֲר!שׁ, וְהָיוּ עוֹשִׂים עֲבוֹדַת הָאֲדָמָה בִּידֵיהֶם. כֵּיוָן שֶׁבָּא נֹחַ, הִתְקִין אֻמָּנוּת לָהֶם וְכָל הַכֵּלִים שֶׁצְּרִיכִים לְתַקֵּן אֶת הָאֲדָמָה לַעֲשׂוֹת פֵּרוֹת. זֶהוּ שֶׁכָּתוּב זֶה יְנַחֲמֵנוּ מִמַּעֲשֵׂנוּ וּמֵעִצְּבוֹן יָדֵינוּ מִן הָאֲדָמָה. שֶׁהוּא הוֹצִיא אֶת הָאָרֶץ מִמַּה שֶּׁהִתְקַלְּלָה שֶׁהָיוּ זוֹרְעִים חִטִּים - וְקוֹצְרִים קוֹצִים וְדַרְדָּרִים. וְלָכֵן כָּתוּב אִישׁ הָאֲדָמָה.</p>\n<p>רַבִּי יְהוּדָה אָמַר, אִישׁ הָאֲדָמָה, כְּמוֹ שֶׁנֶּאֱמַר (רות א) אִישׁ נָעֳמִי. מִשּׁוּם שֶׁנִּקְרָא צַדִּיק וְהוֹצִיא אֶת הָאָרֶץ בְּקָרְבָּן שֶׁעָשָׂה מִמַּה שֶּׁהִתְקַלְּלָה, שֶׁכָּתוּב לֹא אֹסִף לְקַלֵּל עוֹד אֶת הָאֲדָמָה בַּעֲבוּר הָאָדָם. וְלָכֵן נִקְרָא אִישׁ הָאֲדָמָה, וְעַל זֶה קָרָא לוֹ שֵׁם עַל מַה שֶּׁיָּבֹא.</p>"],[9522011136,"<p>רַבִּי יְהוּדָה פָּתַח, (תהלים מו) לְכוּ חֲזוּ מִפְעֲלוֹת אֱלֹהִים אֲשֶׁר שָׂם שַׁמּוֹת בָּאָרֶץ. פָּסוּק זֶה הֱקִימוּהוּ וְנִתְבָּאֵר. אֲבָל לְכוּ חֲזוּ וְגוֹ' (מה זה חזו? כמו שנאמר (ישעיה כא) חזות קשה הגד לי, במעשי הקדוש ברוך הוא נגלתה נבואה עליונה לבני אדם, אשר שם שמות בארץ שמות ודאי, שהרי השם גורם לכל) (והוא לשון שממון). שֶׁאִלּוּ הָיוּ מִפְעֲלוֹת יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א - שָׂם קִיּוּם בָּאָרֶץ, אֲבָל מִשּׁוּם שֶׁהָיוּ מִפְעֲלוֹת הַשֵּׁם שֶׁל אֱלֹהִים - שָׂם שַׁמּוֹת בָּאָרֶץ.</p>\n<p>אָמַר לוֹ רַבִּי חִיָּיא, כָּעֵת הִתְעוֹרַרְתָּ לָזֶה? לֹא כָּךְ אֲנִי אָמַרְתִּי לוֹ, מִשּׁוּם שֶׁבֵּין שֵׁם זֶה וּבֵין שֵׁם זֶה הַכֹּל הוּא שֶׁבַח. אֲבָל אֲנִי אָמַרְתִּי לוֹ כְּמוֹ שֶׁהֵעִירוּ הַחֲבֵרִים שֶׁשָּׂם שֵׁמוֹת. שַׁמּוֹת בָּאָרֶץ, שֵׁמוֹת מַמָּשׁ (שם בארץ, ולמה? בשביל להשתמש בהם העולם ולהיות קיום בעולם).</p>\n<p>רַבִּי יִצְחָק אָמַר, הַכֹּל הוּא, וַאֲפִלּוּ מַה שֶּׁאָמַר רַבִּי יְהוּדָה - יָפֶה אָמַר. שֶׁאִלּוּ הָעוֹלָם יִהְיֶה בְּשֵׁם הָרַחֲמִים, יִתְקַיֵּם הָעוֹלָם. אֲבָל מִשּׁוּם שֶׁהָעוֹלָם נִבְרָא עַל דִּין וְעוֹמֵד עַל דִּין, שָׂם שַׁמּוֹת בָּאָרֶץ, וְיָפֶה הוּא, שֶׁאִלְמָלֵא כָּךְ לֹא יוּכַל הָעוֹלָם לְהִתְקַיֵּם מִלִּפְנֵי חֲטָאֵי בְּנֵי הָאָדָם.</p>\n<p>בֹּא רְאֵה, כְּשֶׁנּוֹלַד נֹחַ קָרְאוּ לוֹ עַל שֵׁם שֶׁל נֶחָמָה (נח נוח לו, נוח לעולם, נוח לאבות, נוח לבנים, נוח לעליונים, נוח לתחתונים, נוח לעולם הזה, נוח לעולם הבא) וְשֶׁיִּהְיֶה (ולהיות) הַשֵּׁם גּוֹרֵם. אֲבָל לְגַבֵּי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא כָּךְ. נֹחַ בְּהִפּוּךְ אוֹתִיּוֹת - חֵ\"ן, כְּמוֹ שֶׁנֶּאֱמַר וְנֹחַ מָצָא חֵן. אָמַר רַבִּי יוֹסֵי, חֵן הַיְנוּ נֹחַ. בַּצַּדִּיקִים, הַשֵּׁם שֶׁלָּהֶם גּוֹרֵם לְטוֹב. בָּרְשָׁעִים, הַשֵּׁם שֶׁלָּהֶם גּוֹרֵם לְרַע. בְּנֹחַ כָּתוּב וְנֹחַ מָצָא חֵן בְּעֵינֵי ה'. בְּעֵר בְּכוֹר יְהוּדָה הִתְהַפְּכוּ אוֹתִיּוֹתָיו לְרַע. עֵ\"ר רַ\"ע. רַע בְּעֵינֵי ה'.</p>\n<p>בֹּא רְאֵה, כֵּיוָן שֶׁנּוֹלַד נֹחַ, רָאָה אֶת מַעֲשֵׂי בְּנֵי הָאָדָם שֶׁהֵם חוֹטְאִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהָיָה גוֹנֵז עַצְמוֹ וְעָסַק בַּעֲבוֹדַת רִבּוֹנוֹ כְּדֵי לֹא לָלֶכֶת בְּדַרְכָּם. וְכִי תֹאמַר, בַּמָּה הוּא עָסַק? בְּאוֹתוֹ סֵפֶר שֶׁל אָדָם וְסֵפֶר שֶׁל חֲנוֹךְ. וְהָיָה עוֹסֵק בָּהֶם לַעֲבֹד אֶת רִבּוֹנוֹ.</p>\n<p>בֹּא רְאֵה שֶׁכָּךְ הוּא, שֶׁהֲרֵי מֵאֵיפֹה יָדַע נֹחַ לְהַקְרִיב קָרְבָּן לְרִבּוֹנוֹ? אֶלָּא מִשּׁוּם שֶׁמָּצָא חָכְמָה עַל מָה הָעוֹלָם עוֹמֵד, וְיָדַע שֶׁהוּא עוֹמֵד עַל הַקָּרְבָּן, וְאִלְמָלֵא הַקָּרְבָּן לֹא הָיוּ עוֹמְדִים עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>רַבִּי שִׁמְעוֹן הָיָה הוֹלֵךְ בַּדֶּרֶךְ וְהָיוּ עִמּוֹ רַבִּי אֶלְעָזָר בְּנוֹ וְרַבִּי יוֹסֵי וְרַבִּי חִיָּיא. עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי אֶלְעָזָר לְאָבִיו, הַדֶּרֶךְ מְתֻקֶּנֶת לְפָנֵינוּ, רוֹצִים לִשְׁמֹעַ דִּבְרֵי תוֹרָה</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (קהלת י) וְגַם בַּדֶּרֶךְ כְּשֶׁהַסָּכָל הֹלֵךְ לִבּוֹ חָסֵר וְגוֹ'. כְּשֶׁבֶּן אָדָם רוֹצֶה לְתַקֵּן דְּרָכָיו לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, עַד שֶׁלֹּא יֵצֵא לַדֶּרֶךְ צָרִיךְ לְהִמָּלֵךְ בּוֹ וּלְהִתְפַּלֵּל לְפָנָיו עַל דַּרְכּוֹ, כְּמוֹ שֶׁשָּׁנִינוּ שֶׁכָּתוּב (תהלים פה) צֶדֶק לְפָנָיו יְהַלֵּךְ וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו. שֶׁהֲרֵי הַשְּׁכִינָה לֹא נִפְרֶדֶת מִמֶּנּוּ.</p>\n<p>וּמִי שֶׁלֹּא מַאֲמִין בְּרִבּוֹנוֹ, מַה כָּתוּב בּוֹ? וְגַם בַּדֶּרֶךְ שֶׁהַסָּכָל הֹלֵךְ לִבּוֹ חָסֵר. מִי זֶה לִבּוֹ? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יֵלֵךְ עִמּוֹ בַּדֶּרֶךְ וְגוֹרֵעַ מִסִּיּוּעוֹ בְּדַרְכּוֹ. מִשּׁוּם שֶׁאוֹתוֹ בֶּן אָדָם שֶׁלֹּא מַאֲמִין בְּרִבּוֹנוֹ, עַד שֶׁלֹּא יֵצֵא לְדַרְכּוֹ לֹא בִקֵּשׁ אֶת סִיּוּעַ רִבּוֹנוֹ.</p>\n<p>וַאֲפִלּוּ בַּדֶּרֶךְ כְּשֶׁהוּא הוֹלֵךְ, לֹא עוֹסֵק בְּדִבְרֵי תוֹרָה, וְלָכֵן לִבּוֹ חָסֵר, שֶׁאֵינוֹ הוֹלֵךְ יַחַד עִם רִבּוֹנוֹ וְלֹא נִמְצָא בְדַרְכּוֹ. וְאוֹמֵר לַכֹּל סָכָל הוּא - וַאֲפִלּוּ כְּשֶׁשּׁוֹמֵעַ דְּבַר אֱמוּנָה שֶׁל רִבּוֹנוֹ, הוּא אוֹמֵר שֶׁזּוֹ טִפְּשׁוּת לַעֲסֹק בָּזֶה.</p>\n<p>כְּמוֹ זֶה שֶׁשָּׁאֲלוּ לְבֶן אָדָם עַל אוֹת הַבְּרִית שֶׁרָשְׁמוּ בִּבְשַׂר הָאָדָם, וְאוֹמֵר שֶׁלֹּא דְּבַר אֱמוּנָה הוּא. שָׁמַע זֹאת רַבִּי יֵיבָא הַזָּקֵן וְהִסְתַּכֵּל בּוֹ, וְנַעֲשָׂה גַל שֶׁל עֲצָמוֹת. וְאָנוּ בַּדֶּרֶךְ הַזּוֹ בְּסִיּוּעַ הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצִים לוֹמַר דִּבְרֵי תוֹרָה.</p>\n<p>פָּתַח וְאָמַר, (תהלים פו) הוֹרֵנִי ה' דַּרְכֶּךְ אֲהַלֵּךְ בַּאֲמִתֶּךְ יַחֵד לְבָבִי לְיִרְאָה שְׁמֶךְ. פָּסוּק זֶה קָשֶׁה, שֶׁהֲרֵי שָׁנִינוּ, הַכֹּל בְּיַד הַקָּדוֹשׁ בָּרוּךְ הוּא חוּץ מִלִּהְיוֹת צַדִּיק אוֹ רָשָׁע. וְדָוִד אֵיךְ תָּבַע אֶת זֶה מֵהַקָּדוֹשׁ בָּרוּךְ הוּא?</p>\n<p>אֶלָּא דָּוִד כָּךְ אָמַר, הוֹרֵנִי ה' דַּרְכֶּךְ - אוֹתָהּ דֶּרֶךְ מִישׁוֹר וּמְתֻקֶּנֶת לְגַלּוֹת עֵינַי וְלָדַעַת אוֹתוֹ. אַחַר כָּךְ אֲהַלֵּךְ בַּאֲמִתֶּךְ - אֵלֵךְ בְּדֶרֶךְ אֱמֶת וְלֹא אֶסְטֶה לְיָמִין וְלִשְׂמֹאל. יַחֵד לְבָבִי - מַה זֶּה לְבָבִי? כְּמוֹ שֶׁנֶּאֱמַר (שם עג) צוּר לְבָבִי וְחֶלְקִי. וְכָל זֶה אֲנִי מְבַקֵּשׁ לְיִרְאָה אֶת שְׁמֶךְ. לְהִדָּבֵק בְּיִרְאָתֶךְ, לִשְׁמֹר אֶת דְּרָכַי כָּרָאוּי. לְיִרְאָה שְׁמֶךְ - מְקוֹם חֶלְקִי שֶׁבּוֹ שְׁרוּיָה הַיִּרְאָה לִירָא.</p>\n<p>בֹּא רְאֵה, כָּל בֶּן אָדָם שֶׁיָּרֵא אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שְׁרוּיָה עִמּוֹ הָאֱמוּנָה כָּרָאוּי, שֶׁהֲרֵי אוֹתוֹ אָדָם הוּא שָׁלֵם בַּעֲבוֹדַת רִבּוֹנוֹ. וּמִי שֶׁלֹּא שְׁרוּיָה בּוֹ יִרְאַת רִבּוֹנוֹ, לֹא שְׁרוּיָה בּוֹ אֱמוּנָה, וְאֵינוֹ כְדַאי לִהְיוֹת לוֹ חֵלֶק לָעוֹלָם הַבָּא.</p>\n<p>עוֹד פָּתַח וְאָמַר, (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם. אַשְׁרֵיהֶם הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּיקָרָם. בֹּא רְאֵה מַה כָּתוּב, וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ. מַה זֶּה כְּאוֹר נֹגַהּ? כְּמוֹ אוֹתוֹ הָאוֹר הַמֵּאִיר שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשֵׂה בְרֵאשִׁית, זֶהוּ שֶׁגָּנַז לַצַּדִּיקִים לָעוֹלָם הַבָּא. הוֹלֵךְ וָאוֹר - שֶׁהוּא עוֹלֶה בְאוֹרוֹ תָּמִיד וְלֹא גוֹרֵעַ מִמֶּנּוּ.</p>\n<p>אֲבָל בָּרְשָׁעִים מַה כָּתוּב? (שם) דֶּרֶךְ רְשָׁעִים כָּאֲפֵלָה לֹא יָדְעוּ בַּמֶּה יִכָּשֵׁלוּ. לֹא יָדְעוּ - וְכִי לֹא יוֹדְעִים? אֶלָּא רְשָׁעִים שֶׁהוֹלְכִים בְּדֶרֶךְ עֲקֻמָּה בָּעוֹלָם הַזֶּה וְלֹא רוֹצִים לְהִסְתַּכֵּל (להם) שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לָדוּן אוֹתָם בְּאוֹתוֹ עוֹלָם וּלְהַכְנִיסָם בְּדִין גֵּיהִנֹּם. וְהֵם צוֹוְחִים וְאוֹמְרִים: אוֹי לָנוּ שֶׁלֹּא הִרְכַּנְנוּ אָזְנַיִם וְלֹא הִקְשַׁבְנוּ בְּאוֹתוֹ עוֹלָם. וּבְכָל יוֹם אוֹמְרִים: וַי לָנוּ!</p>\n<p>בֹּא רְאֵה, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָאִיר לַצַּדִּיקִים לָעוֹלָם הַבָּא וְלָתֵת לָהֶם שְׂכַר חֶלְקָם, מָקוֹם שֶׁעַיִן לֹא שׁוֹלֶטֶת לַעֲמֹד עָלָיו, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ. וְכָתוּב (שם סו) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפֹּשְׁעִים בִּי. וְכָתוּב (מלאכי ג) וְעַסּוֹתֶם רְשָׁעִים כִּי יִהְיוּ אֵפֶר תַּחַת כַּפּוֹת רַגְלֵיכֶם. אַשְׁרֵי הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. עֲלֵיהֶם כָּתוּב (ישעיה ס) צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ. וְכָתוּב (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן:</p>"],[9522011137,"<p>אֵלֶּה תּוֹלְדת נֹחַ. רַבִּי חִיָּיא פָּתַח, (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁעוֹסְקִים בַּתּוֹרָה וְיוֹדְעִים דַּרְכֵי הַתּוֹרָה שֶׁבִּגְלָלָהּ יִזְכּוּ לָעוֹלָם הַבָּא.</p>\n<p>בֹּא רְאֵה, לְכָל יִשְׂרָאֵל יֵשׁ חֵלֶק לָעוֹלָם הַבָּא, מָה הַטַּעַם? מִשּׁוּם שֶׁשּׁוֹמְרִים הַבְּרִית שֶׁהָעוֹלָם עוֹמֵד עָלֶיהָ, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. וְעַל זֶה, יִשְׂרָאֵל שֶׁשּׁוֹמְרִים הַבְּרִית וְקִבְּלוּ אוֹתָהּ, יֵשׁ לָהֶם חֵלֶק לָעוֹלָם הַבָּא.</p>\n<p>וְלֹא עוֹד, אֶלָּא מִשּׁוּם כָּךְ נִקְרְאוּ צַדִּיקִים. מִכָּאן לָמַדְנוּ, כָּל מִי שֶׁשּׁוֹמֵר הַבְּרִית הַזּוֹ שֶׁהָעוֹלָם עוֹמֵד עָלֶיהָ, נִקְרָא צַדִּיק. מִנַּיִן לָנוּ? מִיּוֹסֵף. מִשּׁוּם שֶׁשָּׁמַר אֶת בְּרִית הָעוֹלָם זָכָה שֶׁנִּקְרָא צַדִּיק. וְעַל כָּךְ וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, אֵלֶּה - בְּכָל מָקוֹם פָּסַל אֶת הָרִאשׁוֹנִים. שָׁנִינוּ וְכוּ'. מַה כָּתוּב לְמַעְלָה בְּפָרָשַׁת בְּרֵאשִׁית? (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וּמִשָּׁם יִפָּרֵד וְגוֹ'. אוֹתוֹ הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא וְנִכְנָס לַגָּן וּמַשְׁקֶה אוֹתוֹ מֵהַשְׁקָאָה שֶׁלְּמַעְלָה, וְעוֹשֶׂה לוֹ נַחַת וְעוֹשֶׂה פֵרוֹת וּמְגַדֵּל זְרָעִים, הוּא אָז נוֹחַ לַכֹּל. וְזֶה נוֹחַ לַגָּן. וְזֶה עוֹשֶׂה מְנוּחָה בּוֹ (נ\"א: לגן, והגן נח בו), כְּמוֹ שֶׁנֶּאֱמַר (שם) כִּי בוֹ שָׁבַת, וְכָתוּב וַיִּשְׁבּת בַּיּוֹם הַשְּׁבִיעִי. וְזֶה סוֹד שֶׁדָּבָר זֶה עוֹשֶׂה תוֹלָדוֹת וְלֹא אַחֵר.</p>\n<p>בֹּא רְאֵה, כְּמוֹ זֶה נֹחַ לְמַטָּה הַבְּרִית הַקָּדוֹשׁ הָיָה דֻגְמָא שֶׁלְּמַעְלָה, וְעַל זֶה נִקְרָא אִישׁ הָאֲדָמָה. וְסוֹד לָמַדְנוּ, שֶׁהֲרֵי נֹחַ הִצְטָרֵךְ לַתֵּבָה לְהִתְחַבֵּר עִמָּהּ וּלְקַיֵּם זֶרַע שֶׁל הַכֹּל, שֶׁכָּתוּב לְחַיּוֹת זֶרַע.</p>\n<p>מִי זוֹ הַתֵּבָה? (זה) אֲרוֹן הַבְּרִית. וְנֹחַ וְהַתֵּבָה לְמַטָּה כָּךְ הֵם כְּמוֹ דֻגְמָא (זו) שֶׁלְּמַעְלָה. בְּנֹחַ כָּתוּב בְּרִית, שֶׁכָּתוּב וַהֲקִימֹתִי אֶת בְּרִיתִי אִתָּךְ. וְעַד שֶׁהִתְקַיֵּם בּוֹ בְּרִית לֹא נִכְנַס לַתֵּבָה, שֶׁכָּתוּב וַהֲקִימֹתִי אֶת בְּרִיתִי אִתָּךְ וּבָאתָ אֶל הַתֵּבָה. וְאָז הָיְתָה הַתֵּבָה אֲרוֹן הַבְּרִית.</p>\n<p>(זו) תֵּבָה וְנֹחַ, הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה. וּבִגְלַל שֶׁהַבְּרִית הַזֹּאת לְמַעְלָה, הוּא עוֹשֶׂה תוֹלָדוֹת. כְּמוֹ זֶה נֹחַ (למטה) הוּא עוֹשֶׂה תוֹלָדוֹת. מִשּׁוּם כָּךְ (כמו שנאמר) אֵלֶּה תּוֹלְדת נֹחַ.</p>\n<p>נֹחַ אִישׁ צַדִּיק, כָּךְ הוּא בְּוַדַּאי כְּמוֹ שֶׁלְּמַעְלָה. וְעַל זֶה כָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. וְהָאָרֶץ מִתְקַיֶּמֶת עַל זֶה, שֶׁהֲרֵי הוּא הָעַמּוּד שֶׁהָעוֹלָם עוֹמֵד עָלָיו, וּמִיהוּ? זֶה צַדִּיק, וְנֹחַ נִקְרָא צַדִּיק לְמַטָּה.</p>\n<p>וְסוֹד (נ\"א: זה) שֶׁל הַכֹּל - אֶת הָאֱלֹהִים הִתְהַלֶּךְ נֹחַ. דַּוְקָא. שֶׁלֹּא נִפְרַד מִמֶּנּוּ לְעוֹלָמִים, וְשֶׁיִּהְיֶה הוּא בָּאָרֶץ כְּמוֹ שֶׁלְּמַעְלָה אִישׁ צַדִּיק יְסוֹד הָעוֹלָם. בְּרִית שָׁלוֹם, שָׁלוֹם שֶׁל הָעוֹלָם. אִישׁ הָאֲדָמָה וַדַּאי. וְעַל זֶה (בראשית ו) וְנֹחַ מָצָא חֵן בְּעֵינֵי ה'.</p>\n<p>תָּמִים הָיָה בְּדרֹתָיו, מַה זֶּה בְּדרֹתָיו? אֵלֶּה אוֹתָם שֶׁיָּצְאוּ מִמֶּנּוּ. הוּא הִשְׁלִים אֶת כֻּלָּם, וְהוּא הָיָה שָׁלֵם מִכֻּלָּם. תָּמִים הָיָה - שֶׁנּוֹלַד מָהוּל, שֶׁכָּתוּב הִתְהַלֵּךְ לְפָנַי וֶהֱיֵה תָמִים. בְּדרֹתָיו - וְלֹא בַּדּוֹרוֹת שֶׁל הָעוֹלָם, שֶׁהֲרֵי מִמֶּנּוּ יָצְאוּ (תולדות בעולם).</p>\n<p>בֹּא רְאֵה, נֹחַ רָאוּי הָיָה מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם לִהְיוֹת בַּתֵּבָה בְּחִבּוּר אֶחָד לְהִכָּנֵס בָּהּ, וְעַד שֶׁלֹּא הִתְחַבְּרוּ כְּאֶחָד, לֹא הָיָה הָעוֹלָם כָּרָאוּי. אַחַר כָּךְ מַה כָּתוּב? (שם ט) וּמֵאֵלֶּה נָפְצָה כָל הָאָרֶץ. מַהוּ נָפְצָה? כְּמוֹ שֶׁנֶּאֱמַר (שם ב) וּמִשָּׁם יִפָּרֵד. שֶׁמִּשָּׁם נִמְצָא פֵרוּד וְהִתְפַּזְּרוּ תוֹלָדוֹת לְכָל הַצְּדָדִים</p>\n<p>וְהַכֹּל אֶחָד כְּדֻגְמָא אַחַת. מִשּׁוּם כָּךְ אֵלֶּה תּוֹלְדֹת נֹחַ. אֵלֶּה וַדַּאי. שֶׁהֲרֵי יְסוֹד הָעוֹלָם הוּא שֶׁעוֹשֶׂה תוֹלָדוֹת לְקַיֵּם בָּאָרֶץ. בָּא רַבִּי אַבָּא וּנְשָׁקוֹ. אָמַר, אַרְיֵה בְּכֹחוֹ נוֹקֵב סֶלַע וְשׁוֹבֵר. כָּךְ זֶה בְּוַדַּאי. וּבֹא וּרְאֵה, מִשִּׁעוּר הַתֵּבָה גַּם כָּךְ זֶה.</p>\n<p>לָמָּה נֹחַ נֹחַ פַּעֲמַיִם? אֶלָּא כָּל צַדִּיק וְצַדִּיק שֶׁבָּעוֹלָם יֵשׁ לוֹ שְׁתֵּי רוּחוֹת - רוּחַ אַחַת בָּעוֹלָם הַזֶּה, וְרוּחַ אַחַת בָּעוֹלָם הַבָּא. וְכָךְ תִּמְצָא בְּכָל הַצַּדִּיקִים: מֹשֶׁה מֹשֶׁה, יַעֲקֹב יַעֲקֹב, אַבְרָהָם אַבְרָהָם, שְׁמוּאֵל שְׁמוּאֵל, שֵׁם שֵׁם. פְּרָט לְיִצְחָק שֶׁלֹּא כָתוּב בּוֹ כְּמוֹ שֶׁכָּתוּב בָּהֶם, מִשּׁוּם שֶׁיִּצְחָק, בְּשָׁעָה שֶׁנִּקְרַב עַל גַּבֵּי הַמִּזְבֵּחַ, יָצְאָה נִשְׁמָתוֹ שֶׁהָיְתָה בּוֹ בָּעוֹלָם הַזֶּה. וְכֵיוָן שֶׁנֶּאֱמַר בְּאַבְרָהָם בָּרוּךְ מְחַיֵּה הַמֵּתִים, שָׁבָה אֵלָיו נִשְׁמָתוֹ שֶׁל הָעוֹלָם הַבָּא. מִשּׁוּם זֶה תִּמְצָא שֶׁלֹּא יִחֵד הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת שְׁמוֹ אֶלָּא עַל יִצְחָק, מִשּׁוּם שֶׁנֶּחְשַׁב כְּמֵת. וְעַל זֶה רָמַז הַכָּתוּב וְאָמַר (איוב טו) הֵן בִּקְדשָׁו לֹא יַאֲמִין וְגוֹ'.</p>\n<p>דָּבָר אַחֵר אֵלֶּה תּוֹלְדת, מִשּׁוּם שֶׁהָיָה צַדִּיק שִׁבַּח אוֹתוֹ פַּעֲמַיִם. תָּמִים הָיָה בְּדרֹתָיו, אֲבָל בְּדוֹרוֹת אֲחֵרִים אֵינוֹ נֶחְשָׁב לִכְלוּם, כְּמוֹ דּוֹרוֹ שֶׁל אַבְרָהָם וְדוֹר מֹשֶׁה וְדוֹר דָּוִד. דָּבָר אַחֵר, רְאֵה מֶה עָשָׂה בְּדוֹר שֶׁכֻּלָּם רְשָׁעִים, קַל וָחֹמֶר אִלּוּ הָיָה בְּדוֹר שֶׁכֻּלָּם צַדִּיקִים. ע\"כ התוספתא</p>"],[9522011138,"<p>רַבִּי אֶלְעָזָר פָּתַח, (תהלים מו) לְכוּ חֲזוּ מִפְעֲלוֹת ה' אֲשֶׁר שָׂם שַׁמּוֹת בָּאָרֶץ. הַפָּסוּק הַזֶּה הֲרֵי נִתְבָּאֵר, וּבֵאֲרוּהוּ. אֲבָל לְכוּ חֲזוּ, מַה זֶּה חֲזוּ? כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כא) חָזוּת קָשָׁה הֻגַּד לִי. בְּמַעֲשָׂיו שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה מִתְגַּלָּה נְבוּאָה עֶלְיוֹנָה לִבְנֵי אָדָם. אֲשֶׁר שָׂם שַׁמּוֹת - שֵׁמוֹת וַדַּאי, שֶׁהֲרֵי הַשֵּׁם גּוֹרֵם לַכֹּל.</p>\n<p>כָּתוּב וַיִּקְרָא אֶת שְׁמוֹ נֹחַ לֵאמֹר זֶה וְגוֹ', לָמָּה כָּאן לֵאמֹר? וְלָמָּה זֶה? אֶלָּא לֵאמֹר זוֹ הָאִשָּׁה. זֶה זֶה צַדִּיק. (רמז כמו שהקדוש ברוך הוא קרא לו נח, מנוחת הארץ, לאמר, מה זה לאמר? אלא מקום זה קרא לו נח, ומי הוא? ארץ הקדושה, לאמר זה ינחמנו ממעשנו וגו', עשה אותו הקדוש ברוך הוא למטה כדגמא עליונה). (נ\"א: זה זה צדיק, וכן נח (לאמר, נח) זה צדיק, לאמר זו נקבה, משום שלא נפרדים זה מזה, אמר רבי יצחק, לאמר זו ארץ הקדושה) (וזה אמת). כָּתוּב כָּאן זֶה יְנַחֲמֵנוּ, וְכָתוּב שָׁם (ישעיה כה) זֶה ה' קִוִּינוּ לוֹ. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁרְשׁוּמִים בָּרֹשֶׁם שֶׁל חוֹתֶמֶת הַמֶּלֶךְ לִהְיוֹת בִּשְׁמוֹ רְשׁוּמִים, וְהוּא שָׂם שֵׁמוֹת בָּאָרֶץ כָּרָאוּי.</p>\n<p>כָּתוּב וַיִּקְרָא אֶת שְׁמוֹ נֹחַ, וְכָתוּב וַיִּקְרָא שְׁמוֹ יַעֲקֹב. לָמָּה לֹא כָתוּב אֶת? אֶלָּא שָׁם דַּרְגָּה אַחֶרֶת (ד\"א אחת) וְכָאן דַּרְגָּה אַחֶרֶת, (נ\"א: את, כמו שנאמר ואראה את ה') כַּכָּתוּב (שם ו) וָאֶרְאֶה אֶת ה'. וָאֶרְאֶה ה' לֹא כָתוּב אֶלָּא אֶת ה', גַּם כָּךְ בְּנֹחַ וַיִּקְרָא אֶת שְׁמוֹ נֹחַ. וַיִּקְרָא שְׁמוֹ יַעֲקֹב - דַּרְגָּה שֶׁלּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מַמָּשׁ קָרְאָה לוֹ יַעֲקֹב. אֲבָל כָּאן אֶת - לְהַכְלִיל אֶת הַשְּׁכִינָה (נ\"א: שהיא דרגה אחרת למטה).</p>"],[9522011139,"<p>אֵלֶּה תּוֹלְדת נֹחַ וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (תהלים קיב) טוֹב אִישׁ חוֹנֵן וּמַלְוֶה יְכַלְכֵּל דְּבָרָיו בְּמִשְׁפָּט. טוֹב אִישׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּקְרָא טוֹב, כְּמוֹ שֶׁכָּתוּב (שם קמה) טוֹב ה' לַכֹּל, וְכָתוּב (שמות טו) ה' אִישׁ מִלְחָמָה. לַכֹּל הַזֶּה חוֹנֵן וּמַלְוֶה, לְמָקוֹם שֶׁאֵין לוֹ מִשֶּׁלּוֹ, וְאוֹתוֹ מָקוֹם נִזּוֹן מִמֶּנּוּ. יְכַלְכֵּל דְּבָרָיו בְּמִשְׁפָּט - שֶׁהֲרֵי אוֹתוֹ דָבָר לֹא נִזּוֹן אֶלָּא בְּמִשְׁפָּט, כְּמוֹ שֶׁנֶּאֱמַר (תהלים פט) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֲךְ.</p>\n<p>דָּבָר אַחֵר טוֹב אִישׁ - זֶה צַדִּיק, שֶׁכָּתוּב (ישעיה ג) אִמְרוּ צַדִּיק כִּי טוֹב כִּי פְּרִי מַעַלְלֵיהֶם יֹאכֵלוּ. רַבִּי יוֹסֵי אָמַר, זֶה נֹחַ, שֶׁכָּתוּב נֹחַ אִישׁ צַדִּיק. רַבִּי יִצְחָק אָמַר, זֶה הַשֶּׁבַח שֶׁל הַשַּׁבָּת שֶׁבּוֹ פָּתַח טוֹב, שֶׁכָּתוּב (תהלים צב) טוֹב לְהוֹדוֹת לַה'.</p>\n<p>רַבִּי חִיָּיא אָמַר, הַכֹּל אֶחָד, וְכֻלָּם אָמְרוּ דָּבָר אֶחָד. וְזֶה עוֹשֶׂה תוֹלָדוֹת בָּעוֹלָם. תּוֹלָדוֹת שֶׁל הָעוֹלָם מִי הֵם? אֵלּוּ נִשְׁמוֹת הַצַּדִּיקִים שֶׁהֵם פְּרִי מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַטֵּר בְּעַטְּרוֹתָיו, מִתְעַטֵּר מִלְמַעְלָה וּמִלְּמַטָּה, מִלְמַעְלָה מִמָּקוֹם שֶׁלְּעֹמֶק הַכֹּל. מִתְעַטֵּר מִלְּמַטָּה בַּמֶּה? בְּנִשְׁמוֹת הַצַּדִּיקִים. וְאָז נוֹסָפִים חַיִּים מִלְמַעְלָה וּמִלְּמַטָּה, וְנִכְלָל מְקוֹם הַמִּקְדָּשׁ מִכָּל הַצְּדָדִים, וְהַבְּאֵר מִתְמַלֵּאת וְהַיָּם נִשְׁלָם, וְאָז נוֹתֵן לַכֹּל.</p>"],[9522011140,"<p>כָּתוּב (משלי ה) שְׁתֵה מַיִם מִבּוֹרֶךְ וְנוֹזְלִים מִתּוֹךְ בְּאֵרֶךְ. לָמָּה (כאן) בּוֹרֶךְ בַּתְּחִלָּה וְאַחַר כָּךְ בְּאֵרֶךְ? שֶׁהֲרֵי בּוֹר לֹא נִקְרָא אֶלָּא רֵיק שֶׁאֵינוֹ נוֹבֵעַ. בְּאֵר - מַיִם שֶׁנּוֹבְעִים? אֶלָּא הַכֹּל מָקוֹם אֶחָד הוּא. אֶלָּא מָקוֹם שֶׁהָעֲנִיִּים (נ\"א שהעני) אֲחוּזִים בּוֹ נִקְרָא בּוֹר, שֶׁאֵין לוֹ מִשֶּׁלּוֹ אֶלָּא מַה שֶּׁנּוֹתְנִים לְתוֹכוֹ, וּמִיהוּ? דָּלֶ\"ת.</p>\n<p>אַחַר כָּךְ נַעֲשֶׂה בְאֵר שֶׁהוּא נוֹבֵעַ וּמָלֵא (שמתמלא) מִכָּל הַצְּדָדִים, וּמִיהוּ? הֵ\"א. מִתְמַלֵּאת מִלְמַעְלָה וְנוֹבַעַת מִלְּמַטָּה. מִתְמַלֵּאת מִלְמַעְלָה כְּמוֹ שֶׁאָמַרְנוּ, וְנוֹבַעַת מִלְּמַטָּה מִנִּשְׁמוֹת הַצַּדִּיקִים.</p>\n<p>דָּבָר אַחֵר, שְׁתֵה מַיִם מִבּוֹרֶךְ - זֶה דָּוִד הַמֶּלֶךְ, שֶׁכָּתוּב בּוֹ (שמואל ב כג) מִי יַשְׁקֵנִי מַיִם מִבֹּאר בֵּית לֶחֶם. וְנוֹזְלִים - זֶה אַבְרָהָם. מִתּוֹךְ - זֶה יַעֲקֹב, שֶׁהוּא בָּאֶמְצַע. בְּאֵרֶךְ - זֶה יִצְחָק, שֶׁנִּקְרָא בְּאֵר מַיִם חַיִּים. הֲרֵי בַּפָּסוּק הַזֶּה נִמְצֵאת הַמֶּרְכָּבָה הַקְּדוֹשָׁה הָעֶלְיוֹנָה מֵהָאָבוֹת. וְדָוִד הַמֶּלֶךְ הִתְחַבֵּר עִמָּם. יֵשׁ מִי שֶׁיֹּאמַר, וְנוֹזְלִים - זֶה יִצְחָק. מִתּוֹךְ - זֶה מֹשֶׁה, שֶׁהוּא בָּאֶמְצַע. בְּאֵרֶךְ - זֶה אַהֲרֹן, שֶׁנִּקְרָא בְּאֵר מַיִם חַיִּים, וְדָוִד הַמֶּלֶךְ שֶׁהִתְחַבֵּר עִמָּהֶם.</p>\n<p>תְּשׁוּקַת הַנְּקֵבָה לַזָּכָר אֵינָהּ אֶלָּא כַּאֲשֶׁר נִכְנֶסֶת בָּהּ רוּחַ וְשׁוֹפֶכֶת מַיִם כְּנֶגֶד הַמַּיִם הָעֶלְיוֹנִים הַזְּכָרִיִּים. כָּךְ כְּנֶסֶת יִשְׂרָאֵל לֹא מְעוֹרֶרֶת הִשְׁתּוֹקְקוּת לַקָּדוֹשׁ- בָּרוּךְ-הוּא אֶלָּא בְּרוּחַ הַצַּדִּיקִים שֶׁנִּכְנָסִים בְּתוֹכָהּ, וְאָז נוֹבְעִים מַיִם מִתּוֹכָהּ כְּנֶגֶד מֵי הַזָּכָר. וְהַכֹּל נַעֲשֶׂה תְשׁוּקָה אַחַת (ואגדה אחת) וְקִשּׁוּר אֶחָד. וְזֶהוּ רָצוֹן שֶׁל הַכֹּל וְהַטִּיּוּל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְטַיֵּל עִם נִשְׁמוֹת הַצַּדִּיקִים.</p>\n<p>בֹּא רְאֵה, כָּל אוֹתָן תּוֹלְדוֹת גַּן הָעֵדֶן לֹא יוֹצְאִים מִצַּדִּיק אֶלָּא כְּשֶׁנִּכְנָס בַּתֵּבָה הַזּוֹ בְּחִבּוּר אֶחָד, וְהַכֹּל גְּנוּזִים בָּהּ, וְאַחַר כָּךְ יוֹצְאִים מִמֶּנָּה. גַּם כָּאן נֹחַ אִישׁ צַדִּיק לֹא הוֹצִיא תוֹלָדוֹת לִפְרוֹת בָּעוֹלָם עַד שֶׁנִּכְנַס בַּתֵּבָה, וְהִתְכַּנְּסוּ הַכֹּל בָּהּ וְהָיוּ גְנוּזִים בָּהּ, וְאַחַר כָּךְ יָצְאוּ מִמֶּנָּה לִפְרוֹת בָּעוֹלָם וּלְהִתְקַיֵּם בָּאָרֶץ. וְאִלְמָלֵא שֶׁיָּצְאוּ מִתּוֹךְ הַתֵּבָה, לֹא הִתְקַיְּמוּ בָעוֹלָם.</p>\n<p>וְהַכֹּל כְּמוֹ שֶׁלְּמַעְלָה - מִתּוֹךְ תֵּבָה יוֹצְאִים לְמַעְלָה, מִתּוֹךְ תֵּבָה יוֹצְאִים לְמַטָּה, זֶה כְּמוֹ זֶה. (מתוך) וְכָאן הִתְקַיֵּם הָעוֹלָם וְלֹא מִקֹּדֶם לָזֶה, שֶׁמִּשּׁוּם כָּךְ כָּתוּב וְנוֹזְלִים מִתּוֹךְ בְּאֵרֶךְ, וְכָתוּב וַיּוֹלֶד נֹחַ שְׁלֹשָׁה בָנִים.</p>"],[9522011141,"<p>וַתִּשָּׁחֵת הָאָרֶץ לִפְנֵי הָאֱלֹהִים. אָמַר רַבִּי יְהוּדָה, כֵּיוָן שֶׁכָּתוּב וַתִּשָּׁחֵת הָאָרֶץ, לָמָּה לִפְנֵי הָאֱלֹהִים? אֶלָּא כֵּיוָן שֶׁעָשׂוּ חֲטָאֵיהֶם בְּגָלוּי לְעֵינֵי הַכֹּל, אָז כָּתוּב לִפְנֵי הָאֱלֹהִים.</p>\n<p>רַבִּי יוֹסֵי אָמַר, אֲנִי אָמַרְתִּי הָפוּךְ. וַתִּשָּׁחֵת הָאָרֶץ לִפְנֵי הָאֱלֹהִים - בַּהַתְחָלָה לִפְנֵי הָאֱלֹהִים, שֶׁלֹּא הָיוּ עוֹשִׂים בְּגָלוּי. לִפְנֵי הָאֱלֹהִים עָשׂוּ וְלֹא לִפְנֵי בְּנֵי אָדָם. וּלְבַסּוֹף עָשׂוּ בְגָלוּי. זֶהוּ שֶׁכָּתוּב וַתִּמָּלֵא הָאָרֶץ חָמָס, שֶׁלֹּא הָיָה מָקוֹם בְּכָל הָאָרֶץ שֶׁלֹּא הָיָה בְגָלוּי, וּבִגְלַל כָּךְ אָמַר הַפָּסוּק בִּשְׁנֵי גְוָנִים.</p>\n<p>אֵלֶּה תּוֹלְדת נֹחַ - רַבִּי אַבָּא אָמַר, מִיּוֹם שֶׁעָבַר אָדָם עַל מִצְוַת רִבּוֹנוֹ, כָּל בְּנֵי הָאָדָם שֶׁנּוֹלְדוּ אַחַר כָּךְ נִקְרְאוּ בְּנֵי הָאָדָם. וְלֹא לְשֶׁבַח נִקְרְאוּ כָּךְ, אֶלָּא כְּמוֹ שֶׁאָמַר בְּנוֹ שֶׁל אוֹתוֹ שֶׁעָבַר עַל מִצְוַת רִבּוֹנוֹ.</p>\n<p>כֵּיוָן שֶׁבָּא נֹחַ, נִקְרְאוּ בְּנֵי הָעוֹלָם עַל שֵׁם נֹחַ. תּוֹלְדת נֹחַ לְשֶׁבַח. שֶׁהֶעֱמִידָם בָּעוֹלָם. וְלֹא תוֹלְדוֹת אָדָם שֶׁהֶעֱבִירָם מֵהָעוֹלָם וְגָרַם מָוֶת לְכֻלָּם.</p>\n<p>אָמַר לוֹ רַבִּי יוֹסֵי, אִם כָּךְ, הֲרֵי כָּתוּב אַחַר כָּךְ, וַיֵּרֶד ה' לִרְאוֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם. בְּנֵי הָאָדָם כָּתוּב, וְלֹא כָתוּב בְּנֵי נֹחַ. אָמַר לוֹ, מִשּׁוּם שֶׁאָדָם (שחטא ד\"א חטא) לִפְנֵי רִבּוֹנוֹ, טוֹב לוֹ שֶׁלֹּא נִבְרָא וְלֹא יִכְתֹּב עָלָיו הַכָּתוּב פָּסוּק זֶה.</p>\n<p>אֶלָּא בּא רְאֵה, כָּתוּב (משלי י) בֵּן חָכָם יְשַׂמַּח אָב. כַּאֲשֶׁר הַבֵּן טוֹב, כָּל בְּנֵי הָעוֹלָם זוֹכְרִים אֶת אָבִיו לְטוֹב. וּכְשֶׁהוּא רַע, כֻּלָּם זוֹכְרִים אֶת אָבִיו לְרַע. אָדָם, מִשּׁוּם שֶׁחָטָא וְעָבַר עַל מִצְוַת רִבּוֹנוֹ, כְּשֶׁבָּאוּ אוֹתָם שֶׁמָּרְדוּ בְּרִבּוֹנָם מַה כָּתוּב? אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם. אָדָם הָרִאשׁוֹן שֶׁמָּרַד בְּרִבּוֹנוֹ וְעָבַר עַל מִצְוָתוֹ,</p>\n<p>וְלָכֵן אֵלֶּה תּוֹלְדת נֹחַ. אֵלֶּה וְלֹא הָרִאשׁוֹנִים. אֵלֶּה שֶׁיָּצְאוּ וְנִכְנְסוּ לְתוֹךְ הַתֵּבָה וְהוֹצִיאוּ תוֹלָדוֹת לְעוֹלָמִים. וְלֹא תוֹלְדוֹת אָדָם שֶׁיָּצָא מִגַּן עֵדֶן וְלֹא הוֹצִיא אוֹתָם מִשָּׁם.</p>"],[9522011142,"<p>בֹּא רְאֵה, אִלּוּ הוֹצִיא אָדָם תּוֹלָדוֹת מִגַּן עֵדֶן, לֹא הָיוּ מֻשְׁמָדִים לְדוֹרֵי דוֹרוֹת, וְלֹא נֶחְשַׁךְ אוֹר הַלְּבָנָה לְעוֹלָמִים, וְכֻלָּם הָיוּ קַיָּמִים לְעוֹלָמִים, וַאֲפִלּוּ מַלְאָכִים עֶלְיוֹנִים לֹא עָמְדוּ לִפְנֵיהֶם בְּאוֹר וְזִיו וְחָכְמָה, כְּמוֹ שֶׁנֶּאֱמַר בְּצֶלֶם אֱלֹהִים בָּרָא אוֹתוֹ. אֲבָל כֵּיוָן שֶׁגָּרַם הַחֵטְא וְיָצָא מִגַּן עֵדֶן וְעָשָׂה תוֹלָדוֹת בַּחוּץ, לֹא הִתְקַיְּמוּ בָעוֹלָם וְלֹא הָיוּ כָּרָאוּי.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, וְכִי אֵיךְ יָכְלוּ לַעֲשׂוֹת תּוֹלָדוֹת שָׁם, שֶׁהֲרֵי אִלְמָלֵא לֹא נִמְשַׁךְ עָלָיו יֵצֶר הָרָע וְחָטָא, יִתְקַיֵּם הוּא בָּעוֹלָם לְבַדּוֹ וְלֹא יַעֲשֶׂה תוֹלָדוֹת? כְּמוֹ זֶה אִלְמָלֵא שֶׁחָטְאוּ יִשְׂרָאֵל בָּעֵגֶל וְהִמְשִׁיכוּ עֲלֵיהֶם יֵצֶר הָרָע, לֹא יַעֲשׂוּ לְעוֹלָמִים תּוֹלָדוֹת וְלֹא יָבאוּ דוֹרוֹת אֲחֵרִים לָעוֹלָם.</p>\n<p>אָמַר לוֹ, אִלְמָלֵא לֹא חָטָא אָדָם, לֹא יַעֲשֶׂה תוֹלָדוֹת כְּמוֹ זֶה מִצַּד שֶׁל יֵצֶר הָרָע, אֲבָל יַעֲשֶׂה תוֹלָדוֹת מִצַּד שֶׁל רוּחַ הַקֹּדֶשׁ. שֶׁעַכְשָׁו אֵינוֹ עוֹשֶׂה תוֹלָדוֹת אֶלָּא מִצַּד הַיֵּצֶר הָרָע, וּמִשּׁוּם שֶׁכָּל תּוֹלְדוֹת בְּנֵי הָאָדָם כֻּלָּם מִן הַצַּד שֶׁל יֵצֶר הָרָע, לָכֵן אֵין לָהֶם קִיּוּם, וְאִי אֶפְשָׁר לָהֶם לְהִתְקַיֵּם, שֶׁהַצַּד הָאַחֵר מְעֹרָב בָּהֶם (ואפשר להם בצד האחר).</p>\n<p>אֲבָל אִלְמָלֵא לֹא חָטָא אָדָם וְלֹא גֹרַשׁ מִגַּן עֵדֶן, הָיָה עוֹשֶׂה תוֹלָדוֹת מִצַּד שֶׁל רוּחַ הַקֹּדֶשׁ, שֶׁקְּדוֹשִׁים כְּמַלְאָכִים עֶלְיוֹנִים עוֹמְדִים לְדוֹרֵי דוֹרוֹת כְּמוֹ שֶׁהָיָה לְמַעְלָה. כֵּיוָן שֶׁחָטָא וְהוֹלִיד בָּנִים מִחוּץ לְגַן עֵדֶן וְלֹא זָכָה לְהוֹצִיאָם מִן הַגָּן, לֹא הִתְקַיְּמוּ אֲפִלּוּ לְהִשְׁתָּרֵשׁ בָּעוֹלָם הַזֶּה, עַד שֶׁבָּא נֹחַ, שֶׁהוּא צַדִּיק, וְנִכְנַס בַּתֵּבָה, וּמֵהַתֵּבָה יָצְאוּ כָּל דּוֹרוֹת הָעוֹלָם, וּמִשָּׁם הִתְפַּזְּרוּ לְכָל אַרְבַּע רוּחוֹת הָעוֹלָם.</p>"],[9522011143,"<p>וַיַּרְא אֱלֹהִים אֶת הָאָרֶץ וְהִנֵּה נִשְׁחָתָה. לָמָּה נִשְׁחָתָה? מִשּׁוּם כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ, כְּמוֹ שֶׁנֶּאֱמַר. רַבִּי חִיָּיא פָּתַח פָּסוּק וְאָמַר, (יונה ג) וַיַּרְא אֱלֹהִים אֶת מַעֲשֵׂיהֶם כִּי שָׁבוּ מִדַּרְכָּם הָרָעָה. בֹּא רְאֵה, בְּשָׁעָה שֶׁבְּנֵי אָדָם זוֹכִים וְשׁוֹמְרִים אֶת מִצְווֹת הַתּוֹרָה, אָז הָאָרֶץ מִתְחַזֶּקֶת וְנִמְצֵאת בָּהּ כָּל הַשִּׂמְחָה. מָה הַטַּעַם? מִשּׁוּם שֶׁהַשְּׁכִינָה שׁוֹרָה עַל הָאָרֶץ. וְאָז הַכֹּל, עֶלְיוֹנִים וְתַחְתּוֹנִים, בְּחֶדְוָה. וּכְשֶׁבְּנֵי אָדָם מַשְׁחִיתִים דַּרְכֵיהֶם וְלֹא שׁוֹמְרִים אֶת מִצְווֹת הַתּוֹרָה וְחוֹטְאִים לִפְנֵי רִבּוֹנָם, אָז כִּבְיָכוֹל דּוֹחִים אֶת הַשְּׁכִינָה מֵהָעוֹלָם, וְנִשְׁאֶרֶת הָאָרֶץ מֻשְׁחֶתֶת, שֶׁהֲרֵי הַשְּׁכִינָה נִדְחֲתָה וְלֹא שׁוֹרָה עָלֶיהָ, וְאָז הִיא נִשְׁחֶתֶת. מָה הַטַּעַם נִשְׁחֶתֶת? מִשּׁוּם שֶׁשּׁוֹרָה רוּחַ אַחֶרֶת עָלֶיהָ שֶׁמְּחַבֶּלֶת אֶת הָעוֹלָם. וְעַל זֶה אוֹמְרִים, שֶׁיִּשְׂרָאֵל נוֹתְנִים עֹז לֵאלֹהִים שֶׁמַּעֲמִידִים אֶת הָעוֹלָם. אֱלֹהִים זוֹ שְׁכִינָה.</p>\n<p>וְאִם חַס וְשָׁלוֹם אִם יִשְׂרָאֵל יִמָּצְאוּ רְשָׁעִים, מַה כָּתוּב? (תהלים ו) רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים וְגוֹ', מִשּׁוּם שֶׁרֶשֶׁת הֵכִינוּ לִפְעָמַי. כָּפַף נַפְשִׁי, בְּסִבַּת חָמָס וְשִׂנְאַת חִנָּם. כָּרוּ לְפָנַי שׁוּחָה וְגוֹ', כְּמוֹ שֶׁבְּדוֹר הַמַּבּוּל, שֶׁמִּשּׁוּם הֶחָמָס שֶׁהָיָה בֵינֵיהֶם, הָיְתָה בֵינֵיהֶם שִׂנְאָה וְאֵיבָה.</p>\n<p>יָכוֹל אַף בְּאֶרֶץ יִשְׂרָאֵל כֵּן? וַהֲרֵי שָׁנִינוּ שֶׁאֶרֶץ יִשְׂרָאֵל לֹא שׁוֹרָה עָלֶיהָ רוּחַ אַחֶרֶת וְלֹא מְמֻנֶּה אַחֵר חוּץ מֵהַקָּדוֹשׁ בָּרוּךְ הוּא בִּלְבַדּוֹ. בֹּא רְאֵה שֶׁאֶרֶץ יִשְׂרָאֵל כָּךְ הִיא שֶׁלֹּא שׁוֹרֶה עָלֶיהָ מְמֻנֶּה וְלֹא שָׁלִיחַ אַחֵר פְּרָט לַקָּדוֹשׁ-בָּרוּךְ- הוּא לְבַדּוֹ, אֲבָל שָׁעָה אַחַת שׁוֹרֶה עָלֶיהָ לְהַשְׁחִית אֶת בְּנֵי הָאָדָם. מִנַּיִן לָנוּ? מִדָּוִד, שֶׁכָּתוּב (דברי הימים א כא) וַיַּרְא דָוִד אֶת מַלְאַךְ ה' וְחַרְבּוֹ שְׁלוּפָה בְּיָדוֹ נְטוּיָה עַל יְרוּשָׁלַיִם, וְאָז נִשְׁחֲתָה הָאָרֶץ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אֲפִלּוּ בְּאוֹתָהּ שָׁעָה הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה. כָּתוּב כָּאן מַלְאַךְ ה', וְכָתוּב שָׁם (בראשית מח) הַמַּלְאָךְ הַגֹּאֵל אֹתִי, וְכָתוּב וַיִּסַּע מַלְאַךְ הָאֱלֹהִים. הֵן לְטוֹב הֵן לְרַע שׁוֹלֵט עָלֶיהָ הַקָּדוֹשׁ בָּרוּךְ הוּא. לְטוֹב - מִשּׁוּם שֶׁלֹּא נִמְסְרָה תַּחַת שְׁאָר הַמְמֻנִּים, וְכָל דַּיָּרֵי הָעוֹלָם יִתְבַּיְּשׁוּ מִמַּעֲשֵׂיהֶם. לְרַע - כְּדֵי שֶׁלֹּא יִשְׂמְחוּ אֵלֶּה לִשְׁלֹט עָלֶיהָ.</p>\n<p>וְאִם תֹּאמַר, וַהֲרֵי כָּתוּב (איכה א) כִּי רָאֲתָה גוֹיִם בָּאוּ מִקְדָּשָׁהּ, וְהֶחֱרִיבוּ בֵיתָהּ. וְאִם לֹא שׁוֹלְטִים אוֹתָם מְמֻנִּים, לֹא נֶחֱרַב הַמִּקְדָּשׁ! בֹּא רְאֵה, כָּתוּב כִּי אַתָּה עָשִׂיתָ, וְכָתוּב (שם ב) עָשָׂה ה' אֲשֶׁר זָמָם.</p>\n<p>בֹּא רְאֵה, כָּתוּב וַיַּרְא אֱלֹהִים אֶת הָאָרֶץ וְהִנֵּה נִשְׁחָתָה. נִשְׁחָתָה וַדַּאי, כְּמוֹ שֶׁנֶּאֱמַר. כָּךְ גַּם (יונה ג) וַיַּרְא אֱלֹהִים אֶת מַעֲשֵׂיהֶם כִּי שָׁבוּ מִדַּרְכָּם הָרָעָה. שֶׁהֲרֵי אָז הָאָרֶץ קוֹרֵאת לְמַעְלָה וְעוֹלָה בַּעֲלִיָּה עֶלְיוֹנָה וּמְקַשֶּׁטֶת פָּנֶיהָ כִּנְקֵבָה שֶׁמִּתְקַשֶּׁטֶת אֶל הַזָּכָר, כָּךְ גַּם הָאָרֶץ, שֶׁהֲרֵי גִּדְּלָה בָנִים צַדִּיקִים לַמֶּלֶךְ.</p>\n<p>וְעַכְשָׁו שֶׁלֹּא שָׁבוּ דּוֹר הַמַּבּוּל מַה כָּתוּב? וַיַּרְא אֱלֹהִים אֶת הָאָרֶץ וְהִנֵּה נִשְׁחָתָה, כְּאִשָּׁה שֶׁנִּטְמְאָה וְהִסְתִּירָה פָנֶיהָ מִבַּעְלָהּ. וּבִזְמַן שֶׁמִּתְרַבִּים חֲטָאֵי בְּנֵי הָאָדָם בְּגָלוּי, הָאָרֶץ שָׂמָה פָנֶיהָ כִּנְקֵבָה שֶׁאֵין לָהּ בּוּשָׁה מִכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כד) וְהָאָרֶץ חָנְפָה תַּחַת יֹשְׁבֶיהָ. וְעַל זֶה וַיַּרְא כִּי נִשְׁחָתָה וַדַּאי. מָה הַטַּעַם? מִשּׁוּם כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ עַל הָאָרֶץ.</p>"],[9522011144,"<p>רַבִּי אֶלְעָזָר הָלַךְ אֶל רַבִּי יוֹסֵי בְּרַבִּי שִׁמְעוֹן בֶּן לָקוֹנְיָא חָמִיו. כֵּיוָן שֶׁרָאָה אוֹתוֹ, הִתְקִין לוֹ שָׁטִיחַ שֶׁל כִּסּוּי בְּמוֹטוֹת שֶׁל עֵץ, וְיָשְׁבוּ. אָמַר לוֹ חָמִיו, אֶפְשָׁר שֶׁשָּׁמַעְתָּ מֵאָבִיךְ זֶה שֶׁכָּתוּב (איכה ב) עָשָׂה ה' אֲשֶׁר זָמָם בִּצַּע אֶמְרָתוֹ אֲשֶׁר צִוָּה מִימֵי קֶדֶם?</p>\n<p>אָמַר לוֹ, הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, בִּצַּע אֶמְרָתוֹ - שֶׁקָּרַע הָאַדֶּרֶת שֶׁלּוֹ. אֲשֶׁר צִוָּה מִימֵי קֶדֶם - שֶׁהֲרֵי אוֹתָהּ הָאַדֶּרֶת צִוָּה מֵאוֹתָם יָמִים רִאשׁוֹנִים עֶלְיוֹנִים, וּבַיּוֹם שֶׁחָרַב בֵּית הַמִּקְדָּשׁ קָרַע אוֹתָהּ, מִשּׁוּם שֶׁהָאַדֶּרֶת הַזּוֹ הִיא כְבוֹדוֹ וְתִקּוּנוֹ, וְקָרַע אוֹתָהּ.</p>\n<p>אָמַר לוֹ, עָשָׂה ה' אֲשֶׁר זָמָם, וְכִי מֶלֶךְ חוֹשֵׁב (קדם) לְהָרַע לְבָנָיו עַד שֶׁלֹּא יָבאוּ לַחֲ א!? אָמַר לוֹ, (משל) לְמֶלֶךְ שֶׁהָיָה לוֹ כְּלִי יָקָר, וּבְכָל יוֹם הָיָה פּוֹחֵד עָלָיו שֶׁלֹּא יִשָּׁבֵר וְהָיָה מִסְתַּכֵּל בּוֹ וּמָצָא חֵן בְּעֵינָיו. לְיָמִים בָּא בְּנוֹ וְהִרְגִּיז אֶת הַמֶּלֶךְ. לָקַח הַמֶּלֶךְ אוֹתוֹ כְּלִי יָקָר וְשָׁבַר אוֹתוֹ. זֶהוּ שֶׁכָּתוּב עָשָׂה ה' אֲשֶׁר זָמָם.</p>\n<p>בֹּא רְאֵה, מִיּוֹם שֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ הָיָה הַקָּדוֹשׁ בָּרוּךְ הוּא מִסְתַּכֵּל בּוֹ וְחָבִיב עָלָיו הַרְבֵּה, וְהָיָה פּוֹחֵד עַל יִשְׂרָאֵל שֶׁיֶּחְטְאוּ וְיֵחָרֵב בֵּית הַמִּקְדָּשׁ. וְכָךְ בְּכָל פַּעַם שֶׁהָיָה בָּא אֵצֶל בֵּית הַמִּקְדָּשׁ, הָיָה לוֹבֵשׁ אוֹתָהּ אַדֶּרֶת. אַחַר שֶׁגָּרְמוּ הַחֲטָאִים וְהִרְגִּיזוּ לִפְנֵי הַמֶּלֶךְ, נֶחֱרַב בֵּית הַמִּקְדָּשׁ וְקָרַע אוֹתָהּ הָאַדֶּרֶת (קרע אותה האדרת ונחרב בית המקדש). הַיְנוּ שֶׁכָּתוּב עָשָׂה ה' אֲשֶׁר זָמָם.</p>\n<p>בִּצַע אֶמְרָתוֹ וְגוֹ' (האמרתו הזו בתחלה ישבה בראש אמיר, והרי התעטרו עטרה לראש ואילן נאה לפניו, והיא מימי קדם ודאי, ואז עצבות לפניו בבתים החיצונים ודאי, (ישעיה לג) והן אראלם צעקו חצה,</p>\n<p>(שם כב) ויקרא ה' אלהים צבאות ביום ההוא וגו'). הַיְנוּ בִּזְמַן שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ. אֲבָל בִּזְמַן אַחֵר אֵין חֶדְוָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ זְמַן שֶׁאוֹבְדִים רִשְׁעֵי הָעוֹלָם וְאוֹתָם שֶׁהִרְגִּיזוּ לְפָנָיו. זֶהוּ שֶׁכָּתוּב (משלי יא) וּבַאֲבֹד רְשָׁעִים רִנָּה. וְכֵן בְּכָל דּוֹר וְדוֹר שֶׁעוֹשֶׂה דִין בְּרִשְׁעֵי הָעוֹלָם, חֶדְוָה וְתִשְׁבַּחַת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי שָׁנִינוּ שֶׁאֵין חֶדְוָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁהוּא עוֹשֶׂה דִין בָּרְשָׁעִים אֶלָּא? בּא רְאֵה, בְּשָׁעָה שֶׁנַּעֲשֶׂה דִין בָּרְשָׁעִים, חֶדְווֹת וְתִשְׁבָּחוֹת לְפָנָיו עַל שֶׁנֶּאֶבְדוּ מֵהָעוֹלָם. וְהַדְּבָרִים הַלָּלוּ כְּשֶׁמַּגִּיעַ אוֹתוֹ זְמַן שֶׁהִמְתִּין לָהֶם וְלֹא שָׁבוּ אֵלָיו מֵחֲטָאֵיהֶם. אֲבָל אִם נַעֲשֶׂה בָהֶם דִּין עַד שֶׁלֹּא הִגִּיעַ זְמַנָּם, (ועד) שֶׁלֹּא נִשְׁלָם חֶטְאָם, כְּמוֹ שֶׁנֶּאֱמַר (בראשית טו) כִּי לֹא שָׁלֵם עֲוֹן הָאֱמוֹרִי עַד הֵנָּה, אָז אֵין חֶדְוָה לְפָנָיו, וְרַע לְפָנָיו עַל שֶׁנֶּאֶבְדוּ.</p>\n<p>וְאִם תֹּאמַר, לָמָּה עוֹשֶׂה בָהֶם דִּין טֶרֶם שֶׁהִגִּיעַ זְמַנָּם? אֶלָּא הֵם גָּרְמוּ רַע לְעַצְמָם, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא אֵינוֹ עוֹשֶׂה דִין בְּטֶרֶם מַגִּיעַ זְמַנָּם, אֶלָּא מִשּׁוּם שֶׁמִּשְׁתַּתְּפִים עִם יִשְׂרָאֵל לְהָרַע לָהֶם, וְלָכֵן עוֹשֶׂה בָהֶם דִּין וּמְאַבְּדָם מֵהָעוֹלָם בְּלֹא הַזְּמַן. וְזֶהוּ שֶׁרַע לְפָנָיו. וְלָכֵן הִטְבִּיעַ מִצְרַיִם בַּיָּם וְהֶאֱבִיד שׂוֹנְאֵי יִשְׂרָאֵל בִּימֵי יְהוֹשָׁפָט, וְכֵן כֻּלָּם, שֶׁהֲרֵי מִשּׁוּם יִשְׂרָאֵל נֶאֶבְדוּ לִפְנֵי זְמַנָּם.</p>\n<p>אֲבָל כְּשֶׁהֻשְׁלַם הַזְּמַן שֶׁחִכָּה לָהֶם וְלֹא שָׁבוּ, אָז חֶדְוָה וְתִשְׁבַּחַת לְפָנָיו עַל שֶׁאָבְדוּ מֵהָעוֹלָם, פְּרָט לַזְּמַן שֶׁחָרַב בֵּית הַמִּקְדָּשׁ, שֶׁאַף עַל גַּב שֶׁהֻשְׁלַם הַזְּמַן שֶׁלָּהֶם שֶׁהִרְגִּיזוּ לְפָנָיו, לֹא הָיְתָה חֶדְוָה לְפָנָיו. וּמֵאוֹתוֹ זְמַן לֹא הָיְתָה חֶדְוָה לְפָנָיו לְמַעְלָה וּלְמַטָּה.</p>"],[9522011145,"<p>כִּי לְיָמִים עוֹד שִׁבְעָה אָנֹכִי מַמְטִיר עַל הָאָרֶץ אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה וְגוֹ'. רַבִּי יְהוּדָה אָמַר, אַרְבָּעִים יוֹם וְאַרְבָּעִים לַיְלָה הַלָּלוּ, מַה מַּעֲשֵׂיהֶם? אֶלָּא אַרְבָּעִים יוֹם לְהַלְקוֹת רִשְׁעֵי הָעוֹלָם, וְכָתוּב (דברים כה) אַרְבָּעִים יַכֶּנּוּ לֹא יֹסִיף, כְּנֶגֶד אַרְבָּעָה רוּחוֹת הָעוֹלָם, לְכָל אֶחָד עֲשָׂרָה. מִשּׁוּם שֶׁבֶּן אָדָם נִבְרָא מֵאַרְבָּעָה רוּחוֹת הָעוֹלָם, וְעַל זֶה וּמָחִיתִי אֶת כָּל הַיְקוּם. וְצָרִיךְ אַרְבָּעִים לְהַלְקוֹת וְלִמְחוֹת אֶת הָעוֹלָם.</p>\n<p>רַבִּי יִצְחָק הָיָה מָצוּי לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ פָּסוּק זֶה (שאמרו) שֶׁכָּתוּב וַתִּשָּׁחֵת הָאָרֶץ לִפְנֵי הָאֱלֹהִים. אִם בְּנֵי אָדָם חָטְאוּ - הָאָרֶץ בַּמָּה חָטְאָה? אָמַר לוֹ, מִשּׁוּם שֶׁכָּתוּב כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ, כְּמוֹ שֶׁנֶּאֱמַר. כְּמוֹ זֶה, (ויקרא יח) וַתִּטְמָא הָאֶרֶץ וָאֶפְקֹד עֲונָהּ עָלֶיהָ. אֶלָּא בְּנֵי אָדָם חָטְאוּ. וְאִם תֹּאמַר, הָאָרֶץ בַּמֶּה? אֶלָּא עִקַּר הָאָרֶץ הֵם בְּנֵי הָאָדָם, וְהֵם מַשְׁחִיתִים אֶת הָאָרֶץ וְהִיא נִשְׁחֶתֶת, וְהַכָּתוּב מוֹכִיחַ, שֶׁכָּתוּב וַיַּרְא אֱלֹהִים אֶת הָאָרֶץ וְהִנֵּה נִשְׁחָתָה כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ עַל הָאָרֶץ.</p>\n<p>בֹּא רְאֵה, כָּל חֲטָאֵי הָאָדָם כֻּלָּם, הַשְׁחָתָתָם תְּלוּיָה בִּתְשׁוּבָה. וְהַחֵטְא שֶׁל שׁוֹפֵךְ זֶרַע עַל הָאָרֶץ וּמַשְׁחִית דַּרְכּוֹ וּמוֹצִיא זֶרַע עַל הָאָרֶץ - מַשְׁחִית אוֹתוֹ וּמַשְׁחִית אֶת הָאָרֶץ, וְעָלָיו כָּתוּב (ירמיה ב) נִכְתַּם עֲונֵךְ לְפָנַי, וְכָתוּב בּוֹ (תהלים ה) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגֻרְךְ רָע. פְּרָט לִתְשׁוּבָה גְדוֹלָה. וְכָתוּב (בראשית לח) וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי ה' וַיְמִיתֵהוּ ה', וַהֲרֵי נִתְבָּאֵר.</p>\n<p>אָמַר לוֹ, לָמָּה דָן הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם בְּמַיִם וְלֹא בְּאֵשׁ וְלֹא בְּדָבָר אַחֵר? אָמַר לוֹ, סוֹד הוּא, שֶׁהֲרֵי הֵם הִשְׁחִיתוּ דַרְכָּם בִּשְׁבִיל שֶׁמַּיִם עֶלְיוֹנִים וּמַיִם תַּחְתּוֹנִים לֹא הִתְחַבְּרוּ זָכָר וּנְקֵבָה כָּרָאוּי. (ומי הם המים העליונים? בינה, ומים תחתונים מלכות, ה\"א עליונה ה\"א תחתונה, וכאשר הם משחיתים, נסתלק י\"ו, שהוא זכר, ונשאר ה\"א בה\"א ומים במים). מַה הֵם הִשְׁחִיתוּ דַרְכָּם, כְּמוֹ זֶה מַיִם זְכָרִיִּים וּנְקֵבִיִּים. וְעַל זֶה נִדּוֹנוּ בְּמַיִם, בְּמַה שֶּׁהֵם חָטְאוּ.</p>\n<p>וְהַמַּיִם הָיוּ רוֹתְחִים וּפוֹשְׁטִים מֵהֶם אֶת הָעוֹר, כְּמוֹ שֶׁהִשְׁחִיתוּ דַרְכָּם בְּמַיִם רוֹתְחִים. דִּין כְּנֶגֶד דִּין. זֶהוּ שֶׁכָּתוּב נִבְקְעוּ כָּל מַעְיְנוֹת תְּהוֹם רַבָּה. הֲרֵי מַיִם תַּחְתּוֹנִים. וַאֲרֻבֹּת הַשָּׁמַיִם נִפְתָּחוּ - זֶה מַיִם עֶלְיוֹנִים. מַיִם עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>רַבִּי חִיָּיא וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים בַּדֶּרֶךְ, וְהִגִּיעוּ לְהָרִים גְּדוֹלִים, וּמָצְאוּ בֵּין הֶהָרִים עַצְמוֹת בְּנֵי אָדָם שֶׁהָיוּ מֵאוֹתָם בְּנֵי הַמַּבּוּל, וּפָסְעוּ שְׁלֹשׁ מֵאוֹת פְּסִיעוֹת בְּעֶצֶם אַחַת. תָּמְהוּ. אָמְרוּ, הַיְנוּ מַה שֶּׁאָמְרוּ חֲבֵרֵינוּ שֶׁהֵם לֹא הָיוּ פּוֹחֲדִים מִדִּין הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁכָּתוּב (איוב כא) וַיֹּאמְרוּ לָאֵל סוּר מִמֶּנּוּ וְדַעַת דְּרָכֶיךְ לֹא חָפָצְנוּ. מֶה עָשׂוּ? הָיוּ סוֹתְמִים בְּרַגְלֵיהֶם אֶת מַעְיְנוֹת הַתְּהוֹם, וּמַיִם רְתוּחִים יוֹצְאִים וְלֹא יָכְלוּ לַעֲמֹד בָּהֶם, עַד שֶׁהָיוּ נִשְׁמָטִים וְנוֹפְלִים בָּאָרֶץ וּמֵתִים.</p>"],[9522011146,"<p>וַיּוֹלֶד נֹחַ שְׁלֹשָׁה בָנִים וְגוֹ'. אָמַר רַבִּי חִיָּיא לְרַבִּי יְהוּדָה, בּא וְאֹמַר לְךְ דְּבָרִים שֶׁשָּׁמַעְתִּי בָּזֶה. מָשָׁל לְאָדָם שֶׁמַּכְנִיס לִנְקֵבָה שֶׁמִּתְעַבֶּרֶת (ד\"א פרי מעיה) בְּפַעַם אַחַת, וְיָצְאוּ שְׁנַיִם אוֹ שְׁלֹשָׁה בָנִים. (כל) אֶחָד נִפְרָד מֵאַחֵר בִּדְרָכָיו בְּמַעֲשָׂיו. זֶה צַדִּיק וְזֶה רָשָׁע וְזֶה בֵּינוֹנִי. אַף גַּם כָּאן שְׁלֹשָׁה קְשָׁרִים שֶׁל רוּחַ הוֹלְכִים וְשָׁטִים וְנִכְלָלִים בִּשְׁלֹשָׁה עוֹלָמוֹת.</p>\n<p>בֹּא רְאֵה, נְשָׁמָה יוֹצֵאת וְנִכְנֶסֶת בֵּין הָרֵי פֵרוּד, וּמִתְחַבֶּרֶת הָרוּחַ בַּנְּשָׁמָה. יוֹרֶדֶת לְמַטָּה, מִתְחַבֶּרֶת הַנֶּפֶשׁ בָּרוּחַ, וְכֻלָּם (הולכים ד\"א יורדים) וּמִתְחַבְּרִים זֶה עִם זֶה. אָמַר רַבִּי יְהוּדָה, נֶפֶשׁ וְרוּחַ כְּלוּלִים זֶה עִם זֶה. הַנְּשָׁמָה שׁוֹרָה בִּדְרָכָיו שֶׁל בֶּן אָדָם, (וזה) וְהוּא מָדוֹר נִסְתָּר שֶׁלֹּא נוֹדָע מְקוֹמוֹ.</p>\n<p>בָּא בֶּן אָדָם לְהִטָּהֵר - מְסַיְּעִים לוֹ בִּנְשָׁמָה קְדוֹשָׁה וּמְטַהֲרִים אוֹתוֹ וּמְקַדְּשִׁים אוֹתוֹ וְנִקְרָא קָדוֹשׁ. לֹא זָכָה וְלֹא בָא לְהִטָּהֵר - שְׁתֵּי דְרָגוֹת פּוֹתְחִים, שֶׁהֵם נֶפֶשׁ וְרוּחַ בּוֹ. אֵין בּוֹ נְשָׁמָה קְדוֹשָׁה (סיוע שלמעלה, וזה כפי דרכו). וְלֹא עוֹד, אֶלָּא שֶׁאִם יִטְמָא - מְטַמְּאִים אוֹתוֹ. וְהַסִּיּוּעַ שֶׁלְּמַעְלָה מְסִירִים מִמֶּנּוּ. מִכָּאן וָהָלְאָה כָּל אֶחָד לְפִי דַרְכּוֹ.</p>\n<p>קִשּׁוּרִים רָמִים שֶׁל הֵיכְלֵי הַהֵיכָלוֹת (של אותו צד) אָנוּ פְּתוּחֵי עֵינַיִם, פְּתוּחֵי אָזְנַיִם. קוֹל מֵהַקּוֹלוֹת יוֹרֵד מִלְמַעְלָה לְמַטָּה, מְשַׁבֵּר הָרִים וּסְלָעִים. מִי הֵם שֶׁרוֹאִים וְלֹא רוֹאִים? אֲטוּמֵי אָזְנַיִם, סְתוּמֵי עֵינַיִם, לֹא רוֹאִים וְלֹא שׁוֹמְעִים, לֹא יוֹדְעִים בַּשֵּׂכֶל, אֶחָד שֶׁכָּלוּל בִּשְׁנַיִם בְּתוֹכָם. דּוֹחִים אוֹתָם הַחוּצָה.</p>\n<p>הֵם נִדְבָּקִים בֵּין (ס\"א בו) בְּאוֹתָם שְׁנַיִם, הָאֶחָד אֻמַּן הָאָמָּנִים לֹא שׁוֹרֶה (ס\"א שמים) בְתוֹכָם. לֹא נִכְנָסִים בֵּין סְפָרִים קְדוֹשִׁים. כָּל אֵלּוּ שֶׁל אֻמָּן זֶה לֹא שׁוֹרֶה בְתוֹכָם, לֹא נִכְתְּבוּ בְּסֵפֶר הַזִּכְרוֹנוֹת וְנִמְחִים מִסֵּפֶר הַחַיִּים, כְּמוֹ שֶׁנֶּאֱמַר (תהלים סט) יִמָּחוּ מִסֵּפֶר חַיִּים וְעִם צַדִּיקִים אַל יִכָּתֵבוּ.</p>\n<p>אוֹי לָהֶם כְּשֶׁיֵּצְאוּ מֵהָעוֹלָם הַזֶּה. אוֹי לָהֶם (לחייהם). מִי יִתְבַּע אוֹתָם כַּאֲשֶׁר יִמָּסְרוּ בִּידֵי דוּמָה וְיִשָּׂרְפוּ בְּאֵשׁ שֶׁדּוֹלֶקֶת וְלֹא יֵצְאוּ מִמֶּנָּה רַק בְּרָאשֵׁי חֳדָשִׁים וְשַׁבָּתוֹת, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ יָבֹא כָל בָּשָׂר לְהִשְׁתַּחֲווֹת לְפָנַי אָמַר ה'. אַחַר כָּךְ כָּרוֹז שֶׁבְּצַד צָפוֹן מַכְרִיז עֲלֵיהֶם וְאוֹמֵר, (תהלים ט) יָשׁוּבוּ רְשָׁעִים לִשְׁאוֹלָה וְגוֹ'. כַּמָּה אֲגֻדּוֹת שֶׁל יִסּוּרִים יִתְכַּנְּסוּ עֲלֵיהֶם בְּאַרְבָּעָה צְדָדִים. אֵשׁ לוֹהֶטֶת בְּגֵיא בֶן הִנּוֹם.</p>\n<p>שָׁלש פְּעָמִים בְּיוֹם מִתְפַּקְּדִים (נשרפים). וְלֹא עוֹד, אֶלָּא בִּזְמַן שֶׁיִּשְׂרָאֵל עוֹנִים בְּקוֹל רָם אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ, הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְמַלֵּא רַחֲמִים וְחָס עַל הַכֹּל, וְרוֹמֵז לַמַּלְאָךְ הַמְמֻנֶּה עַל שַׁעֲרֵי הַגֵּיהִנֹּם, שֶׁשְּׁמוֹ סמריא\"ל, וּשְׁלֹשָׁה מַפְתְּחוֹת בְּיָדוֹ, וּפוֹתֵחַ שְׁלֹשָׁה שְׁעָרִים שֶׁבְּצַד הַמִּדְבָּר, וְרוֹאִים אֶת אוֹר הָעוֹלָם הַזֶּה. בָּא עָשָׁן שֶׁל אֵשׁ וְסוֹתֵם הַדְּרָכִים.</p>\n<p>וְאָז שְׁלֹשָׁה מְמֻנִּים שֶׁתַּחַת יְדֵיהֶם שָׁלֹשׁ מַגְרֵפוֹת, מְנַשְּׁבִים בִּידֵיהֶם וּמַחֲזִירִים עָשָׁן לִמְקוֹמָם, וְנוֹתְנִים לָהֶם רְוָחָה שָׁעָה וָחֵצִי. וְאַחַר כָּךְ שָׁבִים לָאֵשׁ שֶׁלָּהֶם. וְכָךְ שָׁלֹשׁ פְּעָמִים בְּיוֹם. וּבְכָל זְמַן שֶׁאוֹמְרִים יִשְׂרָאֵל אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ וְכוּ', מְרַוְּחִים לָהֶם. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁדַּרְכָּם מְאִירָה בְּאוֹתוֹ עוֹלָם לְכָל הַצְּדָדִים, כְּמוֹ שֶׁנֶּאֱמַר (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם. (עד כאן התוספתא).</p>"],[9522011147,"<p>רַבִּי אַבָּא אָמַר, בַּגֵּיהִנֹּם יֵשׁ מְדוֹרִים עַל מְדוֹרִים, שְׁנִיִּים שְׁלִישִׁיִּים, עַד שֶׁבַע. וַהֲרֵי בֵּאֲרוּהָ הַחֲבֵרִים. וְאַשְׁרֵי הַצַּדִּיקִים שֶׁהֵם נִשְׁמָרִים מֵחֲטָאֵי הָרְשָׁעִים וְלֹא הוֹלְכִים בְּדַרְכֵיהֶם וְלֹא נִטְמָאִים בָּהֶם. וְכָל מִי שֶׁנִּטְמָא, כְּשֶׁהוֹלֵךְ לְאוֹתוֹ עוֹלָם יוֹרֵד לַגֵּיהִנֹּם, וְיוֹרֵד עַד הַמָּדוֹר הַתַּחְתּוֹן.</p>\n<p>וּשְׁנֵי מְדוֹרִים הֵם שֶׁסְּמוּכִים זֶה עִם זֶה - שְׁאוֹל וַאֲבַדּוֹן. מִי שֶׁיּוֹרֵד לַשְּׁאוֹל, דָּנִים אוֹתוֹ שָׁם וּמְקַבֵּל עָנְשׁוֹ, וּמַעֲלִים אוֹתוֹ לְמָדוֹר עֶלְיוֹן אַחֵר. וְכֵן דַּרְגָּה אַחַר דַּרְגָּה, עַד שֶׁהֵם מַעֲלִים אוֹתוֹ. אֲבָל מִי שֶׁיּוֹרֵד לָאֲבַדּוֹן, לֹא מַעֲלִים אוֹתוֹ לְעוֹלָמִים, וְלָכֵן נִקְרָא אֲבַדּוֹן, שֶׁהֲרֵי אָבוּד הוּא מֵהַכֹּל.</p>\n<p>בֹּא רְאֵה, נֹחַ הַצַּדִּיק הָיָה מַתְרֶה בִּבְנֵי דוֹרוֹ, וְלֹא הָיוּ שׁוֹמְעִים לוֹ, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֵבִיא עֲלֵיהֶם דִּין הַגֵּיהִנֹּם. מַהוּ דִּין גֵּיהִנֹּם? אֵשׁ וְשֶׁלֶג, מַיִם וְאֵשׁ. זֶה צוֹנֵן וְזֶה רוֹתֵחַ. וְכֻלָּם נִדּוֹנוּ בְּדִין הַגֵּיהִנֹּם וְאָבְדוּ מֵהָעוֹלָם,</p>\n<p>וְאַחַר כָּךְ הִתְקַיֵּם הָעוֹלָם כָּרָאוּי לוֹ. וְנִכְנַס נֹחַ בַּתֵּבָה וְהִכְנִיס בָּהּ כָּל מִין וּמִין (מבריות) הָעוֹלָם. וַדַּאי נֹחַ עֵץ עֹשֶׂה פְּרִי הָיָה. וְיָצְאוּ מֵהַתֵּבָה כָּל מִינֵי הָעוֹלָם כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>בֹּא רְאֵה, כְּשֶׁעֵץ זֶה עוֹשֶׂה הַפְּרִי, מִתְחַבֵּר בְּעֵץ פְּרִי כָּל אוֹתָם מִינִים שֶׁלְּמַעְלָה חַיּוֹת גְּדוֹלוֹת וּקְטַנּוֹת, וְכַמָּה מִינִים כָּל מִין לְמִינוֹ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת. כְּמוֹ זֶה נֹחַ בַּתֵּבָה. וְכֻלָּם יָצְאוּ מֵהַתֵּבָה, וְהִתְקַיֵּם הָעוֹלָם כְּמוֹ שֶׁלְּמַעְלָה. וְלָכֵן נֹחַ נִקְרָא אִישׁ הָאֲדָמָה. נֹחַ נִקְרָא אִישׁ צַדִּיק. וַהֲרֵי בֵּאֲרוּהָ.</p>\n<p>רַבִּי חִיָּיא אָמַר, שְׁלֹשׁ מֵאוֹת שָׁנָה עַד שֶׁלֹּא בָא הַמַּבּוּל הָיָה נֹחַ מַתְרֶה בָהֶם עַל מַעֲשֵׂיהֶם וְלֹא הָיוּ שׁוֹמְעִים לוֹ, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁלִים הַזְּמַן שֶׁחִכָּה לָהֶם וְאָבְדוּ מֵהָעוֹלָם בֹּא רְאֵה מַה כָּתוּב לְמַעְלָה, וַיְהִי כִּי הֵחֵל הָאָדָם לָרֹב עַל פְּנֵי הָאֲדָמָה וּבָנוֹת יֻלְּדוּ לָהֶם. וְהָיוּ הוֹלְכִים עֲרֻמִּים לְעֵין כֹּל. מַה כָּתוּב? (בראשית ו) וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם וְגוֹ'. וְזֶה הָיָה יְסוֹד וְעִקָּר לְהִמָּשֵׁךְ בְּחֶטְאָם עַד שֶׁגָּרַם לָהֶם לְהִשָּׁמֵד מֵהָעוֹלָם, וְלָכֵן נִמְשְׁכוּ אַחַר יֵצֶר הָרָע וּבְגִזְעוֹ וּבְשָׁרְשׁוֹ וְדָחוּ אֶת הָאֱמוּנָה הַקְּדוֹשָׁה מִבֵּינֵיהֶם, וְנִטְמְאוּ (נ\"א: ונאבדו) כְּמוֹ שֶׁנֶּאֱמַר. לָכֵן קֵץ כָּל בָּשָׂר בָּא לְפָנַי - לְלַמֵּד קָטֵגוֹרְיָה עֲלֵיהֶם.</p>"],[9522011148,"<p>וַיֹּאמֶר אֱלֹהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי. (חזרנו לדבר הראשון, קץ כל בשר בא לפני, בא לפני ודאי, משום שהם גרמו). רַבִּי יְהוּדָה פָּתַח, (תהלים לט) הוֹדִיעֵנִי ה' קִצִּי וּמִדַּת יָמַי מַה הִיא אֵדְעָה מֶה חָדֵל אָנִי. אָמַר דָּוִד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: שְׁנֵי קִצִּים הֵם, אֶחָד לְיָמִין וְאֶחָד לִשְׂמֹאל, וְהֵם שְׁתֵּי דְרָכִים לָלֶכֶת בָּהֶם בְּנֵי אָדָם לְאוֹתוֹ הָעוֹלָם. קֵץ לְיָמִין - שֶׁכָּתוּב (דניאל יב) לְקֵץ הַיָּמִין. וְקֵץ לִשְׂמֹאל - שֶׁכָּתוּב (איוב כח) קֵץ שָׂם לַחֹשֶׁךְ וּלְכָל תַּכְלִית הוּא חוֹקֵר (אבן אפל וצלמות, מה זה ולכל תכלית הוא חוקר? מי הוא החוקר? אלא אותו קץ לשמאל שמחשיך פני הבריות). מַהוּ וּלְכָל תַּכְלִית? בִּזְמַן שֶׁשָּׁרוּי הַדִּין עַל הָעוֹלָם לְהַשְׁמִיד - אֶבֶן אֹפֶל וְצַלְמָוֶת. קֵץ שָׂם לַחֹשֶׁךְ - זֶה מַלְאַךְ הַמָּוֶת, זֶה נָחָשׁ. קֵץ כָּל בָּשָׂר, קֵץ שָׂם לַחֹשֶׁךְ, שֶׁהֲרֵי מִצַּד שֶׁל הִתּוּךְ הַזָּהָב הוּא בָא. וּלְכָל תַּכְלִית - בִּזְמַן שֶׁדִּין שָׁרוּי עַל הָעוֹלָם, הוּא חוֹקֵר לִהְיוֹת קָטֵגוֹר לָעוֹלָם לְהַחְשִׁיךְ פְּנֵי הַבְּרִיּוֹת. קֵץ לְיָמִין, כְּמוֹ שֶׁאָמַרְנוּ שֶׁכָּתוּב לְקֵץ הַיָּמִין.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְדָנִיֵּאל: וְאַתָּה לֵךְ לַקֵּץ וְתָנוּחַ. אָמַר לוֹ: מְנוּחָה בָּעוֹלָם הַזֶּה אוֹ בָּעוֹלָם הַהוּא? אָמַר לוֹ: בָּעוֹלָם הַהוּא, כְּמוֹ שֶׁנֶּאֱמַר יָנוּחוּ עַל מִשְׁכְּבוֹתָם. (דניאל יב) (ותעמד לגורלך לקץ הימין, אמר לו, ' לאיזה מקום, שהרי לא ידעתי מה יהיה עלי באותו עולם? אמר לו', ותנוח). אָמַר לוֹ: בִּזְמַן שֶׁיָּקוּמוּ מֵהֶעָפָר, אָקוּם בֵּינֵיהֶם אוֹ לֹא? אָמַר לוֹ: וְתַעֲמֹד. אָמַר לוֹ: הֲרֵי יָדַעְתִּי שֶׁיָּקוּמוּ כִּתּוֹת כִּתּוֹת, מֵהֶם שֶׁל צַדִּיקֵי אֱמֶת וּמֵהֶם שֶׁל רִשְׁעֵי הָעוֹלָם, וְלֹא יָדַעְתִּי עִם מִי מֵהֶם אָקוּם. אָמַר לוֹ: לְגוֹרָלְךְ. אָמַר לוֹ: הֲרֵי אָמַרְתָּ וְאַתָּה לֵךְ לַקֵּץ. יֵשׁ קֵץ לְיָמִין וְיֵשׁ קֵץ לִשְׂמֹאל, וְלֹא יָדַעְתִּי לְאֵיזֶה קֵץ, לְקֵץ הַיָּמִין אוֹ לְקֵץ הַיָּמִים? אָמַר לוֹ: לְקֵץ הַיָּמִין.</p>\n<p>גַּם כָּאן דָּוִד אָמַר לַקָּדוֹשׁ-בָּרוּךְ- הוּא, (תהלים לט), הוֹדִיעֵנִי ה' קִצִּי, מַהוּ חֵלֶק גּוֹרָלִי. וְלֹא נָחָה דַעְתּוֹ עַד שֶׁהִתְבַּשֵּׂר שֶׁיִּהְיֶה לְיָמִין, שֶׁכָּתוּב (שם קי) שֵׁב לִימִינִי. בֹּא רְאֵה, גַּם הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לוֹ לְנֹחַ, קֵץ כָּל בָּשָׂר בָּא לְפָנַי. מִיהוּ? זֶה הַקֵּץ שֶׁמַּחְשִׁיךְ פְּנֵי הַבְּרִיּוֹת, שֶׁהוּא קֵץ כָּל בָּשָׂר,</p>\n<p>בָּא לְפָנַי. מִכָּאן לָמַדְנוּ שֶׁרִשְׁעֵי הָעוֹלָם מַקְדִּימִים וּמוֹשְׁכִים אוֹתוֹ עֲלֵיהֶם לְהַחְשִׁיךְ לָהֶם. שֶׁכֵּיוָן שֶׁנּוֹתְנִים לוֹ רְשׁוּת, הוּא נוֹטֵל אֶת הַנְּשָׁמָה, וְלֹא נוֹטֵל עַד שֶׁנּוֹתְנִים לוֹ רְשׁוּת, וְעַל זֶה בָּא לְפָנַי לִטֹּל רְשׁוּת לְהַחְשִׁיךְ פְּנֵי בְּנֵי הָעוֹלָם. וְלָכֵן וְהִנְנִי מַשְׁחִיתָם אֶת הָאָרֶץ. וְעַל זֶה עֲשֵׂה לְךְ תֵּבַת עֲצֵי גֹפֶר, כְּדֵי לְהִנָּצֵל, וְלֹא יוּכַל לִשְׁלֹט עָלֶיךְ.</p>\n<p>בֹּא רְאֵה, שָׁנִינוּ, בִּזְמַן שֶׁיֵּשׁ מָוֶת בָּעִיר אוֹ בָּעוֹלָם (נ\"א: שנתנה רשות למלאך המות להשחית) לֹא יֵרָאֶה אָדָם בַּשּׁוּק, מִשּׁוּם שֶׁיֵּשׁ לוֹ רְשׁוּת לַמַּשְׁחִית לְהַשְׁחִית הַכֹּל. מִשּׁוּם כָּךְ אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: אַתָּה צָרִיךְ לְהִשָּׁמֵר, וְלֹא תַרְאֶה אֶת עַצְמְךְ לִפְנֵי הַמַּשְׁחִית שֶׁלֹּא יִשְׁלֹט עָלֶיךְ.</p>\n<p>וְאִם תֹּאמַר, מִי נָתַן כָּאן מַשְׁחִית, שֶׁהֲרֵי מַיִם הָיוּ וְהִתְגַּבְּרוּ.? בֹּא רְאֵה, אֵין לְךְ דִּין בָּעוֹלָם אוֹ כְּשֶׁמֻּכֶּה אוֹ כְּשֶׁנִּמְסָר הָעוֹלָם בְּדִין, שֶׁלֹּא נִמְצָא אוֹתוֹ הַמַּשְׁחִית שֶׁהוֹלֵךְ בְּתוֹךְ אוֹתָם הַדִּינִים שֶׁנַּעֲשִׂים בָּעוֹלָם. גַּם כָּאן בַּמַּבּוּל כָּךְ הָיָה, וְהַמַּשְׁחִית הוֹלֵךְ בְּתוֹךְ הַמַּבּוּל. וְהוּא נִקְרָא כָּךְ, שֶׁנִּכְלָל בַּשֵּׁם הַזֶּה. וְעַל זֶה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְנֹחַ לִשְׁמֹר עַצְמוֹ וְלֹא יִתְרָאֶה בָּעוֹלָם.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי הַתֵּבָה הַזּוֹ נִרְאֵית בְּתוֹךְ הָעוֹלָם הַזֶּה וְהַמַּשְׁחִית הוֹלֵךְ בְּתוֹכוֹ? כָּל זְמַן שֶׁלֹּא נִרְאִים פְּנֵי אָדָם לִפְנֵי הַמַּשְׁחִית, לֹא יָכוֹל לִשְׁלֹט עָלָיו. מִנַּיִן לָנוּ? מִמִּצְרַיִם, שֶׁכָּתוּב (שמות יב) וְאַתֶּם לֹא תֵצְאוּ אִישׁ מִפֶּתַח בֵּיתוֹ עַד בֹּקֶר. מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא נִמְצָא וְהוּא יָכוֹל לְהַשְׁחִית, וְלֹא צָרִיךְ לְהִתְרָאוֹת לְפָנָיו. לָכֵן הָיָה גָנוּז נֹחַ וְכָל אֵלּוּ שֶׁעִמּוֹ בְּתוֹךְ הַתֵּבָה, וְהַמַּשְׁחִית לֹא יָכֹל לִשְׁלֹט עֲלֵיהֶם.</p>\n<p>רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. פָּגְשׁוּ בְּאוֹתָם הָרֵי אֲרָרָט. רָאוּ רִשּׁוּמִים בְּקִיעִים בַּדֶּרֶךְ שֶׁהָיוּ מִימֵי הַמַּבּוּל. אָמַר רַבִּי חִיָּיא לְרַבִּי יוֹסֵי, הַבְּקִיעִים הַלָּלוּ שֶׁהָיוּ מִימֵי הַמַּבּוּל וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁאִירָם לְדוֹרֵי דוֹרוֹת, כְּדֵי שֶׁלֹּא יִמָּחֶה חֶטְאָם שֶׁל הָרְשָׁעִים לְפָנָיו.</p>\n<p>שֶׁכָּךָ דֶּרֶךְ הַקָּדוֹשׁ בָּרוּךְ הוּא: לַצַּדִּיקִים שֶׁעוֹשִׂים רְצוֹנוֹ - רוֹצֶה שֶׁיִּזְכְּרוּ אוֹתָם לְמַעְלָה וּלְמַטָּה וְלֹא יִשָּׁכַח זִכְרָם לְדוֹרֵי דוֹרוֹת לְטוֹב. כְּמוֹ זֶה לָרְשָׁעִים שֶׁלֹּא עוֹשִׂים רְצוֹנוֹ - כְּדֵי שֶׁלֹּא יִשָּׁכַח חֶטְאָם, וּלְהַזְכִּיר עָנְשֵׁיהֶם וְזִכְרוֹנָם לְרַע לְדוֹרֵי דוֹרוֹת, הַיְינוּ שֶׁכָּתוּב (ירמיה ב) נִכְתָּם עֲוֹנֵךְ לְפָנַי וְגוֹ'.</p>"],[9522011149,"<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (ישעיה י) צַהֲלִי קוֹלֵךְ בַּת גַּלִּים הַקְשִׁיבִי לַיְשָׁה עֲנִיָּה עֲנָתוֹת. פָּסוּק זֶה פֵּרְשׁוּהוּ הַחֲבֵרִים. אֲבָל פָּסוּק זֶה נֶאֱמַר עַל כְּנֶסֶת יִשְׂרָאֵל. צַהֲלִי קוֹלֵךְ בַּת גַּלִּים - בִּתּוֹ שֶׁל אַבְרָהָם אָבִינוּ, כָּךְ פֵּרְשׁוּהָ בַּת גַּלִּים, כַּכָּתוּב (שיר ד) גַּל נָעוּל. גַּלִּים הֵם מְאוֹרוֹת שֶׁמִּתְכַּנְּסִים וְהוֹלְכִים וְנִכְנָסִים לְתוֹכָהּ וּמְמַלְּאִים אוֹתָהּ, כַּכָּתוּב (שם) שְׁלָחַיִךְ פַּרְדֵּס רִמּוֹנִים.</p>\n<p>הַקְשִׁיבִי לַיְשָׁה, כְּמוֹ שֶׁנֶּאֱמַר (איוב ד) לַיִשׁ אֹבֵד מִבְּלִי טָרֶף. לַיִשׁ - זָכָר. לַיְשָׁה - נְקֵבָה. לָמָּה נִקְרָא לַיִשׁ? אִם מִשּׁוּם שֶׁכָּתוּב (משלי ל) לַיִשׁ גִּבּוֹר בַּבְּהֵמָה, אוֹ מִשּׁוּם שֶׁכָּתוּב לַיִשׁ אֹבֵד מִבְּלִי טָרֶף. אֶלָּא הַכֹּל הוּא לַיִשׁ, גְּבוּרָה תַחְתּוֹנָה שֶׁבָּאָה מִגְּבוּרָה עֶלְיוֹנָה. לַיִשׁ אֹבֵד מִבְּלִי טָרֶף - בְּשָׁעָה שֶׁאוֹתָם נְחָלִים מִסְתַּלְּקִים וְלֹא נִכְנָסִים לְתוֹכָהּ, אָז נִקְרֵאת לַיְשָׁה שֶׁאוֹבֶדֶת מִבְּלִי טֶרֶף, שֶׁכָּתוּב לַיִשׁ אֹבֵד מִבְּלִי טָרֶף וּבְנֵי לָבִיא יִתְפָּרָדוּ.</p>\n<p>וּמַה שֶּׁאָמַר לַיְשָׁה, הַיְנוּ עֲנִיָּה עֲנָתוֹת, עֹנִי שֶׁל עֲנִיּוּת, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה א) מִן הַכֹּהֲנִים אֲשֶׁר בַּעֲנָתוֹת, וְכָתוּב (מלכים א ב) עֲנָתֹת לֵךְ עַל שָׂדֶיךְ. מַה מַּשְׁמִיעֵנוּ? אֶלָּא כָּל זְמַן שֶׁהַמֶּלֶךְ דָּוִד הָיָה קַיָּם, עָלָה אֶבְיָתָר בְּעֹשֶׁר וּבַכֹּל. אַחַר כָּךְ אָמַר לוֹ שְׁלֹמֹה, עֲנָתֹת לֵךְ עַל שָׂדֶיךְ.</p>\n<p>לָמָּה קָרָא לוֹ שְׁלֹמֹה כָּךְ? אֶלָּא אָמַר לוֹ, בְּיָמֶיךְ הָיָה אַבָּא בְּעֹנִי, וְעַכְשָׁו לֵךְ עַל שָׂדֶיךְ. כָּעֵת יֵשׁ לוֹמַר, לָמָּה נִקְרָא אֶבְיָתָר עֲנָתוֹת? אִם תֹּאמַר שֶׁהָיָה מֵעֲנָתוֹת, הֲרֵי שָׁנִינוּ שֶׁכָּתוּב (שמואל א כב) וַיִּמָּלֵט בֵּן אֶחָד לַאֲחִימֶלֶךְ בֶּן אֲחִטוּב וּשְׁמוֹ אֶבְיָתָר. וְהוּא מִנּוֹב הָיָה, שֶׁהֲרֵי נוֹב הָיְתָה עִיר הַכֹּהֲנִים. וְאַף עַל פִּי שֶׁאָמְרוּ, הִיא נוֹב הִיא עֲנָתוֹת, וְלָמָּה נִקְרֵאת עֲנָתוֹת? מִשּׁוּם שֶׁיָּרְדָה לְעֹנִי וְאָבְדָה הָעִיר עַל יְדֵי שָׁאוּל וְאָבְדוּ הַכֹּהֲנִים. אֶלָּא עֲנָתוֹת כְּפָר הָיָה, וְאֵינָהּ נוֹב, וְלָכֵן קָרָא לָהּ אֶבְיָתָר עֲנָתוֹת, מִשּׁוּם שֶׁאָמַר (מלכים א ב) וְכִי הִתְעַנִּיתָ בְּכֹל אֲשֶׁר הִתְעַנָּה אָבִי. וְהוּא הָיָה מֵהָעִיר נוֹב, וְעַל הָעֹנִי שֶׁל דָּוִד שֶׁהָיָה לוֹ בְּיָמָיו קָרָא לוֹ כָּךְ.</p>\n<p>אָמַר רַבִּי חִיָּיא, הָעוֹלָם הָיָה בְּעֹנִי מִיּוֹם שֶׁעָבַר אָדָם עַל מִצְווֹת הַקָּדוֹשׁ בָּרוּךְ הוּא, עַד שֶׁבָּא נֹחַ וְהִקְרִיב קָרְבָּן וְהִתְיַשֵּׁב הָעוֹלָם. אָמַר רַבִּי יוֹסֵי, לֹא הִתְיַשֵּׁב הָעוֹלָם וְלֹא יָצְאָה הָאָרֶץ מִזֻּהֲמַת הַנָּחָשׁ, עַד שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי וְנֶאֶחְזוּ בְּעֵץ הַחַיִּים, וְאָז הִתְיַשֵּׁב הָעוֹלָם.</p>\n<p>וְאִלְמָלֵא שֶׁחָזְרוּ יִשְׂרָאֵל וְחָטְאוּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא הָיוּ מֵתִים לְעוֹלָמִים, שֶׁהֲרֵי נִפְסְקָה מֵהֶם זֻהֲמַת הַנָּחָשׁ. כֵּיוָן שֶׁחָטְאוּ, אָז נִשְׁבְּרוּ אוֹתָם הַלּוּחוֹת הָרִאשׁוֹנִים שֶׁהָיְתָה בָּהֶם חֵרוּת שֶׁל הַכֹּל, הַחֵרוּת מֵאוֹתוֹ הַנָּחָשׁ שֶׁהוּא קֵץ כָּל בָּשָׂר.</p>\n<p>וּכְשֶׁקָּמוּ הַלְוִיִּם לַהֲרֹג הֶרֶג, אָז הִתְעוֹרֵר הַנָּחָשׁ הָרָע וְהָיָה הוֹלֵךְ לִפְנֵיהֶם, וְלֹא יָכֹל לִשְׁלֹט בָּהֶם, מִשּׁוּם שֶׁיִּשְׂרָאֵל הָיוּ מִזְדָּרְזִים כֻּלָּם בַּחֲגוֹרוֹת מְזֻיָּנוֹת, וְלֹא יָכֹל הַנָּחָשׁ לִשְׁלֹט בָּהֶם. וְכֵיוָן שֶׁאָמַר לְמֹשֶׁה (שמות לג) וְעַתָּה הוֹרֵד עֶדְיְךְ מֵעָלֶיךְ, נִתְּנָה רְשׁוּת לַנָּחָשׁ הַזֶּה לִשְׁלֹט עֲלֵיהֶם</p>\n<p>בֹּא רְאֵה מַה כָּתוּב (שם), וַיִּתְנַצְּלוּ בְּנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חֹרֵב. וַיִּתְנַצְּלוּ? וַיְנַצְּלוּ צָרִיךְ לִהְיוֹת! אֶלָּא וַיִּתְנַצְּלוּ עַל יְדֵי הָאַחֵר, מִשּׁוּם שֶׁנִּתְּנָה רְשׁוּת לַנָּחָשׁ לִשְׁלֹט. אֶת עֶדְיָם מֵהַר חֹרֵב, שֶׁקִּבְּלוּ מֵהַר חוֹרֵב כְּשֶׁנִּתְּנָה תוֹרָה לְיִשְׂרָאֵל.</p>\n<p>אָמַר רַבִּי חִיָּיא, נֹחַ שֶׁהָיָה צַדִּיק, לָמָּה לֹא הָיָה מְבַטֵּל מָוֶת מֵהָעוֹלָם? אֶלָּא מִשּׁוּם שֶׁעֲדַיִן לֹא הִסְתַּלְּקָה הַזֻּהֲמָה מִן הָעוֹלָם. וְעוֹד, שֶׁהֵם לֹא הֶאֱמִינוּ בַּקָּדוֹשׁ- בָּרוּךְ-הוּא, וְכֻלָּם אֲחוּזִים בֶּעָלִים שֶׁל הָאִילָן לְמַטָּה וּמִתְלַבְּשִׁים בְּרוּחַ טֻמְאָה.</p>\n<p>וְעוֹד הוֹסִיפוּ אַחַר כָּךְ לַחֲטֹא וְלָלֶכֶת אַחַר יֵצֶר הָרָע כְּבָרִאשׁוֹנָה. וְהַתּוֹרָה הַקְּדוֹשָׁה, שֶׁהִיא עֵץ הַחַיִּים, עֲדַיִן לֹא הוֹרִיד אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָרֶץ, וְעוֹד שֶׁהוּא מָשַׁךְ אוֹתוֹ בָּעוֹלָם אַחַר כָּךְ, שֶׁכָּתוּב וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל בְּתוֹךְ אָהֳלֹה, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522011150,"<p>עַד שֶׁהָיוּ הוֹלְכִים, רָאוּ יְהוּדִי אֶחָד שֶׁהָיָה בָּא. אָמַר רַבִּי יוֹסֵי, הָאִישׁ הַזֶּה הוּא יְהוּדִי וְנִרְאֶה. כְּשֶׁהִגִּיעַ אֲלֵיהֶם, שָׁאֲלוּ אוֹתוֹ. אָמַר לָהֶם, אֲנִי שְׁלִיחַ מִצְוָה, שֶׁהֲרֵי אָנוּ גָרִים בִּכְפָר רָאמִין, וְהִגִּיעַ זְמַן הֶחָג, וְאָנוּ צְרִיכִים לוּלָב עִם הַמִּינִים שֶׁלּוֹ עִמּוֹ, וַאֲנִי הוֹלֵךְ לִקְטֹף אוֹתָם לְמִצְוָה. הָלְכוּ כְּאֶחָד.</p>\n<p>אָמַר לָהֶם אוֹתוֹ יְהוּדִי, אַרְבַּעַת מִינֵי הַלּוּלָב הַלָּלוּ שֶׁבְּכֻלָּם בָּאִים לְרַצּוֹת בְּעַד הָעוֹלָם (נ\"א: על המים), שְׁמַעְתֶּם לָמָּה אָנוּ צְרִיכִים אוֹתָם בֶּחָג? אָמַר לוֹ, כְּבָר הֵעִירוּ בָזֶה הַחֲבֵרִים, אֲבָל אִם דָּבָר חָדָשׁ הוּא תַּחַת יָדְךְ - אֱמֹר אוֹתָהּ.</p>\n<p>אָמַר לָהֶם, וַדַּאי אוֹתוֹ מָקוֹם שֶׁאָנוּ גָרִים בּוֹ הוּא קָטָן, וְכֻלָּם עוֹסְקִים בַּתּוֹרָה, וְיֵשׁ עָלֵינוּ תַּלְמִיד חָכָם וּשְׁמוֹ רַבִּי יִצְחָק בַּר יוֹסֵי מָחוֹזָאָה, וּבְכָל יוֹם וָיוֹם אוֹמֵר לָנוּ דִּבְרֵי תוֹרָה חֲדָשִׁים, וְאָמַר שֶׁהֲרֵי בֶּחָג זְמַן הוּא לִשְׁלֹט. (ישראל שולטים באותו זמן ולוקחים לולב שמראה שאנו נצחנו על כל אותם שנקראים המון העם ולשלט עליהם) (אזי עבר על נפשנו המים הזידונים ברוך ה' שלא נתננו טרף לשניהם, וכי יש שנים למים? אלא) (שכל אותם גדולים) אוֹתָם שְׁאָר הָעַמִּים. אוֹתָם מְמֻנִּים גְּדוֹלִים עַל שְׁאָר הָעַמִּים עַכּוּ\"ם, וּמִתְבָּרְכִים מִצִּדָּם שֶׁל יִשְׂרָאֵל, וְקוֹרְאִים לָהֶם מַיִם הַזֵּידוֹנִים, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קכד) הַמַּיִם הַזֵּידוֹנִים.</p>\n<p>וּבִשְׁבִיל לִשְׁלֹט עֲלֵיהֶם בָּאנוּ בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ בְּאוֹתָם אַרְבָּעָה מִינֵי הַלּוּלָב לְרַצּוֹת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא (עליהם) וְלִשְׁלֹט עֲלֵיהֶם בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ, וּלְהָעִיר עָלֵינוּ מַיִם קְדוֹשִׁים לְנַסֵּךְ עַל גַּבֵּי הַמִּזְבֵּחַ.</p>\n<p>עוֹד אָמַר לָהֶם, בְּרֹאשׁ הַשָּׁנָה הִתְעוֹרְרוּת רִאשׁוֹנָה הִיא בָּעוֹלָם. מַה זֶּה הִתְעוֹרְרוּת רִאשׁוֹנָה? זֶה בֵּית דִּין הַתַּחְתּוֹן (נ\"א: זה ראש השנה ממש) שֶׁמִּתְעוֹרֵר לָדוּן אֶת הָעוֹלָם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב עַל הָעוֹלָם בְּדִין וְדָן אֶת הָעוֹלָם.</p>\n<p>וְשׁוֹלֵט בֵּית הַדִּין (שלמטה) הַזֶּה לָדוּן אֶת הָעוֹלָם, עַד יוֹם הַכִּפּוּרִים שֶׁמְּאִירִים פָּנֶיהָ, וְלֹא נִמְצָא נָחָשׁ מַלְשִׁין בָּעוֹלָם, שֶׁהוּא מִתְעַסֵּק בְּמַה שֶּׁמְּבִיאִים לוֹ אוֹתוֹ הַשָּׂעִיר, שֶׁהוּא מִצַּד רוּחַ הַטֻּמְאָה כָּרָאוּי לוֹ. וּמִשּׁוּם שֶׁמִּתְעַסֵּק בְּאוֹתוֹ שָׂעִיר, לֹא קָרֵב לַמִּקְדָּשׁ.</p>\n<p>וְשָׂעִיר זֶה כְּמוֹ אוֹתוֹ שָׂעִיר שֶׁל רֹאשׁ חֹדֶשׁ שֶׁמִּתְעַסֵּק בּוֹ וּמְאִירוֹת פָּנֶיהָ שֶׁל רֹאשׁ הַשָּׁנָה (כך בראש השנה) (מאירים) (פני המקדש). וְעַל זֶה כָּל יִשְׂרָאֵל מוֹצְאִים רַחֲמִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וַחֲטָאֵיהֶם מִתְבַּטְּלִים. וְסוֹד אֶחָד אָמַר לָנוּ, וְלֹא נִתְּנָה רְשׁוּת לְגַלּוֹת פְּרָט לַחֲסִידִים קְדוֹשִׁים עֶלְיוֹנִים חֲכָמִים. אָמַר רַבִּי יוֹסֵי, מַהוּ? אָמַר לָהֶם, עֲדַיִן לֹא בָדַקְתִּי אֶתְכֶם.</p>\n<p>הָלְכוּ, אַחַר כָּךְ אָמַר לָהֶם, כְּשֶׁהַלְּבָנָה מִתְקָרֶבֶת לַשֶּׁמֶשׁ, מְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא צַד הַצָּפוֹן וְאוֹחֵז בּוֹ בְּאַהֲבָה וּמוֹשֵׁךְ אוֹתוֹ אֵלָיו, וְהַדָּרוֹם מִתְעוֹרֵר מִצַּד אַחֵר, וְהַלְּבָנָה עוֹלָה וּמִתְחַבֶּרֶת בַּמִּזְרָח. וְאָז יוֹנֶקֶת מִשְּׁנֵי צְדָדִים וְנוֹטֶלֶת בְּרָכוֹת בַּחֲשַׁאי, וְאָז מִתְבָּרֶכֶת הַלְּבָנָה וּמִתְמַלֵּאת. וְכָאן מִתְקָרֶבֶת הָאִשָּׁה לְבַעְלָהּ.</p>\n<p>כְּמוֹ שֶׁיֵּשׁ סוֹד דְּמוּת אֵיבְרֵי (נ\"א בתקוני האיברים) הָאָדָם וְתִקּוּנָיו, כָּךְ גַּם יֵשׁ (הוא) סוֹד שֶׁל דְּמוּת אֵיבְרֵי הַנְּקֵבָה וְתִקּוּנֵי הַנְּקֵבָה, וְהַכֹּל מְפֹרָשׁ בְּתוֹכֵנוּ. כָּךְ גַּם יֵשׁ לְמַעְלָה (מי) שֶׁאוֹחֵז בָּהּ וּמִתְעוֹרֵר כְּנֶגֶד בְּאַהֲבָה, כָּךְ גַּם יֵשׁ לְמַטָּה סוֹד וְתִקּוּן הָאָדָם הַתַּחְתּוֹן הָאַחֵר תַּחַת הַלְּבָנָה (ד\"א ותקון הנקבה).</p>\n<p>כְּמוֹ שֶׁזְּרוֹעַ שְׂמֹאל לְמַעְלָה אוֹחֶזֶת בָּהּ וּמִתְעוֹרֵר כְּנֶגְדָּהּ בְּאַהֲבָה, כָּךְ גַּם יֵשׁ לְמַטָּה. (ווי העמודים כלם עומדים איברים להאחז זה בזה ולהתקשר זה בזה קשרי האמונה צד הקדשה מצד של רוח טמאה שהוא סוד הנחש שלמטה). נָחָשׁ זֶה הוּא זְרוֹעַ שְׂמֹאל שֶׁל רוּחַ הַטֻּמְאָה, וְאוֹחֵז בּוֹ מִי שֶׁרוֹכֵב עָלָיו, וְקָרֵב לַלְּבָנָה וּמוֹשֵׁךְ אוֹתָהּ בֵּינֵיהֶם (נ\"א: בדבקות) שֶׁל דְּבֵקוּת וְנִטְמֵאת.</p>\n<p>וְאָז יִשְׂרָאֵל לְמַטָּה מַקְרִיבִים שָׂעִיר, וְאוֹתוֹ נָחָשׁ נִמְשָׁךְ אַחַר אוֹתוֹ הַשָּׂעִיר, וְהַלְּבָנָה נִטְהֶרֶת וְעוֹלָה לְמַעְלָה וּמִתְקַשֶּׁרֶת לְמַעְלָה לְהִתְבָּרֵךְ, וּפָנֶיהָ מְאִירִים מַה שֶּׁנֶּחְשְׁכָה לְמַטָּה.</p>\n<p>אָז כָּאן בְּיוֹם הַכִּפּוּרִים, כֵּיוָן שֶׁאוֹתוֹ נָחָשׁ הָרָע מִתְעַסֵּק בְּאוֹתוֹ שָׂעִיר, הַלְּבָנָה נִפְרֶדֶת מִמֶּנּוּ וּמִתְעַסֶּקֶת (בישראל) לְלַמֵּד עֲלֵיהֶם סָנֵגוֹרְיָא, וְסוֹכֶכֶת עֲלֵיהֶם כְּמוֹ אֵם עַל הַבָּנִים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְבָרֵךְ אוֹתָם מִלְמַעְלָה וּמוֹחֵל לָהֶם.</p>\n<p>אַחַר כָּךְ כְּשֶׁיִּשְׂרָאֵל מַגִּיעִים לֶחָג, מְעוֹרְרִים צַד יָמִין לְמַעְלָה, כְּדֵי שֶׁתִּתְקַשֵּׁר בּוֹ הַלְּבָנָה וְיֵאוֹרוּ פָנֶיהָ כָּרָאוּי. וְאָז מְחַלֶּקֶת (נותנת) חֵלֶק שֶׁלָּהּ בְּרָכוֹת לְכָל אוֹתָם מְמֻנִּים שֶׁלְּמַטָּה שֶׁיִּתְעַסְּקוּ בְּחֶלְקָם, וְלֹא יָבֹאוּ לִינֹק וּלְהִתְקָרֵב לַצַּד שֶׁל חֵלֶק יִשְׂרָאֵל.</p>\n<p>כְּמוֹ זֶה לְמַטָּה - כְּשֶׁשְּׁאָר הָעַמִּים מִתְבָּרְכִים, כֻּלָּם מִתְעַסְּקִים בִּירֻשַּׁת חֶלְקָם, וְלֹא יָבֹאוּ לְהִתְעָרֵב עִם יִשְׂרָאֵל וְלַחְמֹד חֵלֶק יְרֻשָּׁתָם. וְלָכֵן יִשְׂרָאֵל מוֹשְׁכִים בְּרָכוֹת לְכָל אוֹתָם מְמֻנִּים, כְּדֵי שֶׁיִּתְעַסְּקוּ בְחֶלְקָם וְלֹא יִתְעָרְבוּ עִמָּם.</p>\n<p>וּכְשֶׁהַלְּבָנָה מִתְמַלֵּאת בְּרָכוֹת לְמַעְלָה כָּרָאוּי. יִשְׂרָאֵל בָּאִים וְיוֹנְקִים מִמֶּנָּה לְבַדָּם. וְעַל זֶה כָּתוּב (במדבר כט) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם. מַה זֶּה עֲצֶרֶת? כְּתַרְגּוּמוֹ כְּנִישׁוּ (התכגסות). כָּל מַה שֶּׁכִּנְּסוּ מֵאוֹתָם בְּרָכוֹת עֶלְיוֹנוֹת, לֹא יוֹנְקִים מִמֶּנָּה עַמִּים אֲחֵרִים, פְּרָט לְיִשְׂרָאֵל לְבַדָּם. וְלָכֵן כָּתוּב עֲצֶרֶת תִּהְיֶה לָכֶם, לָכֶם וְלֹא לִשְׁאָר הָעַמִּים, לָכֶם וְלֹא לִשְׁאָר הַמְמֻנִּים.</p>\n<p>וְעַל זֶה הֵם מְרַצִּים עַל הַמַּיִם, לָתֵת לָהֶם חֵלֶק בְּרָכוֹת שֶׁיִּתְעַסְּקוּ בוֹ, וְלֹא יִתְעָרְבוּ אַחַר כָּךְ בְּחֶדְוַת יִשְׂרָאֵל כְּשֶׁיּוֹנְקִים בְּרָכוֹת עֶלְיוֹנוֹת. וְעַל אוֹתוֹ יוֹם כָּתוּב דּוֹדִי לִי וַאֲנִי לוֹ. שֶׁלֹּא מִתְעָרֵב אַחֵר עִמָּנוּ.</p>\n<p>לְמֶלֶךָ שֶׁהִזְמִין אֲהוּבוֹ לִסְעוּדָה עֶלְיוֹנָה שֶׁעָשָׂה לוֹ לְיוֹם רָשׁוּם. אֲהוּב הַמֶּלֶךְ הֲרֵי יוֹדֵעַ שֶׁהַמֶּלֶךְ רוֹצֶה בּוֹ. אָמַר הַמֶּלֶךְ, כָּעֵת אֲנִי רוֹצֶה לִשְׂמֹחַ עִם אֲהוּבִי, וַאֲנִי חוֹשֵׁשׁ שֶׁכַּאֲשֶׁר אֲנִי בִּסְעוּדָה עִם אֲהוּבִי, יִכָּנְסוּ כָּל אוֹתָם פְּקִידִים מְמֻנִּים וְיֵשְׁבוּ עִמָּנוּ לַשֻּׁלְחָן לִסְעֹד סְעוּדַת הַשִּׂמְחָה עִם אֲהוּבִי. מֶה עָשָׂה? הִקְדִּים אוֹתוֹ אָהוּב מִינִים שֶׁל יְרָקוֹת וּבְשַׂר שְׁוָרִים וְהִקְרִיב לִפְנֵי אוֹתָם פְּקִידִים מְמֻנִּים לֶאֱכֹל. אַחַר כָּךְ יָשַׁב הַמֶּלֶךְ עִם אֲהוּבוֹ לְאוֹתָהּ הַסְּעוּדָה הָעֶלְיוֹנָה מִכָּל עִדּוּנֵי הָעוֹלָם. וּבְעוֹד שֶׁהוּא לְבַדּוֹ עִם הַמֶּלֶךְ, בִּקֵּשׁ מִמֶּנּוּ כָּל צְרָכָיו וְנָתַן לוֹ, וְשָׂמַח הַמֶּלֶךְ עִם אֲהוּבוֹ לְבַדּוֹ, וְלֹא הִתְעָרְבוּ אֲחֵרִים בֵּינֵיהֶם. כָּךְ יִשְׂרָאֵל עִם הַקָּדוֹשׁ בָּרוּךְ הוּא. לָכֵן כָּתוּב בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם.</p>\n<p>אָמְרוּ רַבִּי יוֹסֵי וְרַבִּי חִיָּיא, הַקָּדוֹשׁ בָּרוּךְ הוּא הִתְקִין הַדֶּרֶךְ לְפָנֵינוּ. אַשְׁרֵי אוֹתָם שֶׁעוֹסְקִים בַּתּוֹרָה. בָּאוּ וּנְשָׁקוּהוּ. קָרָא עָלָיו רַבִּי יוֹסֵי, (ישעיה נד) וְכָל בָּנַיִךְ לִמּוּדֵי ה' וְרַב שְׁלוֹם בָּנָיִךְ. כְּשֶׁהִגִּיעוּ לַשָּׂדֶה, יָשְׁבוּ. אָמַר אוֹתוֹ הָאִישׁ, מַה שּׁוֹנֶה שֶׁכָּתוּב (בראשית יט) וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה וְגוֹ', וּמַה שּׁוֹנֶה בַּמַּבּוּל שֶׁכָּתוּב אֱלֹהִים אֱלֹהִים בְּכָל מָקוֹם, (למה) וְלֹא כָתוּב וַה' (בכל)? .</p>\n<p>אֶלָּא שָׁנִינוּ, בְּכָל מָקוֹם שֶׁכָּתוּב וַה' - הוּא וּבֵית דִּינוֹ. אֱלֹהִים סְתָם - דִּין לְבַדּוֹ. אֶלָּא בִּסְדֹם נַעֲשָׂה דִין וְלֹא לְהַשְׁמִיד עוֹלָם, וְלָכֵן הוּא הִתְעָרֵב בְּדִין, אֲבָל בַּמַּבּוּל הֻשְׁמַד כָּל הָעוֹלָם וְכָל אוֹתָם שֶׁנִּמְצְאוּ (בלבדו) בָּעוֹלָם.</p>\n<p>וְאִם תֹּאמַר, (הרי) נֹחַ וּמִי שֶׁהָיָה עִמּוֹ (נצלו הרי) נִסְתָּר מִן הָעַיִן הָיָה, שֶׁלֹּא נִרְאֶה. וְעַל זֶה כָּל מַה שֶּׁנִּמְצָא בָּעוֹלָם הִשְׁמִיד אוֹתוֹ, וְעַל זֶה וַה' בְּגִלּוּי, וְלֹא הִשְׁמִיד הַכֹּל. אֱלֹהִים צָרִיךְ הַסְתָּרָה, וְצָרִיךְ (אדם) לְהִשָּׁמֵר, שֶׁהֲרֵי הַכֹּל מַשְׁמִיד, וְעַל זֶה אֱלֹהִים לְבַדּוֹ הָיָה.</p>\n<p>וְזְהִ סוֹד (תהלים כט) ה' לַמַּבּוּל יָשָׁב. מַה זֶּה יָשָׁב? אִלְמָלֵא פָּסוּק כָּתוּב, לֹא יָכֹלְנוּ לְאָמְרוֹ. יָשַׁב לְבַדּוֹ, שֶׁלֹּא בָא עִם דִּין. כָּתוּב כָּאן יָשָׁב, וְכָתוּב שָׁם (ויקרא יג) בָּדָד יֵשֵׁב לְבַדּוֹ.</p>\n<p>וּמִשּׁוּם שֶׁנֹּחַ הָיָה נִסְתָּר מִן הָעַיִן, אַחַר כָּךְ נַעֲשָׂה דִין, וְהֻשְׁמַד הָעוֹלָם וְנָח רֻגְזוֹ, מַה כָּתוּב? וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ וְגוֹ'. שֶׁהֲרֵי כְּשֶׁהִשְׁמִיד הָעוֹלָם, לֹא נִזְכַּר שֶׁהָיָה נִסְתָּר מֵהָעַיִן,</p>\n<p>וְסוֹד (זה) לָמַדְנוּ - הַקָּדוֹשׁ בָּרוּךְ הוּא נִסְתָּר וְגָלוּי. גָּלוּי הוּא בֵּית הַדִּין שֶׁלְּמַטָּה, וְנִסְתָּר הוּא מָקוֹם שֶׁכָּל הַבְּרָכוֹת יוֹצְאוֹת מִשָּׁם. וְלָכֵן כָּל דִּבְרֵי הָאָדָם שֶׁהֵם בַּסֵּתֶר, בְּרָכוֹת שׁוֹרוֹת עָלָיו. וְכָל אוֹתָם שֶׁבַּנִּגְלֶה, אוֹתוֹ מָקוֹם שֶׁל בֵּית דִּין שׁוֹרִים עָלָיו, מִשּׁוּם שֶׁהוּא מָקוֹם בְּגִלּוּי, וְאוֹתוֹ שֶׁנִּקְרָא רַע עַיִן שׁוֹלֵט עָלָיו, וְהַכֹּל הוּא בְּסוֹד עֶלְיוֹן כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>בָּכָה רַבִּי יוֹסֵי וְאָמַר, אַשְׁרֵי הַדּוֹר שֶׁרַבִּי שִׁמְעוֹן שָׁרוּי בְּתוֹכוֹ, שֶׁהֲרֵי זְכוּתוֹ הִזְמִינָה לָנוּ בֶּהָרִים דְּבָרִים עֶלְיוֹנִים כָּאֵלֶּה (עד כאן). אָמַר רַבִּי יוֹסֵי, הָאִישׁ הַזֶּה בָּא לְהוֹדִיעֵנוּ הַדְּבָרִים הַלָּלוּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח אוֹתוֹ אֵלֵינוּ. כְּשֶׁבָּאוּ וְסִדְּרוּ הַדְּבָרִים לִפְנֵי רַבִּי שִׁמְעוֹן, אָמַר, וַדַּאי שֶׁיָּפֶה אָמַר.</p>"],[9522011151,"<p>רַבִּי אֶלְעָזָר הָיָה יוֹשֵׁב יוֹם אֶחָד לִפְנֵי רַבִּי שִׁמְעוֹן אָבִיו. אָמַר לוֹ, קֵץ כָּל בָּשָׂר הַזֶּה נֶהֱנָה מֵאוֹתָם קָרְבָּנוֹת שֶׁהָיוּ יִשְׂרָאֵל מַקְרִיבִים עַל גַּבֵּי הַמִּזְבֵּחַ אוֹ לֹא? אָמַר לוֹ, כֻּלָּם הָיוּ מְסֻפָּקִים כְּאֶחָד לְמַעְלָה וּלְמַטָּה.</p>\n<p>וּבֹא וּרְאֵה, כֹּהֲנִים וּלְוִיִּם וְיִשְׂרְאֵלִים הֵם נִקְרָאִים אָדָם בְּחִבּוּר שֶׁל אוֹתָם רְצוֹנוֹת קְדוֹשִׁים שֶׁעוֹלִים מִתּוֹכָם. אוֹתוֹ כֶּשֶׂב אוֹ אַיִל אוֹ אוֹתָהּ בְּהֵמָה שֶׁמַּקְרִיבִים, צָרִיךְ עַד שֶׁלֹּא תֻקְרַב עַל הַמִּזְבֵּחַ לְפָרֵשׁ עָלֶיהָ כָּל הַחֲטָאִים וְכָל הָרְצוֹנוֹת הָרָעִים לְהִתְוַדּוֹת עָלֶיהָ, וְאָז הַהִיא נִקְרֵאת בְּהֵמָה בַּכֹּל בְּתוֹךְ אוֹתָם חֲטָאִים וְרָעוֹת וְהִרְהוּרִים.</p>\n<p>כְּמוֹ הַקָּרְבָּן שֶׁל הָעֲזָאזֵל שֶׁכָּתוּב (ויקרא יו) וְהִתְוַדָּה עָלָיו אֶת כָּל עֲונֹת בְּנֵי יִשְׂרָאֵל וְגוֹ' - כָּךְ גַּם כָּאן. וּכְשֶׁעוֹלֶה עַל הַמִּזְבֵּחַ מַשָּׂא עַל אֶחָד שְׁנַיִם, וְלָכֵן זֶה עוֹלֶה לִמְקוֹמוֹ וְזֶה עוֹלֶה לִמְקוֹמוֹ. זֶה בְּסוֹד אָדָם, וְזֶה בְּסוֹד בְּהֵמָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לו) אָדָם וּבְהֵמָה תּוֹשִׁיעַ ה'.</p>\n<p>הַחֲבִתִּין וְכָל שְׁאָר הַמְּנָחוֹת לְעוֹרֵר רוּחַ קְדוֹשָׁה בִּרְצוֹן הַכֹּהֲנִים וְשִׁירַת הַלְוִיִּם וּבִתְפִלַּת יִשְׂרָאֵל. וּבְאוֹתוֹ עָשָׁן וְשֶׁמֶן וְקֶמַח שֶׁעוֹלִים, מִתְרַוִּים וּמִסְתַּפְּקִים (ס\"א ומתפנקים ס\"א ומתפשטים) כָּל שְׁאָר בַּעֲלֵי הַדִּינִים שֶׁלֹּא יְכוֹלִים לִשְׁלֹט בְּאוֹתוֹ הַדִּין שֶׁנִּמְסָר לָהֶם, וְהַכֹּל בִּזְמַן אֶחָד. בּא רְאֵה, הַכֹּל נַעֲשָׂה בְּסוֹד הָאֱמוּנָה לְהִסְתַּפֵּק זֶה בָּזֶה וְלַעֲלוֹת לְמַעְלָה מִי שֶׁצָּרִיךְ עַד אֵין סוֹף.</p>"],[9522011152,"<p>אָמַר רַבִּי שִׁמְעוֹן, הֲרִימוֹתִי יָדַי בִּתְפִלּוֹת לְמַעְלָה, שֶׁכְּשֶׁרָצוֹן הָעֶלְיוֹן לְמַעְלָה לְמַעְלָה עוֹמֵד עַל אוֹתוֹ רָצוֹן שֶׁלֹּא נוֹדָע וְלֹא נִתְפָּס כְּלָל לְעוֹלָמִים, הָרֹאשׁ הַיּוֹתֵר נִסְתָּר שֶׁלְּמַעְלָה, וְאוֹתוֹ הָרֹאשׁ מוֹצִיא מַה שֶּׁמּוֹצִיא, וְלֹא יָדוּעַ, וּמֵאִיר מַה שֶּׁמֵּאִיר הַכֹּל בְּסֵתֶר.</p>\n<p>רְצוֹן הַמַּחֲשָׁבָה הָעֶלְיוֹנָה לִרְדֹּף אַחֲרָיו וְלִהְיוֹת מוּאָר מִמֶּנּוּ. מָסָךְ אֶחָד נִפְרָד. וּמִתּוֹךְ אוֹתוֹ מָסָךְ בִּרְדִיפַת אוֹתָהּ מַחֲשָׁבָה עֶלְיוֹנָה מַגִּיעָה וְלֹא מַגִּיעָה עַד אוֹתוֹ מָסָךְ, מְאִירָה מַה שֶּׁמְּאִירָה. וְאָז אוֹתָהּ מַחֲשָׁבָה עֶלְיוֹנָה מְאִירָה בְּאוֹר (בסתר) נִסְתָּר שֶׁלֹּא יָדוּעַ, וְאוֹתָהּ מַחֲשָׁבָה לֹא יוֹדֵעַ.</p>\n<p>וְאָז מַכֶּה אוֹר הַמַּחֲשָׁבָה הַזֶּה שֶׁלֹּא נוֹדָע בָּאוֹר שֶׁל הַמָּסָךְ שֶׁעוֹמֵד, שֶׁמֵּאִיר מִמַּה שֶּׁלֹּא יָדוּעַ וְלֹא נוֹדָע וְלֹא הִתְגַּלָּה. וְאָז (נ\"א: זה) זֶה אוֹר הַמַּחֲשָׁבָה שֶׁלֹּא נוֹדָע מַכֶּה בָּאוֹר שֶׁל הַמָּסָךְ, וּמְאִירִים כְּאֶחָד. וְנַעֲשִׂים תִּשְׁעָה הֵיכָלוֹת.</p>\n<p>וְהַהֵיכָלוֹת אֵינָם אוֹרוֹת וְלֹא רוּחוֹת וְלֹא נְשָׁמוֹת, וְאֵין מִי שֶׁעוֹמֵד בָּהֶם. הָרָצוֹן שֶׁל כָּל תִּשְׁעָה הָאוֹרוֹת שֶׁעוֹמְדִים כֻּלָּם בַּמַּחֲשָׁבָה, שֶׁהוּא אֶחָד מֵהֶם בְּחֶשְׁבּוֹן כֻּלָּם לִרְדּף אַחֲרֵיהֶם. בְּשָׁעָה שֶׁעוֹמְדִים בַּמַּחֲשָׁבָה וְלֹא נִדְבָּקִים וְלֹא נוֹדָעִים. וְאֵלֶּה לֹא עוֹמְדִים לֹא בְּרָצוֹן וְלֹא בְּמַחֲשָׁבָה עֶלְיוֹנָה (עליונות). תּוֹפְסִים בָּהּ וְלֹא תוֹפְסִים. בְּאֵלֶּה עוֹמְדִים כָּל סוֹדוֹת הָאֱמוּנָה וְכָל אוֹתָם הָאוֹרוֹת מִסּוֹד הַמַּחֲשָׁבָה הָעֶלְיוֹנָה (שלמטה ולמטה) כֻּלָּם נִקְרָאִים אֵין סוֹף. עַד כָּאן מַגִּיעִים אוֹרוֹת וְלֹא מַגִּיעִים וְלֹא נוֹדָעִים. אֵין כָּאן רָצוֹן וְלֹא מַחֲשָׁבָה.</p>\n<p>(אז) כְּשֶׁמְּאִירָה הַמַּחֲשָׁבָה וְלֹא נוֹדַעַת (ידוע) מִמִּי שֶׁמְּאִירָה, אָז מִתְלַבֶּשֶׁת וְנִסְתֶּרֶת לְתוֹךְ הַבִּינָה וּמְאִירָה לְמִי שֶׁמְּאִירָה, וְנִכְנָסִים זֶה בָּזֶה, עַד שֶׁכֻּלָּם נִכְלָלִים כְּאֶחָד.</p>\n<p>וּבְסוֹד הַקָּרְבָּן כְּשֶׁעוֹלֶה, הַכֹּל נִקְשָׁר זֶה בָּזֶה וּמֵאִיר זֶה בָּזֶה. אָז עוֹמְדִים כֻּלָּם בַּעֲלִיָּה, וְהַמַּחֲשָׁבָה מִתְעַטֶּרֶת עִם אֵין סוֹף. אוֹתוֹ הָאוֹר שֶׁמּוּאֶרֶת מִמֶּנּוּ הַמַּחֲשָׁבָה הָעֶלְיוֹנָה שֶׁלֹּא נוֹדַעַת בָּהּ כְּלָל נִקְרָא אֵין סוֹף, וּמִמֶּנּוּ נִמְצָא וְעוֹמֵד וּמֵאִיר לְמִי שֶׁמֵּאִיר, וְעַל זֶה הַכֹּל עוֹמֵד. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>בֹּא רְאֵה, קֵץ כָּל בָּשָׂר הַזֶּה, כְּמוֹ שֶׁהַקֶּשֶׁר נִמְצָא לְמַעְלָה בְּשִׂמְחָה, גַּם כָּאן לְמַטָּה בְּחֶדְוָה, וְרָצוֹן לְהִסְתַּפֵּק הַכֹּל לְמַעְלָה וּלְמַטָּה. וְהָאֵם עוֹמֶדֶת עַל יִשְׂרָאֵל כָּרָאוּי.</p>\n<p>בֹּא רְאֵה, בְּכָל רֹאשׁ חֹדֶשׁ וְחֹדֶשׁ כְּשֶׁמִּתְחַדֶּשֶׁת הַלְּבָנָה, נוֹתְנִים לְקֵץ כָּל בָּשָׂר הַזֶּה חֵלֶק אֶחָד יוֹתֵר עַל הַקָּרְבָּנוֹת לְהִתְעַסֵּק בּוֹ וְיִשְׁתַּמֵּשׁ בְּחֶלְקוֹ, וְיִהְיֶה צַד שֶׁל יִשְׂרָאֵל לְבַדָּם כְּדֵי שֶׁיִּתְאַחֲדוּ עִם מַלְכָּם, וְזֶהוּ הַשָּׂעִיר, מִשּׁוּם שֶׁהוּא בְּחֵלֶק עֵשָׂו, שֶׁכָּתוּב בּוֹ שָׂעִיר, (בראשית כז) הֵן עֵשָׂו אָחִי אִישׁ שָׂעִיר. וְעַל זֶה הוּא הִשְׁתַּמֵּשׁ בְּחֶלְקוֹ, וְיִשְׂרָאֵל מִשְׁתַּמְּשִׁים בְּחֶלְקָם, וְלָכֵן כָּתוּב (תהלים קלה) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ יִשְׂרָאֵל לִסְגֻלָּתוֹ.</p>\n<p>בֹּא רְאֵה, קֵץ כָּל בָּשָׂר הַזֶּה, כָּל רְצוֹנוֹ אֵינוֹ אֶלָּא בְּבָשָׂר תָּמִיד, וְלָכֵן תִּקּוּן הַבָּשָׂר תָּמִיד אֵלָיו, וְלָכֵן נִקְרָא קֵץ כָּל בָּשָׂר. וּכְשֶׁהוּא שׁוֹלֵט, שׁוֹלֵט עַל הַגּוּף וְלֹא עַל הַנְּשָׁמָה. הַנְּשָׁמָה עוֹלָה לִמְקוֹמָהּ, וְהַבָּשָׂר נִתָּן לַמָּקוֹם הַזֶּה. כְּמוֹ זֶה בְּקָרְבָּן, שֶׁהָרָצוֹן עוֹלֶה לְמָקוֹם אֶחָד, וְהַבָּשָׂר לְמָקוֹם אֶחָד.</p>\n<p>וְהָאִישׁ שֶׁהוּא צַדִּיק, הוּא קָרְבָּן מַמָּשׁ לְכַפָּרָה, וְאַחֵר שֶׁאֵינוֹ צַדִּיק אֵינוֹ קָרְבָּן, מִשּׁוּם שֶׁיֵּשׁ בּוֹ מוּם, שֶׁכָּתוּב (ויקרא כב) כִּי לֹא לְרָצוֹן וְגוֹ'. וְעַל זֶה הַצַּדִּיקִים הֵם כַּפָּרַת הָעוֹלָם וְהֵם קָרְבָּן בָּעוֹלָם. בֹּא רְאֵה, וַיֹּאמֶר אֱלֹהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי. לִטֹּל רְשׁוּת לְהַחְשִׁיךְ פְּנֵי בְּנֵי הָעוֹלָם. וְלָכֵן הִנְנִי מַשְׁחִיתָם אֶת הָאָרֶץ. (ועל זה עשה לך תבת עצי גפר, כדי להנצל בה ולא יוכל לשלט עליך, רבי חייא ורבי יוסי היו הולכים בדרך אמר אחד). כָּתוּב וַיַּעַשׂ נֹחַ כְּכֹל אֲשֶׁר צִוָּהוּ ה'.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, וְנֹחַ בֶּן שֵׁשׁ מֵאוֹת שָׁנָה וְגוֹ'. וְכִי לָמָּה בָּא הַחֶשְׁבּוֹן הַזֶּה לִמְנוֹת? אֶלָּא אִלּוּ לֹא הָיָה נֹחַ בֶּן שֵׁשׁ מֵאוֹת שָׁנָה, לֹא יִכָּנֵס לַתֵּבָה וְלֹא יִתְחַבֵּר עִמָּהּ. כֵּיוָן שֶׁהִשְׁתַּלֵּם בְּשֵׁשׁ מֵאוֹת שָׁנָה, אָז הִתְחַבֵּר עִמָּהּ.</p>\n<p>וְעַל כֵּן, מִיּוֹם שֶׁהִשְׁתַּלֵּם חֶטְאָם שֶׁל בְּנֵי הָעוֹלָם, חִכָּה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁהִשְׁתַּלֵּם נֹחַ בְּשֵׁשׁ מֵאוֹת שָׁנָה, וְנִשְׁלְמָה דַרְגָּתוֹ כָּרָאוּי וְהָיָה צַדִּיק שָׁלֵם, וְאָז נִכְנַס לַתֵּבָה. וְהַכֹּל כְּמוֹ שֶׁלְּמַעְלָה. וְנֹחַ בֶּן שֵׁשׁ מֵאוֹת שָׁנָה, כְּמוֹ שֶׁאָמַרְנוּ. וְלָכֵן לֹא נֶאֱמַר כְּבֶן שֵׁשׁ מֵאוֹת שָׁנָה (ד\"א כנגד ששת צדדי העולם). עוֹד פָּתַח וְאָמַר, וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל מַיִם. מָה הַטַּעַם הִנְנִי כֵּיוָן שֶׁאָמַר וַאֲנִי? אֶלָּא אֲנִי, אָנֹכִי, (הנני) - הַכֹּל זֶה דָּבָר אֶחָד.</p>"],[9522011153,"<p>בֹּא רְאֵה, בְּכָל מָקוֹם אֲנִי נַעֲשֶׂה גּוּף לַנְּשָׁמָה, וַדַּאי שֶׁמְּקַבֶּלֶת מִמַּה שֶּׁלְּמַעְלָה, וְלָכֵן נִרְמָז בְּאוֹת הַבְּרִית, שֶׁכָּתוּב אֲנִי הִנֵּה בְּרִיתִי אִתָּךְ. אֲנִי שֶׁקַּיֶּמֶת בְּגָלוּי מְזֻמֶּנֶת לָדַעַת, אֲנִי כִּסֵּא לְמַה שֶּׁלְּמַעְלָה, אֲנִי שֶׁעוֹשָׂה נְקָמוֹת לְדוֹרֵי דוֹרוֹת. וַאֲנִי - כּוֹלֵל זָכָר וּנְקֵבָה כְּאֶחָד. אַחַר כָּךְ נִרְשָׁם לְבַדּוֹ, שֶׁהִזְדַּמֵּן לַעֲשׂוֹת דִּין. הִנְנִי. מֵבִיא אֶת הַמַּבּוּל מַיִם.</p>\n<p>כֵּיוָן שֶׁאָמַר מֵבִיא אֶת הַמַּבּוּל, לֹא יָדַעְנוּ שֶׁהוּא מַיִם? אֶלָּא אֶת הַמַּבּוּל, לְרַבּוֹת מַלְאַךְ הַמָּוֶת. שֶׁאַף עַל גַּב שֶׁהָיוּ מַיִם, הַמַּשְׁחִית (להשחית בהם) (היה) הוֹלֵךְ בָּעוֹלָם לְהַשְׁמִיד בְּאוֹתָם הַמַּיִם.</p>\n<p>אֲנִי ה' - כָּךְ שָׁנִינוּ, נֶאֱמָן אֲנִי לְשַׁלֵּם שָׂכָר טוֹב לַצַּדִּיקִים וּלְהִפָּרַע מֵהָרְשָׁעִים. וְלָכֵן הִבְטִיחַ לָהֶם הַפָּסוּק לַצַּדִּיקִים בַּאֲנִי, לְשַׁלֵּם שָׂכָר טוֹב שֶׁלָּהֶם לָעוֹלָם הַבָּא. וְאִיֵּם לָרְשָׁעִים לְהִפָּרַע מֵהֶם לָעוֹלָם הַבָּא בַּאֲנִי.</p>\n<p>לְשַׁחֵת כָּל בָּשָׂר - כְּמוֹ שֶׁהֶעֱמַדְנוּ, שֶׁזֶּהוּ הַמַּשְׁחִית שֶׁל הָעוֹלָם, וְעַל זֶה כָּתוּב (שמות יב) וְלֹא יִתֵּן הַמַּשְׁחִית לָבֹא אֶל בָּתֵּיכֶם לִנְגֹּף. וְזֶה הוּא לְשַׁחֵת כָּל בָּשָׂר, מִצַּד שֶׁל קֵץ כָּל בָּשָׂר בָּא לְפָנַי. שֶׁהֲרֵי כֵּיוָן שֶׁהִגִּיעַ זְמַן שֶׁחִכָּה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא (ד\"א וחכה להם) עַד שֶׁהִשְׁלִים נֹחַ לְשֵׁשׁ מֵאוֹת שָׁנָה, אָז לְשַׁחֵת כָּל בָּשָׂר. אָמַר, כָּךְ לָמַדְנוּ מִשְּׁמוֹ שֶׁל רַבִּי יִצְחָק (ס\"א ברבי יוסי מחוזאי), שֶׁאָמַר לָנוּ, (ס\"א זה שאמרתי לכם).</p>"],[9522011154,"<p>פָּתַח וְאָמַר, (ישעיה לח) אָמַרְתִּי לֹא אֶרְאֶה יָהּ יָהּ בְּאֶרֶץ הַחַיִּים לֹא אַבִּיט אָדָם עוֹד עִם יוֹשְׁבֵי חָדֶל. אָמַרְתִּי לֹא אֶרְאֶה יָהּ, כַּמָּה אֲטוּמִים הֵם בְּנֵי אָדָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים בְּדִבְרֵי הַתּוֹרָה, אֶלָּא מִסְתַּכְּלִים בְּדִבְרֵי הָעוֹלָם וְנִשְׁכַּחַת מֵהֶם רוּחַ חָכְמָה.</p>\n<p>שֶׁכְּשֶׁאָדָם מִסְתַּלֵּק מֵהָעוֹלָם הַזֶּה וְנוֹתֵן חֶשְׁבּוֹן לְרִבּוֹנוֹ מִכָּל מַה שֶּׁעָשָׂה בָּעוֹלָם הַזֶּה בְּעוֹד שֶׁהוּא קַיָּם רוּחַ וְגוּף כְּאֶחָד, וְרוֹאֶה מַה שֶּׁרוֹאֶה, עַד שֶׁהוֹלֵךְ לְאוֹתוֹ עוֹלָם וּפוֹגֵשׁ בְּאָדָם הָרִאשׁוֹן יוֹשֵׁב בְּשַׁעַר גַּן עֵדֶן לִרְאוֹת כָּל אוֹתָם שֶׁשָּׁמְרוּ אֶת מִצְווֹת רִבּוֹנָם וְשָׂמֵחַ בָּהֶם.</p>\n<p>וְכַמָּה צַדִּיקִים סְבִיב אָדָם. אֵלּוּ שֶׁנִּמְנְעוּ מִדֶּרֶךְ הַגֵּיהִנֹּם וְסָטוּ לְדֶרֶךְ גַּן הָעֵדֶן, וְאֵלֶּה נִקְרָאִים יוֹשְׁבֵי חָדֶל. וְלֹא כָתוּב יוֹשְׁבֵי חָלֶד, כִּי אֵינָם כְּמוֹ חֻלְדָּה שֶׁגּוֹרֶרֶת וּמַנִּיחָה וְלֹא יוֹדַעַת לְמִי מַנִּיחָה, אֶלָּא יוֹשְׁבֵי חָדֶל, כְּמוֹ שֶׁנֶּאֱמַר (שם ב) חִדְלוּ לָכֶם מִן הָאָדָם וְגוֹ', (אלא יושבי חדל) שֶׁנִּמְנְעוּ מִדֶּרֶךְ הַגֵּיהִנֹּם, וְהֶחֱזִיקוּ בָהֶם לְהַכְנִיסָם בְּגַן עֵדֶן.</p>\n<p>דָּבָר אַחֵר יוֹשְׁבֵי חָדֶל - אֵלּוּ בַּעֲלֵי תְשׁוּבָה שֶׁמָּנְעוּ עַצְמָם מֵאוֹתָם חֲטָאֵי הָרְשָׁעִים. וּמִשּׁוּם שֶׁאָדָם הָרִאשׁוֹן שָׁב בִּתְשׁוּבָה לִפְנֵי רִבּוֹנוֹ, יוֹשֵׁב (עם) עַל אוֹתָם שֶׁנִּמְנְעוּ מֵחֲטָאֵיהֶם וְהֵם בְּנֵי חָדֶל, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לט) אֵדְעָה מֶה חָדֵל אָנִי. וְלָכֵן הוּא יוֹשֵׁב בְּשַׁעַר גַּן הָעֵדֶן וְשָׂמֵחַ בַּצַּדִּיקִים שֶׁבָּאִים בְּאוֹתָהּ דֶּרֶךְ שֶׁל גַּן עֵדֶן</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, אָמַרְתִּי לֹא אֶרְאֶה יָהּ. וְכִי מִי יָכוֹל לִרְאוֹת יָהּ? אֶלָּא סוֹף הַכָּתוּב מוֹכִיחַ, שֶׁכָּתוּב יָהּ בְּאֶרֶץ הַחַיִּים. בֹּא רְאֵה, כְּשֶׁהַנְּשָׁמוֹת עוֹלוֹת לִמְקוֹם צְרוֹר הַחַיִּים, שָׁם נֶהֱנִים בַּזֹּהַר שֶׁל הָאַסְפַּקְלַרְיָה שֶׁמְּאִירָה מֵהַמָּקוֹם הָעֶלְיוֹן שֶׁל הַכֹּל. וְאִלּוּ לֹא הִתְלַבְּשָׁה הַנְּשָׁמָה בַּזֹּהַר שֶׁל לְבוּשׁ אַחֵר, לֹא תוּכַל לְהִתְקָרֵב לִרְאוֹת אֶת אוֹתוֹ הָאוֹר.</p>\n<p>וְסוֹד הַדָּבָר - כְּמוֹ שֶׁנּוֹתְנִים לַנְּשָׁמָה לְבוּשׁ שֶׁמִּתְלַבֶּשֶׁת בּוֹ לַעֲמֹד בָּעוֹלָם הַזֶּה, כָּךְ גַּם נוֹתְנִים לָהּ לְבוּשׁ שֶׁל זֹהַר עֶלְיוֹן לַעֲמֹד בָּהּ בְּאוֹתוֹ עוֹלָם וּלְהִסְתַּכֵּל בְּתוֹךְ אוֹתָהּ אַסְפַּקְלַרְיָה שֶׁמְּאִירָה מִתּוֹךְ אוֹתָהּ אֶרֶץ הַחַיִּים.</p>\n<p>בֹּא רְאֵה, מֹשֶׁה לֹא יָכֹל לְהִתְקָרֵב לְהִסְתַּכֵּל בְּמַה שֶּׁהִסְתַּכֵּל אֶלָּא כְּשֶׁהִתְלַבֵּשׁ בִּלְבוּשׁ אַחֵר, כְּמוֹ שֶׁנֶּאֱמַר (שמות כד) וַיָּבא מֹשֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר. וְתַרְגּוּם, בְּאֶמְצָעוּת הֶעָנָן. וְהִתְלַבֵּשׁ בּוֹ כְּמִי שֶׁמִּתְלַבֵּשׁ בִּלְבוּשׁ. וְלָכֵן (שם כ) וּמֹשֶׁה נִגַּשׁ אֶל הָעֲרָפֶל אֲשֶׁר שָׁם הָאֱלֹהִים, וְכָתוּב (שם כד) וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן וְגוֹ', וַיְהִי מֹשֶׁה בָּהָר אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה, וְיָכֹל לְהִסְתַּכֵּל בְּמַה שֶּׁהִסְתַּכֵּל.</p>\n<p>כְּמוֹ זֶה מִתְלַבְּשׁוֹת נִשְׁמוֹת הַצַּדִּיקִים בְּאוֹתוֹ הָעוֹלָם בִּלְבוּשׁ כְּמוֹ שֶׁל אוֹתוֹ הָעוֹלָם, שֶׁלֹּא יִתְנַהֵג אֶלָּא בִּלְבוּשׁ כְּמוֹ זֶה, וְעוֹמְדִים לְהִסְתַּכֵּל בָּאוֹר הַמֵּאִיר בְּאוֹתָהּ אֶרֶץ הַחַיִּים. וְזֶהוּ יָהּ יָהּ בְּאֶרֶץ הַחַיִּים, שֶׁהָיָה סָבוּר שֶׁלֹּא יִזְכֶּה לְאוֹתוֹ אוֹר וּלְאוֹתָהּ הִסְתַּכְּלוּת, מִשּׁוּם שֶׁהַנָּהָר הַשּׁוֹפֵעַ מַפְסִיק אוֹתוֹ וְלֹא הוֹלִיד. לֹא אַבִּיט אָדָם עוֹד - זֶה אָדָם הָרִאשׁוֹן, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וְכָל זֶה לָמָּה? כִּי אָמַר לוֹ הַנָּבִיא, כִּי מֵת אַתָּה - בָּעוֹלָם הַזֶּה, וְלֹא תִחְיֶה - לָעוֹלָם הַבָּא. מִשּׁוּם שֶׁמִּי שֶׁלֹּא (היה) מוֹלִיד בָּנִים בָּעוֹלָם הַזֶּה, כְּשֶׁיּוֹצֵא מִמֶּנּוּ, מְגָרְשִׁים אוֹתוֹ מִכָּל מַה שֶּׁאָמַרְנוּ, וְלֹא שׁוֹרֶה לִרְאוֹת בְּאוֹתוֹ אוֹר הַמֵּאִיר (כל שכן וכל שכן לשאר העמים ושאר בני האדם). וּמָה חִזְקִיָּה שֶׁהָיְתָה לוֹ זְכוּת אָבוֹת וְהוא זַכַּאי צַדִּיק וְחָסִיד כָּךְ, כָּל שֶׁכֵּן מִי שֶׁאֵין לוֹ זְכוּת אָבוֹת וְחוֹטֵא לִפְנֵי רִבּוֹנוֹ.</p>\n<p>הַלְּבוּשׁ הַזֶּה שֶׁאָמַרְנוּ הוּא (הם) מַה שֶּׁאָמְרוּ הַחֲבֵרִים, חָלוּק שֶׁל רַבָּנָן שֶׁמִּתְלַבְּשִׁים בּוֹ בְּאוֹתוֹ הָעוֹלָם. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁגָּנַז לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא כַּמָּה טוֹבוֹת וְעִדּוּנִים לָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ.</p>"]]});
